/* Tự sinh bởi tools/build-data.js */
window.DATA = window.DATA || {};
window.DATA.mcq = [{"id":"q0001","unit":1,"stem":"A manufacturer produces a unique piece of machinery according to one customer's technical requirements. Which method is most appropriate?","options":["Mass production","Unit production","Continuous production","Batch production"],"answer":1,"explain":"Unit production là sản xuất từng chiếc đơn lẻ theo yêu cầu riêng của một khách hàng. Mass production là sản xuất hàng loạt sản phẩm giống hệt nhau, còn batch production là sản xuất theo lô nên không phù hợp với một máy độc nhất.","extra":[{"en":"one-off order","vi":"đơn hàng làm riêng một lần"},
{"en":"custom-built","vi":"được chế tạo theo yêu cầu"},
{"en":"technical specification","vi":"thông số kỹ thuật"}]},
{"id":"q0002","unit":1,"stem":"The factory has experienced frequent equipment failures. Regular ______ is necessary to prevent unexpected interruptions.","options":["capacity planning","machine maintenance","inventory management","quality assurance"],"answer":1,"explain":"Machine maintenance (bảo trì máy móc) giúp ngăn thiết bị hỏng đột xuất. Capacity planning là lập kế hoạch công suất và quality assurance là đảm bảo chất lượng, đều không trực tiếp giải quyết hỏng hóc thiết bị.","extra":[{"en":"preventive maintenance","vi":"bảo trì phòng ngừa"},
{"en":"equipment failure","vi":"hỏng thiết bị"},
{"en":"unplanned downtime","vi":"thời gian ngừng máy ngoài kế hoạch"}]},
{"id":"q0003","unit":3,"stem":"A company purchases raw materials but has not yet used them in production. On its balance sheet, these materials are generally classified as ______.","options":["receivables","goodwill","inventory","equity"],"answer":2,"explain":"Nguyên vật liệu đã mua nhưng chưa dùng được ghi nhận là inventory (hàng tồn kho). Receivables là các khoản phải thu, goodwill là lợi thế thương mại, equity là vốn chủ sở hữu.","extra":[{"en":"raw materials","vi":"nguyên vật liệu thô"},
{"en":"work in progress","vi":"sản phẩm dở dang"},
{"en":"finished goods","vi":"thành phẩm"}]},
{"id":"q0004","unit":4,"stem":"Before investing in a start-up, the fund examines its financial records, legal contracts and business risks. This process is called ______.","options":["bookkeeping","due diligence","cross-promotion","performance measurement"],"answer":1,"explain":"Due diligence là thẩm định kỹ lưỡng hồ sơ tài chính, hợp đồng và rủi ro trước khi đầu tư. Bookkeeping chỉ là ghi sổ kế toán, cross-promotion là quảng bá chéo.","extra":[{"en":"conduct due diligence","vi":"tiến hành thẩm định"},
{"en":"financial backer","vi":"nhà tài trợ vốn"},
{"en":"venture capital","vi":"vốn đầu tư mạo hiểm"}]},
{"id":"q0005","unit":2,"stem":"A business introduces a system in which materials arrive shortly before they are required for production. This is an example of ______ manufacturing.","options":["mass","continuous","Just-in-time","unit"],"answer":2,"explain":"Just-in-time là hệ thống nguyên liệu đến đúng lúc cần dùng để giảm tồn kho. Mass và continuous production nói về cách thức/quy mô sản xuất, unit production là sản xuất đơn chiếc.","extra":[{"en":"JIT delivery","vi":"giao hàng đúng lúc"},
{"en":"lean manufacturing","vi":"sản xuất tinh gọn"},
{"en":"stock holding costs","vi":"chi phí lưu kho"}]},
{"id":"q0006","unit":4,"stem":"The company borrowed $2 million. The original amount it must repay, excluding interest, is the ______.","options":["security","leverage","principal","return on investment"],"answer":2,"explain":"Principal là số tiền gốc phải hoàn trả, chưa tính lãi. Security là tài sản thế chấp, leverage là đòn bẩy tài chính, ROI là tỷ suất sinh lời của khoản đầu tư.","extra":[{"en":"outstanding principal","vi":"dư nợ gốc"},
{"en":"repayment schedule","vi":"lịch trả nợ"},
{"en":"accrued interest","vi":"lãi tích lũy"}]},
{"id":"q0007","unit":2,"stem":"One stage of the production process operates more slowly than all the others, restricting total output. This is a production ______.","options":["yield","bottleneck","specification","tier"],"answer":1,"explain":"Bottleneck là khâu nghẽn cổ chai, chậm hơn các khâu khác và giới hạn tổng sản lượng. Yield là tỷ lệ sản phẩm đạt chuẩn, specification là thông số kỹ thuật, tier là cấp bậc.","extra":[{"en":"remove a bottleneck","vi":"gỡ điểm nghẽn"},
{"en":"throughput","vi":"năng suất thông qua"},
{"en":"production line balancing","vi":"cân bằng chuyền"}]},
{"id":"q0008","unit":6,"stem":"A hotel promotes its restaurant to existing spa customers and offers restaurant guests discounts on spa treatments. This is ______.","options":["restructuring","cross-promotion","short selling","decentralization"],"answer":1,"explain":"Cross-promotion là hai bên quảng bá chéo cho khách hàng của nhau, đúng như khách sạn quảng bá nhà hàng và spa. Restructuring là tái cấu trúc, short selling là bán khống, decentralization là phân quyền.","extra":[{"en":"cross-selling","vi":"bán chéo sản phẩm"},
{"en":"joint promotion","vi":"khuyến mãi chung"},
{"en":"customer loyalty","vi":"sự trung thành của khách hàng"}]},
{"id":"q0009","unit":6,"stem":"A corporation transfers authority from its headquarters to regional offices. It intends to ______ its decision-making.","options":["centralize","downgrade","decentralize","standardize"],"answer":2,"explain":"Decentralize là phân quyền từ trụ sở về các văn phòng khu vực. Centralize là làm ngược lại (tập trung quyền), còn downgrade và standardize không liên quan đến việc chuyển giao quyền.","extra":[{"en":"delegate authority","vi":"ủy quyền"},
{"en":"regional office","vi":"văn phòng khu vực"},
{"en":"flat structure","vi":"cơ cấu tổ chức phẳng"}]},
{"id":"q0010","unit":1,"stem":"Managers estimate whether existing equipment and facilities can satisfy forecast demand next year. They are undertaking ______.","options":["capacity planning","tax accounting","forensic accounting","inventory replenishment"],"answer":0,"explain":"Capacity planning là đánh giá xem thiết bị, cơ sở vật chất có đáp ứng nhu cầu dự báo hay không. Tax và forensic accounting là các mảng kế toán, inventory replenishment là bổ sung hàng tồn.","extra":[{"en":"demand forecast","vi":"dự báo nhu cầu"},
{"en":"spare capacity","vi":"công suất dư"},
{"en":"capacity utilization","vi":"mức sử dụng công suất"}]},
{"id":"q0011","unit":5,"stem":"A mature product generates reliable profits and provides funds for the development of new products. It is often called a ______.","options":["cash cow","financial liability","production bottleneck","joint venture"],"answer":0,"explain":"Cash cow là sản phẩm trưởng thành mang lại lợi nhuận ổn định để tài trợ cho sản phẩm mới. Liability là nợ phải trả, bottleneck là điểm nghẽn, joint venture là liên doanh.","extra":[{"en":"product life cycle","vi":"vòng đời sản phẩm"},
{"en":"steady revenue stream","vi":"dòng doanh thu ổn định"},
{"en":"market share","vi":"thị phần"}]},
{"id":"q0012","unit":4,"stem":"An investor uses borrowed money to increase the size of an investment. This practice is known as ______.","options":["bootstrapping","diversification","leverage","bookkeeping"],"answer":2,"explain":"Leverage là dùng vốn vay để tăng quy mô đầu tư (đòn bẩy). Bootstrapping là tự lực bằng vốn riêng, diversification là đa dạng hóa, bookkeeping là ghi sổ.","extra":[{"en":"highly leveraged","vi":"vay nợ nhiều"},
{"en":"gearing ratio","vi":"tỷ lệ nợ trên vốn"},
{"en":"margin trading","vi":"giao dịch ký quỹ"}]},
{"id":"q0013","unit":2,"stem":"A manufacturer establishes procedures to prevent defects and ensure that products consistently meet required standards. These procedures form part of ______.","options":["quality assurance","capacity planning","financial accounting","waste disposal"],"answer":0,"explain":"Quality assurance là hệ thống quy trình phòng ngừa lỗi và đảm bảo sản phẩm luôn đạt chuẩn. Capacity planning là công suất, financial accounting là kế toán tài chính, waste disposal là xử lý chất thải.","extra":[{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"meet the standard","vi":"đạt tiêu chuẩn"}]},
{"id":"q0014","unit":5,"stem":"A regulation specifies the maximum level of industrial pollution permitted. This level is an emissions ______.","options":["coalition","threshold","backdown","compromise"],"answer":1,"explain":"Threshold là ngưỡng, ở đây là mức phát thải tối đa cho phép. Coalition là liên minh, backdown là sự nhượng bộ, compromise là thỏa hiệp.","extra":[{"en":"exceed the threshold","vi":"vượt ngưỡng"},
{"en":"emissions limit","vi":"giới hạn khí thải"},
{"en":"environmental regulation","vi":"quy định môi trường"}]},
{"id":"q0015","unit":6,"stem":"Following several years of losses, the company closes unprofitable divisions and reorganizes its business activities. It decides to ______.","options":["replenish","relaunch","restructure","reassess"],"answer":2,"explain":"Restructure là tái cấu trúc, đóng các bộ phận thua lỗ và sắp xếp lại hoạt động. Replenish là bổ sung, relaunch là tái tung sản phẩm, reassess là đánh giá lại, không bao hàm việc đóng bộ phận.","extra":[{"en":"corporate restructuring","vi":"tái cấu trúc doanh nghiệp"},
{"en":"cut costs","vi":"cắt giảm chi phí"},
{"en":"turnaround plan","vi":"kế hoạch xoay chuyển tình thế"}]},
{"id":"q0016","unit":3,"stem":"A company deliberately uses accounting loopholes to make its financial position appear stronger than it really is. This may be described as ______.","options":["managerial accounting","bookkeeping","cost accounting","creative accounting"],"answer":3,"explain":"Creative accounting là lợi dụng kẽ hở kế toán để làm tình hình tài chính trông tốt hơn thực tế. Bookkeeping, cost và managerial accounting là các hoạt động kế toán thông thường, không có ý đồ che giấu.","extra":[{"en":"loophole","vi":"kẽ hở"},
{"en":"window dressing","vi":"tô vẽ báo cáo tài chính"},
{"en":"falsify accounts","vi":"làm giả sổ sách"}]},
{"id":"q0017","unit":4,"stem":"A borrower pledges a property to protect the lender in case the loan is not repaid. The property serves as ______.","options":["equity","security","principal","receivables"],"answer":1,"explain":"Security là tài sản thế chấp bảo đảm cho người cho vay. Equity là vốn chủ sở hữu, principal là tiền gốc, receivables là khoản phải thu.","extra":[{"en":"collateral","vi":"tài sản đảm bảo"},
{"en":"secured loan","vi":"khoản vay có thế chấp"},
{"en":"foreclose","vi":"tịch thu tài sản thế chấp"}]},
{"id":"q0018","unit":2,"stem":"The operations manager investigates the exact point at which delays originate. The manager wants to ______ the source of the problem.","options":["pinpoint","multiply","offset","comply"],"answer":0,"explain":"Pinpoint là xác định chính xác nguyên nhân hoặc vị trí của vấn đề. Multiply là nhân lên, offset là bù đắp, comply là tuân thủ, đều không hợp ngữ cảnh.","extra":[{"en":"root cause analysis","vi":"phân tích nguyên nhân gốc"},
{"en":"identify weaknesses","vi":"nhận diện điểm yếu"},
{"en":"remediate","vi":"khắc phục"}]},
{"id":"q0019","unit":6,"stem":"A business discovers a group of customers whose needs have not been adequately served by existing suppliers. This is an ______ market.","options":["identical","volatile","untapped","standardized"],"answer":2,"explain":"Untapped market là thị trường chưa được khai thác, nhóm khách hàng chưa được phục vụ tốt. Volatile là biến động mạnh, identical là giống hệt, standardized là được tiêu chuẩn hóa.","extra":[{"en":"untapped potential","vi":"tiềm năng chưa khai thác"},
{"en":"niche market","vi":"thị trường ngách"},
{"en":"market gap","vi":"khoảng trống thị trường"}]},
{"id":"q0020","unit":2,"stem":"Purchasing, production and distribution policies should ______ with the company's long-term strategic vision.","options":["incur","hover","falsify","align"],"answer":3,"explain":"Align with là phù hợp, đồng bộ với tầm nhìn chiến lược dài hạn. Incur là gánh chịu (chi phí), hover là lơ lửng, falsify là làm giả, đều không đi với with trong nghĩa này.","extra":[{"en":"strategic vision","vi":"tầm nhìn chiến lược"},
{"en":"be aligned with","vi":"thống nhất với"},
{"en":"long-term objectives","vi":"mục tiêu dài hạn"}]},
{"id":"q0021","unit":1,"stem":"A company produces 10,000 identical bottles using a highly automated assembly line. This is best described as ______.","options":["unit production","mass production","batch production","customized production"],"answer":1,"explain":"Mass production là sản xuất hàng loạt sản phẩm giống nhau trên dây chuyền tự động hóa cao. Unit production là đơn chiếc, batch là theo lô, customized là tùy biến theo khách, đều trái với 10.000 chai giống hệt.","extra":[{"en":"assembly line","vi":"dây chuyền lắp ráp"},
{"en":"economies of scale","vi":"lợi thế quy mô"},
{"en":"standardized product","vi":"sản phẩm tiêu chuẩn hóa"}]},
{"id":"q0022","unit":1,"stem":"A factory groups products into separate lots, completing one group before switching to another. Which production method is being used?","options":["continuous production","unit production","batch production","mass production"],"answer":2,"explain":"Batch production là sản xuất theo lô, xong một nhóm mới chuyển sang nhóm khác. Continuous là chạy liên tục không ngừng, unit là đơn chiếc, mass là hàng loạt liên tục một loại.","extra":[{"en":"production run","vi":"đợt sản xuất"},
{"en":"changeover time","vi":"thời gian chuyển đổi dây chuyền"},
{"en":"batch size","vi":"kích cỡ lô"}]},
{"id":"q0023","unit":3,"stem":"A business must pay suppliers for goods already received. These unpaid amounts are recorded as ______.","options":["receivables","cash equivalents","liabilities","retained earnings"],"answer":2,"explain":"Các khoản chưa trả cho nhà cung cấp là liabilities (nợ phải trả). Receivables là khoản phải thu, cash equivalents là tương đương tiền, retained earnings là lợi nhuận giữ lại.","extra":[{"en":"accounts payable","vi":"các khoản phải trả"},
{"en":"current liabilities","vi":"nợ ngắn hạn"},
{"en":"trade creditor","vi":"chủ nợ thương mại"}]},
{"id":"q0024","unit":3,"stem":"A company owns a well-known brand name that contributes to its market value. The brand-related value is an example of an ______ asset.","options":["intangible","current","physical","liquid"],"answer":0,"explain":"Giá trị thương hiệu là tài sản vô hình (intangible), không có hình thái vật chất. Current là tài sản ngắn hạn, physical là hữu hình, liquid là có tính thanh khoản cao.","extra":[{"en":"brand equity","vi":"giá trị thương hiệu"},
{"en":"intellectual property","vi":"sở hữu trí tuệ"},
{"en":"tangible asset","vi":"tài sản hữu hình"}]},
{"id":"q0025","unit":3,"stem":"A company sets aside an estimated amount to cover a probable future obligation. In accounting, this amount may be recorded as ______.","options":["provisions","receivables","cash equivalents","treasury shares"],"answer":0,"explain":"Provisions là khoản dự phòng cho nghĩa vụ có khả năng phát sinh trong tương lai. Receivables là khoản phải thu, cash equivalents là tương đương tiền, treasury shares là cổ phiếu quỹ.","extra":[{"en":"provision for bad debts","vi":"dự phòng nợ xấu"},
{"en":"contingent liability","vi":"nợ tiềm tàng"},
{"en":"write off","vi":"xóa sổ"}]},
{"id":"q0026","unit":3,"stem":"A business sells shares that it previously repurchased from investors. These shares are known as ______ shares.","options":["ordinary","treasury","preference","derivative"],"answer":1,"explain":"Treasury shares là cổ phiếu quỹ, công ty đã mua lại từ nhà đầu tư. Ordinary và preference là cổ phiếu phổ thông và ưu đãi, derivative là công cụ phái sinh, không phải cổ phiếu.","extra":[{"en":"share buyback","vi":"mua lại cổ phiếu"},
{"en":"issued share capital","vi":"vốn cổ phần đã phát hành"},
{"en":"dividend payout","vi":"chi trả cổ tức"}]},
{"id":"q0027","unit":3,"stem":"A company earns a profit but keeps part of it in the business rather than distributing it to shareholders. The retained amount is called ______.","options":["deferred tax","retained earnings","accounts payable","loan principal"],"answer":1,"explain":"Retained earnings là lợi nhuận giữ lại để tái đầu tư thay vì chia cho cổ đông. Deferred tax là thuế hoãn lại, accounts payable là khoản phải trả, loan principal là gốc vay.","extra":[{"en":"dividend","vi":"cổ tức"},
{"en":"reinvest profits","vi":"tái đầu tư lợi nhuận"},
{"en":"shareholders' equity","vi":"vốn chủ sở hữu"}]},
{"id":"q0028","unit":4,"stem":"A financial institution pools money from many investors and invests it in a diversified portfolio. This institution operates a ______.","options":["mortgage loan","mutual fund","joint venture","venture capital loan"],"answer":1,"explain":"Mutual fund là quỹ tương hỗ gom tiền nhiều nhà đầu tư vào danh mục đa dạng. Mortgage loan là vay thế chấp, joint venture là liên doanh, venture capital loan là khoản vay vốn mạo hiểm.","extra":[{"en":"investment portfolio","vi":"danh mục đầu tư"},
{"en":"fund manager","vi":"người quản lý quỹ"},
{"en":"diversify risk","vi":"phân tán rủi ro"}]},
{"id":"q0029","unit":4,"stem":"A borrower fails to make the required loan payments according to the agreed terms. The borrower is in ______.","options":["default","leverage","acquisition","due diligence"],"answer":0,"explain":"Default là vỡ nợ, không trả nợ đúng hạn. Leverage là đòn bẩy, acquisition là thâu tóm, due diligence là thẩm định, đều không phải tình trạng không trả được nợ.","extra":[{"en":"default on a loan","vi":"vỡ nợ khoản vay"},
{"en":"default risk","vi":"rủi ro vỡ nợ"},
{"en":"late payment penalty","vi":"phạt trả chậm"}]},
{"id":"q0030","unit":4,"stem":"An investor expects the gain generated by an investment relative to the amount invested. The investor is measuring the ______.","options":["interest rate","return on investment","loan principal","security"],"answer":1,"explain":"Return on investment (ROI) đo lợi nhuận thu được so với vốn bỏ ra. Interest rate là lãi suất, loan principal là gốc vay, security là tài sản bảo đảm.","extra":[{"en":"rate of return","vi":"tỷ suất sinh lời"},
{"en":"payback period","vi":"thời gian hoàn vốn"},
{"en":"break-even point","vi":"điểm hòa vốn"}]},
{"id":"q0031","unit":4,"stem":"A company buys a controlling interest in another business. This transaction is an ______.","options":["acquisition","auditing","offset","backdown"],"answer":0,"explain":"Acquisition là việc mua lại phần sở hữu kiểm soát của doanh nghiệp khác. Auditing là kiểm toán, offset là bù trừ, backdown là sự nhượng bộ.","extra":[{"en":"hostile take-over","vi":"thâu tóm thù địch"},
{"en":"merger and acquisition","vi":"mua bán và sáp nhập"},
{"en":"controlling stake","vi":"cổ phần chi phối"}]},
{"id":"q0032","unit":4,"stem":"A financial instrument whose value is derived from an underlying asset is known as a ______.","options":["bondholder","derivative","mortgage","cash equivalent"],"answer":1,"explain":"Derivative là công cụ phái sinh, giá trị phụ thuộc vào tài sản cơ sở. Bondholder là người giữ trái phiếu, mortgage là thế chấp, cash equivalent là tương đương tiền.","extra":[{"en":"underlying asset","vi":"tài sản cơ sở"},
{"en":"futures contract","vi":"hợp đồng tương lai"},
{"en":"hedging","vi":"phòng ngừa rủi ro"}]},
{"id":"q0033","unit":2,"stem":"A government introduces new rules requiring factories to reduce harmful emissions. Companies must ______ with the regulations.","options":["comply","incur","hover","backtrack"],"answer":0,"explain":"Comply with là tuân thủ quy định. Incur là gánh chịu, hover là lơ lửng, backtrack là rút lại lập trường, đều không đi với regulations theo nghĩa này.","extra":[{"en":"comply with regulations","vi":"tuân thủ quy định"},
{"en":"non-compliance","vi":"không tuân thủ"},
{"en":"regulatory requirements","vi":"yêu cầu pháp lý"}]},
{"id":"q0034","unit":5,"stem":"A pressure group publicly criticizes a company's misleading environmental claims. The group questions the company's ______.","options":["downtime","integrity","capacity","principal"],"answer":1,"explain":"Pressure group chỉ trích tuyên bố môi trường gây hiểu lầm, tức là nghi ngờ integrity (sự trung thực, liêm chính) của công ty. Downtime là thời gian ngừng máy, capacity là công suất, principal là tiền gốc.","extra":[{"en":"greenwashing","vi":"tẩy xanh"},
{"en":"corporate integrity","vi":"sự liêm chính doanh nghiệp"},
{"en":"public scrutiny","vi":"sự giám sát của công chúng"}]},
{"id":"q0035","unit":5,"stem":"A government decides to ______ stricter environmental rules after consulting businesses and community organizations.","options":["enact","incur","replenish","falsify"],"answer":0,"explain":"Enact là ban hành, thông qua luật hay quy định. Incur là gánh chịu, replenish là bổ sung, falsify là làm giả.","extra":[{"en":"enact legislation","vi":"ban hành luật"},
{"en":"come into force","vi":"có hiệu lực"},
{"en":"public consultation","vi":"tham vấn công chúng"}]},
{"id":"q0036","unit":5,"stem":"A politician initially supports a proposal but later withdraws that support after facing strong criticism. The politician has decided to ______.","options":["replenish","backtrack","relaunch","offset"],"answer":1,"explain":"Backtrack là rút lại lập trường đã ủng hộ trước đó. Replenish là bổ sung, relaunch là tung lại, offset là bù đắp.","extra":[{"en":"back down","vi":"nhượng bộ"},
{"en":"U-turn","vi":"sự đảo ngược chính sách"},
{"en":"withdraw support","vi":"rút lại sự ủng hộ"}]},
{"id":"q0037","unit":5,"stem":"A company offers financial compensation to balance the additional costs caused by a new environmental requirement. It aims to ______ those costs.","options":["offset","impose","multiply","hover"],"answer":0,"explain":"Offset là bù đắp, cân bằng chi phí phát sinh. Impose là áp đặt, multiply là nhân lên, hover là lơ lửng.","extra":[{"en":"carbon offset","vi":"bù đắp carbon"},
{"en":"compensate for","vi":"bồi thường cho"},
{"en":"additional costs","vi":"chi phí phát sinh thêm"}]},
{"id":"q0038","unit":5,"stem":"A group of political parties joins together to form a government. This arrangement is called a ______.","options":["threshold","coalition","commission","compromise"],"answer":1,"explain":"Coalition là liên minh của nhiều đảng cùng lập chính phủ. Threshold là ngưỡng, commission là ủy ban hoặc hoa hồng, compromise là thỏa hiệp.","extra":[{"en":"coalition government","vi":"chính phủ liên minh"},
{"en":"ruling party","vi":"đảng cầm quyền"},
{"en":"form an alliance","vi":"lập liên minh"}]},
{"id":"q0039","unit":5,"stem":"A worker is legally qualified to receive a particular pension benefit. The worker is ______ the benefit.","options":["opposed to","eligible for","dismayed by","embedded in"],"answer":1,"explain":"Eligible for là đủ điều kiện nhận quyền lợi. Opposed to là phản đối, dismayed by là thất vọng, embedded in là gắn chặt vào, không đúng nghĩa.","extra":[{"en":"eligibility criteria","vi":"tiêu chí đủ điều kiện"},
{"en":"pension scheme","vi":"chế độ lương hưu"},
{"en":"entitlement","vi":"quyền được hưởng"}]},
{"id":"q0040","unit":6,"stem":"A business moves its manufacturing facilities to another city to reduce operating expenses. It decides to ______ its production.","options":["relocate","downgrade","retrain","decelerate"],"answer":0,"explain":"Relocate là chuyển cơ sở sản xuất sang nơi khác. Downgrade là hạ cấp, retrain là đào tạo lại, decelerate là giảm tốc, đều không nói về chuyển địa điểm.","extra":[{"en":"relocation costs","vi":"chi phí di dời"},
{"en":"offshoring","vi":"chuyển sản xuất ra nước ngoài"},
{"en":"reduce operating expenses","vi":"giảm chi phí vận hành"}]},
{"id":"q0041","unit":6,"stem":"A company teaches existing employees new skills so they can operate newly installed equipment. It plans to ______ its workforce.","options":["restructure","retrain","reassess","relaunch"],"answer":1,"explain":"Retrain là đào tạo lại nhân viên kỹ năng mới. Restructure là tái cấu trúc, reassess là đánh giá lại, relaunch là tung lại sản phẩm.","extra":[{"en":"upskill","vi":"nâng cao kỹ năng"},
{"en":"on-the-job training","vi":"đào tạo tại chỗ"},
{"en":"skills gap","vi":"khoảng cách kỹ năng"}]},
{"id":"q0042","unit":6,"stem":"A company changes its product range to better serve the needs of a particular customer group. It wants to ______ to that clientele.","options":["cater","falsify","incur","hover"],"answer":0,"explain":"Cater to là phục vụ, đáp ứng nhu cầu một nhóm khách hàng. Falsify là làm giả, incur là gánh chịu, hover là lơ lửng.","extra":[{"en":"cater to customer needs","vi":"đáp ứng nhu cầu khách hàng"},
{"en":"target market","vi":"thị trường mục tiêu"},
{"en":"tailor products","vi":"điều chỉnh sản phẩm theo nhu cầu"}]},
{"id":"q0043","unit":6,"stem":"A business responds quickly to changing customer preferences and adjusts its processes without lengthy delays. It is considered ______.","options":["volatile","agile","blatant","identical"],"answer":1,"explain":"Agile là linh hoạt, phản ứng nhanh với thay đổi mà không chậm trễ. Volatile là biến động, blatant là trắng trợn, identical là giống hệt.","extra":[{"en":"agile management","vi":"quản trị linh hoạt"},
{"en":"respond to change","vi":"ứng phó với thay đổi"},
{"en":"customer preferences","vi":"thị hiếu khách hàng"}]},
{"id":"q0044","unit":6,"stem":"A café has an excellent reputation and attracts a loyal group of regular customers. This group is its ______.","options":["infrastructure","clientele","backbench","protagonists"],"answer":1,"explain":"Clientele là tập khách hàng thường xuyên. Infrastructure là cơ sở hạ tầng, backbench là ghế sau trong quốc hội, protagonists là nhân vật chính hay người ủng hộ.","extra":[{"en":"loyal customer base","vi":"tập khách hàng trung thành"},
{"en":"repeat business","vi":"khách quay lại"},
{"en":"word of mouth","vi":"truyền miệng"}]},
{"id":"q0045","unit":6,"stem":"A company introduces a higher-priced product with superior materials and additional services. It positions the product as ______.","options":["premium","substitute","standardized","volatile"],"answer":0,"explain":"Premium là cao cấp, giá cao hơn nhờ chất lượng và dịch vụ tốt hơn. Substitute là sản phẩm thay thế, standardized là tiêu chuẩn hóa, volatile là biến động.","extra":[{"en":"premium pricing","vi":"định giá cao cấp"},
{"en":"upmarket","vi":"phân khúc cao cấp"},
{"en":"value-added service","vi":"dịch vụ giá trị gia tăng"}]},
{"id":"q0046","unit":3,"stem":"A company has significant unpaid invoices from customers. These amounts are classified as ______.","options":["receivables","provisions","treasury shares","deferred taxes"],"answer":0,"explain":"Hóa đơn khách hàng chưa thanh toán là receivables (khoản phải thu). Provisions là dự phòng, treasury shares là cổ phiếu quỹ, deferred taxes là thuế hoãn lại.","extra":[{"en":"accounts receivable","vi":"các khoản phải thu"},
{"en":"overdue invoice","vi":"hóa đơn quá hạn"},
{"en":"credit control","vi":"kiểm soát tín dụng"}]},
{"id":"q0047","unit":6,"stem":"A firm's revenue fluctuates sharply because of unpredictable market conditions. Its revenue is described as ______.","options":["identical","volatile","embedded","standardized"],"answer":1,"explain":"Volatile là biến động mạnh, khó đoán. Identical là giống hệt, embedded là gắn chặt, standardized là tiêu chuẩn hóa, đều không mô tả doanh thu dao động.","extra":[{"en":"volatile market","vi":"thị trường biến động"},
{"en":"fluctuate","vi":"dao động"},
{"en":"economic downturn","vi":"suy thoái kinh tế"}]},
{"id":"q0048","unit":2,"stem":"A production manager uses performance ______ to compare actual output, defect rates and delivery times against targets.","options":["metrics","loopholes","securities","protagonists"],"answer":0,"explain":"Performance metrics là các chỉ số đo hiệu suất như sản lượng, tỷ lệ lỗi, thời gian giao hàng. Loopholes là kẽ hở, securities là chứng khoán, protagonists là nhân vật chính.","extra":[{"en":"key performance indicator","vi":"chỉ số đo lường hiệu quả chính"},
{"en":"benchmark","vi":"chuẩn đối sánh"},
{"en":"meet targets","vi":"đạt mục tiêu"}]},
{"id":"q0049","unit":2,"stem":"The company wants to improve its supply chain by ensuring that materials are available when needed. It must carefully manage its ______.","options":["inventory","equity","goodwill","legislation"],"answer":0,"explain":"Inventory (hàng tồn kho) cần được quản lý để nguyên liệu luôn sẵn sàng. Equity là vốn chủ, goodwill là lợi thế thương mại, legislation là luật pháp.","extra":[{"en":"inventory management","vi":"quản lý tồn kho"},
{"en":"replenish stock","vi":"bổ sung hàng"},
{"en":"stockout","vi":"hết hàng"}]},
{"id":"q0050","unit":6,"stem":"A company introduces a new version of a product after reviewing customer feedback and correcting its weaknesses. It plans to ______ the product.","options":["relaunch","default","decentralize","backdown"],"answer":0,"explain":"Relaunch là tái tung sản phẩm phiên bản mới sau khi sửa điểm yếu. Default là vỡ nợ, decentralize là phân quyền, backdown là nhượng bộ.","extra":[{"en":"product relaunch","vi":"tái ra mắt sản phẩm"},
{"en":"revamp","vi":"làm mới"},
{"en":"customer feedback","vi":"phản hồi khách hàng"}]},
{"id":"q0051","unit":1,"stem":"A furniture company manufactures a limited number of desks in groups, changing the design and materials between groups. Which method does it use?","options":["Continuous production","Batch production","Mass production","Unit production"],"answer":1,"explain":"Batch production là sản xuất theo nhóm, giữa các nhóm đổi thiết kế và vật liệu. Continuous và mass production dành cho sản phẩm giống nhau với khối lượng lớn, unit production là từng chiếc riêng lẻ.","extra":[{"en":"production batch","vi":"lô sản xuất"},
{"en":"small-scale production","vi":"sản xuất quy mô nhỏ"},
{"en":"customization","vi":"sự tùy biến"}]},
{"id":"q0052","unit":1,"stem":"The production supervisor noticed that workers were waiting for components from the previous stage. The delay has disrupted the entire ______.","options":["supply chain","production yield","linear workflow","financial backer"],"answer":2,"explain":"Delay khi công nhân chờ chi tiết từ công đoạn trước làm gián đoạn linear workflow (quy trình tuần tự từng bước). Supply chain là chuỗi cung ứng rộng hơn, yield là tỷ lệ thành phẩm, financial backer là nhà tài trợ vốn.","extra":[{"en":"sequential process","vi":"quy trình tuần tự"},
{"en":"workflow disruption","vi":"gián đoạn quy trình"},
{"en":"idle time","vi":"thời gian chờ nhàn rỗi"}],"needsReview":true},
{"id":"q0053","unit":3,"stem":"A company has enough cash to cover its short-term obligations and owns assets that can be converted into cash within a year. These assets are generally classified as ______.","options":["intangible assets","current assets","treasury shares","deferred taxes"],"answer":1,"explain":"Tài sản chuyển thành tiền trong vòng một năm là current assets (tài sản ngắn hạn). Intangible assets là tài sản vô hình, treasury shares là cổ phiếu quỹ, deferred taxes là thuế hoãn lại.","extra":[{"en":"liquid assets","vi":"tài sản thanh khoản"},
{"en":"working capital","vi":"vốn lưu động"},
{"en":"balance sheet","vi":"bảng cân đối kế toán"}]},
{"id":"q0054","unit":3,"stem":"An accountant investigates suspected fraud by examining financial records and collecting evidence for possible legal proceedings. This is known as ______.","options":["cost accounting","tax accounting","forensic accounting","managerial accounting"],"answer":2,"explain":"Forensic accounting là kế toán pháp y, điều tra gian lận và thu thập chứng cứ cho tố tụng. Cost accounting tính giá thành, tax accounting liên quan thuế, managerial accounting phục vụ quản lý nội bộ.","extra":[{"en":"forensic accountant","vi":"kế toán pháp y"},
{"en":"financial fraud","vi":"gian lận tài chính"},
{"en":"audit trail","vi":"dấu vết kiểm toán"}]},
{"id":"q0055","unit":2,"stem":"A manufacturer wants to reduce the amount of raw materials stored in its warehouse while ensuring that production is not interrupted. Which approach would best support this objective?","options":["Just-in-time manufacturing","Unit production","Continuous production","Mass production"],"answer":0,"explain":"Just-in-time giúp giảm lượng nguyên liệu tồn kho mà không làm gián đoạn sản xuất. Unit, continuous và mass production là các phương thức sản xuất, không nhằm giảm tồn kho.","extra":[{"en":"JIT inventory","vi":"tồn kho JIT"},
{"en":"lean production","vi":"sản xuất tinh gọn"},
{"en":"reduce waste","vi":"giảm lãng phí"}]},
{"id":"q0056","unit":4,"stem":"A company issues bonds to raise funds. Investors who purchase and hold these bonds are called ______.","options":["creditors","bondholders","financial backers","shareholders"],"answer":1,"explain":"Bondholders là người mua và giữ trái phiếu của công ty. Creditor là chủ nợ nói chung, financial backer là nhà tài trợ, shareholder là cổ đông chứ không phải người giữ trái phiếu.","extra":[{"en":"issue bonds","vi":"phát hành trái phiếu"},
{"en":"bond yield","vi":"lợi suất trái phiếu"},
{"en":"maturity date","vi":"ngày đáo hạn"}]},
{"id":"q0057","unit":2,"stem":"A business is unable to deliver products on time because one stage of its production process cannot handle the required volume. Managers need to address the ______.","options":["production yield","production bottleneck","performance metric","value added"],"answer":1,"explain":"Một khâu không xử lý được khối lượng cần thiết gây production bottleneck (nghẽn cổ chai). Production yield là tỷ lệ thành phẩm, performance metric là chỉ số đo lường, value added là giá trị gia tăng.","extra":[{"en":"on-time delivery","vi":"giao hàng đúng hạn"},
{"en":"production capacity","vi":"công suất sản xuất"},
{"en":"throughput","vi":"thông lượng"}]},
{"id":"q0058","unit":6,"stem":"A company has expanded into a new market but has not yet reached customers who could benefit from its products. It needs to increase its market ______.","options":["downtime","exposure","principal","provision"],"answer":1,"explain":"Market exposure là mức độ tiếp cận thị trường, khách hàng biết đến sản phẩm. Downtime là thời gian ngừng máy, principal là tiền gốc, provision là khoản dự phòng.","extra":[{"en":"brand exposure","vi":"mức độ nhận diện thương hiệu"},
{"en":"market penetration","vi":"thâm nhập thị trường"},
{"en":"reach new customers","vi":"tiếp cận khách hàng mới"}]},
{"id":"q0059","unit":6,"stem":"A retailer gives customers who purchase a new coffee machine a discount on compatible coffee capsules. This strategy encourages customers to buy products that ______ each other.","options":["falsify","complement","incur","decelerate"],"answer":1,"explain":"Complement là bổ trợ cho nhau, như máy pha cà phê và viên nén tương thích. Falsify là làm giả, incur là gánh chịu, decelerate là giảm tốc.","extra":[{"en":"complementary products","vi":"sản phẩm bổ sung"},
{"en":"substitute product","vi":"sản phẩm thay thế"},
{"en":"bundle pricing","vi":"giá trọn gói"}]},
{"id":"q0060","unit":1,"stem":"Before expanding production, managers compare expected demand with the available machinery, labor and factory space. This is part of ______.","options":["capacity planning","bookkeeping","short selling","creative accounting"],"answer":0,"explain":"Capacity planning là so sánh nhu cầu dự kiến với máy móc, nhân lực, mặt bằng sẵn có. Bookkeeping là ghi sổ, short selling là bán khống, creative accounting là kế toán sáng tạo gây hiểu lầm.","extra":[{"en":"production capacity","vi":"công suất sản xuất"},
{"en":"expand production","vi":"mở rộng sản xuất"},
{"en":"resource allocation","vi":"phân bổ nguồn lực"}]},
{"id":"q0061","unit":4,"stem":"A firm uses its own savings and revenue to finance its early development rather than relying on external investors. This approach is called ______.","options":["leverage","bootstrapping","acquisition","due diligence"],"answer":1,"explain":"Bootstrapping là tự tài trợ bằng tiền tiết kiệm và doanh thu của chính mình. Leverage là vay mượn, acquisition là thâu tóm, due diligence là thẩm định.","extra":[{"en":"self-funded","vi":"tự tài trợ"},
{"en":"seed funding","vi":"vốn khởi nghiệp ban đầu"},
{"en":"start-up capital","vi":"vốn khởi nghiệp"}]},
{"id":"q0062","unit":6,"stem":"A company's sales have increased rapidly, but its growth has started to slow and become stable. Its sales are beginning to ______.","options":["flatten out","falsify","backtrack","replenish"],"answer":0,"explain":"Flatten out là chững lại, ổn định sau khi tăng nhanh. Falsify là làm giả, backtrack là rút lại lập trường, replenish là bổ sung.","extra":[{"en":"level off","vi":"chững lại"},
{"en":"plateau","vi":"đạt đỉnh rồi ổn định"},
{"en":"rapid growth","vi":"tăng trưởng nhanh"}]},
{"id":"q0063","unit":3,"stem":"A business has an obligation to pay tax in a future period because of temporary differences in accounting and tax treatment. This may give rise to ______.","options":["goodwill","deferred tax","cash equivalents","receivables"],"answer":1,"explain":"Deferred tax là thuế hoãn lại, phát sinh do chênh lệch tạm thời giữa kế toán và thuế. Goodwill là lợi thế thương mại, cash equivalents là tương đương tiền, receivables là khoản phải thu.","extra":[{"en":"tax liability","vi":"nghĩa vụ thuế"},
{"en":"temporary difference","vi":"chênh lệch tạm thời"},
{"en":"tax accounting","vi":"kế toán thuế"}]},
{"id":"q0064","unit":2,"stem":"A manufacturer introduces regular inspections at every stage to ensure that products meet established standards. This is an important part of ______.","options":["quality assurance","inventory management","capacity planning","financial leverage"],"answer":0,"explain":"Quality assurance là kiểm tra định kỳ ở mọi khâu để đảm bảo đạt tiêu chuẩn. Inventory management là quản lý tồn kho, capacity planning là công suất, financial leverage là đòn bẩy tài chính.","extra":[{"en":"quality inspection","vi":"kiểm tra chất lượng"},
{"en":"quality standard","vi":"tiêu chuẩn chất lượng"},
{"en":"defect prevention","vi":"phòng ngừa lỗi"}]},
{"id":"q0065","unit":4,"stem":"A company sells a building and uses the proceeds to repay part of its outstanding debt. This action may help it reduce its financial ______.","options":["clientele","leverage","exposure","yield"],"answer":1,"explain":"Dùng tiền bán tòa nhà trả bớt nợ làm giảm leverage (mức độ vay nợ). Exposure là mức độ chịu rủi ro, clientele là tập khách hàng, yield là lợi suất, nên leverage sát nhất.","extra":[{"en":"debt-to-equity ratio","vi":"tỷ lệ nợ trên vốn chủ"},
{"en":"pay down debt","vi":"trả bớt nợ"},
{"en":"asset sale","vi":"bán tài sản"}],"needsReview":true},
{"id":"q0066","unit":4,"stem":"A bank agrees to lend money to a business only after reviewing its financial statements and assessing its ability to repay. The bank is acting as a ______.","options":["creditor","bondholder","backpacker","barista"],"answer":0,"explain":"Creditor là chủ nợ, bên cho vay tiền sau khi đánh giá khả năng trả nợ. Bondholder là người giữ trái phiếu, backpacker và barista không liên quan.","extra":[{"en":"creditworthiness","vi":"năng lực tín dụng"},
{"en":"credit assessment","vi":"đánh giá tín dụng"},
{"en":"lending criteria","vi":"tiêu chí cho vay"}]},
{"id":"q0067","unit":3,"stem":"A firm uses misleading financial reports to conceal the actual condition of its business. It may have attempted to ______ its accounts.","options":["enhance","falsify","replenish","align"],"answer":1,"explain":"Falsify là làm giả sổ sách để che giấu thực trạng. Enhance là nâng cao, replenish là bổ sung, align là căn chỉnh, đều có nghĩa tích cực hoặc trung tính.","extra":[{"en":"cook the books","vi":"làm giả sổ sách"},
{"en":"misleading statement","vi":"báo cáo gây hiểu lầm"},
{"en":"financial misstatement","vi":"sai lệch báo cáo tài chính"}]},
{"id":"q0068","unit":1,"stem":"A company has several departments that perform tasks one after another, with each stage depending on the completion of the previous one. This describes a ______.","options":["linear workflow","joint venture","cash cow","mutual fund"],"answer":0,"explain":"Linear workflow là quy trình tuần tự, mỗi bước phụ thuộc bước trước. Joint venture là liên doanh, cash cow là sản phẩm sinh lời, mutual fund là quỹ tương hỗ.","extra":[{"en":"workflow","vi":"quy trình làm việc"},
{"en":"parallel processing","vi":"xử lý song song"},
{"en":"handover","vi":"bàn giao công đoạn"}]},
{"id":"q0069","unit":6,"stem":"A government introduces a policy that removes certain restrictions on an industry to encourage competition. It decides to ______ the industry.","options":["decentralize","deregulate","downgrade","restructure"],"answer":1,"explain":"Deregulate là bãi bỏ quy định để khuyến khích cạnh tranh. Decentralize là phân quyền, downgrade là hạ cấp, restructure là tái cấu trúc doanh nghiệp.","extra":[{"en":"deregulation","vi":"sự bãi bỏ quy định"},
{"en":"free market","vi":"thị trường tự do"},
{"en":"barriers to entry","vi":"rào cản gia nhập"}]},
{"id":"q0070","unit":7,"stem":"A business is considering investing in a new technology, but the expected benefits and costs are uncertain. It should carefully assess the potential ______.","options":["risk tolerance","industrial emissions","life expectancy","consumer spending"],"answer":0,"explain":"Risk tolerance là mức chấp nhận rủi ro, cần đánh giá khi đầu tư vào công nghệ có lợi ích và chi phí không chắc chắn. Industrial emissions, life expectancy, consumer spending không liên quan đến rủi ro của dự án.","extra":[{"en":"risk assessment","vi":"đánh giá rủi ro"},
{"en":"cost-benefit analysis","vi":"phân tích chi phí lợi ích"},
{"en":"risk appetite","vi":"khẩu vị rủi ro"}],"needsReview":true},
{"id":"q0071","unit":3,"stem":"A company has received payment from customers but has not yet paid its suppliers. The amounts owed to suppliers are recorded as ______.","options":["receivables","liabilities","goodwill","cash equivalents"],"answer":1,"explain":"Nợ nhà cung cấp là liabilities (nợ phải trả). Receivables là khoản phải thu, goodwill là lợi thế thương mại, cash equivalents là tương đương tiền.","extra":[{"en":"accounts payable","vi":"các khoản phải trả"},
{"en":"trade credit","vi":"tín dụng thương mại"},
{"en":"payment terms","vi":"điều khoản thanh toán"}]},
{"id":"q0072","unit":3,"stem":"An enterprise owns a trademark, a patent and a valuable brand reputation. These items are examples of ______ assets.","options":["current","intangible","physical","liquid"],"answer":1,"explain":"Nhãn hiệu, bằng sáng chế và uy tín thương hiệu là tài sản vô hình (intangible). Current là ngắn hạn, physical là hữu hình, liquid là dễ chuyển thành tiền.","extra":[{"en":"patent","vi":"bằng sáng chế"},
{"en":"trademark","vi":"nhãn hiệu đã đăng ký"},
{"en":"goodwill","vi":"lợi thế thương mại"}]},
{"id":"q0073","unit":3,"stem":"A company's directors decide to distribute part of its accumulated profits to shareholders. The remaining undistributed profits are known as ______.","options":["retained earnings","loan principal","provisions","accounts receivable"],"answer":0,"explain":"Phần lợi nhuận chưa chia là retained earnings. Loan principal là gốc vay, provisions là dự phòng, accounts receivable là khoản phải thu.","extra":[{"en":"declare a dividend","vi":"công bố cổ tức"},
{"en":"profit distribution","vi":"phân phối lợi nhuận"},
{"en":"accumulated profit","vi":"lợi nhuận lũy kế"}]},
{"id":"q0074","unit":2,"stem":"A company buys a large quantity of raw materials because it expects prices to rise. However, the materials remain unused for several months. Which function should monitor and control these stocks?","options":["production scheduling","inventory management","forensic accounting","performance measurement"],"answer":1,"explain":"Inventory management là quản lý và kiểm soát hàng tồn kho. Production scheduling là lập lịch sản xuất, forensic accounting là điều tra gian lận, performance measurement là đo hiệu suất.","extra":[{"en":"stock control","vi":"kiểm soát hàng tồn"},
{"en":"overstocking","vi":"tồn kho quá mức"},
{"en":"warehouse costs","vi":"chi phí kho bãi"}]},
{"id":"q0075","unit":4,"stem":"A financial institution invests in a range of securities and uses sophisticated strategies to manage investment risks and seek returns. It may operate as a ______.","options":["hedge fund","mortgage loan","joint venture","treasury share"],"answer":0,"explain":"Hedge fund là quỹ phòng hộ dùng chiến lược phức tạp để quản lý rủi ro và tìm lợi nhuận. Mortgage loan là vay thế chấp, joint venture là liên doanh, treasury share là cổ phiếu quỹ.","extra":[{"en":"hedge against risk","vi":"phòng ngừa rủi ro"},
{"en":"institutional investor","vi":"nhà đầu tư tổ chức"},
{"en":"asset management","vi":"quản lý tài sản"}]},
{"id":"q0076","unit":4,"stem":"A company borrows money to purchase a house or commercial property, using that property as collateral. This type of borrowing is a ______.","options":["mutual fund","mortgage loan","derivative","bond issue"],"answer":1,"explain":"Mortgage loan là khoản vay mua bất động sản và dùng chính tài sản đó làm tài sản đảm bảo. Mutual fund là quỹ, derivative là phái sinh, bond issue là phát hành trái phiếu.","extra":[{"en":"mortgage repayments","vi":"các kỳ trả nợ thế chấp"},
{"en":"fixed-rate","vi":"lãi suất cố định"},
{"en":"property valuation","vi":"định giá bất động sản"}]},
{"id":"q0077","unit":2,"stem":"A business wants to determine whether its production process is generating enough usable products from the materials supplied. It should examine its ______.","options":["production yield","lead time","downtime","strategic vision"],"answer":0,"explain":"Production yield là tỷ lệ sản phẩm dùng được so với nguyên liệu đầu vào. Lead time là thời gian chờ, downtime là thời gian ngừng máy, strategic vision là tầm nhìn chiến lược.","extra":[{"en":"yield rate","vi":"tỷ lệ thành phẩm"},
{"en":"scrap rate","vi":"tỷ lệ phế phẩm"},
{"en":"material waste","vi":"lãng phí nguyên liệu"}]},
{"id":"q0078","unit":2,"stem":"A manufacturer has reduced the time between receiving an order and delivering the finished product. It has successfully shortened its ______.","options":["conversion","lead time","threshold","turnover"],"answer":1,"explain":"Lead time là khoảng thời gian từ khi nhận đơn đến khi giao hàng. Conversion, threshold và turnover không dùng để chỉ thời gian này.","extra":[{"en":"reduce lead time","vi":"rút ngắn thời gian chờ"},
{"en":"order fulfilment","vi":"thực hiện đơn hàng"},
{"en":"delivery schedule","vi":"lịch giao hàng"}]},
{"id":"q0079","unit":2,"stem":"A company is legally required to pay a supplier within 30 days. If it fails to meet this obligation, it may ______ a penalty or additional costs.","options":["incur","offset","align","cater"],"answer":0,"explain":"Incur là phải chịu (khoản phạt, chi phí) do vi phạm. Offset là bù đắp, align là căn chỉnh, cater là phục vụ, không đi với penalty theo nghĩa này.","extra":[{"en":"incur costs","vi":"phát sinh chi phí"},
{"en":"late payment fee","vi":"phí trả chậm"},
{"en":"contractual obligation","vi":"nghĩa vụ hợp đồng"}]},
{"id":"q0080","unit":4,"stem":"A business sells shares to investors to obtain capital without taking out a loan. It is using ______ financing.","options":["debt","equity","mortgage","derivative"],"answer":1,"explain":"Bán cổ phần để huy động vốn mà không vay là equity financing (huy động vốn cổ phần). Debt là nợ vay, mortgage là thế chấp, derivative là phái sinh.","extra":[{"en":"raise capital","vi":"huy động vốn"},
{"en":"issue shares","vi":"phát hành cổ phiếu"},
{"en":"debt financing","vi":"huy động vốn vay"}]},
{"id":"q0081","unit":4,"stem":"A company wants to protect its market share by purchasing a competitor. This business decision may result in a ______.","options":["take-over","backdown","backtrack","downgrade"],"answer":0,"explain":"Mua đối thủ để bảo vệ thị phần là take-over (thâu tóm). Backdown và backtrack là nhượng bộ hoặc rút lại lập trường, downgrade là hạ cấp.","extra":[{"en":"hostile bid","vi":"chào mua thù địch"},
{"en":"merger","vi":"sáp nhập"},
{"en":"market consolidation","vi":"hợp nhất thị trường"}]},
{"id":"q0082","unit":3,"stem":"A firm has a strong reputation, but its latest financial statements contain errors that could damage investors' trust. The firm needs to restore its ______.","options":["downtime","credibility","capacity","exposure"],"answer":1,"explain":"Báo cáo sai sót làm tổn hại niềm tin nên cần khôi phục credibility (uy tín). Downtime là thời gian ngừng máy, capacity là công suất, exposure là mức độ phơi nhiễm.","extra":[{"en":"restore trust","vi":"khôi phục niềm tin"},
{"en":"financial reporting","vi":"lập báo cáo tài chính"},
{"en":"restate accounts","vi":"điều chỉnh lại báo cáo"}]},
{"id":"q0083","unit":5,"stem":"A company introduces a new law requiring businesses to disclose their environmental impact. The law is an example of government ______.","options":["legislation","coalition","compromise","backbench"],"answer":0,"explain":"Legislation là luật do chính phủ ban hành, ví dụ luật buộc công bố tác động môi trường. Coalition là liên minh, compromise là thỏa hiệp, backbench là ghế sau.","extra":[{"en":"pass legislation","vi":"thông qua luật"},
{"en":"disclosure requirement","vi":"yêu cầu công bố thông tin"},
{"en":"environmental impact","vi":"tác động môi trường"}]},
{"id":"q0084","unit":5,"stem":"A company has been criticized for releasing excessive pollutants. It must reduce its ______ to meet environmental standards.","options":["cash equivalents","industrial emissions","retained earnings","interest rates"],"answer":1,"explain":"Industrial emissions là khí thải công nghiệp, thứ cần giảm để đạt chuẩn môi trường. Cash equivalents, retained earnings, interest rates là khái niệm tài chính, không liên quan đến ô nhiễm.","extra":[{"en":"carbon emissions","vi":"khí thải carbon"},
{"en":"pollution control","vi":"kiểm soát ô nhiễm"},
{"en":"carbon credits","vi":"tín chỉ carbon"}]},
{"id":"q0085","unit":5,"stem":"An environmental organization attempts to influence lawmakers to introduce stricter pollution controls. It is trying to ______ the government.","options":["lobby","replenish","restructure","relaunch"],"answer":0,"explain":"Lobby là vận động hành lang để tác động đến nhà làm luật. Replenish là bổ sung, restructure là tái cấu trúc, relaunch là tung lại.","extra":[{"en":"lobbying group","vi":"nhóm vận động hành lang"},
{"en":"pressure group","vi":"nhóm gây áp lực"},
{"en":"influence policy","vi":"tác động đến chính sách"}]},
{"id":"q0086","unit":5,"stem":"A company initially rejects a proposed agreement but later accepts some of its terms after negotiations. It has decided to ______.","options":["give ground","make up","let on","fend off"],"answer":0,"explain":"Give ground là nhượng bộ, chấp nhận một phần điều khoản sau thương lượng. Make up là bù đắp hoặc bịa, let on là tiết lộ, fend off là chống đỡ, không đúng nghĩa.","extra":[{"en":"reach a compromise","vi":"đạt được thỏa hiệp"},
{"en":"back down","vi":"lùi bước"},
{"en":"meet halfway","vi":"nhượng bộ nhau một nửa"}]},
{"id":"q0087","unit":6,"stem":"A business introduces a new training program to help employees adapt to changes in technology. The company wants to ______ its workforce.","options":["retrain","relocate","downgrade","deregulate"],"answer":0,"explain":"Retrain là đào tạo lại để nhân viên thích ứng với công nghệ mới. Relocate là di dời, downgrade là hạ cấp, deregulate là bãi bỏ quy định.","extra":[{"en":"reskill","vi":"đào tạo kỹ năng mới"},
{"en":"adapt to technology","vi":"thích ứng công nghệ"},
{"en":"staff development","vi":"phát triển nhân sự"}]},
{"id":"q0088","unit":6,"stem":"A company reduces the number of management layers and gives local branches more authority. It is seeking to become more ______.","options":["volatile","decentralized","identical","misleading"],"answer":1,"explain":"Giảm tầng quản lý và trao quyền cho chi nhánh nghĩa là doanh nghiệp trở nên decentralized (phân quyền). Volatile là biến động, identical là giống hệt, misleading là gây hiểu lầm.","extra":[{"en":"flatten the hierarchy","vi":"giảm tầng nấc quản lý"},
{"en":"local autonomy","vi":"quyền tự chủ địa phương"},
{"en":"management layers","vi":"các tầng quản lý"}]},
{"id":"q0089","unit":6,"stem":"A product is designed to meet a particular customer segment's needs rather than appeal to everyone. The company is trying to ______ to that segment.","options":["cater","incur","hover","falsify"],"answer":0,"explain":"Cater to nghĩa là đáp ứng nhu cầu của một nhóm khách hàng cụ thể (cater to a segment). Incur là phải gánh chịu (chi phí), hover là lơ lửng/dao động quanh một mức, falsify là làm giả – đều không hợp ngữ cảnh.","extra":[{"en":"niche market","vi":"thị trường ngách"},
{"en":"target audience","vi":"đối tượng mục tiêu"},
{"en":"tailor a product to","vi":"điều chỉnh sản phẩm cho phù hợp với"}]},
{"id":"q0090","unit":2,"stem":"A company's operating costs have increased, but its revenue has remained almost unchanged. Its profit margin may therefore ______.","options":["enhance","decelerate","flatten out","deteriorate"],"answer":3,"explain":"Chi phí tăng mà doanh thu gần như không đổi thì biên lợi nhuận sẽ xấu đi (deteriorate = suy giảm). Enhance là nâng cao, cải thiện nên ngược nghĩa; decelerate nói về tốc độ chậm lại chứ không nói về mức xấu đi; flatten out là đi ngang, không phản ánh việc bị thu hẹp.","extra":[{"en":"squeeze margins","vi":"bóp nghẹt biên lợi nhuận"},
{"en":"operating costs","vi":"chi phí hoạt động"},
{"en":"erode profits","vi":"làm xói mòn lợi nhuận"}]},
{"id":"q0091","unit":6,"stem":"A firm has an opportunity to enter a market that competitors have largely ignored. The market represents an ______ opportunity.","options":["outstanding","untapped","volatile","identical"],"answer":1,"explain":"Untapped nghĩa là chưa được khai thác – đúng với thị trường mà đối thủ bỏ qua. Outstanding là xuất sắc (hoặc chưa thanh toán), volatile là biến động mạnh, identical là giống hệt nên đều không hợp.","extra":[{"en":"untapped potential","vi":"tiềm năng chưa khai thác"},
{"en":"first-mover advantage","vi":"lợi thế người đi đầu"},
{"en":"gap in the market","vi":"khoảng trống thị trường"}]},
{"id":"q0092","unit":6,"stem":"A company offers a lower-priced alternative to a premium product. The new product is intended to act as a ______.","options":["substitute","derivative","security","provision"],"answer":0,"explain":"Substitute là sản phẩm thay thế, ví dụ hàng giá rẻ thay cho hàng cao cấp. Derivative là công cụ phái sinh tài chính, security là chứng khoán/sự bảo đảm, provision là khoản dự phòng – không phải loại sản phẩm.","extra":[{"en":"close substitute","vi":"sản phẩm thay thế gần"},
{"en":"budget range","vi":"dòng sản phẩm giá rẻ"},
{"en":"price elasticity","vi":"độ co giãn của giá"}]},
{"id":"q0093","unit":3,"stem":"A company records the purchase and sale of goods in chronological order, maintaining accurate financial records. This activity is called ______.","options":["auditing","bookkeeping","short selling","due diligence"],"answer":1,"explain":"Bookkeeping là việc ghi chép các giao dịch mua bán theo thứ tự thời gian để giữ sổ sách chính xác. Auditing là kiểm toán (kiểm tra sổ sách), short selling là bán khống, due diligence là thẩm định trước giao dịch.","extra":[{"en":"double-entry bookkeeping","vi":"ghi sổ kép"},
{"en":"general ledger","vi":"sổ cái"},
{"en":"financial records","vi":"hồ sơ tài chính"}]},
{"id":"q0094","unit":3,"stem":"A company has a large amount of money in its bank account and short-term deposits that can be quickly converted into cash. These are ______.","options":["cash equivalents","receivables","provisions","treasury shares"],"answer":0,"explain":"Cash equivalents là tiền gửi ngân hàng và các khoản đầu tư ngắn hạn dễ quy đổi thành tiền mặt. Receivables là khoản phải thu, provisions là khoản dự phòng, treasury shares là cổ phiếu quỹ – không phải là tiền hay tương đương tiền.","extra":[{"en":"liquid assets","vi":"tài sản có tính thanh khoản cao"},
{"en":"short-term deposit","vi":"tiền gửi ngắn hạn"},
{"en":"cash on hand","vi":"tiền mặt hiện có"}]},
{"id":"q0095","unit":6,"stem":"A business wants to improve the way its employees' tasks and responsibilities contribute to its overall strategic objectives. It needs to ______ individual activities with its strategy.","options":["incur","align","falsify","hover"],"answer":1,"explain":"Align with nghĩa là làm cho phù hợp, thống nhất với (chiến lược). Incur là gánh chịu chi phí, falsify là làm giả, hover là lơ lửng – không có nghĩa căn chỉnh mục tiêu.","extra":[{"en":"strategic alignment","vi":"sự thống nhất chiến lược"},
{"en":"corporate objectives","vi":"mục tiêu của công ty"},
{"en":"be in line with","vi":"phù hợp với"}]},
{"id":"q0096","unit":5,"stem":"A company has a product that consistently generates more revenue than its operating costs and supports other business activities. The product is a ______.","options":["cash cow","production bottleneck","mortgage loan","financial liability"],"answer":0,"explain":"Cash cow là sản phẩm/mảng kinh doanh luôn tạo ra nhiều tiền hơn chi phí và nuôi các hoạt động khác. Bottleneck là điểm nghẽn sản xuất, mortgage loan là khoản vay thế chấp, liability là nợ phải trả – đều không tạo lợi nhuận ổn định.","extra":[{"en":"star product","vi":"sản phẩm ngôi sao"},
{"en":"market share","vi":"thị phần"},
{"en":"steady revenue stream","vi":"nguồn doanh thu ổn định"}]},
{"id":"q0097","unit":2,"stem":"A company is considering whether to replace an old production system. Managers compare actual costs, output and defect rates against targets. This is an example of ______.","options":["performance measurement","short selling","creative accounting","waste disposal"],"answer":0,"explain":"So sánh chi phí, sản lượng và tỷ lệ lỗi thực tế với mục tiêu là đo lường hiệu suất (performance measurement). Short selling là bán khống, creative accounting là kế toán sáng tạo (làm đẹp số liệu), waste disposal là xử lý chất thải – đều không liên quan.","extra":[{"en":"key performance indicator (KPI)","vi":"chỉ số đánh giá hiệu suất chính"},
{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"benchmark against","vi":"so sánh với chuẩn"}]},
{"id":"q0098","unit":6,"stem":"A business has grown quickly, but its current organizational structure is no longer suitable. Managers decide to review the structure and evaluate possible changes. They need to ______ the existing arrangement.","options":["reassess","replenish","impose","backtrack"],"answer":0,"explain":"Reassess nghĩa là đánh giá lại cấu trúc hiện có. Replenish là bổ sung hàng, impose là áp đặt, backtrack là rút lại/quay lui – không hợp với việc xem xét lại cơ cấu tổ chức.","extra":[{"en":"organizational structure","vi":"cơ cấu tổ chức"},
{"en":"review the options","vi":"xem xét các phương án"},
{"en":"flatten the hierarchy","vi":"giảm bớt cấp bậc quản lý"}]},
{"id":"q0099","unit":4,"stem":"An investor sells borrowed shares in the hope of buying them back later at a lower price. This investment strategy is called ______.","options":["leverage","short selling","bootstrapping","cross-promotion"],"answer":1,"explain":"Short selling là bán cổ phiếu vay mượn, hy vọng mua lại sau với giá thấp hơn. Leverage là dùng đòn bẩy vốn vay, bootstrapping là tự xoay xở vốn không gọi vốn ngoài, cross-promotion là chéo quảng bá sản phẩm.","extra":[{"en":"bearish market","vi":"thị trường giá xuống"},
{"en":"margin call","vi":"yêu cầu bổ sung ký quỹ"},
{"en":"go long","vi":"mua vào dài hạn"}]},
{"id":"q0100","unit":2,"stem":"A company wants to increase the amount of materials available in its warehouse after stocks have fallen below the required level. It must ______ its inventory.","options":["replenish","falsify","decelerate","downgrade"],"answer":0,"explain":"Replenish là bổ sung lại hàng tồn kho khi đã xuống dưới mức cần thiết. Falsify là làm giả, decelerate là giảm tốc, downgrade là hạ cấp – không làm tăng lượng hàng.","extra":[{"en":"reorder level","vi":"mức đặt hàng lại"},
{"en":"stock-out","vi":"tình trạng hết hàng"},
{"en":"safety stock","vi":"hàng tồn kho an toàn"}]},
{"id":"q0101","unit":1,"stem":"A manufacturer produces customized laboratory equipment, with each item designed and assembled separately according to a specific order.","options":["Batch production","Mass production","Unit production","Continuous production"],"answer":2,"explain":"Mỗi sản phẩm được thiết kế và lắp ráp riêng theo đơn đặt hàng là unit production (sản xuất đơn chiếc). Batch production là sản xuất theo lô, mass production là sản xuất hàng loạt, continuous production là sản xuất liên tục không ngừng.","extra":[{"en":"made to order","vi":"sản xuất theo đơn đặt hàng"},
{"en":"one-off product","vi":"sản phẩm đơn chiếc"},
{"en":"bespoke","vi":"đặt làm riêng"}]},
{"id":"q0102","unit":1,"stem":"The company has experienced repeated interruptions because its machines have not been serviced regularly. It needs to improve its ______.","options":["machine maintenance","capacity planning","inventory management","performance measurement"],"answer":0,"explain":"Máy hỏng/dừng lặp lại do không được bảo dưỡng định kỳ nên cần cải thiện machine maintenance (bảo trì máy móc). Capacity planning là hoạch định công suất, inventory management là quản lý tồn kho, performance measurement là đo lường hiệu suất – không giải quyết nguyên nhân hỏng máy.","extra":[{"en":"preventive maintenance","vi":"bảo trì phòng ngừa"},
{"en":"breakdown","vi":"sự cố hỏng máy"},
{"en":"service schedule","vi":"lịch bảo dưỡng"}]},
{"id":"q0103","unit":3,"stem":"A retailer allows customers to pay 30 days after receiving their purchases. The outstanding amounts are recorded as ______.","options":["liabilities","provisions","cash equivalents","receivables"],"answer":3,"explain":"Số tiền khách hàng nợ sau khi nhận hàng được ghi là receivables (khoản phải thu). Liabilities là nợ phải trả của công ty, provisions là khoản dự phòng, cash equivalents là tương đương tiền.","extra":[{"en":"accounts receivable","vi":"các khoản phải thu"},
{"en":"credit terms","vi":"điều khoản tín dụng"},
{"en":"bad debt","vi":"nợ xấu"}]},
{"id":"q0104","unit":4,"stem":"A company wants to determine whether its investment in new machinery has generated sufficient financial benefits compared with its original cost. Which metric should it examine?","options":["Interest rates","Return on investment","Loan principal","Production yield"],"answer":1,"explain":"Return on investment (ROI) so sánh lợi ích tài chính thu được với chi phí đầu tư ban đầu. Interest rates là lãi suất, loan principal là tiền gốc khoản vay, production yield là năng suất/sản lượng đạt chuẩn – không đo hiệu quả khoản đầu tư.","extra":[{"en":"payback period","vi":"thời gian hoàn vốn"},
{"en":"capital expenditure","vi":"chi tiêu vốn"},
{"en":"cost-benefit analysis","vi":"phân tích chi phí – lợi ích"}]},
{"id":"q0105","unit":1,"stem":"A factory organizes production so that each stage is completed before the next stage begins. This arrangement is known as a ______.","options":["linear workflow","joint venture","supply chain","cross-promotion"],"answer":0,"explain":"Mỗi giai đoạn hoàn thành rồi mới sang giai đoạn kế tiếp là quy trình tuyến tính (linear workflow). Joint venture là liên doanh, supply chain là chuỗi cung ứng, cross-promotion là quảng bá chéo – không mô tả cách tổ chức công đoạn sản xuất.","extra":[{"en":"production sequence","vi":"trình tự sản xuất"},
{"en":"stage of production","vi":"công đoạn sản xuất"},
{"en":"workflow","vi":"quy trình làm việc"}]},
{"id":"q0106","unit":4,"stem":"A business uses borrowed capital to finance an expansion, increasing both its potential returns and its financial exposure. This is an example of ______.","options":["bootstrapping","short selling","leverage","bookkeeping"],"answer":2,"explain":"Dùng vốn vay để mở rộng làm tăng cả lợi nhuận tiềm năng lẫn rủi ro tài chính là leverage (đòn bẩy tài chính). Bootstrapping là tự lực không vay vốn ngoài, short selling là bán khống, bookkeeping là ghi sổ.","extra":[{"en":"debt-to-equity ratio","vi":"tỷ lệ nợ trên vốn chủ sở hữu"},
{"en":"highly leveraged","vi":"vay nợ nhiều"},
{"en":"financial exposure","vi":"mức độ rủi ro tài chính"}]},
{"id":"q0107","unit":4,"stem":"A company purchases another business after reviewing its assets, contracts, debts and legal risks. The review conducted before the transaction is called ______.","options":["forensic accounting","due diligence","quality assurance","capacity planning"],"answer":1,"explain":"Việc rà soát tài sản, hợp đồng, nợ và rủi ro pháp lý trước khi mua lại doanh nghiệp là due diligence (thẩm định). Forensic accounting là kế toán điều tra gian lận, quality assurance là đảm bảo chất lượng, capacity planning là hoạch định công suất.","extra":[{"en":"carry out due diligence","vi":"tiến hành thẩm định"},
{"en":"merger and acquisition (M&A)","vi":"mua bán và sáp nhập"},
{"en":"hostile take-over","vi":"thâu tóm thù địch"}]},
{"id":"q0108","unit":2,"stem":"A manufacturer has enough orders to keep its production line operating, but one particular stage cannot process items quickly enough. This stage is a ______.","options":["production yield","performance metric","value-added activity","production bottleneck"],"answer":3,"explain":"Công đoạn không xử lý kịp khiến cả dây chuyền chậm lại là production bottleneck (nút thắt cổ chai). Production yield là sản lượng đạt chuẩn, performance metric là chỉ số hiệu suất, value-added activity là hoạt động tạo thêm giá trị.","extra":[{"en":"throughput","vi":"thông lượng sản xuất"},
{"en":"remove a bottleneck","vi":"loại bỏ điểm nghẽn"},
{"en":"idle capacity","vi":"công suất nhàn rỗi"}]},
{"id":"q0109","unit":5,"stem":"A government introduces new rules that require factories to reduce the pollutants released during manufacturing. These pollutants are known as ______.","options":["industrial emissions","cash equivalents","carbon credits","consumer spending"],"answer":0,"explain":"Chất ô nhiễm thải ra trong sản xuất gọi là industrial emissions (khí thải công nghiệp). Cash equivalents là tương đương tiền, carbon credits là tín chỉ carbon (quyền phát thải), consumer spending là chi tiêu tiêu dùng.","extra":[{"en":"environmental regulation","vi":"quy định về môi trường"},
{"en":"cut emissions","vi":"cắt giảm khí thải"},
{"en":"comply with standards","vi":"tuân thủ tiêu chuẩn"}]},
{"id":"q0110","unit":6,"stem":"A company decides to transfer authority from its central office to regional branches so that local managers can make more decisions. It intends to ______ its operations.","options":["restructure","decentralize","downgrade","relaunch"],"answer":1,"explain":"Chuyển quyền quyết định từ trụ sở về các chi nhánh khu vực là decentralize (phân quyền). Restructure là tái cơ cấu nói chung, downgrade là hạ cấp, relaunch là ra mắt lại sản phẩm – không nói rõ việc phân quyền.","extra":[{"en":"delegate authority","vi":"ủy quyền"},
{"en":"head office","vi":"trụ sở chính"},
{"en":"regional branch","vi":"chi nhánh khu vực"}]},
{"id":"q0111","unit":3,"stem":"A business has accumulated profits that have not been distributed to shareholders. These profits are classified as ______.","options":["receivables","deferred taxes","retained earnings","treasury shares"],"answer":2,"explain":"Lợi nhuận tích lũy chưa chia cho cổ đông là retained earnings (lợi nhuận giữ lại). Receivables là khoản phải thu, deferred taxes là thuế hoãn lại, treasury shares là cổ phiếu quỹ do công ty mua lại.","extra":[{"en":"dividend payout","vi":"việc chi trả cổ tức"},
{"en":"reinvest profits","vi":"tái đầu tư lợi nhuận"},
{"en":"shareholders' equity","vi":"vốn chủ sở hữu"}]},
{"id":"q0112","unit":4,"stem":"A bank lends money to a customer to purchase a house, using the property as collateral. This arrangement is a ______.","options":["mutual fund","derivative","joint venture","mortgage loan"],"answer":3,"explain":"Khoản vay mua nhà có tài sản thế chấp là mortgage loan (vay thế chấp). Mutual fund là quỹ tương hỗ, derivative là công cụ phái sinh, joint venture là liên doanh – không phải khoản vay.","extra":[{"en":"collateral","vi":"tài sản thế chấp"},
{"en":"fixed-rate mortgage","vi":"vay thế chấp lãi suất cố định"},
{"en":"foreclose on a property","vi":"phát mại tài sản thế chấp"}]},
{"id":"q0113","unit":3,"stem":"A company uses a registered symbol to distinguish its products from those of competitors. The symbol is protected by a ______.","options":["trademark","patent","provision","liability"],"answer":0,"explain":"Biểu tượng đã đăng ký dùng để phân biệt sản phẩm với đối thủ được bảo hộ bởi trademark (nhãn hiệu). Patent bảo hộ sáng chế, provision là khoản dự phòng, liability là nợ phải trả.","extra":[{"en":"registered trademark","vi":"nhãn hiệu đã đăng ký"},
{"en":"intellectual property","vi":"sở hữu trí tuệ"},
{"en":"brand identity","vi":"nhận diện thương hiệu"}]},
{"id":"q0114","unit":2,"stem":"A firm introduces a system in which materials arrive at the factory only when they are needed for production. This approach is associated with ______.","options":["mass production","Just-in-time manufacturing","unit production","continuous production"],"answer":1,"explain":"Nguyên liệu chỉ đến nhà máy khi cần dùng là đặc trưng của Just-in-time (JIT). Mass, unit và continuous production chỉ mô tả quy mô/kiểu sản xuất, không liên quan đến thời điểm nhận nguyên liệu.","extra":[{"en":"minimize inventory","vi":"giảm thiểu hàng tồn kho"},
{"en":"just-in-time delivery","vi":"giao hàng đúng lúc"},
{"en":"lean manufacturing","vi":"sản xuất tinh gọn"}]},
{"id":"q0115","unit":4,"stem":"A company has failed to make the repayments required under its loan agreement. It is considered to be in ______.","options":["leverage","acquisition","default","funding"],"answer":2,"explain":"Không trả được các khoản theo hợp đồng vay là rơi vào tình trạng default (vỡ nợ). Leverage là đòn bẩy tài chính, acquisition là mua lại doanh nghiệp, funding là việc cấp vốn.","extra":[{"en":"default on a loan","vi":"không trả được khoản vay"},
{"en":"default risk","vi":"rủi ro vỡ nợ"},
{"en":"credit rating","vi":"xếp hạng tín nhiệm"}]},
{"id":"q0116","unit":4,"stem":"A business sells a portion of its ownership to investors in order to raise capital without taking out a loan. This is known as ______ financing.","options":["debt","mortgage","derivative","equity"],"answer":3,"explain":"Bán một phần quyền sở hữu cho nhà đầu tư để huy động vốn mà không vay là equity financing (huy động vốn cổ phần). Debt financing là vay nợ, mortgage là vay thế chấp, derivative là phái sinh.","extra":[{"en":"issue new shares","vi":"phát hành cổ phiếu mới"},
{"en":"venture capital","vi":"vốn đầu tư mạo hiểm"},
{"en":"dilute ownership","vi":"pha loãng quyền sở hữu"}]},
{"id":"q0117","unit":3,"stem":"A company is suspected of manipulating its accounts to conceal fraudulent transactions. Specialists are brought in to investigate the financial evidence. They are performing ______.","options":["forensic accounting","cost accounting","tax accounting","bookkeeping"],"answer":0,"explain":"Điều tra bằng chứng tài chính để phát hiện gian lận là forensic accounting (kế toán pháp y). Cost accounting là kế toán chi phí, tax accounting là kế toán thuế, bookkeeping chỉ là ghi sổ thông thường.","extra":[{"en":"financial fraud","vi":"gian lận tài chính"},
{"en":"audit trail","vi":"dấu vết kiểm toán"},
{"en":"cook the books","vi":"làm giả sổ sách"}]},
{"id":"q0118","unit":5,"stem":"A company has a product that generates stable and substantial profits, helping finance other activities. The product is commonly described as a ______.","options":["financial backer","cash cow","production bottleneck","mutual fund"],"answer":1,"explain":"Sản phẩm tạo lợi nhuận ổn định, lớn và nuôi các hoạt động khác là cash cow. Financial backer là nhà tài trợ vốn, production bottleneck là điểm nghẽn sản xuất, mutual fund là quỹ tương hỗ.","extra":[{"en":"profit centre","vi":"trung tâm lợi nhuận"},
{"en":"mature product","vi":"sản phẩm ở giai đoạn trưởng thành"},
{"en":"fund other projects","vi":"tài trợ cho các dự án khác"}]},
{"id":"q0119","unit":2,"stem":"The manager identifies the exact point at which defective products begin to appear on the production line. The manager attempts to ______ the source of the problem.","options":["enhance","replenish","pinpoint","multiply"],"answer":2,"explain":"Pinpoint nghĩa là xác định chính xác (nguồn gốc vấn đề). Enhance là nâng cao, replenish là bổ sung, multiply là nhân lên – không có nghĩa xác định đúng điểm lỗi.","extra":[{"en":"root cause analysis","vi":"phân tích nguyên nhân gốc rễ"},
{"en":"defective product","vi":"sản phẩm lỗi"},
{"en":"troubleshoot","vi":"khắc phục sự cố"}]},
{"id":"q0120","unit":6,"stem":"A company introduces a high-end service package with exclusive features and additional customer support. It positions the package as a ______ offering.","options":["standardized","identical","substitute","premium"],"answer":3,"explain":"Gói dịch vụ cao cấp với tính năng độc quyền và hỗ trợ thêm được định vị là premium offering. Standardized là tiêu chuẩn hóa, identical là giống hệt, substitute là sản phẩm thay thế – đều không thể hiện phân khúc cao cấp.","extra":[{"en":"premium pricing","vi":"định giá cao cấp"},
{"en":"upmarket","vi":"phân khúc cao cấp"},
{"en":"value proposition","vi":"đề xuất giá trị"}]},
{"id":"q0121","unit":4,"stem":"An investor purchases shares in a company and becomes entitled to a portion of its ownership. The investor has acquired an ownership ______.","options":["stake","security","principal","liability"],"answer":0,"explain":"Ownership stake là phần sở hữu (cổ phần) trong công ty. Security là chứng khoán nói chung hoặc sự bảo đảm, principal là tiền gốc, liability là nợ phải trả – không đi với ownership theo nghĩa này.","extra":[{"en":"controlling stake","vi":"cổ phần chi phối"},
{"en":"minority shareholder","vi":"cổ đông thiểu số"},
{"en":"hold a stake in","vi":"nắm giữ cổ phần trong"}]},
{"id":"q0122","unit":3,"stem":"A business records the value of a probable future obligation that can be reasonably estimated. This amount is recognized as a ______.","options":["receivable","provision","cash equivalent","trademark"],"answer":1,"explain":"Khoản ghi nhận cho nghĩa vụ có thể xảy ra trong tương lai và ước tính được là provision (dự phòng). Receivable là khoản phải thu, cash equivalent là tương đương tiền, trademark là nhãn hiệu.","extra":[{"en":"make a provision for","vi":"trích lập dự phòng cho"},
{"en":"contingent liability","vi":"nợ tiềm tàng"},
{"en":"bad debt provision","vi":"dự phòng nợ xấu"}]},
{"id":"q0123","unit":2,"stem":"A manufacturer wants to assess how much usable output it obtains from the materials entering its production process. It should measure its ______.","options":["downtime","lead time","production yield","line efficiency"],"answer":2,"explain":"Production yield là tỷ lệ sản phẩm dùng được thu về từ nguyên liệu đầu vào. Downtime là thời gian ngừng máy, lead time là thời gian từ đặt hàng đến giao, line efficiency là hiệu suất dây chuyền (không đo đầu ra so với nguyên liệu).","extra":[{"en":"scrap rate","vi":"tỷ lệ phế phẩm"},
{"en":"raw materials","vi":"nguyên liệu thô"},
{"en":"waste reduction","vi":"giảm lãng phí"}]},
{"id":"q0124","unit":4,"stem":"A company sells shares that it has borrowed, expecting to repurchase them later at a lower price. This strategy is called ______.","options":["leverage","bootstrapping","acquisition","short selling"],"answer":3,"explain":"Bán cổ phiếu vay mượn rồi mua lại sau với giá thấp hơn là short selling (bán khống). Leverage là đòn bẩy vay nợ, bootstrapping là tự xoay vốn, acquisition là mua lại doanh nghiệp.","extra":[{"en":"bearish bet","vi":"cược giá giảm"},
{"en":"short squeeze","vi":"bóp ngược lệnh bán khống"},
{"en":"cover a short position","vi":"đóng vị thế bán khống"}]},
{"id":"q0125","unit":6,"stem":"A business discovers that its existing products do not meet the needs of a group of potential customers. This group represents an ______ market.","options":["untapped","volatile","identical","outstanding"],"answer":0,"explain":"Nhóm khách hàng tiềm năng chưa được sản phẩm hiện có đáp ứng là thị trường untapped (chưa khai thác). Volatile là biến động mạnh, identical là giống hệt, outstanding là xuất sắc/chưa trả.","extra":[{"en":"market research","vi":"nghiên cứu thị trường"},
{"en":"emerging market","vi":"thị trường mới nổi"},
{"en":"customer needs","vi":"nhu cầu khách hàng"}]},
{"id":"q0126","unit":3,"stem":"A company must pay its suppliers for raw materials already delivered. These unpaid obligations are classified as ______.","options":["receivables","liabilities","goodwill","equity"],"answer":1,"explain":"Khoản công ty còn phải trả cho nhà cung cấp là liabilities (nợ phải trả). Receivables là khoản phải thu (ngược chiều), goodwill là lợi thế thương mại, equity là vốn chủ sở hữu.","extra":[{"en":"accounts payable","vi":"các khoản phải trả"},
{"en":"current liabilities","vi":"nợ ngắn hạn"},
{"en":"balance sheet","vi":"bảng cân đối kế toán"}]},
{"id":"q0127","unit":2,"stem":"A company introduces a new system to monitor defect rates, delivery times and employee productivity against established targets. This is an example of ______.","options":["creative accounting","inventory management","performance measurement","short selling"],"answer":2,"explain":"Theo dõi tỷ lệ lỗi, thời gian giao hàng và năng suất so với mục tiêu là performance measurement (đo lường hiệu suất). Creative accounting là làm đẹp số liệu kế toán, inventory management là quản lý tồn kho, short selling là bán khống.","extra":[{"en":"performance target","vi":"mục tiêu hiệu suất"},
{"en":"on-time delivery","vi":"giao hàng đúng hạn"},
{"en":"productivity gains","vi":"mức tăng năng suất"}]},
{"id":"q0128","unit":6,"stem":"An organization closes several unprofitable divisions and reorganizes its departments to improve efficiency. It decides to ______ its operations.","options":["upgrade","replenish","relocate","restructure"],"answer":3,"explain":"Đóng các bộ phận thua lỗ và sắp xếp lại phòng ban để tăng hiệu quả là restructure (tái cơ cấu). Upgrade là nâng cấp, replenish là bổ sung hàng, relocate là chuyển địa điểm – không nói về tổ chức lại bộ máy.","extra":[{"en":"streamline operations","vi":"tinh giản hoạt động"},
{"en":"cost-cutting","vi":"cắt giảm chi phí"},
{"en":"divest a division","vi":"thoái vốn khỏi một bộ phận"}]},
{"id":"q0129","unit":6,"stem":"A firm wants to attract customers from another business by promoting complementary products to both customer groups. It uses ______.","options":["cross-promotion","short selling","forensic accounting","capacity planning"],"answer":0,"explain":"Quảng bá các sản phẩm bổ trợ cho cả hai nhóm khách hàng là cross-promotion (quảng bá chéo). Short selling là bán khống, forensic accounting là kế toán pháp y, capacity planning là hoạch định công suất.","extra":[{"en":"complementary products","vi":"sản phẩm bổ trợ"},
{"en":"joint marketing campaign","vi":"chiến dịch tiếp thị chung"},
{"en":"customer base","vi":"tệp khách hàng"}]},
{"id":"q0130","unit":4,"stem":"A company borrows money and must repay the original amount together with interest. The original amount borrowed is the loan ______.","options":["security","principal","leverage","funding"],"answer":1,"explain":"Số tiền gốc đã vay (chưa tính lãi) là loan principal. Security là tài sản bảo đảm, leverage là đòn bẩy tài chính, funding là nguồn vốn nói chung.","extra":[{"en":"repayment schedule","vi":"lịch trả nợ"},
{"en":"outstanding balance","vi":"dư nợ còn lại"},
{"en":"accrued interest","vi":"lãi tích lũy"}]},
{"id":"q0131","unit":2,"stem":"A firm keeps too many materials in storage, increasing warehouse expenses and the risk of waste. Which function should improve its control of stock?","options":["production scheduling","quality assurance","inventory management","financial accounting"],"answer":2,"explain":"Tồn kho quá nhiều làm tăng chi phí kho và rủi ro lãng phí, vì vậy cần cải thiện inventory management (quản lý tồn kho). Production scheduling là lập lịch sản xuất, quality assurance là đảm bảo chất lượng, financial accounting là kế toán tài chính.","extra":[{"en":"excess stock","vi":"hàng tồn dư thừa"},
{"en":"stock turnover","vi":"vòng quay hàng tồn kho"},
{"en":"warehousing costs","vi":"chi phí kho bãi"}]},
{"id":"q0132","unit":3,"stem":"A company has developed a new invention and obtains exclusive legal rights to produce or sell it. It has been granted a ______.","options":["trademark","goodwill","security","patent"],"answer":3,"explain":"Quyền pháp lý độc quyền sản xuất hoặc bán một phát minh được cấp bằng patent (bằng sáng chế). Trademark bảo hộ nhãn hiệu, goodwill là lợi thế thương mại, security là chứng khoán/bảo đảm.","extra":[{"en":"file a patent","vi":"nộp đơn xin cấp bằng sáng chế"},
{"en":"patent infringement","vi":"vi phạm bằng sáng chế"},
{"en":"licensing agreement","vi":"hợp đồng cấp phép"}]},
{"id":"q0133","unit":6,"stem":"A government removes certain restrictions that previously limited competition in an industry. This process is known as ______.","options":["deregulation","decentralization","restructuring","downsize"],"answer":0,"explain":"Gỡ bỏ các hạn chế cạnh tranh trong một ngành là deregulation (nới lỏng/bãi bỏ quy định). Decentralization là phân quyền, restructuring là tái cơ cấu, downsize là thu hẹp quy mô – không nói đến việc gỡ bỏ quy định của chính phủ.","extra":[{"en":"liberalise the market","vi":"tự do hóa thị trường"},
{"en":"red tape","vi":"thủ tục hành chính rườm rà"},
{"en":"state-owned enterprise","vi":"doanh nghiệp nhà nước"}]},
{"id":"q0134","unit":4,"stem":"A company is unable to meet its financial obligations because it has borrowed more than it can reasonably repay. Its excessive use of ______ has increased its financial risk.","options":["cash equivalents","leverage","receivables","retained earnings"],"answer":1,"explain":"Vay quá nhiều so với khả năng trả làm tăng rủi ro tài chính, tức là lạm dụng leverage (đòn bẩy). Cash equivalents là tương đương tiền, receivables là khoản phải thu, retained earnings là lợi nhuận giữ lại – đều không làm tăng rủi ro nợ.","extra":[{"en":"overleveraged","vi":"vay nợ quá mức"},
{"en":"debt burden","vi":"gánh nặng nợ"},
{"en":"insolvency","vi":"mất khả năng thanh toán"}]},
{"id":"q0135","unit":5,"stem":"A business wants to compensate for the additional expenses caused by higher raw-material prices. It may increase revenue elsewhere to ______ these costs.","options":["impose","incur","offset","falsify"],"answer":2,"explain":"Offset costs nghĩa là bù đắp chi phí bằng nguồn khác. Impose là áp đặt, incur là phải chịu (chi phí), falsify là làm giả – không có nghĩa bù đắp.","extra":[{"en":"offset losses","vi":"bù đắp khoản lỗ"},
{"en":"pass on costs to customers","vi":"chuyển chi phí sang khách hàng"},
{"en":"recoup costs","vi":"thu hồi chi phí"}]},
{"id":"q0136","unit":6,"stem":"A company introduces a revised version of an existing product after conducting market research and making substantial improvements. It plans to ______ the product.","options":["downgrade","decentralize","backtrack","relaunch"],"answer":3,"explain":"Ra mắt lại phiên bản cải tiến của sản phẩm sẵn có là relaunch. Downgrade là hạ cấp, decentralize là phân quyền, backtrack là rút lại lập trường – không dùng cho sản phẩm.","extra":[{"en":"product lifecycle","vi":"vòng đời sản phẩm"},
{"en":"rebrand","vi":"đổi thương hiệu"},
{"en":"revamp","vi":"làm mới, cải tiến"}]},
{"id":"q0137","unit":5,"stem":"A business is legally permitted to receive a government grant because it meets all the specified requirements. It is ______ the grant.","options":["eligible for","opposed to","dismayed by","embedded in"],"answer":0,"explain":"Be eligible for nghĩa là đủ điều kiện nhận (khoản trợ cấp). Opposed to là phản đối, dismayed by là thất vọng, embedded in là gắn chặt vào – không hợp ngữ cảnh.","extra":[{"en":"eligibility criteria","vi":"tiêu chí đủ điều kiện"},
{"en":"government subsidy","vi":"trợ cấp của chính phủ"},
{"en":"apply for a grant","vi":"xin cấp tài trợ"}]},
{"id":"q0138","unit":4,"stem":"A financial institution pools money from many investors and invests it in a diversified portfolio of securities. It operates a ______.","options":["hedge fund","mutual fund","mortgage loan","joint venture"],"answer":1,"explain":"Gom tiền của nhiều nhà đầu tư vào danh mục đa dạng là mutual fund (quỹ tương hỗ). Hedge fund dành cho nhà đầu tư lớn, dùng chiến lược phức tạp; mortgage loan là vay thế chấp; joint venture là liên doanh.","extra":[{"en":"diversified portfolio","vi":"danh mục đầu tư đa dạng"},
{"en":"fund manager","vi":"người quản lý quỹ"},
{"en":"pool resources","vi":"gom nguồn lực"}]},
{"id":"q0139","unit":3,"stem":"A company has a strong reputation, but inaccurate financial reports have damaged investors' trust. The company must restore its ______.","options":["turnover","exposure","credibility","downtime"],"answer":2,"explain":"Báo cáo tài chính sai làm mất lòng tin của nhà đầu tư nên công ty phải khôi phục credibility (uy tín, độ tin cậy). Turnover là doanh thu/tỷ lệ nghỉ việc, exposure là mức độ rủi ro, downtime là thời gian ngừng hoạt động.","extra":[{"en":"restore confidence","vi":"khôi phục niềm tin"},
{"en":"financial statements","vi":"báo cáo tài chính"},
{"en":"reputational damage","vi":"thiệt hại danh tiếng"}]},
{"id":"q0140","unit":6,"stem":"A business changes its production facilities to another city to reduce operating costs. It decides to ______ its operations.","options":["reassess","retrain","restructure","relocate"],"answer":3,"explain":"Chuyển cơ sở sản xuất sang thành phố khác để giảm chi phí là relocate. Reassess là đánh giá lại, retrain là đào tạo lại, restructure là tái cơ cấu – không bao hàm việc đổi địa điểm.","extra":[{"en":"move operations offshore","vi":"chuyển hoạt động ra nước ngoài"},
{"en":"relocation costs","vi":"chi phí di dời"},
{"en":"low-cost location","vi":"địa điểm chi phí thấp"}]},
{"id":"q0141","unit":1,"stem":"A firm hires a specialist to supervise and manage the daily activities of its production department. The specialist is responsible for ______ the department.","options":["overseeing","falsifying","offsetting","backtracking"],"answer":0,"explain":"Oversee nghĩa là giám sát, quản lý hoạt động hằng ngày. Falsify là làm giả, offset là bù đắp, backtrack là rút lại – không mô tả việc quản lý.","extra":[{"en":"production supervisor","vi":"giám sát sản xuất"},
{"en":"day-to-day operations","vi":"hoạt động hằng ngày"},
{"en":"be in charge of","vi":"chịu trách nhiệm về"}]},
{"id":"q0142","unit":7,"stem":"A company has experienced a significant decline in sales because consumers are spending less during a period of economic weakness. This situation may be associated with ______.","options":["interest rates","economic downturns","cash equivalents","production yields"],"answer":1,"explain":"Người tiêu dùng giảm chi tiêu trong giai đoạn kinh tế yếu gắn với economic downturns (suy thoái kinh tế). Interest rates là lãi suất, cash equivalents là tương đương tiền, production yields là sản lượng đạt chuẩn.","extra":[{"en":"recession","vi":"suy thoái"},
{"en":"consumer confidence","vi":"niềm tin người tiêu dùng"},
{"en":"weather the downturn","vi":"vượt qua giai đoạn suy thoái"}]},
{"id":"q0143","unit":3,"stem":"A company records transactions involving the purchase and sale of goods in an orderly and systematic manner. This activity is known as ______.","options":["auditing","due diligence","bookkeeping","short selling"],"answer":2,"explain":"Ghi chép có hệ thống các giao dịch mua bán là bookkeeping (ghi sổ kế toán). Auditing là kiểm toán, due diligence là thẩm định, short selling là bán khống.","extra":[{"en":"keep accounts","vi":"giữ sổ sách"},
{"en":"ledger entry","vi":"bút toán sổ cái"},
{"en":"accounting software","vi":"phần mềm kế toán"}]},
{"id":"q0144","unit":4,"stem":"A company borrows funds to purchase equipment and uses the equipment as collateral for the loan. In this context, the equipment may serve as ______.","options":["equity","goodwill","receivables","security"],"answer":3,"explain":"Tài sản được dùng làm bảo đảm cho khoản vay là security (tài sản bảo đảm). Equity là vốn chủ sở hữu, goodwill là lợi thế thương mại, receivables là khoản phải thu – không phải bảo đảm cho khoản vay.","extra":[{"en":"secured loan","vi":"khoản vay có bảo đảm"},
{"en":"unsecured debt","vi":"nợ không có bảo đảm"},
{"en":"pledge assets","vi":"cầm cố tài sản"}]},
{"id":"q0145","unit":6,"stem":"A business identifies a shortage of skilled employees that prevents it from meeting production targets. This shortage is a ______.","options":["deficiency","threshold","compromise","coalition"],"answer":0,"explain":"Skills deficiency (thiếu hụt kỹ năng) là sự thiếu hụt khiến không đạt được mục tiêu. Threshold là ngưỡng, compromise là sự thỏa hiệp, coalition là liên minh – không có nghĩa thiếu hụt.","extra":[{"en":"skills gap","vi":"khoảng cách kỹ năng"},
{"en":"labour shortage","vi":"thiếu hụt lao động"},
{"en":"meet targets","vi":"đạt mục tiêu"}]},
{"id":"q0146","unit":6,"stem":"A firm wants its departments' objectives to support its overall long-term business direction. It must ensure that departmental plans ______ with its strategic vision.","options":["hover","align","incur","falsify"],"answer":1,"explain":"Align with nghĩa là phù hợp, thống nhất với tầm nhìn chiến lược. Hover là lơ lửng, incur là gánh chịu, falsify là làm giả – không dùng với giới từ with theo nghĩa này.","extra":[{"en":"strategic vision","vi":"tầm nhìn chiến lược"},
{"en":"long-term goals","vi":"mục tiêu dài hạn"},
{"en":"be consistent with","vi":"nhất quán với"}]},
{"id":"q0147","unit":3,"stem":"A company has a large amount of money in its bank account and short-term deposits that can be converted into cash quickly. These are classified as ______.","options":["receivables","provisions","cash equivalents","intangible assets"],"answer":2,"explain":"Tiền gửi ngân hàng và khoản gửi ngắn hạn dễ chuyển thành tiền là cash equivalents. Receivables là khoản phải thu, provisions là dự phòng, intangible assets là tài sản vô hình – không thể quy đổi nhanh thành tiền.","extra":[{"en":"liquidity","vi":"tính thanh khoản"},
{"en":"current assets","vi":"tài sản ngắn hạn"},
{"en":"money market","vi":"thị trường tiền tệ"}]},
{"id":"q0148","unit":6,"stem":"An organization teaches its employees new skills because the technology used in their jobs has changed. It needs to ______ its workforce.","options":["relocate","downsize","decentralize","retrain"],"answer":3,"explain":"Dạy nhân viên kỹ năng mới vì công nghệ thay đổi là retrain (đào tạo lại). Relocate là chuyển địa điểm, downsize là cắt giảm nhân sự, decentralize là phân quyền.","extra":[{"en":"upskill","vi":"nâng cao kỹ năng"},
{"en":"staff development","vi":"phát triển nhân sự"},
{"en":"adapt to new technology","vi":"thích ứng công nghệ mới"}]},
{"id":"q0149","unit":5,"stem":"A political organization attempts to persuade lawmakers to support a proposed environmental regulation. It is trying to ______ the legislators.","options":["lobby","replenish","multiply","reassess"],"answer":0,"explain":"Lobby nghĩa là vận động hành lang, thuyết phục nhà lập pháp ủng hộ một quy định. Replenish là bổ sung, multiply là nhân lên, reassess là đánh giá lại – không có nghĩa thuyết phục chính trị gia.","extra":[{"en":"pressure group","vi":"nhóm gây áp lực"},
{"en":"lobbyist","vi":"người vận động hành lang"},
{"en":"draft legislation","vi":"dự thảo luật"}]},
{"id":"q0150","unit":3,"stem":"A company has a large number of unpaid customer invoices. It should strengthen its management of ______ to improve cash collection.","options":["liabilities","receivables","treasury shares","deferred taxes"],"answer":1,"explain":"Nhiều hóa đơn khách hàng chưa thanh toán là vấn đề của receivables (khoản phải thu); quản lý tốt giúp thu tiền nhanh hơn. Liabilities là nợ phải trả, treasury shares là cổ phiếu quỹ, deferred taxes là thuế hoãn lại.","extra":[{"en":"overdue invoice","vi":"hóa đơn quá hạn"},
{"en":"credit control","vi":"kiểm soát tín dụng"},
{"en":"debt collection","vi":"thu hồi nợ"}]},
{"id":"q0151","unit":2,"stem":"A firm introduces systematic checks at every stage to prevent defects before products reach customers. Which function does this describe?","options":["inventory management","performance measurement","auditing","quality assurance"],"answer":3,"explain":"Kiểm tra có hệ thống ở mọi công đoạn để ngăn lỗi là quality assurance (đảm bảo chất lượng). Inventory management là quản lý tồn kho, performance measurement là đo lường hiệu suất, auditing là kiểm toán – không nhằm ngăn lỗi sản phẩm.","extra":[{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"zero defects","vi":"không lỗi"},
{"en":"inspection","vi":"kiểm tra"}]},
{"id":"q0152","unit":6,"stem":"The bank is considering lending to the company because it expects demand to grow among _____ customers over the next two years.","options":["outstanding","prospective","eligible","embedded"],"answer":1,"explain":"Prospective customers là khách hàng tiềm năng sẽ xuất hiện trong tương lai, hợp với việc dự báo nhu cầu tăng. Outstanding là xuất sắc/chưa trả, eligible là đủ điều kiện, embedded là gắn sâu – không diễn đạt khách hàng tương lai.","extra":[{"en":"potential customers","vi":"khách hàng tiềm năng"},
{"en":"demand forecast","vi":"dự báo nhu cầu"},
{"en":"loan application","vi":"hồ sơ xin vay"}]},
{"id":"q0153","unit":3,"stem":"A company recognises an estimated obligation for future warranty claims, although the exact amount and payment date are uncertain. It records a _____.","options":["provision","retained earnings","receivables","treasury shares"],"answer":0,"explain":"Khoản nghĩa vụ ước tính trong tương lai (bảo hành) mà số tiền và thời điểm chưa chắc chắn được ghi nhận là provision (dự phòng). Retained earnings là lợi nhuận giữ lại, receivables là khoản phải thu, treasury shares là cổ phiếu quỹ.","extra":[{"en":"warranty claim","vi":"yêu cầu bảo hành"},
{"en":"estimate liabilities","vi":"ước tính nợ phải trả"},
{"en":"contingency","vi":"khoản dự phòng bất trắc"}]},
{"id":"q0154","unit":4,"stem":"A privately managed investment fund uses complex strategies, including leverage and short selling, to pursue returns. It is most likely a _____.","options":["mutual fund","joint venture","financial backer","hedge fund"],"answer":3,"explain":"Quỹ đầu tư tư nhân dùng chiến lược phức tạp như đòn bẩy và bán khống là hedge fund (quỹ phòng hộ). Mutual fund là quỹ tương hỗ truyền thống, joint venture là liên doanh, financial backer là bên tài trợ vốn nói chung.","extra":[{"en":"high-net-worth investor","vi":"nhà đầu tư giàu có"},
{"en":"risk-adjusted return","vi":"lợi nhuận điều chỉnh theo rủi ro"},
{"en":"alternative investment","vi":"đầu tư thay thế"}]},
{"id":"q0155","unit":5,"stem":"After evidence contradicted its earlier statement, the minister had to _____ and admit that the policy would not achieve its stated target.","options":["backbench","backtrack","backdown","backflip"],"answer":1,"explain":"Backtrack nghĩa là rút lại lập trường, thừa nhận mình sai – hợp với bối cảnh bộ trưởng phải thừa nhận chính sách không đạt mục tiêu. Backbench là danh từ/tính từ chỉ nghị sĩ hàng ghế sau, backdown là danh từ (không dùng như động từ), backflip mang tính khẩu ngữ, thường là đảo ngược hoàn toàn.","extra":[{"en":"U-turn","vi":"đảo ngược chính sách"},
{"en":"go back on one's word","vi":"nuốt lời"},
{"en":"retract a statement","vi":"rút lại phát biểu"}],"needsReview":true},
{"id":"q0156","unit":1,"stem":"In this factory, work moves through a fixed sequence: cutting, shaping, assembly and inspection. This arrangement is best described as a _____.","options":["continuous production","linear workflow","unit production","batch production"],"answer":1,"explain":"Công việc đi qua một trình tự cố định: cắt, tạo hình, lắp ráp, kiểm tra là linear workflow (quy trình tuyến tính). Continuous production là sản xuất liên tục không ngừng, unit production là đơn chiếc, batch production là theo lô – không nhấn mạnh trình tự các bước.","extra":[{"en":"assembly line","vi":"dây chuyền lắp ráp"},
{"en":"production stage","vi":"công đoạn sản xuất"},
{"en":"sequential process","vi":"quy trình tuần tự"}],"needsReview":true},
{"id":"q0157","unit":1,"stem":"Before opening a second plant, managers estimate the maximum output their facilities, workforce and equipment can support. They are undertaking _____.","options":["capacity planning","inventory management","performance measurement","production scheduling"],"answer":0,"explain":"Ước tính sản lượng tối đa mà cơ sở, nhân lực và thiết bị đáp ứng được là capacity planning (hoạch định công suất). Inventory management là quản lý tồn kho, performance measurement là đo lường hiệu suất, production scheduling là lập lịch sản xuất chi tiết.","extra":[{"en":"operate at full capacity","vi":"hoạt động hết công suất"},
{"en":"expand production","vi":"mở rộng sản xuất"},
{"en":"forecast demand","vi":"dự báo nhu cầu"}]},
{"id":"q0158","unit":3,"stem":"A customer list, a registered brand and a patent are examples of assets that have no physical substance. They are classified as _____.","options":["raw materials","current assets","intangible assets","cash equivalents"],"answer":2,"explain":"Danh sách khách hàng, nhãn hiệu đã đăng ký và bằng sáng chế là tài sản không có hình thái vật chất, tức intangible assets (tài sản vô hình). Raw materials là nguyên liệu, current assets là tài sản ngắn hạn, cash equivalents là tương đương tiền.","extra":[{"en":"tangible assets","vi":"tài sản hữu hình"},
{"en":"goodwill","vi":"lợi thế thương mại"},
{"en":"brand value","vi":"giá trị thương hiệu"}]},
{"id":"q0159","unit":2,"stem":"After several quarters of rapid growth, the company's sales stopped increasing and remained at roughly the same level. Sales began to _____.","options":["incur","multiply","level off","decelerate"],"answer":2,"explain":"Doanh số ngừng tăng và ở mức tương đương là level off (đi ngang, chững lại). Incur là gánh chịu, multiply là nhân lên, decelerate là chậm dần (vẫn còn tăng nhưng chậm hơn) nên không đúng với trạng thái đứng yên.","extra":[{"en":"plateau","vi":"chững lại, đạt đỉnh"},
{"en":"stagnate","vi":"đình trệ"},
{"en":"sales growth","vi":"tăng trưởng doanh số"}]},
{"id":"q0160","unit":7,"stem":"Two firms agree to establish and operate a new enterprise together, sharing resources, risks and returns. This arrangement is a _____.","options":["joint venture","acquisition","take-over","mutual fund"],"answer":0,"explain":"Hai công ty cùng lập và vận hành doanh nghiệp mới, chia sẻ nguồn lực, rủi ro và lợi nhuận là joint venture (liên doanh). Acquisition và take-over là mua lại một công ty, mutual fund là quỹ tương hỗ.","extra":[{"en":"joint venture agreement","vi":"hợp đồng liên doanh"},
{"en":"strategic alliance","vi":"liên minh chiến lược"},
{"en":"share risks and rewards","vi":"chia sẻ rủi ro và lợi ích"}]},
{"id":"q0161","unit":5,"stem":"The new regulation requires factories to collect, treat and remove their unwanted materials safely. It primarily concerns _____.","options":["carbon credits","consumer spending","waste disposal","industrial emissions"],"answer":2,"explain":"Thu gom, xử lý và loại bỏ chất thải không mong muốn một cách an toàn là waste disposal (xử lý chất thải). Carbon credits là tín chỉ carbon, consumer spending là chi tiêu tiêu dùng, industrial emissions là khí thải công nghiệp (chất thải vào không khí).","extra":[{"en":"hazardous waste","vi":"chất thải nguy hại"},
{"en":"recycling scheme","vi":"chương trình tái chế"},
{"en":"environmental compliance","vi":"tuân thủ môi trường"}]},
{"id":"q0162","unit":2,"stem":"The consultant recommended immediate action to correct the weaknesses identified in the quality system. The company must _____ the deficiencies.","options":["remediate","pinpoint","enhance","replenish"],"answer":0,"explain":"Khắc phục các điểm yếu của hệ thống chất lượng là remediate (sửa chữa, khắc phục). Pinpoint chỉ là xác định chính xác điểm lỗi, enhance là nâng cao, replenish là bổ sung – không có nghĩa sửa chữa khiếm khuyết.","extra":[{"en":"corrective action","vi":"hành động khắc phục"},
{"en":"non-compliance","vi":"không tuân thủ"},
{"en":"quality audit","vi":"đánh giá chất lượng"}]},
{"id":"q0163","unit":3,"stem":"A business holds short-term deposits and highly liquid instruments that can be converted into known amounts of cash with insignificant risk. These are _____.","options":["receivables","cash equivalents","provisions","intangible assets"],"answer":1,"explain":"Tiền gửi ngắn hạn và công cụ có tính thanh khoản cao, quy đổi được thành số tiền xác định với rủi ro không đáng kể là cash equivalents. Receivables là khoản phải thu, provisions là dự phòng, intangible assets là tài sản vô hình.","extra":[{"en":"highly liquid","vi":"có tính thanh khoản cao"},
{"en":"treasury bills","vi":"tín phiếu kho bạc"},
{"en":"working capital","vi":"vốn lưu động"}]},
{"id":"q0164","unit":5,"stem":"During negotiations, the supplier agreed to _____ the delivery deadline in exchange for a higher order volume.","options":["fend off","recoup","offset","give ground on"],"answer":3,"explain":"Give ground on nghĩa là nhượng bộ về một điểm (ở đây là hạn giao hàng) để đổi lấy lợi ích khác. Fend off là chống đỡ, recoup là thu hồi lại, offset là bù đắp – không diễn tả sự nhượng bộ trong đàm phán.","extra":[{"en":"make a concession","vi":"nhượng bộ"},
{"en":"reach a compromise","vi":"đạt được thỏa hiệp"},
{"en":"bargaining position","vi":"vị thế đàm phán"}],"needsReview":true},
{"id":"q0165","unit":4,"stem":"Rather than seek a bank loan or issue shares, the founders financed the start-up with personal savings and early sales revenue. This is an example of _____.","options":["bootstrapping","leverage","funding","due diligence"],"answer":0,"explain":"Tự tài trợ khởi nghiệp bằng tiền tiết kiệm và doanh thu ban đầu, không vay hay phát hành cổ phiếu là bootstrapping. Leverage là dùng vốn vay, funding là việc cấp vốn nói chung, due diligence là thẩm định.","extra":[{"en":"seed funding","vi":"vốn hạt giống"},
{"en":"self-funded","vi":"tự cấp vốn"},
{"en":"angel investor","vi":"nhà đầu tư thiên thần"}]},
{"id":"q0166","unit":6,"stem":"An organisation that can respond quickly to shifting customer needs and adjust its processes is described as _____.","options":["agile","volatile","binding","standardized"],"answer":0,"explain":"Tổ chức phản ứng nhanh với nhu cầu khách hàng thay đổi và điều chỉnh quy trình là agile (linh hoạt, nhanh nhẹn). Volatile là biến động bất ổn, binding là ràng buộc, standardized là tiêu chuẩn hóa (cứng nhắc, ngược nghĩa).","extra":[{"en":"adapt to change","vi":"thích ứng với thay đổi"},
{"en":"responsive to customers","vi":"đáp ứng khách hàng"},
{"en":"flexible working","vi":"làm việc linh hoạt"}]},
{"id":"q0167","unit":5,"stem":"An independent _____ was appointed to investigate complaints about the regulator's conduct and publish its findings.","options":["provision","coalition","backbench","commission"],"answer":3,"explain":"Commission là ủy ban độc lập được chỉ định điều tra và công bố kết quả. Provision là khoản dự phòng, coalition là liên minh, backbench là hàng ghế sau của nghị viện – không phải cơ quan điều tra.","extra":[{"en":"public inquiry","vi":"cuộc điều tra công khai"},
{"en":"regulatory body","vi":"cơ quan quản lý"},
{"en":"publish findings","vi":"công bố kết quả"}]},
{"id":"q0168","unit":4,"stem":"The legal team developed a defence strategy to _____ a hostile take-over bid from a competitor.","options":["back down","fend off","backtrack","offset"],"answer":1,"explain":"Fend off a take-over bid nghĩa là chống lại, ngăn chặn một cuộc thâu tóm thù địch. Back down và backtrack là nhượng bộ/rút lui, offset là bù đắp – đều trái với mục tiêu chống đỡ.","extra":[{"en":"hostile bid","vi":"đề nghị thâu tóm thù địch"},
{"en":"poison pill","vi":"chiến lược viên thuốc độc chống thâu tóm"},
{"en":"white knight","vi":"hiệp sĩ trắng (bên cứu trợ)"}]},
{"id":"q0169","unit":3,"stem":"Because accounting rules and tax rules recognise certain transactions in different periods, the firm reports a _____ balance.","options":["retained earning","goodwill","deferred tax","cash equivalent"],"answer":2,"explain":"Khi quy tắc kế toán và thuế ghi nhận giao dịch ở các kỳ khác nhau thì phát sinh số dư deferred tax (thuế hoãn lại). Retained earning là lợi nhuận giữ lại, goodwill là lợi thế thương mại, cash equivalent là tương đương tiền – không do chênh lệch thời điểm ghi nhận.","extra":[{"en":"timing difference","vi":"chênh lệch thời điểm"},
{"en":"tax liability","vi":"nghĩa vụ thuế"},
{"en":"tax accounting","vi":"kế toán thuế"}]},
{"id":"q0170","unit":3,"stem":"In Australia, compulsory employer contributions to employees' retirement savings are commonly associated with _____.","options":["provision","equity","superannuation","severance"],"answer":2,"explain":"Superannuation là quỹ hưu trí bắt buộc do chủ lao động đóng góp ở Úc. Provision là khoản dự phòng, equity là vốn chủ sở hữu, severance là trợ cấp thôi việc – không phải tiết kiệm hưu trí.","extra":[{"en":"pension scheme","vi":"chế độ lương hưu"},
{"en":"employer contribution","vi":"phần đóng góp của chủ lao động"},
{"en":"severance pay","vi":"trợ cấp thôi việc"}]},
{"id":"q0171","unit":1,"stem":"A manufacturer orders a specialist component today but will receive it in six weeks. The six-week interval is the component's _____.","options":["downtime","conversion","production yield","lead time"],"answer":3,"explain":"Khoảng thời gian từ lúc đặt hàng đến lúc nhận hàng (sáu tuần) là lead time. Downtime là thời gian ngừng máy, conversion là chuyển đổi, production yield là sản lượng đạt chuẩn.","extra":[{"en":"delivery schedule","vi":"lịch giao hàng"},
{"en":"reduce lead times","vi":"rút ngắn thời gian chờ"},
{"en":"supply chain delay","vi":"chậm trễ chuỗi cung ứng"}]},
{"id":"q0172","unit":3,"stem":"An auditor discovered that the manager had deliberately altered invoices to conceal unauthorised payments. The manager had attempted to _____ the records.","options":["mislead","falsify","flatten out","audit"],"answer":1,"explain":"Cố ý sửa hóa đơn để che giấu khoản chi trái phép là falsify the records (làm giả hồ sơ). Mislead là gây hiểu lầm nhưng không đi với records theo nghĩa làm giả, flatten out là đi ngang, audit là kiểm toán (việc của kiểm toán viên, không phải của người quản lý).","extra":[{"en":"fraudulent invoice","vi":"hóa đơn gian lận"},
{"en":"embezzlement","vi":"biển thủ"},
{"en":"unauthorised payment","vi":"khoản chi trái phép"}]},
{"id":"q0173","unit":2,"stem":"The supplier classifies its distributors as first-, second- and third-level partners. Each category represents a different _____.","options":["specification","tier","metric","threshold"],"answer":1,"explain":"Các cấp nhà phân phối thứ nhất, thứ hai, thứ ba là các tier (tầng, cấp) khác nhau. Specification là thông số kỹ thuật, metric là chỉ số đo lường, threshold là ngưỡng.","extra":[{"en":"tier-one supplier","vi":"nhà cung cấp cấp một"},
{"en":"supply chain","vi":"chuỗi cung ứng"},
{"en":"distribution network","vi":"mạng lưới phân phối"}]},
{"id":"q0174","unit":5,"stem":"When households reduce purchases of non-essential goods, total _____ may weaken, slowing economic growth.","options":["return on investment","industrial emissions","consumer spending","waste disposal"],"answer":2,"explain":"Hộ gia đình giảm mua hàng không thiết yếu làm yếu đi consumer spending (chi tiêu tiêu dùng) và làm chậm tăng trưởng. Return on investment là lợi tức đầu tư, industrial emissions là khí thải, waste disposal là xử lý chất thải.","extra":[{"en":"disposable income","vi":"thu nhập khả dụng"},
{"en":"discretionary spending","vi":"chi tiêu tùy ý"},
{"en":"economic growth","vi":"tăng trưởng kinh tế"}]},
{"id":"q0175","unit":5,"stem":"The contract contains a _____ clause, meaning the parties are legally required to comply with it.","options":["binding","standardized","prospective","remediable"],"answer":0,"explain":"Điều khoản binding là có ràng buộc pháp lý, các bên bắt buộc tuân thủ. Standardized là tiêu chuẩn hóa, prospective là tương lai/tiềm năng, remediable là có thể khắc phục – không nói về hiệu lực ràng buộc.","extra":[{"en":"legally binding","vi":"có hiệu lực ràng buộc pháp lý"},
{"en":"breach of contract","vi":"vi phạm hợp đồng"},
{"en":"terms and conditions","vi":"điều khoản và điều kiện"}]},
{"id":"q0176","unit":1,"stem":"The operations team assigns start dates, completion dates and machine time to each order for the coming week. This is _____.","options":["production scheduling","capacity planning","performance measurement","inventory management"],"answer":0,"explain":"Ấn định ngày bắt đầu, ngày hoàn thành và thời gian máy cho từng đơn hàng là production scheduling (lập lịch sản xuất). Capacity planning là hoạch định công suất dài hạn, performance measurement là đo hiệu suất, inventory management là quản lý tồn kho.","extra":[{"en":"production schedule","vi":"kế hoạch sản xuất"},
{"en":"deadline","vi":"hạn chót"},
{"en":"work order","vi":"lệnh sản xuất"}]},
{"id":"q0177","unit":3,"stem":"Cash, trade receivables and goods held for sale are all examples of _____.","options":["intangible assets","equity","current assets","liabilities"],"answer":2,"explain":"Tiền mặt, các khoản phải thu thương mại và hàng hóa để bán đều là tài sản có thể chuyển thành tiền trong vòng một năm nên gọi là current assets (tài sản ngắn hạn). Intangible assets là tài sản vô hình (bằng sáng chế, thương hiệu); equity là vốn chủ sở hữu; liabilities là nợ phải trả, đều không phù hợp.","extra":[{"en":"fixed assets","vi":"tài sản cố định"},
{"en":"trade receivables","vi":"các khoản phải thu thương mại"},
{"en":"working capital","vi":"vốn lưu động"}]},
{"id":"q0178","unit":6,"stem":"Facing persistent losses, the retailer plans to reduce the size of its workforce and close several smaller outlets. It intends to _____.","options":["relaunch","upgrade","relocate","downsize"],"answer":3,"explain":"Downsize nghĩa là thu hẹp quy mô, cắt giảm nhân sự và đóng bớt cơ sở. Relaunch là tái tung ra sản phẩm/thương hiệu; upgrade là nâng cấp; relocate là chuyển địa điểm, đều không mang nghĩa cắt giảm quy mô.","extra":[{"en":"cut back on costs","vi":"cắt giảm chi phí"},
{"en":"redundancy package","vi":"gói trợ cấp thôi việc"},
{"en":"streamline operations","vi":"tinh gọn hoạt động"}]},
{"id":"q0179","unit":4,"stem":"A contract whose value changes according to the price of an underlying share, currency or commodity is a _____.","options":["bondholder","derivative","mortgage loan","treasury share"],"answer":1,"explain":"Derivative (công cụ phái sinh) là hợp đồng có giá trị phụ thuộc vào giá của tài sản cơ sở như cổ phiếu, tiền tệ, hàng hóa. Bondholder là người giữ trái phiếu; mortgage loan là khoản vay thế chấp; treasury share là cổ phiếu quỹ, đều không có đặc điểm này.","extra":[{"en":"underlying asset","vi":"tài sản cơ sở"},
{"en":"futures contract","vi":"hợp đồng tương lai"},
{"en":"options trading","vi":"giao dịch quyền chọn"}]},
{"id":"q0180","unit":5,"stem":"After being given a comfortable office, flexible hours and a generous budget, the new director was _____, happily enjoying every advantage.","options":["a level playing field","a cash cow","a pig in mud","a backbench"],"answer":2,"explain":"\"Happy as a pig in mud\" là thành ngữ chỉ người vô cùng hài lòng, thoải mái tận hưởng. A level playing field là sân chơi công bằng; a cash cow là sản phẩm sinh lời đều; a backbench là hàng ghế sau nghị viện, đều không miêu tả một người.","extra":[{"en":"perks of the job","vi":"đặc quyền của công việc"},
{"en":"in clover","vi":"sống sung túc, thoải mái"},
{"en":"a generous budget","vi":"ngân sách hào phóng"}]},
{"id":"q0181","unit":1,"stem":"The company uses the same dimensions, materials and testing requirements for every item in this product range. The products are _____.","options":["prospective","volatile","customized","standardized"],"answer":3,"explain":"Khi mọi sản phẩm dùng cùng kích thước, vật liệu và tiêu chuẩn kiểm tra thì chúng được tiêu chuẩn hóa (standardized). Customized là làm theo yêu cầu riêng, trái nghĩa; prospective là tiềm năng; volatile là biến động mạnh.","extra":[{"en":"mass production","vi":"sản xuất hàng loạt"},
{"en":"product range","vi":"dòng sản phẩm"},
{"en":"quality standards","vi":"tiêu chuẩn chất lượng"}]},
{"id":"q0182","unit":5,"stem":"The main people involved in a dispute or negotiation are often referred to as the _____.","options":["creditors","protagonists","backbenchers","bondholders"],"answer":1,"explain":"Protagonists là những nhân vật/bên chính tham gia vào một tranh chấp hay cuộc đàm phán. Creditors là chủ nợ; backbenchers là nghị sĩ hàng ghế sau; bondholders là người giữ trái phiếu, không chỉ các bên chính trong tranh chấp.","extra":[{"en":"key stakeholders","vi":"các bên liên quan chính"},
{"en":"reach a settlement","vi":"đạt được thỏa thuận"},
{"en":"the parties involved","vi":"các bên liên quan"}]},
{"id":"q0183","unit":5,"stem":"The savings generated by automation helped _____ the higher cost of imported components.","options":["offset","impose","incur","recoup"],"answer":0,"explain":"Offset nghĩa là bù đắp, triệt tiêu một khoản bất lợi bằng khoản có lợi, nên khoản tiết kiệm từ tự động hóa bù cho chi phí linh kiện nhập khẩu cao. Impose là áp đặt; incur là chịu (chi phí); recoup là thu hồi khoản đã mất, không hợp với \"the higher cost\" ở đây.","extra":[{"en":"offset costs","vi":"bù đắp chi phí"},
{"en":"carbon offset","vi":"bù đắp lượng khí thải carbon"},
{"en":"cost savings","vi":"khoản tiết kiệm chi phí"}]},
{"id":"q0184","unit":2,"stem":"Cybersecurity procedures are now deeply integrated into the firm's everyday operations; they have become _____.","options":["embedded","agile","prospective","decentralized"],"answer":0,"explain":"Embedded nghĩa là được gắn sâu, tích hợp vào hoạt động thường ngày. Agile là linh hoạt, nhanh nhẹn; prospective là tiềm năng; decentralized là phân quyền, không diễn đạt việc quy trình đã trở thành một phần cố hữu.","extra":[{"en":"deeply embedded","vi":"ăn sâu, gắn chặt"},
{"en":"cybersecurity breach","vi":"vụ vi phạm an ninh mạng"},
{"en":"day-to-day operations","vi":"hoạt động hằng ngày"}]},
{"id":"q0185","unit":6,"stem":"The shift from paper-based transactions to real-time digital platforms brought a fundamental _____ in the way the sector operates.","options":["downgrade","revolution","update","reassessment"],"answer":1,"explain":"\"A fundamental revolution\" chỉ một cuộc cách mạng, thay đổi căn bản về cách ngành vận hành khi chuyển từ giấy sang nền tảng số thời gian thực. Downgrade là hạ cấp; update là cập nhật nhỏ; reassessment là đánh giá lại, đều quá nhẹ hoặc không phải là một sự thay đổi lớn.","extra":[{"en":"digital transformation","vi":"chuyển đổi số"},
{"en":"paradigm shift","vi":"sự thay đổi mô hình"},
{"en":"real-time data","vi":"dữ liệu thời gian thực"}],"needsReview":true},
{"id":"q0186","unit":5,"stem":"Improvements in healthcare and living conditions have increased average _____ in many economies.","options":["risk tolerance","production yield","life expectancy","consumer spending"],"answer":2,"explain":"Life expectancy là tuổi thọ trung bình, tăng lên nhờ y tế và điều kiện sống tốt hơn. Risk tolerance là mức chấp nhận rủi ro; production yield là sản lượng đầu ra; consumer spending là chi tiêu tiêu dùng, không liên quan trực tiếp đến sức khỏe.","extra":[{"en":"ageing population","vi":"dân số già hóa"},
{"en":"standard of living","vi":"mức sống"},
{"en":"birth rate","vi":"tỷ lệ sinh"}]},
{"id":"q0187","unit":4,"stem":"A bank or supplier to whom a company owes money is known as a _____.","options":["creditor","financial backer","debtor","bondholder"],"answer":0,"explain":"Creditor là chủ nợ, tức ngân hàng hay nhà cung cấp mà công ty nợ tiền. Financial backer là bên tài trợ vốn nói chung; debtor là con nợ (ngược chiều); bondholder là người nắm giữ trái phiếu, hẹp hơn và không phải chủ nợ nói chung.","extra":[{"en":"outstanding debt","vi":"khoản nợ chưa thanh toán"},
{"en":"trade creditor","vi":"chủ nợ thương mại"},
{"en":"settle a debt","vi":"thanh toán dứt nợ"}]},
{"id":"q0188","unit":7,"stem":"Parliament voted to _____ the new environmental rules, giving them the force of law.","options":["impose","compromise","lobby","enact"],"answer":3,"explain":"Enact là ban hành, thông qua để trở thành luật, hợp với \"giving them the force of law\". Impose là áp đặt; compromise là thỏa hiệp; lobby là vận động hành lang, không phải hành động của quốc hội thông qua luật.","extra":[{"en":"enact legislation","vi":"ban hành luật"},
{"en":"come into force","vi":"có hiệu lực"},
{"en":"environmental regulations","vi":"quy định môi trường"}]},
{"id":"q0189","unit":2,"stem":"After using most of its packaging materials, the warehouse placed an order to _____ its stock.","options":["pinpoint","replenish","remediate","multiply"],"answer":1,"explain":"Replenish là bổ sung lại hàng tồn kho sau khi đã dùng gần hết. Pinpoint là xác định chính xác; remediate là khắc phục (sự cố, lỗi); multiply là nhân lên, đều không đúng nghĩa với việc đặt hàng bổ sung kho.","extra":[{"en":"restock","vi":"nhập lại hàng"},
{"en":"stock level","vi":"mức tồn kho"},
{"en":"reorder point","vi":"điểm đặt hàng lại"}]},
{"id":"q0190","unit":6,"stem":"The HR department tracks the proportion of employees who leave and are replaced each year. This is employee _____.","options":["lead time","clientele","exposure","turnover"],"answer":3,"explain":"Staff turnover là tỷ lệ nhân viên nghỉ việc và được thay thế trong năm. Lead time là thời gian chờ từ lúc đặt hàng đến khi giao; clientele là tập khách hàng; exposure là mức độ phơi nhiễm rủi ro, không đo tỷ lệ nghỉ việc.","extra":[{"en":"staff retention","vi":"giữ chân nhân viên"},
{"en":"high turnover","vi":"tỷ lệ nghỉ việc cao"},
{"en":"recruitment costs","vi":"chi phí tuyển dụng"}]},
{"id":"q0191","unit":1,"stem":"The redesign creates additional usefulness and economic worth at each stage of production. It increases _____.","options":["value added","lead time","production yield","downtime"],"answer":0,"explain":"Value added là giá trị gia tăng, phần giá trị và lợi ích kinh tế được thêm vào ở mỗi công đoạn sản xuất. Lead time là thời gian chờ; production yield là tỷ lệ sản phẩm đạt; downtime là thời gian máy ngừng, không mô tả giá trị tăng thêm.","extra":[{"en":"value chain","vi":"chuỗi giá trị"},
{"en":"add value to","vi":"gia tăng giá trị cho"},
{"en":"gross margin","vi":"biên lợi nhuận gộp"}]},
{"id":"q0192","unit":5,"stem":"In the UK Parliament, MPs who are not ministers or members of the frontbench collectively sit on the _____.","options":["protagonists","coalition","commission","backbench"],"answer":3,"explain":"Backbench là các hàng ghế sau trong Quốc hội Anh, nơi các nghị sĩ không giữ chức bộ trưởng hay vị trí lãnh đạo ngồi. Protagonists là các bên chính; coalition là liên minh; commission là ủy ban, không phải khu vực ghế ngồi.","extra":[{"en":"backbencher","vi":"nghị sĩ hàng ghế sau"},
{"en":"frontbench","vi":"hàng ghế trước (lãnh đạo)"},
{"en":"cabinet minister","vi":"bộ trưởng nội các"}]},
{"id":"q0193","unit":5,"stem":"Investors expect accurate disclosure and ethical conduct from a firm; they want its leadership to demonstrate _____.","options":["leverage","integrity","credibility","exposure"],"answer":1,"explain":"Integrity là sự chính trực, trung thực và đạo đức trong hành xử, khớp với \"ethical conduct\" và \"accurate disclosure\". Credibility là độ đáng tin cậy, gần nghĩa nhưng thiên về hình ảnh hơn là đạo đức; leverage là đòn bẩy tài chính; exposure là mức độ rủi ro.","extra":[{"en":"corporate governance","vi":"quản trị doanh nghiệp"},
{"en":"ethical conduct","vi":"hành vi đạo đức"},
{"en":"full disclosure","vi":"công bố đầy đủ"}],"needsReview":true},
{"id":"q0194","unit":3,"stem":"A currency is described as _____ when its exchange rate changes sharply and frequently.","options":["standardized","identical","binding","volatile"],"answer":3,"explain":"Volatile mô tả thứ gì thay đổi mạnh và thường xuyên, ví dụ tỷ giá. Standardized là được tiêu chuẩn hóa; identical là giống hệt; binding là có tính ràng buộc, không mô tả biến động tỷ giá.","extra":[{"en":"exchange rate fluctuation","vi":"biến động tỷ giá"},
{"en":"volatile market","vi":"thị trường biến động"},
{"en":"currency risk","vi":"rủi ro tiền tệ"}]},
{"id":"q0195","unit":6,"stem":"The hotel redesigned its services to _____ the needs of business travellers as well as holidaymakers.","options":["align with","comply with","cater to","attribute to"],"answer":2,"explain":"Cater to the needs of là đáp ứng nhu cầu của một nhóm khách hàng. Align with là điều chỉnh cho khớp; comply with là tuân thủ (quy định); attribute to là quy cho, không đi với \"the needs of\" theo nghĩa phục vụ.","extra":[{"en":"cater for","vi":"phục vụ, đáp ứng"},
{"en":"target market","vi":"thị trường mục tiêu"},
{"en":"customer needs","vi":"nhu cầu khách hàng"}]},
{"id":"q0196","unit":3,"stem":"Shares that a company has bought back and holds itself, rather than leaving them in public investors' hands, are called _____.","options":["provisions","receivables","treasury shares","cash equivalents"],"answer":2,"explain":"Treasury shares là cổ phiếu quỹ, tức cổ phiếu công ty mua lại và tự nắm giữ. Provisions là các khoản dự phòng; receivables là khoản phải thu; cash equivalents là các khoản tương đương tiền, không phải cổ phiếu.","extra":[{"en":"share buyback","vi":"mua lại cổ phiếu"},
{"en":"issued share capital","vi":"vốn cổ phần đã phát hành"},
{"en":"shareholders' equity","vi":"vốn chủ sở hữu"}]},
{"id":"q0197","unit":1,"stem":"The network of suppliers, manufacturers, warehouses and distributors involved in moving a product to customers is the _____.","options":["linear workflow","stock market","assembly line","supply chain"],"answer":3,"explain":"Supply chain là chuỗi cung ứng gồm nhà cung cấp, nhà sản xuất, kho và nhà phân phối đưa sản phẩm đến khách hàng. Linear workflow là quy trình tuyến tính; stock market là thị trường chứng khoán; assembly line là dây chuyền lắp ráp trong nhà máy.","extra":[{"en":"supply chain management","vi":"quản lý chuỗi cung ứng"},
{"en":"logistics","vi":"hậu cần"},
{"en":"distribution network","vi":"mạng lưới phân phối"}]},
{"id":"q0198","unit":5,"stem":"The government introduced new _____ requiring companies to disclose their industrial emissions.","options":["legitimacy","legislation","commission","infrastructure"],"answer":1,"explain":"Legislation là luật, văn bản pháp luật; \"new legislation requiring companies to disclose emissions\" là hợp lý. Legitimacy là tính hợp pháp; commission là ủy ban; infrastructure là cơ sở hạ tầng, không phải thứ có thể \"yêu cầu\" công ty công bố.","extra":[{"en":"introduce legislation","vi":"đưa ra luật"},
{"en":"industrial emissions","vi":"khí thải công nghiệp"},
{"en":"regulatory compliance","vi":"tuân thủ quy định"}]},
{"id":"q0199","unit":5,"stem":"The company had publicly promised not to raise subscription fees, but a week later announced a sharp increase, making a dramatic U-turn. Critics accused it of performing a _____.","options":["backtrack","backdown","backflip","compromise"],"answer":2,"explain":"\"Perform a backflip\" là cách nói chỉ việc đảo ngược hoàn toàn lập trường, hợp với \"dramatic U-turn\". Backdown là danh từ/cụm \"back down\" nghĩa là nhượng bộ rút lui; compromise là thỏa hiệp, đều không nói về việc quay ngoắt 180 độ so với lời hứa.","extra":[{"en":"U-turn","vi":"đảo ngược chính sách"},
{"en":"go back on a promise","vi":"nuốt lời hứa"},
{"en":"subscription fee","vi":"phí thuê bao"}],"needsReview":true},
{"id":"q0200","unit":2,"stem":"Managers use clearly defined _____, such as defect rates and delivery reliability, to assess whether operations meet their targets.","options":["performance metrics","production bottlenecks","interest rates","cash equivalents"],"answer":0,"explain":"Performance metrics là các chỉ số đo hiệu suất như tỷ lệ lỗi, độ tin cậy giao hàng, dùng để đánh giá việc đạt mục tiêu. Production bottlenecks là điểm nghẽn sản xuất; interest rates là lãi suất; cash equivalents là các khoản tương đương tiền, không dùng để đánh giá vận hành.","extra":[{"en":"key performance indicator (KPI)","vi":"chỉ số hiệu suất chính"},
{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"benchmark against","vi":"so sánh với chuẩn"}]},
{"id":"q0201","unit":2,"stem":" A factory produces 12,000 units per day, but 900 units fail to meet the required specifications. Which metric measures the proportion of output that meets quality requirements?","options":["Line efficiency","Capacity utilization","Production yield","Performance measurement"],"answer":2,"explain":"Production yield là tỷ lệ sản phẩm đạt yêu cầu chất lượng trên tổng sản lượng (ở đây khoảng 92,5%). Line efficiency là hiệu suất dây chuyền theo thời gian; capacity utilization là mức sử dụng công suất; performance measurement là khái niệm chung, không phải một tỷ lệ cụ thể.","extra":[{"en":"first-pass yield","vi":"tỷ lệ đạt ngay lần đầu"},
{"en":"scrap rate","vi":"tỷ lệ phế phẩm"},
{"en":"meet specifications","vi":"đạt thông số kỹ thuật"}]},
{"id":"q0202","unit":3,"stem":" A specialist investigates whether managers deliberately falsified accounting records to conceal fraudulent transactions. Which field is most relevant?","options":["Forensic accounting","Tax accounting","Cost accounting","Managerial accounting"],"answer":0,"explain":"Forensic accounting là kế toán pháp y, điều tra gian lận và hồ sơ bị làm giả. Tax accounting liên quan đến thuế; cost accounting phân tích chi phí sản xuất; managerial accounting phục vụ ra quyết định nội bộ, không chuyên điều tra gian lận.","extra":[{"en":"fraud investigation","vi":"điều tra gian lận"},
{"en":"cook the books","vi":"làm giả sổ sách"},
{"en":"audit trail","vi":"dấu vết kiểm toán"}]},
{"id":"q0203","unit":5,"stem":" A long-established product division generates substantial profits that finance the company's new projects. It is best described as a _____.","options":["Mutual fund","Joint venture","Financial backer","Cash cow"],"answer":3,"explain":"Cash cow (bò sữa) là bộ phận/sản phẩm lâu đời tạo lợi nhuận lớn ổn định để tài trợ cho dự án mới. Mutual fund là quỹ tương hỗ; joint venture là liên doanh; financial backer là bên tài trợ, không phải bộ phận sinh lời.","extra":[{"en":"BCG matrix","vi":"ma trận BCG"},
{"en":"mature product","vi":"sản phẩm trưởng thành"},
{"en":"fund new ventures","vi":"tài trợ các dự án mới"}]},
{"id":"q0204","unit":5,"stem":" The government decided to _____ a new environmental levy on companies that exceed the permitted emissions threshold.","options":["offset","impose","recoup","compromise"],"answer":1,"explain":"Impose a levy là áp đặt một khoản thuế/phí lên doanh nghiệp. Offset là bù đắp; recoup là thu hồi khoản đã mất; compromise là thỏa hiệp, không đi với việc chính phủ ban hành khoản thu mới.","extra":[{"en":"environmental levy","vi":"thuế môi trường"},
{"en":"impose a fine","vi":"áp mức phạt"},
{"en":"emissions limit","vi":"giới hạn khí thải"}]},
{"id":"q0205","unit":3,"stem":" A patent has economic value but no physical substance. In accounting, it is classified as an _____.","options":["Inventory","Current asset","Intangible asset","Cash equivalent"],"answer":2,"explain":"Bằng sáng chế có giá trị kinh tế nhưng không có hình thái vật chất nên là tài sản vô hình (intangible asset). Inventory là hàng tồn kho; current asset là tài sản ngắn hạn; cash equivalent là khoản tương đương tiền, đều có tính hữu hình hoặc thanh khoản cao.","extra":[{"en":"intellectual property","vi":"sở hữu trí tuệ"},
{"en":"amortization","vi":"khấu hao tài sản vô hình"},
{"en":"brand value","vi":"giá trị thương hiệu"}]},
{"id":"q0206","unit":2,"stem":" The purchasing department was instructed to _____ raw materials after the factory's inventory fell below the required level.","options":["relocate","downgrade","decelerate","replenish"],"answer":3,"explain":"Replenish là bổ sung nguyên liệu khi tồn kho xuống dưới mức yêu cầu. Relocate là chuyển địa điểm; downgrade là hạ cấp; decelerate là làm chậm lại, không phù hợp với việc đặt mua thêm nguyên liệu.","extra":[{"en":"reorder level","vi":"mức đặt hàng lại"},
{"en":"raw materials","vi":"nguyên vật liệu"},
{"en":"stockout","vi":"hết hàng tồn kho"}]},
{"id":"q0207","unit":4,"stem":" Company A purchases enough shares in Company B to gain control of its management and business decisions. This transaction is a _____.","options":["Take-over","Joint venture","Cross-promotion","Mutual fund"],"answer":0,"explain":"Take-over là việc mua đủ cổ phần để giành quyền kiểm soát công ty khác (thâu tóm). Joint venture là liên doanh hai bên cùng góp vốn; cross-promotion là cùng quảng bá chéo; mutual fund là quỹ tương hỗ, đều không đạt quyền kiểm soát.","extra":[{"en":"hostile take-over","vi":"thâu tóm thù địch"},
{"en":"controlling stake","vi":"cổ phần chi phối"},
{"en":"merger and acquisition","vi":"sáp nhập và mua lại"}]},
{"id":"q0208","unit":5,"stem":" After making an inaccurate public statement about its financial performance, the company had to _____ and correct its earlier claim.","options":["backflip","backtrack","back down","give ground on"],"answer":1,"explain":"Backtrack nghĩa là rút lại, sửa lại điều đã nói trước đó, hợp với \"correct its earlier claim\". Backflip nhấn mạnh đảo ngược lập trường hẳn; back down là nhượng bộ trước áp lực; give ground on là nhường bước trong đàm phán.","extra":[{"en":"retract a statement","vi":"rút lại phát ngôn"},
{"en":"issue a correction","vi":"đưa ra đính chính"},
{"en":"misleading statement","vi":"tuyên bố gây hiểu lầm"}],"needsReview":true},
{"id":"q0209","unit":2,"stem":" A manufacturer receives materials from suppliers only when they are required for production, thereby minimizing inventory holding costs. This approach is known as _____.","options":["Batch production","Mass production","Continuous production","Just-in-time manufacturing"],"answer":3,"explain":"Just-in-time (JIT) là nhận nguyên vật liệu đúng lúc cần cho sản xuất, giảm chi phí lưu kho. Batch production sản xuất theo lô; mass production là hàng loạt; continuous production là liên tục, không gắn với việc giảm tồn kho kiểu này.","extra":[{"en":"JIT delivery","vi":"giao hàng đúng lúc"},
{"en":"holding costs","vi":"chi phí lưu kho"},
{"en":"lean manufacturing","vi":"sản xuất tinh gọn"}]},
{"id":"q0210","unit":3,"stem":" A company reports an accounting tax expense that differs from the tax currently payable because of temporary differences. Which concept explains this?","options":["Deferred tax","Goodwill","Retained earnings","Treasury shares"],"answer":0,"explain":"Deferred tax (thuế hoãn lại) phát sinh do chênh lệch tạm thời giữa kế toán và thuế. Goodwill là lợi thế thương mại; retained earnings là lợi nhuận giữ lại; treasury shares là cổ phiếu quỹ, không giải thích chênh lệch chi phí thuế.","extra":[{"en":"temporary differences","vi":"chênh lệch tạm thời"},
{"en":"tax liability","vi":"nghĩa vụ thuế"},
{"en":"income tax expense","vi":"chi phí thuế thu nhập"}]},
{"id":"q0211","unit":4,"stem":" An individual buys corporate bonds and is entitled to receive interest and repayment under the bond agreement. This investor is a _____.","options":["Creditor","Financial backer","Bondholder","Principal"],"answer":2,"explain":"Bondholder là người nắm giữ trái phiếu, được nhận lãi và hoàn vốn theo hợp đồng trái phiếu. Creditor là chủ nợ nói chung (rộng hơn); financial backer là bên tài trợ; principal là số tiền gốc, không phải một nhà đầu tư.","extra":[{"en":"coupon payment","vi":"lãi trái phiếu định kỳ"},
{"en":"corporate bond","vi":"trái phiếu doanh nghiệp"},
{"en":"maturity date","vi":"ngày đáo hạn"}],"needsReview":true},
{"id":"q0212","unit":2,"stem":" Rather than relying only on final inspections, a manufacturer establishes procedures throughout production to prevent defects. This is an example of _____.","options":["Performance measurement","Quality assurance","Forensic accounting","Production scheduling"],"answer":1,"explain":"Quality assurance là thiết lập quy trình xuyên suốt sản xuất để ngăn lỗi, thay vì chỉ kiểm tra cuối. Performance measurement là đo hiệu suất; forensic accounting là kế toán pháp y; production scheduling là lập lịch sản xuất, không nhằm phòng ngừa lỗi.","extra":[{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"defect prevention","vi":"phòng ngừa lỗi"},
{"en":"zero defects","vi":"không lỗi"}]},
{"id":"q0213","unit":6,"stem":" A multinational firm transfers decision-making authority from its headquarters to regional branches to improve local responsiveness. It intends to _____.","options":["decentralize","downsize","downgrade","relaunch"],"answer":0,"explain":"Decentralize là phân quyền, chuyển quyền ra quyết định từ trụ sở về chi nhánh khu vực. Downsize là thu hẹp quy mô; downgrade là hạ cấp; relaunch là tái ra mắt, không liên quan đến chuyển quyền.","extra":[{"en":"head office","vi":"trụ sở chính"},
{"en":"regional branch","vi":"chi nhánh khu vực"},
{"en":"delegate authority","vi":"ủy quyền"}]},
{"id":"q0214","unit":1,"stem":" Before building another factory, managers estimate the maximum output that existing facilities and proposed equipment can achieve. This is _____.","options":["Inventory management","Machine maintenance","Production scheduling","Capacity planning"],"answer":3,"explain":"Capacity planning là lập kế hoạch năng lực sản xuất, ước tính sản lượng tối đa của cơ sở và thiết bị. Inventory management là quản lý tồn kho; machine maintenance là bảo trì máy; production scheduling là lập lịch, không ước tính công suất tối đa.","extra":[{"en":"spare capacity","vi":"công suất dư"},
{"en":"operate at full capacity","vi":"hoạt động hết công suất"},
{"en":"expand capacity","vi":"mở rộng công suất"}]},
{"id":"q0215","unit":3,"stem":" The prices of a manufacturer's key raw materials fluctuate sharply and unpredictably. These prices are best described as _____.","options":["Embedded","Standardized","Volatile","Identical"],"answer":2,"explain":"Giá biến động mạnh và khó đoán được gọi là volatile. Embedded là được gắn sâu; standardized là được tiêu chuẩn hóa; identical là giống hệt, đều không nói về dao động giá.","extra":[{"en":"commodity prices","vi":"giá hàng hóa"},
{"en":"price swings","vi":"biến động giá"},
{"en":"hedge against risk","vi":"phòng ngừa rủi ro"}]},
{"id":"q0216","unit":5,"stem":" Small businesses that satisfy the stated income and employment requirements are _____ the government's innovation grant.","options":["opposed to","eligible for","attributable to","dismayed by"],"answer":1,"explain":"Eligible for nghĩa là đủ điều kiện nhận (khoản trợ cấp) khi đáp ứng các yêu cầu. Opposed to là phản đối; attributable to là có thể quy cho; dismayed by là thất vọng bởi, không hợp nghĩa câu.","extra":[{"en":"eligibility criteria","vi":"tiêu chí đủ điều kiện"},
{"en":"apply for a grant","vi":"nộp đơn xin trợ cấp"},
{"en":"government subsidy","vi":"trợ cấp chính phủ"}]},
{"id":"q0217","unit":5,"stem":" A manufacturer purchases carbon credits to balance out some greenhouse-gas emissions that it cannot yet eliminate. The credits help it _____ those emissions.","options":["dump","recoup","impose","offset"],"answer":3,"explain":"Carbon credits được mua để bù trừ (offset) lượng khí thải chưa thể loại bỏ. Dump là xả bỏ; recoup là thu hồi khoản đã mất; impose là áp đặt, không mô tả tác dụng của tín chỉ carbon.","extra":[{"en":"carbon neutral","vi":"trung hòa carbon"},
{"en":"carbon footprint","vi":"dấu chân carbon"},
{"en":"greenhouse gas emissions","vi":"khí thải nhà kính"}]},
{"id":"q0218","unit":6,"stem":" A smartphone manufacturer sells earbuds that are designed to work particularly well with its phones. The products _____ one another.","options":["complement","substitute","downgrade","capture"],"answer":0,"explain":"Complement là sản phẩm bổ trợ, được dùng cùng và làm tăng giá trị cho nhau (tai nghe và điện thoại). Substitute là sản phẩm thay thế; downgrade là hạ cấp; capture là chiếm lấy, không mô tả mối quan hệ bổ trợ.","extra":[{"en":"complementary goods","vi":"hàng hóa bổ sung"},
{"en":"substitute goods","vi":"hàng hóa thay thế"},
{"en":"bundle products","vi":"bán trọn gói sản phẩm"}]},
{"id":"q0219","unit":4,"stem":" When calculating a loan repayment, the borrower must distinguish the original amount borrowed from the interest charged. The original amount is called the _____.","options":["Return on investment","Interest rate","Principal","Leverage"],"answer":2,"explain":"Principal là số tiền gốc ban đầu đã vay, phân biệt với tiền lãi. Return on investment là tỷ suất sinh lời; interest rate là lãi suất; leverage là đòn bẩy tài chính, không phải khoản gốc.","extra":[{"en":"repayment period","vi":"thời hạn trả nợ"},
{"en":"outstanding balance","vi":"dư nợ còn lại"},
{"en":"compound interest","vi":"lãi kép"}]},
{"id":"q0220","unit":6,"stem":" Certain informal workplace practices have become so deeply integrated into the company's culture that employees continue to follow them even after new policies are introduced. These practices are _____.","options":["Embedded","Prospective","Agile","Outstanding"],"answer":0,"explain":"Embedded là đã ăn sâu, gắn chặt vào văn hóa công ty. Prospective là tiềm năng; agile là linh hoạt; outstanding là xuất sắc hoặc còn tồn đọng, không diễn tả thói quen ăn sâu.","extra":[{"en":"corporate culture","vi":"văn hóa doanh nghiệp"},
{"en":"resistance to change","vi":"sự kháng cự thay đổi"},
{"en":"deeply rooted","vi":"ăn sâu"}]},
{"id":"q0221","unit":2,"stem":" A warehouse team records incoming and outgoing goods, monitors stock levels, and determines when more materials should be ordered. These activities are part of _____.","options":["Production scheduling","Inventory management","Machine maintenance","Quality assurance"],"answer":1,"explain":"Ghi nhận hàng nhập xuất, theo dõi mức tồn kho và quyết định khi nào đặt thêm nguyên liệu là quản lý tồn kho (inventory management). Production scheduling là lập lịch sản xuất; machine maintenance là bảo trì máy; quality assurance là đảm bảo chất lượng, đều không phải việc này.","extra":[{"en":"stock control","vi":"kiểm soát tồn kho"},
{"en":"stocktake","vi":"kiểm kê hàng"},
{"en":"safety stock","vi":"tồn kho an toàn"}]},
{"id":"q0222","unit":4,"stem":" The company's board introduced several defensive measures to _____ an attempted hostile acquisition.","options":["backtrack","backflip","give ground on","fend off"],"answer":3,"explain":"Fend off nghĩa là chống đỡ, ngăn chặn (một vụ thâu tóm thù địch). Backtrack, backflip là rút lại/đảo ngược lập trường; give ground on là nhượng bộ, trái với việc chống lại cuộc thâu tóm.","extra":[{"en":"poison pill","vi":"chiến lược 'thuốc độc' chống thâu tóm"},
{"en":"hostile bid","vi":"đề nghị thâu tóm thù địch"},
{"en":"white knight","vi":"hiệp sĩ trắng (bên mua thân thiện)"}]},
{"id":"q0223","unit":3,"stem":" During an acquisition, the buyer pays more than the fair value of the target company's identifiable net assets. The excess may be recognized as _____.","options":["Goodwill","Deferred tax","Receivables","Provisions"],"answer":0,"explain":"Phần chênh lệch giữa giá mua và giá trị hợp lý của tài sản ròng có thể xác định được của công ty bị mua được ghi nhận là goodwill (lợi thế thương mại). Deferred tax là thuế hoãn lại; receivables là khoản phải thu; provisions là dự phòng, không phát sinh từ chênh lệch này.","extra":[{"en":"fair value","vi":"giá trị hợp lý"},
{"en":"net assets","vi":"tài sản ròng"},
{"en":"impairment of goodwill","vi":"suy giảm giá trị lợi thế thương mại"}]},
{"id":"q0224","unit":5,"stem":" In the British parliamentary system, legislators who are not government ministers or members of the opposition frontbench are commonly known as the _____.","options":["Coalition","Protagonists","Backbench","Lobby"],"answer":2,"explain":"Backbench gồm các nghị sĩ không giữ chức bộ trưởng hay vị trí lãnh đạo đối lập, ngồi ở hàng ghế sau. Coalition là liên minh chính phủ; protagonists là các bên chính; lobby là nhóm vận động hành lang, không phải nhóm nghị sĩ này.","extra":[{"en":"backbench rebellion","vi":"cuộc nổi dậy của nghị sĩ hàng sau"},
{"en":"opposition party","vi":"đảng đối lập"},
{"en":"Member of Parliament (MP)","vi":"nghị sĩ"}]},
{"id":"q0225","unit":4,"stem":" A company borrows money to finance an investment, expecting that the investment's return will exceed its borrowing cost. It is using financial _____.","options":["Short selling","Leverage","Due diligence","A derivative"],"answer":1,"explain":"Vay tiền để đầu tư với kỳ vọng lợi suất cao hơn chi phí vay là sử dụng đòn bẩy tài chính (leverage). Short selling là bán khống; due diligence là thẩm định; derivative là công cụ phái sinh, không phải việc vay vốn để khuếch đại lợi nhuận.","extra":[{"en":"highly leveraged","vi":"vay nợ nhiều"},
{"en":"cost of borrowing","vi":"chi phí đi vay"},
{"en":"gearing ratio","vi":"tỷ lệ đòn bẩy (nợ/vốn)"}]},
{"id":"q0226","unit":1,"stem":" A manufacturer requires every unit of a product to follow the same approved technical requirements and dimensions. The product is _____.","options":["Identical","Unique","Customized","Standardized"],"answer":3,"explain":"Mọi sản phẩm theo cùng yêu cầu kỹ thuật và kích thước đã được phê duyệt thì là hàng tiêu chuẩn hóa (standardized). Identical là giống hệt nhưng không nhấn mạnh tiêu chuẩn kỹ thuật; unique là độc nhất; customized là làm theo yêu cầu riêng, ngược nghĩa.","extra":[{"en":"technical specifications","vi":"thông số kỹ thuật"},
{"en":"mass-produced","vi":"sản xuất hàng loạt"},
{"en":"uniform quality","vi":"chất lượng đồng đều"}],"needsReview":true},
{"id":"q0227","unit":6,"stem":" A retailer frequently tests new services and reorganizes its teams to respond quickly to changing customer preferences. It is attempting to become more _____.","options":["Embedded","Volatile","Agile","Binding"],"answer":2,"explain":"Agile là nhanh nhẹn, linh hoạt, phản ứng nhanh với thay đổi, hợp với thử nghiệm dịch vụ mới và tổ chức lại nhóm. Embedded là ăn sâu; volatile là biến động; binding là ràng buộc, không mô tả khả năng thích ứng.","extra":[{"en":"customer preferences","vi":"sở thích khách hàng"},
{"en":"adapt to change","vi":"thích ứng với thay đổi"},
{"en":"flexible working","vi":"làm việc linh hoạt"}]},
{"id":"q0228","unit":3,"stem":" A wholesaler has delivered goods to retailers on credit but has not yet received payment. The unpaid amounts are recorded as _____.","options":["Receivables","Cash equivalents","Inventory","Goodwill"],"answer":0,"explain":"Khoản tiền bán chịu chưa thu được được ghi là receivables (khoản phải thu). Cash equivalents là tương đương tiền; inventory là hàng tồn kho; goodwill là lợi thế thương mại, không phải khoản khách hàng nợ.","extra":[{"en":"accounts receivable","vi":"khoản phải thu khách hàng"},
{"en":"sell on credit","vi":"bán chịu"},
{"en":"bad debt","vi":"nợ xấu"}]},
{"id":"q0229","unit":5,"stem":" Researchers compare the average number of years a person is expected to live across different countries. They are studying _____.","options":["Superannuation","Life expectancy","Consumer spending","Waste disposal"],"answer":1,"explain":"Số năm trung bình một người dự kiến sống là life expectancy (tuổi thọ trung bình). Superannuation là quỹ hưu trí; consumer spending là chi tiêu tiêu dùng; waste disposal là xử lý rác thải, không liên quan.","extra":[{"en":"average lifespan","vi":"tuổi thọ trung bình"},
{"en":"demographic trends","vi":"xu hướng nhân khẩu học"},
{"en":"retirement age","vi":"tuổi nghỉ hưu"}]},
{"id":"q0230","unit":1,"stem":" Technicians inspect, clean, and repair factory equipment according to a planned schedule to prevent unexpected stoppages. This is _____.","options":["Capacity planning","Production scheduling","Inventory management","Machine maintenance"],"answer":3,"explain":"Kiểm tra, vệ sinh, sửa chữa thiết bị theo lịch để tránh dừng đột xuất là bảo trì máy (machine maintenance). Capacity planning là hoạch định công suất; production scheduling là lập lịch sản xuất; inventory management là quản lý tồn kho.","extra":[{"en":"preventive maintenance","vi":"bảo trì phòng ngừa"},
{"en":"unplanned downtime","vi":"thời gian ngừng máy ngoài kế hoạch"},
{"en":"breakdown","vi":"hỏng hóc"}]},
{"id":"q0231","unit":5,"stem":" Shareholders were _____ to discover that directors had concealed substantial losses while publicly promising record growth.","options":["dismayed","eligible","embedded","agile"],"answer":0,"explain":"Dismayed là thất vọng, choáng váng khi phát hiện ban giám đốc giấu lỗ. Eligible là đủ điều kiện; embedded là ăn sâu; agile là nhanh nhẹn, không diễn tả cảm xúc của cổ đông.","extra":[{"en":"conceal losses","vi":"che giấu khoản lỗ"},
{"en":"record growth","vi":"tăng trưởng kỷ lục"},
{"en":"shareholder confidence","vi":"niềm tin cổ đông"}]},
{"id":"q0232","unit":6,"stem":" A hotel and an airline agree to advertise each other's services to their respective customers. This marketing technique is called _____.","options":["Joint venture","Take-over","Cross-promotion","Short selling"],"answer":2,"explain":"Cross-promotion là hai bên cùng quảng bá dịch vụ của nhau đến tập khách hàng. Joint venture là liên doanh; take-over là thâu tóm; short selling là bán khống, đều không phải kỹ thuật marketing.","extra":[{"en":"co-branding","vi":"hợp tác thương hiệu"},
{"en":"strategic partnership","vi":"đối tác chiến lược"},
{"en":"loyalty programme","vi":"chương trình khách hàng thân thiết"}]},
{"id":"q0233","unit":3,"stem":" A listed company buys back some of its own issued shares and holds them instead of immediately cancelling them. These are known as _____.","options":["Retained earnings","Receivables","Current assets","Treasury shares"],"answer":3,"explain":"Cổ phiếu công ty mua lại và nắm giữ thay vì hủy ngay là treasury shares (cổ phiếu quỹ). Retained earnings là lợi nhuận giữ lại; receivables là khoản phải thu; current assets là tài sản ngắn hạn, không phải cổ phiếu mua lại.","extra":[{"en":"share repurchase","vi":"mua lại cổ phiếu"},
{"en":"issued shares","vi":"cổ phiếu đã phát hành"},
{"en":"cancel shares","vi":"hủy cổ phiếu"}]},
{"id":"q0234","unit":2,"stem":" The packaging department can process only 400 units per hour, while every other department can process at least 700. The packaging stage is the production _____.","options":["Production yield","Bottleneck","Linear workflow","Value added"],"answer":1,"explain":"Công đoạn chậm nhất (400 đơn vị/giờ) giới hạn toàn bộ dây chuyền nên là điểm nghẽn (bottleneck). Production yield là tỷ lệ đạt; linear workflow là quy trình tuyến tính; value added là giá trị gia tăng, không nói về công đoạn giới hạn năng suất.","extra":[{"en":"remove a bottleneck","vi":"loại bỏ điểm nghẽn"},
{"en":"throughput","vi":"thông lượng"},
{"en":"constraint","vi":"ràng buộc/điểm hạn chế"}]},
{"id":"q0235","unit":3,"stem":" Which category includes short-term, highly liquid investments that can readily be converted into a known amount of cash with insignificant value risk?","options":["Cash equivalents","Receivables","Inventory","Intangible assets"],"answer":0,"explain":"Khoản đầu tư ngắn hạn thanh khoản cao, dễ quy đổi ra tiền xác định và rủi ro giá trị không đáng kể là tương đương tiền (cash equivalents). Receivables là khoản phải thu; inventory là hàng tồn kho; intangible assets là tài sản vô hình, không có tính thanh khoản này.","extra":[{"en":"liquid assets","vi":"tài sản thanh khoản"},
{"en":"money market fund","vi":"quỹ thị trường tiền tệ"},
{"en":"treasury bill","vi":"tín phiếu kho bạc"}]},
{"id":"q0236","unit":6,"stem":" Facing overlapping responsibilities and excessive administrative costs, the company decides to redesign its organizational structure. It plans to _____.","options":["upgrade","relocate","relaunch","restructure"],"answer":3,"explain":"Thiết kế lại cơ cấu tổ chức do trách nhiệm chồng chéo và chi phí hành chính cao là restructure (tái cấu trúc). Upgrade là nâng cấp; relocate là chuyển địa điểm; relaunch là tái ra mắt, không đổi cơ cấu tổ chức.","extra":[{"en":"organizational structure","vi":"cơ cấu tổ chức"},
{"en":"streamline","vi":"tinh giản"},
{"en":"overheads","vi":"chi phí chung"}]},
{"id":"q0237","unit":4,"stem":" Only investors officially recognized by the relevant financial regulator and meeting specified qualification criteria may participate in this private offering. They must be _____.","options":["Prospective","Eligible","Accredited","Outstanding"],"answer":2,"explain":"Accredited investor là nhà đầu tư được cơ quan quản lý công nhận và đáp ứng tiêu chí về trình độ/tài sản. Eligible chỉ chung chung là đủ điều kiện; prospective là tiềm năng; outstanding là xuất sắc hoặc còn tồn đọng, không nêu việc được công nhận chính thức.","extra":[{"en":"private placement","vi":"phát hành riêng lẻ"},
{"en":"qualified investor","vi":"nhà đầu tư đủ điều kiện"},
{"en":"financial regulator","vi":"cơ quan quản lý tài chính"}],"needsReview":true},
{"id":"q0238","unit":1,"stem":" After transforming raw timber into finished furniture, a manufacturer can sell the furniture for much more than the cost of the original materials. The process has created _____.","options":["Conversion","Value added","Downtime","Lead time"],"answer":1,"explain":"Biến gỗ thô thành đồ nội thất bán được giá cao hơn nhiều chi phí nguyên liệu là tạo ra giá trị gia tăng (value added). Conversion là chuyển đổi (không nêu phần giá trị tăng thêm); downtime là thời gian ngừng máy; lead time là thời gian chờ.","extra":[{"en":"finished goods","vi":"thành phẩm"},
{"en":"raw materials","vi":"nguyên liệu thô"},
{"en":"profit margin","vi":"biên lợi nhuận"}],"needsReview":true},
{"id":"q0239","unit":3,"stem":" In Australia, employers commonly contribute to employees' retirement savings accounts under a system known as _____.","options":["Superannuation","Life expectancy","Deferred tax","Consumer spending"],"answer":0,"explain":"Superannuation là hệ thống quỹ hưu trí ở Úc, nơi người sử dụng lao động đóng góp vào tài khoản tiết kiệm hưu trí của nhân viên. Life expectancy là tuổi thọ; deferred tax là thuế hoãn lại; consumer spending là chi tiêu tiêu dùng, không phải hệ thống hưu trí.","extra":[{"en":"pension fund","vi":"quỹ hưu trí"},
{"en":"employer contribution","vi":"khoản đóng góp của người sử dụng lao động"},
{"en":"retirement savings","vi":"tiết kiệm hưu trí"}]},
{"id":"q0240","unit":6,"stem":" To remain financially viable after demand falls, a retailer plans to close several underperforming branches and reduce its workforce. It intends to _____.","options":["downgrade","decentralize","downsize","reassess"],"answer":2,"explain":"Đóng chi nhánh kém hiệu quả và cắt giảm nhân sự là downsize (thu hẹp quy mô). Downgrade là hạ cấp; decentralize là phân quyền; reassess là đánh giá lại, không bao hàm việc cắt giảm.","extra":[{"en":"underperforming branch","vi":"chi nhánh kém hiệu quả"},
{"en":"lay off staff","vi":"sa thải nhân viên"},
{"en":"financially viable","vi":"khả thi về mặt tài chính"}]},
{"id":"q0241","unit":3,"stem":" A company has an existing obligation arising from past events, and settling it is expected to require an outflow of economic resources. This is a _____.","options":["Provision","Equity","Current asset","Liability"],"answer":3,"explain":"Nghĩa vụ hiện tại phát sinh từ sự kiện quá khứ, việc thanh toán dẫn đến dòng ra của nguồn lực kinh tế là định nghĩa của liability (nợ phải trả). Provision là một loại nợ có thời điểm hoặc số tiền không chắc chắn; equity là vốn chủ; current asset là tài sản, nên sai.","extra":[{"en":"present obligation","vi":"nghĩa vụ hiện tại"},
{"en":"contingent liability","vi":"nợ tiềm tàng"},
{"en":"outflow of resources","vi":"dòng ra của nguồn lực"}],"needsReview":true},
{"id":"q0242","unit":6,"stem":" A premium coffee chain adjusts its locations and products to better serve its established group of regular customers. This group is its _____.","options":["Stakeholders","Clientele","Protagonists","Backbench"],"answer":1,"explain":"Clientele là tập khách hàng quen thuộc của một doanh nghiệp. Stakeholders là các bên liên quan nói chung; protagonists là các bên chính trong tranh chấp; backbench là hàng ghế sau nghị viện, không phải nhóm khách hàng.","extra":[{"en":"regular customers","vi":"khách hàng quen"},
{"en":"customer base","vi":"tập khách hàng"},
{"en":"cater for a clientele","vi":"phục vụ một tập khách hàng"}]},
{"id":"q0243","unit":4,"stem":" Before completing an acquisition, the buyer examines the target's contracts, financial records, legal disputes, and operational risks. This investigation is called _____.","options":["Auditing","Bookkeeping","Due diligence","Performance measurement"],"answer":2,"explain":"Due diligence là quá trình thẩm định kỹ hợp đồng, sổ sách, tranh chấp pháp lý và rủi ro vận hành của công ty mục tiêu trước khi mua. Auditing là kiểm toán báo cáo tài chính; bookkeeping là ghi sổ; performance measurement là đo hiệu suất, không bao quát như thẩm định thương vụ.","extra":[{"en":"conduct due diligence","vi":"tiến hành thẩm định"},
{"en":"target company","vi":"công ty mục tiêu"},
{"en":"legal disputes","vi":"tranh chấp pháp lý"}]},
{"id":"q0244","unit":7,"stem":" A business reports an accounting profit but struggles to pay its suppliers because receipts and payments occur at different times. Which concept best explains this situation?","options":["Cash flow","Return on investment","Principal","Equity"],"answer":0,"explain":"Cash flow (dòng tiền) giải thích vì sao doanh nghiệp có lợi nhuận kế toán nhưng thiếu tiền trả nhà cung cấp do thời điểm thu và chi lệch nhau. ROI là tỷ suất sinh lời; principal là tiền gốc; equity là vốn chủ, không giải thích vấn đề thanh khoản này.","extra":[{"en":"cash flow forecast","vi":"dự báo dòng tiền"},
{"en":"cash flow problem","vi":"vấn đề dòng tiền"},
{"en":"working capital","vi":"vốn lưu động"}]},
{"id":"q0245","unit":6,"stem":" International tourists _____ a significant proportion of the resort's customers during the peak season.","options":["cater to","make up","offset","give ground on"],"answer":1,"explain":"Make up nghĩa là chiếm, cấu thành (một tỷ lệ). Cater to là phục vụ, đáp ứng; offset là bù đắp; give ground on là nhượng bộ, không hợp nghĩa \"chiếm một phần đáng kể khách hàng\".","extra":[{"en":"account for","vi":"chiếm (tỷ lệ)"},
{"en":"peak season","vi":"mùa cao điểm"},
{"en":"customer base","vi":"tập khách hàng"}]},
{"id":"q0246","unit":1,"stem":" The production manager decides which orders will be manufactured first and allocates start and completion times. This activity is called _____.","options":["Capacity planning","Inventory management","Performance measurement","Production scheduling"],"answer":3,"explain":"Quyết định đơn hàng nào sản xuất trước và ấn định thời gian bắt đầu, hoàn thành là lập lịch sản xuất (production scheduling). Capacity planning là hoạch định công suất; inventory management là quản lý tồn kho; performance measurement là đo hiệu suất.","extra":[{"en":"prioritize orders","vi":"ưu tiên đơn hàng"},
{"en":"production schedule","vi":"lịch sản xuất"},
{"en":"meet a deadline","vi":"kịp hạn chót"}]},
{"id":"q0247","unit":2,"stem":" The audit identifies weaknesses in internal controls, but consultants believe they can be corrected through training and revised procedures. The weaknesses are _____.","options":["Remediable","Volatile","Prospective","Blatant"],"answer":0,"explain":"Remediable nghĩa là có thể khắc phục được, hợp với việc sửa bằng đào tạo và quy trình mới. Volatile là biến động; prospective là tiềm năng; blatant là trắng trợn, không nói về khả năng sửa chữa.","extra":[{"en":"remedial action","vi":"hành động khắc phục"},
{"en":"internal controls","vi":"kiểm soát nội bộ"},
{"en":"corrective measures","vi":"biện pháp sửa chữa"}]},
{"id":"q0248","unit":4,"stem":" An investor borrows shares, sells them immediately, and hopes to buy them back later at a lower price before returning them. This strategy is _____.","options":["Leverage","Take-over","Short selling","Cross-promotion"],"answer":2,"explain":"Mượn cổ phiếu, bán ngay và hy vọng mua lại giá thấp hơn để trả là bán khống (short selling). Leverage là đòn bẩy vay vốn; take-over là thâu tóm; cross-promotion là quảng bá chéo, không phải chiến lược đầu cơ giá giảm.","extra":[{"en":"bearish outlook","vi":"kỳ vọng giá giảm"},
{"en":"cover a short position","vi":"đóng vị thế bán khống"},
{"en":"speculate","vi":"đầu cơ"}]},
{"id":"q0249","unit":6,"stem":" The human-resources department tracks the proportion of employees who leave the organization and must be replaced each year. It measures employee _____.","options":["Exposure","Turnover","Clientele","Performance yield"],"answer":1,"explain":"Employee turnover là tỷ lệ nhân viên nghỉ việc phải thay thế mỗi năm. Exposure là mức độ rủi ro; clientele là tập khách hàng; performance yield không phải thuật ngữ đo việc nghỉ việc.","extra":[{"en":"staff retention","vi":"giữ chân nhân viên"},
{"en":"attrition rate","vi":"tỷ lệ hao hụt nhân sự"},
{"en":"recruitment drive","vi":"đợt tuyển dụng"}]},
{"id":"q0250","unit":5,"stem":" An agreement states that both parties must comply with an arbitration decision and neither may disregard the clause unilaterally. The clause is legally _____.","options":["Identical","Standardized","Specified","Bindin"],"answer":3,"explain":"Điều khoản mà các bên phải tuân thủ và không được tự ý bỏ qua là có tính ràng buộc pháp lý (binding). Identical là giống hệt; standardized là chuẩn hóa; specified là được nêu rõ, không diễn tả tính bắt buộc.","extra":[{"en":"legally binding","vi":"có giá trị ràng buộc pháp lý"},
{"en":"arbitration clause","vi":"điều khoản trọng tài"},
{"en":"breach of contract","vi":"vi phạm hợp đồng"}],"needsReview":true},
{"id":"q0251","unit":2,"stem":"A factory produces 15,000 components per day, but only 14,100 meet all technical requirements. Which metric measures the proportion of acceptable output?","options":["Capacity planning","Production yield","Line efficiency","Quality assurance"],"answer":1,"explain":"Tỷ lệ sản phẩm đạt yêu cầu trên tổng sản lượng (14.100/15.000) là production yield. Capacity planning là hoạch định công suất; line efficiency là hiệu suất dây chuyền; quality assurance là hệ thống đảm bảo chất lượng, không phải một tỷ lệ đầu ra.","extra":[{"en":"defective units","vi":"sản phẩm lỗi"},
{"en":"output rate","vi":"tốc độ sản lượng"},
{"en":"technical requirements","vi":"yêu cầu kỹ thuật"}]},
{"id":"q0252","unit":3,"stem":" A company suspects that its finance director has deliberately manipulated invoices and concealed fraudulent payments. Which specialist field would be most appropriate for investigating the suspected misconduct?","options":["Bookkeeping","Tax accounting","Forensic accounting","Managerial accounting"],"answer":2,"explain":"Điều tra nghi vấn thao túng hóa đơn và che giấu thanh toán gian lận cần kế toán pháp y (forensic accounting). Bookkeeping là ghi sổ; tax accounting là kế toán thuế; managerial accounting là kế toán quản trị, không chuyên điều tra gian lận.","extra":[{"en":"manipulate invoices","vi":"làm giả hóa đơn"},
{"en":"financial misconduct","vi":"sai phạm tài chính"},
{"en":"embezzlement","vi":"biển thủ"}]},
{"id":"q0253","unit":5,"stem":" A mature business division consistently generates enough profit to finance several experimental projects elsewhere in the company. It functions as a _____.","options":["Mutual fund","Cash cow","Joint venture","Financial backer"],"answer":1,"explain":"Bộ phận trưởng thành luôn sinh đủ lợi nhuận để tài trợ cho các dự án thử nghiệm là cash cow. Mutual fund là quỹ tương hỗ; joint venture là liên doanh; financial backer là bên tài trợ bên ngoài, không phải bộ phận nội bộ sinh lời.","extra":[{"en":"stable revenue stream","vi":"nguồn doanh thu ổn định"},
{"en":"cross-subsidize","vi":"trợ cấp chéo"},
{"en":"experimental projects","vi":"dự án thử nghiệm"}]},
{"id":"q0254","unit":5,"stem":" In response to rising industrial pollution, the authorities decided to _____ a special tax on factories that exceed the emissions threshold.","options":["offset","replenish","impose","recoup"],"answer":2,"explain":"Impose a tax nghĩa là áp đặt một loại thuế lên đối tượng. Offset là bù đắp; replenish là bổ sung hàng tồn; recoup là thu hồi, không hợp với việc chính quyền ban hành thuế.","extra":[{"en":"pollution tax","vi":"thuế ô nhiễm"},
{"en":"emissions threshold","vi":"ngưỡng khí thải"},
{"en":"crack down on","vi":"siết chặt xử lý"}]},
{"id":"q0255","unit":3,"stem":" A registered trademark gives its owner legal rights and may have significant commercial value despite having no physical form. It is classified as an _____.","options":["Intangible asset","Cash equivalent","Current liability","Inventory item"],"answer":0,"explain":"Nhãn hiệu đã đăng ký có giá trị thương mại nhưng không có hình thái vật chất nên là tài sản vô hình (intangible asset). Cash equivalent là tương đương tiền; current liability là nợ ngắn hạn; inventory item là hàng tồn kho, đều không phải tài sản vô hình.","extra":[{"en":"registered trademark","vi":"nhãn hiệu đã đăng ký"},
{"en":"brand equity","vi":"giá trị thương hiệu"},
{"en":"licensing agreement","vi":"hợp đồng cấp phép"}]},
{"id":"q0256","unit":2,"stem":" The warehouse manager discovered that several essential materials were running out and instructed the purchasing team to _____ the stocks immediately.","options":["decelerate","relocate","downgrade","replenish"],"answer":3,"explain":"Replenish là bổ sung ngay nguyên liệu đang cạn. Decelerate là làm chậm; relocate là chuyển địa điểm; downgrade là hạ cấp, không hợp nghĩa việc nhập thêm hàng.","extra":[{"en":"running low","vi":"sắp hết"},
{"en":"place an order","vi":"đặt hàng"},
{"en":"stock shortage","vi":"thiếu hàng tồn"}]},
{"id":"q0257","unit":4,"stem":" A corporation purchases a controlling shareholding in another company and subsequently takes charge of its strategic decisions. This is a _____.","options":["Take-over","Joint venture","Cross-promotion","Merger of equals"],"answer":0,"explain":"Mua cổ phần chi phối rồi nắm quyền quyết định chiến lược của công ty khác là take-over (thâu tóm). Joint venture là liên doanh; cross-promotion là quảng bá chéo; merger of equals là sáp nhập ngang bằng, hai bên không bên nào nắm quyền kiểm soát.","extra":[{"en":"controlling shareholding","vi":"cổ phần chi phối"},
{"en":"acquire a stake","vi":"mua một phần cổ phần"},
{"en":"strategic decisions","vi":"quyết định chiến lược"}]},
{"id":"q0258","unit":5,"stem":" The finance minister initially rejected the proposed budget cuts but later had to _____ after facing strong opposition from coalition partners.","options":["back down","backtrack","backflip","give ground on"],"answer":0,"explain":"Back down là nhượng bộ, rút lui lập trường sau áp lực mạnh từ các đối tác liên minh. Backtrack là rút lại điều đã nói; backflip là đảo ngược hẳn; give ground on cần giới từ \"on\" theo sau, không phù hợp cấu trúc câu.","extra":[{"en":"coalition partners","vi":"đối tác liên minh"},
{"en":"budget cuts","vi":"cắt giảm ngân sách"},
{"en":"strong opposition","vi":"sự phản đối mạnh mẽ"}],"needsReview":true},
{"id":"q0259","unit":1,"stem":" A chemical plant operates around the clock, transforming raw materials into a uniform product without interrupting the production process. This is an example of _____.","options":["Batch production","Unit production","Continuous production","Mass customization"],"answer":2,"explain":"Nhà máy hóa chất chạy suốt ngày đêm, không gián đoạn quy trình, là continuous production. Batch production là sản xuất theo lô; unit production là làm từng chiếc; mass customization là sản xuất hàng loạt có tùy biến, không liên tục như vậy.","extra":[{"en":"process industry","vi":"ngành sản xuất quy trình"},
{"en":"round-the-clock operation","vi":"vận hành suốt 24 giờ"},
{"en":"uniform product","vi":"sản phẩm đồng nhất"}]},
{"id":"q0260","unit":3,"stem":" A company recognizes a tax expense in its financial statements even though the corresponding tax payment will occur in a later accounting period. Which concept is relevant?","options":["Goodwill","Receivables","Deferred tax","Treasury shares"],"answer":2,"explain":"Chi phí thuế được ghi nhận trong báo cáo nhưng thanh toán ở kỳ sau là thuế hoãn lại (deferred tax). Goodwill là lợi thế thương mại; receivables là khoản phải thu; treasury shares là cổ phiếu quỹ, không liên quan thời điểm nộp thuế.","extra":[{"en":"tax payable","vi":"thuế phải nộp"},
{"en":"accounting period","vi":"kỳ kế toán"},
{"en":"deferred tax liability","vi":"thuế thu nhập hoãn lại phải trả"}]},
{"id":"q0261","unit":4,"stem":" An individual purchases government bonds and is entitled to receive the agreed interest and repayment of the debt. In relation to these securities, the individual is a _____.","options":["Creditor","Financial backer","Principal","Bondholder"],"answer":3,"explain":"Người mua trái phiếu chính phủ và được nhận lãi, hoàn nợ gốc là bondholder (người nắm giữ trái phiếu). Creditor là chủ nợ nói chung; financial backer là bên tài trợ; principal là tiền gốc, không phải người đầu tư.","extra":[{"en":"government bond","vi":"trái phiếu chính phủ"},
{"en":"fixed-income security","vi":"chứng khoán thu nhập cố định"},
{"en":"redeem a bond","vi":"mua lại trái phiếu"}],"needsReview":true},
{"id":"q0262","unit":2,"stem":" A manufacturer introduces preventive procedures at every production stage to reduce the likelihood of defects before products reach the final inspection department. This approach is called _____.","options":["Performance measurement","Auditing","Production yield","Quality assurance"],"answer":3,"explain":"Áp dụng quy trình phòng ngừa ở mọi công đoạn để giảm lỗi trước kiểm tra cuối là quality assurance. Performance measurement là đo hiệu suất; auditing là kiểm toán; production yield là tỷ lệ đạt, không phải quy trình phòng ngừa.","extra":[{"en":"preventive measures","vi":"biện pháp phòng ngừa"},
{"en":"final inspection","vi":"kiểm tra cuối cùng"},
{"en":"total quality management","vi":"quản lý chất lượng toàn diện"}]},
{"id":"q0263","unit":6,"stem":" A retail chain gives regional managers greater authority to make pricing and staffing decisions rather than requiring approval from the head office. The company is attempting to _____.","options":["downsize","restructure","decentralize","relocate"],"answer":2,"explain":"Trao cho quản lý khu vực quyền quyết định giá và nhân sự thay vì chờ trụ sở duyệt là decentralize (phân quyền). Downsize là thu hẹp quy mô; restructure là tái cấu trúc chung; relocate là chuyển địa điểm.","extra":[{"en":"delegate decisions","vi":"ủy quyền ra quyết định"},
{"en":"regional managers","vi":"quản lý khu vực"},
{"en":"flatter hierarchy","vi":"cơ cấu phẳng hơn"}]},
{"id":"q0264","unit":1,"stem":" A manufacturer forecasts future demand and determines whether its existing factories and machinery can produce enough units to meet that demand. This is an exercise in _____.","options":["Capacity planning","Production scheduling","Machine maintenance","Inventory management"],"answer":0,"explain":"Dự báo nhu cầu và xem nhà máy, máy móc hiện có đủ sản xuất hay không là hoạch định công suất (capacity planning). Production scheduling là lập lịch; machine maintenance là bảo trì; inventory management là quản lý tồn kho.","extra":[{"en":"demand forecast","vi":"dự báo nhu cầu"},
{"en":"production capacity","vi":"năng lực sản xuất"},
{"en":"meet demand","vi":"đáp ứng nhu cầu"}]},
{"id":"q0265","unit":5,"stem":" An unexpected political crisis causes the prices of essential commodities to fluctuate sharply. These prices are described as _____.","options":["volatile","embedded","identical","binding"],"answer":0,"explain":"volatile = biến động mạnh, thất thường; hợp với giá cả dao động sharply. 'embedded' là ăn sâu, 'identical' là giống hệt, 'binding' là có tính ràng buộc nên không mô tả giá cả.","extra":[{"en":"volatile market","vi":"thị trường biến động"},
{"en":"price fluctuation","vi":"biến động giá"},
{"en":"commodity prices","vi":"giá hàng hóa"}]},
{"id":"q0266","unit":6,"stem":" Applicants who satisfy the income and business-size requirements are _____ a government-backed financing scheme for small enterprises.","options":["opposed to","dismayed by","attributable to","eligible for"],"answer":3,"explain":"be eligible for = đủ điều kiện nhận/hưởng, hợp với 'satisfy the requirements'. 'opposed to' là phản đối, 'dismayed by' là thất vọng, 'attributable to' là có thể quy cho nguyên nhân nào đó.","extra":[{"en":"eligibility criteria","vi":"tiêu chí đủ điều kiện"},
{"en":"government-backed loan","vi":"khoản vay được chính phủ bảo lãnh"},
{"en":"SME (small and medium enterprise)","vi":"doanh nghiệp vừa và nhỏ"}]},
{"id":"q0267","unit":5,"stem":" A company cannot immediately eliminate all of its industrial emissions, so it purchases environmental credits to _____ the remaining impact.","options":["dump","offset","recoup","impose"],"answer":1,"explain":"offset = bù đắp, cân bằng (tác động môi trường bằng tín chỉ carbon). 'dump' là vứt bỏ, 'recoup' là thu hồi khoản đã mất, 'impose' là áp đặt; đều không hợp nghĩa mua tín chỉ để bù.","extra":[{"en":"carbon offset","vi":"bù đắp carbon"},
{"en":"carbon footprint","vi":"dấu chân carbon"},
{"en":"net zero emissions","vi":"phát thải ròng bằng không"}]},
{"id":"q0268","unit":6,"stem":" A laptop manufacturer designs a docking station that expands the functionality of its laptops. The two products _____ each other.","options":["complement","substitute","capture","upgrade"],"answer":0,"explain":"complement = bổ sung cho nhau: docking station làm tăng chức năng laptop. 'substitute' là sản phẩm thay thế nhau (cạnh tranh), 'capture' là giành lấy, 'upgrade' là nâng cấp, không diễn tả quan hệ hai sản phẩm.","extra":[{"en":"complementary goods","vi":"hàng hóa bổ sung"},
{"en":"substitute goods","vi":"hàng hóa thay thế"},
{"en":"product range","vi":"dòng sản phẩm"}]},
{"id":"q0269","unit":4,"stem":" When reviewing a mortgage agreement, borrowers should check the original amount of money borrowed separately from the interest charged. The original amount is the _____.","options":["Interest rate","Principal","Leverage","Return on investment"],"answer":1,"explain":"principal = số tiền gốc vay ban đầu, tách khỏi tiền lãi. 'Interest rate' là lãi suất, 'Leverage' là đòn bẩy tài chính, 'Return on investment' là tỷ suất sinh lời đầu tư.","extra":[{"en":"principal and interest","vi":"gốc và lãi"},
{"en":"outstanding balance","vi":"dư nợ còn lại"},
{"en":"repayment schedule","vi":"lịch trả nợ"}]},
{"id":"q0270","unit":6,"stem":" Although the company officially introduced new workplace rules, long-established informal practices remained deeply integrated into its organizational culture. These practices were _____.","options":["Standardized","Prospective","Agile","Embedded"],"answer":3,"explain":"embedded = ăn sâu, gắn chặt vào văn hóa tổ chức. 'Standardized' là được tiêu chuẩn hóa (chính thức), 'Prospective' là tiềm năng, 'Agile' là linh hoạt; không diễn tả thói quen ăn sâu.","extra":[{"en":"embedded culture","vi":"văn hóa ăn sâu"},
{"en":"informal practices","vi":"thông lệ phi chính thức"},
{"en":"resistance to change","vi":"sự kháng cự thay đổi"}]},
{"id":"q0271","unit":2,"stem":" A logistics department tracks stock movements, records deliveries, monitors warehouse quantities and arranges replacement orders. These tasks are part of _____.","options":["Production scheduling","Machine maintenance","Capacity planning","Inventory management"],"answer":3,"explain":"inventory management = quản lý tồn kho: theo dõi hàng, giao nhận, số lượng kho, đặt hàng bổ sung. 'Production scheduling' là lập lịch sản xuất, 'Machine maintenance' là bảo trì máy, 'Capacity planning' là hoạch định công suất.","extra":[{"en":"stock control","vi":"kiểm soát hàng tồn"},
{"en":"reorder level","vi":"mức đặt hàng lại"},
{"en":"warehouse management","vi":"quản lý kho"}]},
{"id":"q0272","unit":5,"stem":" The board established a series of financial and legal defenses in an attempt to _____ an unwanted acquisition by a competitor.","options":["backtrack","fend off","backflip","back down"],"answer":1,"explain":"fend off = chống đỡ, ngăn chặn (cuộc thôn tính). 'backtrack', 'backflip', 'back down' đều nghĩa là rút lại ý kiến/nhượng bộ, không phải ngăn chặn đối thủ.","extra":[{"en":"hostile takeover","vi":"thâu tóm thù địch"},
{"en":"poison pill","vi":"thuốc độc (biện pháp phòng thủ)"},
{"en":"white knight","vi":"hiệp sĩ trắng (bên mua thân thiện)"}]},
{"id":"q0273","unit":3,"stem":" A company acquires another business for a price exceeding the fair value of its identifiable net assets. The excess purchase consideration may be recorded as _____.","options":["Provisions","Receivables","Inventory","Goodwill"],"answer":3,"explain":"goodwill = lợi thế thương mại, phần giá mua vượt giá trị hợp lý của tài sản ròng xác định được. 'Provisions' là khoản dự phòng, 'Receivables' là khoản phải thu, 'Inventory' là hàng tồn kho.","extra":[{"en":"fair value","vi":"giá trị hợp lý"},
{"en":"identifiable net assets","vi":"tài sản ròng xác định được"},
{"en":"goodwill impairment","vi":"suy giảm lợi thế thương mại"}]},
{"id":"q0274","unit":5,"stem":" In the UK Parliament, ordinary members who do not hold ministerial or senior opposition positions are commonly referred to as the _____.","options":["Backbench","Protagonists","Coalition","Lobby"],"answer":0,"explain":"backbench = các nghị sĩ 'hàng ghế sau', không giữ chức vụ bộ trưởng/đối lập cấp cao. 'Protagonists' là nhân vật chính/người ủng hộ, 'Coalition' là liên minh cầm quyền, 'Lobby' là nhóm vận động hành lang.","extra":[{"en":"backbencher","vi":"nghị sĩ hàng ghế sau"},
{"en":"frontbench","vi":"hàng ghế trước (lãnh đạo)"},
{"en":"cabinet minister","vi":"bộ trưởng nội các"}]},
{"id":"q0275","unit":4,"stem":" A firm uses borrowed capital to increase the potential return on shareholders' investment. This financial strategy involves _____.","options":["Due diligence","Derivative trading","Short selling","Leverage"],"answer":3,"explain":"leverage = đòn bẩy tài chính: dùng vốn vay để tăng lợi suất cho cổ đông. 'Due diligence' là thẩm định, 'Derivative trading' là giao dịch phái sinh, 'Short selling' là bán khống.","extra":[{"en":"highly leveraged","vi":"vay nợ nhiều"},
{"en":"debt-to-equity ratio","vi":"tỷ lệ nợ trên vốn chủ"},
{"en":"gearing","vi":"tỷ lệ đòn bẩy (Anh)"}]},
{"id":"q0276","unit":2,"stem":" A pharmaceutical company requires every package of a particular medicine to follow the same approved measurements, ingredients and production requirements. The product is _____.","options":["Identical","Standardized","Unique","Customized"],"answer":1,"explain":"standardized = được tiêu chuẩn hóa: mọi gói theo cùng quy cách, thành phần, yêu cầu sản xuất. 'Identical' chỉ giống hệt nói chung, 'Unique' là độc nhất, 'Customized' là tùy chỉnh theo khách; hai từ sau trái ý.","extra":[{"en":"standardized procedure","vi":"quy trình chuẩn hóa"},
{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"regulatory approval","vi":"phê duyệt của cơ quan quản lý"}]},
{"id":"q0277","unit":6,"stem":" A business regularly adapts its procedures and quickly reallocates employees when customer preferences change. The organization is becoming more _____.","options":["volatile","embedded","agile","binding"],"answer":2,"explain":"agile = nhanh nhẹn, thích ứng linh hoạt khi nhu cầu khách thay đổi. 'volatile' là biến động bất ổn, 'embedded' là ăn sâu, 'binding' là ràng buộc; đều không mô tả khả năng thích ứng.","extra":[{"en":"agile organization","vi":"tổ chức linh hoạt"},
{"en":"respond to market changes","vi":"phản ứng với thay đổi thị trường"},
{"en":"flexible workforce","vi":"lực lượng lao động linh hoạt"}]},
{"id":"q0278","unit":3,"stem":" A manufacturer has supplied goods to customers on credit, but the customers have not yet paid their invoices. These outstanding amounts are recorded as _____.","options":["Receivables","Cash equivalents","Inventory","Equity"],"answer":0,"explain":"receivables = các khoản phải thu từ khách hàng mua chịu. 'Cash equivalents' là tương đương tiền, 'Inventory' là hàng tồn, 'Equity' là vốn chủ sở hữu; không phải khoản khách chưa trả.","extra":[{"en":"accounts receivable","vi":"các khoản phải thu"},
{"en":"bad debt","vi":"nợ khó đòi"},
{"en":"overdue invoice","vi":"hóa đơn quá hạn"}]},
{"id":"q0279","unit":6,"stem":" A government compares the average number of years people are expected to live in different regions to assess changes in public health. It is examining _____.","options":["Superannuation","Consumer spending","Waste disposal","Life expectancy"],"answer":3,"explain":"life expectancy = tuổi thọ trung bình. 'Superannuation' là quỹ lương hưu, 'Consumer spending' là chi tiêu tiêu dùng, 'Waste disposal' là xử lý rác thải.","extra":[{"en":"ageing population","vi":"dân số già hóa"},
{"en":"public health","vi":"sức khỏe cộng đồng"},
{"en":"demographic trends","vi":"xu hướng nhân khẩu học"}]},
{"id":"q0280","unit":1,"stem":" To prevent equipment breakdowns, engineers regularly inspect, lubricate and repair machines according to a preventive schedule. These activities constitute _____.","options":["Capacity planning","Machine maintenance","Production scheduling","Quality assurance"],"answer":1,"explain":"machine maintenance = bảo trì máy móc: kiểm tra, bôi trơn, sửa chữa định kỳ để tránh hỏng hóc. 'Capacity planning' là hoạch định công suất, 'Production scheduling' là lập lịch, 'Quality assurance' là đảm bảo chất lượng sản phẩm.","extra":[{"en":"preventive maintenance","vi":"bảo trì phòng ngừa"},
{"en":"breakdown","vi":"sự cố hỏng máy"},
{"en":"downtime","vi":"thời gian ngừng máy"}]},
{"id":"q0281","unit":5,"stem":" The company's employees were _____ to learn that management had concealed significant financial losses from investors.","options":["Blatant","Compromised","Dismayed","Eligible"],"answer":2,"explain":"dismayed = thất vọng, sốc khi biết tin xấu; hợp với việc ban quản lý che giấu thua lỗ. 'Blatant' là trắng trợn (không mô tả người), 'Compromised' là bị tổn hại, 'Eligible' là đủ điều kiện.","extra":[{"en":"be dismayed at","vi":"thất vọng vì"},
{"en":"conceal losses","vi":"che giấu thua lỗ"},
{"en":"breach of trust","vi":"vi phạm lòng tin"}]},
{"id":"q0282","unit":6,"stem":" A hotel and a travel agency cooperate by displaying each other's promotional materials and recommending their services to customers. This is an example of _____.","options":["Joint venture","Cross-promotion","Acquisition","Exposure"],"answer":1,"explain":"cross-promotion = quảng bá chéo: hai doanh nghiệp quảng bá cho nhau. 'Joint venture' là liên doanh lập pháp nhân chung, 'Acquisition' là mua lại, 'Exposure' là mức độ được biết đến.","extra":[{"en":"strategic partnership","vi":"đối tác chiến lược"},
{"en":"brand awareness","vi":"mức độ nhận biết thương hiệu"},
{"en":"co-branding","vi":"đồng thương hiệu"}]},
{"id":"q0283","unit":3,"stem":" A corporation purchases its own shares from existing shareholders and holds them instead of immediately cancelling them. These shares are called _____.","options":["Retained earnings","Equity","Current assets","Treasury shares"],"answer":3,"explain":"treasury shares = cổ phiếu quỹ, công ty mua lại từ cổ đông và giữ lại chưa hủy. 'Retained earnings' là lợi nhuận giữ lại, 'Equity' là vốn chủ sở hữu, 'Current assets' là tài sản ngắn hạn.","extra":[{"en":"share buyback","vi":"mua lại cổ phiếu"},
{"en":"issued share capital","vi":"vốn cổ phần đã phát hành"},
{"en":"dividend payout","vi":"chi trả cổ tức"}]},
{"id":"q0284","unit":2,"stem":" A factory's inspection department can examine only 300 products per hour, while the other departments can process 600 products per hour. The inspection department has become a production _____.","options":["Linear workflow","Production yield","Production bottleneck","Value added"],"answer":2,"explain":"bottleneck = nút thắt cổ chai: bộ phận công suất thấp nhất (300/giờ) giới hạn cả dây chuyền. 'Linear workflow' là quy trình tuyến tính, 'Production yield' là sản lượng đạt chuẩn, 'Value added' là giá trị gia tăng.","extra":[{"en":"remove the bottleneck","vi":"gỡ nút thắt"},
{"en":"throughput","vi":"thông lượng"},
{"en":"production capacity","vi":"công suất sản xuất"}]},
{"id":"q0285","unit":3,"stem":" Which of the following refers to short-term investments that are highly liquid and can be converted into a known amount of cash with insignificant risk of value changes?","options":["Receivables","Inventory","Cash equivalents","Intangible assets"],"answer":2,"explain":"cash equivalents = tương đương tiền: đầu tư ngắn hạn thanh khoản cao, chuyển thành tiền mặt dễ dàng với rủi ro thấp. 'Receivables' là khoản phải thu, 'Inventory' là hàng tồn, 'Intangible assets' là tài sản vô hình.","extra":[{"en":"liquid assets","vi":"tài sản thanh khoản"},
{"en":"short-term investment","vi":"đầu tư ngắn hạn"},
{"en":"balance sheet","vi":"bảng cân đối kế toán"}]},
{"id":"q0286","unit":6,"stem":" After identifying duplicated managerial roles and inefficient reporting relationships, a company decides to redesign its organizational structure. It plans to _____.","options":["Restructure","Upgrade","Relocate","Decentralize"],"answer":0,"explain":"restructure = tái cấu trúc, thiết kế lại cơ cấu tổ chức khi có vai trò trùng lặp. 'Upgrade' là nâng cấp, 'Relocate' là chuyển địa điểm, 'Decentralize' là phân quyền, không bao quát việc loại bỏ vai trò trùng lặp và sửa quan hệ báo cáo.","extra":[{"en":"reporting line","vi":"tuyến báo cáo"},
{"en":"streamline operations","vi":"tinh giản hoạt động"},
{"en":"organizational chart","vi":"sơ đồ tổ chức"}]},
{"id":"q0287","unit":4,"stem":" A private investment opportunity is available only to investors formally recognized as meeting specific regulatory financial qualifications. These investors must be _____.","options":["Accredited","Prospective","Outstanding","Premium"],"answer":0,"explain":"accredited investor = nhà đầu tư được công nhận đủ điều kiện tài chính theo quy định. 'Prospective' là tiềm năng, 'Outstanding' là xuất sắc/còn tồn đọng, 'Premium' là cao cấp; không mang nghĩa được công nhận chính thức.","extra":[{"en":"accredited investor","vi":"nhà đầu tư được công nhận"},
{"en":"private placement","vi":"phát hành riêng lẻ"},
{"en":"regulatory requirements","vi":"yêu cầu pháp lý"}]},
{"id":"q0288","unit":2,"stem":" A furniture manufacturer transforms inexpensive timber into finished products that command a much higher selling price. The manufacturing process creates _____.","options":["Conversion","Value added","Downtime","Lead time"],"answer":1,"explain":"value added = giá trị gia tăng: biến gỗ rẻ thành sản phẩm bán giá cao hơn nhiều. 'Conversion' là sự chuyển đổi (không nhấn vào giá trị tạo thêm), 'Downtime' là thời gian ngừng máy, 'Lead time' là thời gian từ đặt hàng đến giao hàng.","extra":[{"en":"add value","vi":"tạo thêm giá trị"},
{"en":"raw materials","vi":"nguyên liệu thô"},
{"en":"finished goods","vi":"thành phẩm"}]},
{"id":"q0289","unit":6,"stem":" In Australia, employer contributions to workers' retirement savings are commonly associated with the system of _____.","options":["Life expectancy","Deferred tax","Superannuation","Consumer spending"],"answer":2,"explain":"superannuation = quỹ hưu trí do chủ lao động đóng góp (cách gọi ở Úc). 'Life expectancy' là tuổi thọ, 'Deferred tax' là thuế hoãn lại, 'Consumer spending' là chi tiêu tiêu dùng.","extra":[{"en":"pension fund","vi":"quỹ hưu trí"},
{"en":"employer contribution","vi":"khoản đóng góp của chủ lao động"},
{"en":"retirement savings","vi":"tiền tiết kiệm hưu trí"}]},
{"id":"q0290","unit":6,"stem":" Following several years of declining revenue, a retail group decides to close unprofitable branches and reduce the size of its workforce. It plans to _____.","options":["downgrade","decentralize","relocate","downsize"],"answer":3,"explain":"downsize = thu hẹp quy mô (đóng chi nhánh, cắt giảm nhân sự). 'downgrade' là hạ cấp, 'decentralize' là phân quyền, 'relocate' là chuyển địa điểm; đều không mang nghĩa giảm quy mô.","extra":[{"en":"lay off staff","vi":"sa thải nhân viên"},
{"en":"cost-cutting measures","vi":"biện pháp cắt giảm chi phí"},
{"en":"redundancy","vi":"cắt giảm nhân sự dư thừa"}]},
{"id":"q0291","unit":3,"stem":" A business has a present obligation resulting from a past transaction and expects that settling it will require an outflow of economic resources. This is a _____.","options":["Equity","Provision","Liability","Cash equivalent"],"answer":2,"explain":"liability = nợ phải trả: nghĩa vụ hiện tại từ giao dịch quá khứ, phải chi nguồn lực để thanh toán. 'Equity' là vốn chủ, 'Cash equivalent' là tương đương tiền. 'Provision' là loại nợ có thời hạn/giá trị chưa chắc chắn, đề không nêu điều này.","extra":[{"en":"current liabilities","vi":"nợ ngắn hạn"},
{"en":"long-term liabilities","vi":"nợ dài hạn"},
{"en":"outflow of resources","vi":"dòng ra của nguồn lực"}],"needsReview":true},
{"id":"q0292","unit":6,"stem":" A luxury hotel changes its services to meet the expectations of its regular customers and high-spending visitors. These customers collectively form its _____.","options":["Stakeholders","Clientele","Protagonists","Backbench"],"answer":1,"explain":"clientele = tập khách hàng thường xuyên/chi tiêu cao của một cơ sở. 'Stakeholders' là các bên liên quan (rộng hơn khách), 'Protagonists' là nhân vật chính, 'Backbench' là nghị sĩ hàng ghế sau.","extra":[{"en":"target clientele","vi":"tập khách hàng mục tiêu"},
{"en":"upmarket","vi":"phân khúc cao cấp"},
{"en":"regular customers","vi":"khách quen"}]},
{"id":"q0293","unit":4,"stem":" Before acquiring a competitor, a company thoroughly examines its financial statements, contracts, legal obligations and operating risks. This process is known as _____.","options":["Due diligence","Auditing","Bookkeeping","Performance measurement"],"answer":0,"explain":"due diligence = thẩm định kỹ lưỡng (tài chính, hợp đồng, pháp lý, rủi ro) trước khi mua lại. 'Auditing' là kiểm toán báo cáo tài chính, 'Bookkeeping' là ghi sổ, 'Performance measurement' là đo lường hiệu suất.","extra":[{"en":"carry out due diligence","vi":"tiến hành thẩm định"},
{"en":"merger and acquisition","vi":"mua bán và sáp nhập"},
{"en":"legal obligations","vi":"nghĩa vụ pháp lý"}]},
{"id":"q0294","unit":7,"stem":" A profitable company cannot pay a supplier on time because the money from its customers will not arrive until several weeks later. Which concept best explains the problem?","options":["Return on investment","Principal","Cash flow","Equity"],"answer":2,"explain":"cash flow = dòng tiền: công ty có lãi nhưng tiền từ khách về chậm nên không trả nhà cung cấp đúng hạn. 'Return on investment' là tỷ suất sinh lời, 'Principal' là tiền gốc, 'Equity' là vốn chủ.","extra":[{"en":"cash flow problem","vi":"vấn đề dòng tiền"},
{"en":"working capital","vi":"vốn lưu động"},
{"en":"payment terms","vi":"điều khoản thanh toán"}]},
{"id":"q0295","unit":6,"stem":" Backpackers and international students _____ a considerable proportion of the customers at the budget hotel.","options":["make up","cater to","offset","bundle into"],"answer":0,"explain":"make up = chiếm (một tỷ lệ). 'cater to' là phục vụ/đáp ứng nhu cầu (sai ngữ pháp vì sau đó là 'a proportion of customers'), 'offset' là bù đắp, 'bundle into' là gộp vào gói.","extra":[{"en":"account for","vi":"chiếm (tỷ lệ)"},
{"en":"budget accommodation","vi":"chỗ ở giá rẻ"},
{"en":"customer base","vi":"tệp khách hàng"}]},
{"id":"q0296","unit":1,"stem":" The production supervisor assigns orders to particular dates, determines the sequence of tasks and sets expected completion times. This is called _____.","options":["Production scheduling","Capacity planning","Inventory management","Performance measurement"],"answer":0,"explain":"production scheduling = lập lịch sản xuất: gán đơn hàng theo ngày, thứ tự công việc, thời hạn hoàn thành. 'Capacity planning' là tính công suất cần có, 'Inventory management' là quản lý tồn kho, 'Performance measurement' là đo lường hiệu quả.","extra":[{"en":"production schedule","vi":"lịch sản xuất"},
{"en":"meet a deadline","vi":"đáp ứng thời hạn"},
{"en":"work order","vi":"lệnh sản xuất"}]},
{"id":"q0297","unit":2,"stem":" The consultant discovered weaknesses in the company's internal procedures but concluded that they could be corrected through additional training. The deficiencies were considered _____.","options":["Volatile","Prospective","Embedded","Remediable"],"answer":3,"explain":"remediable = có thể khắc phục được (bằng đào tạo thêm). 'Volatile' là biến động, 'Prospective' là tiềm năng, 'Embedded' là ăn sâu, đều không hàm ý sửa được.","extra":[{"en":"remedial action","vi":"hành động khắc phục"},
{"en":"internal controls","vi":"kiểm soát nội bộ"},
{"en":"corrective training","vi":"đào tạo khắc phục"}]},
{"id":"q0298","unit":4,"stem":" A trader borrows shares, sells them immediately and later attempts to buy them back at a lower price before returning them to the lender. This strategy is called _____.","options":["Leverage","Short selling","Take-over","Derivative trading"],"answer":1,"explain":"short selling = bán khống: vay cổ phiếu, bán ngay, hy vọng mua lại giá thấp hơn để trả. 'Leverage' là đòn bẩy, 'Take-over' là thâu tóm, 'Derivative trading' là giao dịch phái sinh.","extra":[{"en":"short position","vi":"vị thế bán khống"},
{"en":"bear market","vi":"thị trường giá xuống"},
{"en":"margin trading","vi":"giao dịch ký quỹ"}]},
{"id":"q0299","unit":6,"stem":" The human-resources department calculates the percentage of employees who leave an organization during a particular period. It is measuring employee _____.","options":["Turnover","Exposure","Clientele","Return on investment"],"answer":0,"explain":"turnover (staff turnover) = tỷ lệ nhân viên nghỉ việc trong một kỳ. 'Exposure' là mức độ phơi nhiễm/rủi ro, 'Clientele' là tập khách hàng, 'Return on investment' là tỷ suất sinh lời.","extra":[{"en":"staff retention","vi":"giữ chân nhân viên"},
{"en":"high attrition rate","vi":"tỷ lệ nghỉ việc cao"},
{"en":"employee morale","vi":"tinh thần nhân viên"}]},
{"id":"q0300","unit":5,"stem":" The contract states that the company is legally required to comply with the arbitration ruling and cannot simply ignore it. The ruling is _____.","options":["Standardized","Binding","Identical","Specified"],"answer":1,"explain":"binding = có tính ràng buộc pháp lý, phải tuân thủ. 'Standardized' là chuẩn hóa, 'Identical' là giống hệt, 'Specified' là được chỉ định rõ; không hàm ý bắt buộc phải tuân theo.","extra":[{"en":"legally binding","vi":"ràng buộc về mặt pháp lý"},
{"en":"arbitration","vi":"phân xử, trọng tài"},
{"en":"comply with a ruling","vi":"tuân thủ phán quyết"}]},
{"id":"q0301","unit":1,"stem":"A manufacturer accepts customer orders but repeatedly releases production lots in the wrong sequence. Which function should determine what is produced, in what quantity, and at what time?","options":["Production scheduling","Inventory management","Capacity planning","Lead time"],"answer":0,"explain":"production scheduling quyết định sản xuất gì, bao nhiêu, khi nào, nên giải quyết vấn đề thứ tự sai. 'Inventory management' quản lý tồn kho, 'Capacity planning' tính công suất dài hạn, 'Lead time' chỉ là khoảng thời gian chờ chứ không phải chức năng.","extra":[{"en":"production run","vi":"đợt sản xuất"},
{"en":"batch size","vi":"quy mô lô"},
{"en":"order backlog","vi":"đơn hàng tồn đọng"}]},
{"id":"q0302","unit":3,"stem":"A company acquires another business for more than the fair value of its identifiable net assets. The excess amount may be recorded as:","options":["Trademark","Patent","Goodwill","Deferred tax"],"answer":2,"explain":"goodwill = lợi thế thương mại, phần chênh lệch khi giá mua vượt giá trị hợp lý của tài sản ròng xác định được. 'Trademark' và 'Patent' là tài sản sở hữu trí tuệ riêng, 'Deferred tax' là thuế hoãn lại.","extra":[{"en":"intangible asset","vi":"tài sản vô hình"},
{"en":"purchase price allocation","vi":"phân bổ giá mua"},
{"en":"impairment test","vi":"kiểm tra suy giảm giá trị"}]},
{"id":"q0303","unit":3,"stem":"A balance sheet reports total assets of $8 million and total liabilities of $5 million. The remaining $3 million represents the owners’:","options":["Provisions","Equity","Receivables","Liabilities"],"answer":1,"explain":"Tài sản - nợ phải trả = vốn chủ sở hữu: 8 - 5 = 3 triệu là equity. 'Provisions' là khoản dự phòng, 'Receivables' là khoản phải thu, 'Liabilities' là nợ (đã trừ ra).","extra":[{"en":"accounting equation","vi":"phương trình kế toán"},
{"en":"net assets","vi":"tài sản ròng"},
{"en":"shareholders' equity","vi":"vốn chủ sở hữu"}]},
{"id":"q0304","unit":7,"stem":"Two companies establish a separate business arrangement, contribute resources, and share both control and profits. This arrangement is best described as a:","options":["Mortgage loan","Take-over","Acquisition","Joint venture"],"answer":3,"explain":"joint venture = liên doanh: hai công ty lập cơ cấu riêng, góp nguồn lực, chia quyền kiểm soát và lợi nhuận. 'Take-over' và 'Acquisition' là một bên mua lại bên kia, 'Mortgage loan' là khoản vay thế chấp.","extra":[{"en":"joint venture agreement","vi":"hợp đồng liên doanh"},
{"en":"equity stake","vi":"tỷ lệ sở hữu vốn"},
{"en":"profit sharing","vi":"chia sẻ lợi nhuận"}]},
{"id":"q0305","unit":3,"stem":"The accountant deliberately changes sales figures to make the company's financial position appear stronger than it really is. The accountant has attempted to:","options":["Offset the figures","Recoup the figures","Falsify the records","Reconcile the figures"],"answer":2,"explain":"falsify = làm giả, gian lận số liệu để báo cáo đẹp hơn thực tế. 'Offset' là bù trừ, 'Recoup' là thu hồi khoản đã mất, 'Reconcile' là đối chiếu cho khớp, đều là nghiệp vụ hợp pháp.","extra":[{"en":"falsify accounts","vi":"làm giả sổ sách"},
{"en":"creative accounting","vi":"kế toán sáng tạo (gian lận)"},
{"en":"fraud","vi":"gian lận"}]},
{"id":"q0306","unit":2,"stem":"A production line has sufficient workers and materials, but every unit must pass through one machine that processes items much more slowly than the other stations. The machine creates a:","options":["Linear workflow","Production yield","Production bottleneck","Value-added activity"],"answer":2,"explain":"production bottleneck = nút thắt: một máy chậm hạn chế toàn bộ dây chuyền dù đủ người và nguyên liệu. 'Linear workflow' là quy trình tuyến tính, 'Production yield' là hiệu suất sản lượng, 'Value-added activity' là hoạt động tạo giá trị.","extra":[{"en":"constraint","vi":"điểm hạn chế"},
{"en":"balance the line","vi":"cân bằng dây chuyền"},
{"en":"idle time","vi":"thời gian chờ nhàn rỗi"}]},
{"id":"q0307","unit":4,"stem":"A business borrows heavily to finance an expansion, hoping that the returns generated by the new assets will exceed the cost of borrowing. It is using:","options":["Principal","Return on investment","Short selling","Leverage"],"answer":3,"explain":"leverage = dùng vốn vay để mở rộng, mong lợi suất tài sản mới vượt chi phí vay. 'Principal' là tiền gốc, 'Return on investment' là tỷ suất sinh lời (kết quả, không phải chiến lược vay), 'Short selling' là bán khống.","extra":[{"en":"highly leveraged","vi":"vay đòn bẩy cao"},
{"en":"cost of borrowing","vi":"chi phí vay"},
{"en":"finance an expansion","vi":"tài trợ cho mở rộng"}]},
{"id":"q0308","unit":7,"stem":"After several years of rapid growth, a firm's monthly sales stop increasing and remain relatively stable. The sales figures are said to:","options":["Hover","Level off","Accelerate","Multiply"],"answer":1,"explain":"level off = chững lại, ổn định sau giai đoạn tăng. 'Hover' là dao động quanh một mức (ít dùng cho xu hướng sau tăng trưởng), 'Accelerate' là tăng tốc, 'Multiply' là nhân lên; hai từ sau trái với việc không tăng nữa.","extra":[{"en":"plateau","vi":"đi ngang, chững lại"},
{"en":"sales growth","vi":"tăng trưởng doanh số"},
{"en":"stabilize","vi":"ổn định"}]},
{"id":"q0309","unit":2,"stem":"A manufacturer introduces procedures to prevent defects at every stage of production rather than merely inspecting finished goods. This approach is most closely associated with:","options":["Quality assurance","Machine maintenance","Forensic accounting","Inventory management"],"answer":0,"explain":"quality assurance = đảm bảo chất lượng, phòng ngừa lỗi ở mọi công đoạn thay vì chỉ kiểm tra thành phẩm. 'Machine maintenance' là bảo trì máy, 'Forensic accounting' là kế toán điều tra, 'Inventory management' là quản lý tồn kho.","extra":[{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"zero defects","vi":"không lỗi"}]},
{"id":"q0310","unit":4,"stem":"A borrower is contractually required to repay a loan but fails to make the required payments. The borrower may be considered to be in:","options":["Due diligence","Default","Leverage","Acquisition"],"answer":1,"explain":"default = vỡ nợ, không trả nợ đúng hạn theo hợp đồng. 'Due diligence' là thẩm định, 'Leverage' là đòn bẩy, 'Acquisition' là thương vụ mua lại.","extra":[{"en":"default on a loan","vi":"vỡ nợ khoản vay"},
{"en":"default risk","vi":"rủi ro vỡ nợ"},
{"en":"late payment penalty","vi":"phạt trả chậm"}]},
{"id":"q0311","unit":1,"stem":"Which verb most directly describes the activity of producing finished goods from raw materials through the use of labor, machinery, and industrial processes?","options":["Manufacture","Offset","Recoup","Decentralize"],"answer":0,"explain":"manufacture = sản xuất, chế tạo thành phẩm từ nguyên liệu bằng lao động và máy móc. 'Offset' là bù đắp, 'Recoup' là thu hồi tiền, 'Decentralize' là phân quyền; đều không phải hoạt động sản xuất.","extra":[{"en":"manufacturing plant","vi":"nhà máy sản xuất"},
{"en":"assembly line","vi":"dây chuyền lắp ráp"},
{"en":"industrial process","vi":"quy trình công nghiệp"}]},
{"id":"q0312","unit":7,"stem":"A retailer coordinates deliveries so that components arrive shortly before they are needed in production, reducing the need to store large quantities of inventory. This is an example of:","options":["Mass production","Batch production","Lean accounting","JIT manufacturing"],"answer":3,"explain":"JIT (just-in-time) manufacturing = linh kiện đến ngay trước khi cần, giảm tồn kho. 'Mass production' là sản xuất hàng loạt, 'Batch production' là sản xuất theo lô, 'Lean accounting' là kế toán tinh gọn, không nói về giao hàng đúng lúc.","extra":[{"en":"JIT delivery","vi":"giao hàng đúng lúc"},
{"en":"stockholding costs","vi":"chi phí lưu kho"},
{"en":"supply chain","vi":"chuỗi cung ứng"}]},
{"id":"q0313","unit":6,"stem":"A hotel and an airline jointly promote a package in which customers booking a flight receive a discount on accommodation. The companies are engaging in:","options":["Cross-selling","Short selling","Cross-promotion","Downsizing"],"answer":2,"explain":"cross-promotion = hai doanh nghiệp cùng quảng bá chung (gói khách sạn + vé máy bay). 'Cross-selling' là bán thêm sản phẩm khác cho cùng khách của một công ty, 'Short selling' là bán khống, 'Downsizing' là thu hẹp quy mô.","extra":[{"en":"package deal","vi":"gói ưu đãi trọn gói"},
{"en":"joint promotion","vi":"khuyến mãi chung"},
{"en":"loyalty scheme","vi":"chương trình khách hàng thân thiết"}]},
{"id":"q0314","unit":1,"stem":"A buyer requests a document that precisely states the required dimensions, materials, performance standards, and technical characteristics of a product. The buyer is requesting its:","options":["Threshold","Specification","Infrastructure","Clientele"],"answer":1,"explain":"specification = bản đặc tả kỹ thuật: kích thước, vật liệu, tiêu chuẩn hiệu năng. 'Threshold' là ngưỡng, 'Infrastructure' là cơ sở hạ tầng, 'Clientele' là tập khách hàng.","extra":[{"en":"technical specification","vi":"đặc tả kỹ thuật"},
{"en":"meet the specifications","vi":"đáp ứng thông số"},
{"en":"tolerance","vi":"dung sai"}]},
{"id":"q0315","unit":1,"stem":"A supplier takes 18 days from receiving an order to delivering the finished goods. In operations management, this period is the:","options":["Lead time","Downtime","Turnover","Production yield"],"answer":0,"explain":"lead time = thời gian từ lúc nhận đơn đến lúc giao hàng (18 ngày). 'Downtime' là thời gian ngừng máy, 'Turnover' là doanh thu/vòng quay, 'Production yield' là tỷ lệ sản phẩm đạt chuẩn.","extra":[{"en":"short lead time","vi":"thời gian chờ ngắn"},
{"en":"order fulfilment","vi":"thực hiện đơn hàng"},
{"en":"delivery schedule","vi":"lịch giao hàng"}]},
{"id":"q0316","unit":3,"stem":"After buying back some of its own issued shares, a company holds those shares rather than cancelling them. They are known as:","options":["Retained earnings","Receivables","Cash equivalents","Treasury shares"],"answer":3,"explain":"treasury shares = cổ phiếu quỹ: công ty mua lại cổ phiếu đã phát hành và giữ lại, chưa hủy. 'Retained earnings' là lợi nhuận giữ lại, 'Receivables' là khoản phải thu, 'Cash equivalents' là tương đương tiền.","extra":[{"en":"share repurchase","vi":"mua lại cổ phiếu"},
{"en":"issued shares","vi":"cổ phiếu đã phát hành"},
{"en":"earnings per share","vi":"lãi trên mỗi cổ phiếu"}]},
{"id":"q0317","unit":3,"stem":"A company has delivered goods to customers and issued invoices, but the customers have not paid yet. The amounts owed to the company are recorded as:","options":["Cash equivalents","Receivables","Treasury shares","Goodwill"],"answer":1,"explain":"receivables = khoản phải thu, tiền khách còn nợ sau khi đã giao hàng và xuất hóa đơn. 'Cash equivalents' là tương đương tiền, 'Treasury shares' là cổ phiếu quỹ, 'Goodwill' là lợi thế thương mại.","extra":[{"en":"accounts receivable","vi":"phải thu khách hàng"},
{"en":"credit terms","vi":"điều khoản tín dụng"},
{"en":"debt collection","vi":"thu hồi nợ"}]},
{"id":"q0318","unit":6,"stem":"A company transfers its customer-service centre from one city to another to reduce operating costs while keeping the same business activities. It decides to:","options":["Decentralize","Downsize","Relocate","Downgrade"],"answer":2,"explain":"relocate = chuyển địa điểm (trung tâm CSKH sang thành phố khác) để giảm chi phí. 'Decentralize' là phân quyền, 'Downsize' là cắt giảm quy mô, 'Downgrade' là hạ cấp; không đúng với việc giữ hoạt động nhưng đổi nơi.","extra":[{"en":"relocation costs","vi":"chi phí di dời"},
{"en":"call centre","vi":"tổng đài, trung tâm cuộc gọi"},
{"en":"operating costs","vi":"chi phí vận hành"}]},
{"id":"q0319","unit":6,"stem":"An investor avoids an asset because its market price changes sharply and unpredictably over short periods. The asset is considered:","options":["Standardized","Embedded","Agile","Volatile"],"answer":3,"explain":"volatile = biến động mạnh, khó đoán; nhà đầu tư tránh vì rủi ro. 'Standardized' là chuẩn hóa, 'Embedded' là ăn sâu, 'Agile' là nhanh nhẹn; không mô tả giá thay đổi đột ngột.","extra":[{"en":"volatility","vi":"độ biến động"},
{"en":"risk tolerance","vi":"khả năng chịu rủi ro"},
{"en":"safe-haven asset","vi":"tài sản trú ẩn an toàn"}]},
{"id":"q0320","unit":6,"stem":"A mature product generates reliable revenue and finances the development of newer products, even though its market is no longer expanding quickly. In business terminology, it is a:","options":["Venture","Cash cow","Derivative","Bottleneck"],"answer":1,"explain":"cash cow = 'con bò sữa', sản phẩm trưởng thành mang lại doanh thu ổn định để tài trợ sản phẩm mới. 'Venture' là dự án mạo hiểm, 'Derivative' là công cụ phái sinh, 'Bottleneck' là nút thắt.","extra":[{"en":"mature market","vi":"thị trường bão hòa"},
{"en":"market share","vi":"thị phần"},
{"en":"product life cycle","vi":"vòng đời sản phẩm"}]},
{"id":"q0321","unit":3,"stem":"A company estimates the cost of probable future warranty claims and recognizes an amount for this uncertain obligation in its accounts. The amount is classified as:","options":["Provisions","Receivables","Goodwill","Treasury shares"],"answer":0,"explain":"provision = khoản dự phòng cho nghĩa vụ có thể phát sinh nhưng chưa chắc chắn (như bảo hành). 'Receivables' là khoản phải thu, 'Goodwill' là lợi thế thương mại, 'Treasury shares' là cổ phiếu quỹ.","extra":[{"en":"warranty claim","vi":"yêu cầu bảo hành"},
{"en":"contingent liability","vi":"nợ tiềm tàng"},
{"en":"set aside funds","vi":"trích lập quỹ"}]},
{"id":"q0322","unit":2,"stem":"A factory redesigns its workflow to eliminate unnecessary movement, reduce waiting time, and remove activities that do not add value for customers. Which approach is it applying?","options":["Mass production","Lean manufacturing","Continuous production","Unit production"],"answer":1,"explain":"lean manufacturing = sản xuất tinh gọn: loại bỏ di chuyển thừa, thời gian chờ, hoạt động không tạo giá trị. 'Mass production' là sản xuất hàng loạt, 'Continuous production' là sản xuất liên tục, 'Unit production' là sản xuất đơn chiếc.","extra":[{"en":"eliminate waste","vi":"loại bỏ lãng phí"},
{"en":"continuous improvement","vi":"cải tiến liên tục"},
{"en":"value stream","vi":"dòng giá trị"}]},
{"id":"q0323","unit":6,"stem":"A luxury retailer adjusts its service and product range to suit the preferences of its regular customers. The group of customers it serves is its:","options":["Clientele","Coalition","Protagonists","Bondholders"],"answer":0,"explain":"clientele = tập khách hàng mà cửa hàng phục vụ. 'Coalition' là liên minh, 'Protagonists' là nhân vật chính/người ủng hộ, 'Bondholders' là người nắm giữ trái phiếu.","extra":[{"en":"exclusive clientele","vi":"tập khách độc quyền, cao cấp"},
{"en":"tailor services","vi":"điều chỉnh dịch vụ theo nhu cầu"},
{"en":"customer preferences","vi":"sở thích khách hàng"}]},
{"id":"q0324","unit":6,"stem":"Two brands sell different products that satisfy essentially the same customer need. From the consumer's perspective, the products are likely to be:","options":["Complements","Substitutes","Premiums","Derivatives"],"answer":1,"explain":"substitutes = sản phẩm thay thế: đáp ứng cùng nhu cầu nên người mua có thể đổi qua lại. 'Complements' là sản phẩm bổ trợ dùng cùng nhau, 'Premiums' là phí/hàng cao cấp, 'Derivatives' là công cụ phái sinh.","extra":[{"en":"price elasticity","vi":"độ co giãn của giá"},
{"en":"close substitute","vi":"sản phẩm thay thế gần"},
{"en":"brand switching","vi":"chuyển đổi thương hiệu"}]},
{"id":"q0325","unit":5,"stem":"A company spends $2 million developing a new product. After entering the market, it earns enough revenue to recover the money originally invested. It has managed to:","options":["Offset the investment","Incur the investment","Multiply the investment","Recoup the investment"],"answer":3,"explain":"recoup = thu hồi lại khoản đã bỏ ra. 'Offset' là bù trừ, 'Incur' là phải gánh chi phí, 'Multiply' là nhân lên; chỉ 'recoup' khớp với việc lấy lại vốn đầu tư ban đầu.","extra":[{"en":"recoup losses","vi":"bù lại khoản lỗ"},
{"en":"break even","vi":"hòa vốn"},
{"en":"payback period","vi":"thời gian hoàn vốn"}]},
{"id":"q0326","unit":4,"stem":"A borrower takes out a loan of $100,000. The amount originally borrowed, excluding the interest charged by the lender, is called the:","options":["Creditor","Bondholder","Principal","Interest rate"],"answer":2,"explain":"principal = tiền gốc vay ban đầu, chưa tính lãi. 'Creditor' là chủ nợ, 'Bondholder' là người sở hữu trái phiếu, 'Interest rate' là lãi suất.","extra":[{"en":"loan repayment","vi":"trả nợ vay"},
{"en":"compound interest","vi":"lãi kép"},
{"en":"lender","vi":"bên cho vay"}]},
{"id":"q0327","unit":5,"stem":"After a bill has passed the required legislative process and is formally made law, the government has:","options":["Imposed a creditor","Enacted legislation","Complied with a lobby","Offset a coalition"],"answer":1,"explain":"enact legislation = ban hành luật sau khi dự luật qua quy trình lập pháp. 'Impose a creditor', 'comply with a lobby', 'offset a coalition' không đúng kết hợp từ, vô nghĩa.","extra":[{"en":"pass a bill","vi":"thông qua dự luật"},
{"en":"come into force","vi":"có hiệu lực"},
{"en":"regulatory framework","vi":"khung pháp lý"}]},
{"id":"q0328","unit":1,"stem":"A manager uses measurable indicators such as defect rates, delivery times, and output per worker to monitor whether targets are being achieved. These indicators are:","options":["Performance metrics","Resource allocation","Line efficiency","Strategic vision"],"answer":0,"explain":"performance metrics = các chỉ số đo lường hiệu suất (tỷ lệ lỗi, thời gian giao hàng, năng suất). 'Resource allocation' là phân bổ nguồn lực, 'Line efficiency' là hiệu suất dây chuyền (một chỉ số cụ thể), 'Strategic vision' là tầm nhìn chiến lược.","extra":[{"en":"KPI (key performance indicator)","vi":"chỉ số hiệu suất chính"},
{"en":"benchmark","vi":"chuẩn so sánh"},
{"en":"productivity","vi":"năng suất"}]},
{"id":"q0329","unit":5,"stem":"A medicine can be purchased directly by consumers from a pharmacy without a doctor's prescription. It is an:","options":["Over-the-counter drug","Accredited drug","Deferred drug","Intangible drug"],"answer":0,"explain":"over-the-counter (OTC) drug = thuốc không kê đơn, mua trực tiếp ở hiệu thuốc. 'Accredited', 'Deferred', 'Intangible' không đi với 'drug' theo nghĩa này (lần lượt là được công nhận, hoãn lại, vô hình).","extra":[{"en":"prescription drug","vi":"thuốc kê đơn"},
{"en":"generic drug","vi":"thuốc generic"},
{"en":"pharmaceutical industry","vi":"ngành dược phẩm"}]},
{"id":"q0330","unit":7,"stem":"When the economy contracts, household spending weakens, firms reduce investment, and unemployment may rise. These conditions are commonly associated with:","options":["Economic expansion","Global warming","Economic downturns","Cross-promotion"],"answer":2,"explain":"economic downturns = suy thoái kinh tế: chi tiêu giảm, doanh nghiệp giảm đầu tư, thất nghiệp tăng. 'Economic expansion' là tăng trưởng (ngược lại), 'Global warming' là nóng lên toàn cầu, 'Cross-promotion' là quảng bá chéo.","extra":[{"en":"recession","vi":"suy thoái"},
{"en":"unemployment rate","vi":"tỷ lệ thất nghiệp"},
{"en":"consumer confidence","vi":"niềm tin người tiêu dùng"}]},
{"id":"q0331","unit":3,"stem":"A company holds short-term, highly liquid investments that can readily be converted into a known amount of cash and carry insignificant risk of changes in value. These are:","options":["Receivables","Current liabilities","Inventory","Cash equivalents"],"answer":3,"explain":"cash equivalents = tương đương tiền: đầu tư ngắn hạn, thanh khoản cao, chuyển thành lượng tiền xác định với rủi ro giá trị không đáng kể. 'Receivables' là khoản phải thu, 'Current liabilities' là nợ ngắn hạn, 'Inventory' là hàng tồn kho.","extra":[{"en":"liquidity","vi":"tính thanh khoản"},
{"en":"treasury bills","vi":"tín phiếu kho bạc"},
{"en":"money market fund","vi":"quỹ thị trường tiền tệ"}]},
{"id":"q0332","unit":1,"stem":"A factory produces large quantities of standardized, identical products using an assembly line and highly repetitive tasks. This production method is:","options":["Batch production","Unit production","Continuous production","Mass production"],"answer":3,"explain":"mass production = sản xuất hàng loạt sản phẩm chuẩn hóa giống hệt bằng dây chuyền lắp ráp và thao tác lặp lại. 'Batch production' là theo lô, 'Unit production' là đơn chiếc, 'Continuous production' là chạy liên tục không ngừng (thường cho hóa chất, dầu khí).","extra":[{"en":"economies of scale","vi":"lợi thế kinh tế theo quy mô"},
{"en":"repetitive tasks","vi":"công việc lặp lại"},
{"en":"standardized product","vi":"sản phẩm chuẩn hóa"}]},
{"id":"q0333","unit":4,"stem":"A credit-rating agency changes a company's rating from investment grade to a lower category because its financial risk has increased. The agency has decided to:","options":["Upgrade the company","Downgrade the company","Relaunch the company","Enhance the company"],"answer":1,"explain":"downgrade = hạ bậc xếp hạng tín nhiệm vì rủi ro tăng. 'Upgrade' là nâng bậc, 'Relaunch' là tung ra lại, 'Enhance' là nâng cao chất lượng; đều trái hoặc không hợp ngữ cảnh.","extra":[{"en":"credit rating","vi":"xếp hạng tín nhiệm"},
{"en":"investment grade","vi":"hạng đầu tư"},
{"en":"credit-rating agency","vi":"tổ chức xếp hạng tín nhiệm"}]},
{"id":"q0334","unit":1,"stem":"A manufacturer forecasts future demand and evaluates whether it will need more machines, factory space, and labor over the next three years. This is an example of:","options":["Capacity planning","Production scheduling","Inventory management","Performance measurement"],"answer":0,"explain":"capacity planning = hoạch định công suất: dự báo nhu cầu để quyết định cần thêm máy, mặt bằng, nhân lực. 'Production scheduling' là lập lịch ngắn hạn, 'Inventory management' là quản lý tồn kho, 'Performance measurement' là đo lường hiệu suất.","extra":[{"en":"demand forecast","vi":"dự báo nhu cầu"},
{"en":"expand capacity","vi":"mở rộng công suất"},
{"en":"spare capacity","vi":"công suất dư"}]},
{"id":"q0335","unit":3,"stem":"Temporary differences between the accounting treatment of an item and its tax treatment may give rise to:","options":["Retained earnings","Treasury shares","Deferred tax","Cash equivalents"],"answer":2,"explain":"deferred tax = thuế hoãn lại, phát sinh từ chênh lệch tạm thời giữa kế toán và thuế. 'Retained earnings' là lợi nhuận giữ lại, 'Treasury shares' là cổ phiếu quỹ, 'Cash equivalents' là tương đương tiền.","extra":[{"en":"deferred tax liability","vi":"thuế thu nhập hoãn lại phải trả"},
{"en":"taxable profit","vi":"lợi nhuận chịu thuế"},
{"en":"tax accounting","vi":"kế toán thuế"}]},
{"id":"q0336","unit":5,"stem":"A chief executive first promises that no jobs will be cut, but later withdraws that statement after the company announces a restructuring. The executive has had to:","options":["Back down","Backflip","Compromise","Backtrack"],"answer":3,"explain":"backtrack = rút lại, đảo ngược điều đã hứa/phát biểu trước đó. 'Back down' là nhượng bộ khi bị phản đối, 'Backflip' là đảo ngược lập trường đột ngột (cách nói Úc), 'Compromise' là thỏa hiệp. Backtrack và backflip khá gần nghĩa.","extra":[{"en":"go back on a promise","vi":"nuốt lời hứa"},
{"en":"U-turn","vi":"đảo ngược chính sách"},
{"en":"retract a statement","vi":"rút lại phát biểu"}],"needsReview":true},
{"id":"q0337","unit":6,"stem":"A multinational firm gives regional managers greater authority to make decisions instead of requiring approval from its headquarters for every operational issue. It is seeking to:","options":["Decentralize","Downsize","Deregulate","Downgrade"],"answer":0,"explain":"decentralize = phân quyền: trao thêm quyền quyết định cho quản lý khu vực thay vì trụ sở chính. 'Downsize' là thu hẹp quy mô, 'Deregulate' là bãi bỏ quy định (của nhà nước), 'Downgrade' là hạ cấp.","extra":[{"en":"delegate authority","vi":"ủy quyền"},
{"en":"head office","vi":"trụ sở chính"},
{"en":"chain of command","vi":"hệ thống chỉ huy"}]},
{"id":"q0338","unit":2,"stem":"A factory compares the actual productive time of an assembly line with the time available, aiming to reduce unnecessary stoppages and idle periods. It is evaluating:","options":["Line efficiency","Production yield","Performance metrics","Value added"],"answer":0,"explain":"line efficiency = hiệu suất dây chuyền: so sánh thời gian sản xuất thực tế với thời gian sẵn có, giảm dừng máy và thời gian nhàn rỗi. 'Production yield' là tỷ lệ sản phẩm đạt chuẩn, 'Performance metrics' là các chỉ số nói chung, 'Value added' là giá trị gia tăng.","extra":[{"en":"idle time","vi":"thời gian nhàn rỗi"},
{"en":"utilization rate","vi":"tỷ lệ sử dụng"},
{"en":"overall equipment effectiveness","vi":"hiệu suất thiết bị tổng thể"}]},
{"id":"q0339","unit":4,"stem":"An investor compares the profit generated by an investment with the amount of money committed to it. The investor is assessing its:","options":["Interest rate","Principal","Return on investment","Leverage"],"answer":2,"explain":"return on investment (ROI) = tỷ suất sinh lời, so lợi nhuận với vốn bỏ ra. 'Interest rate' là lãi suất, 'Principal' là tiền gốc, 'Leverage' là đòn bẩy; không phải thước đo lợi nhuận trên vốn đầu tư.","extra":[{"en":"rate of return","vi":"tỷ suất lợi nhuận"},
{"en":"profitability","vi":"khả năng sinh lời"},
{"en":"capital employed","vi":"vốn sử dụng"}]},
{"id":"q0340","unit":4,"stem":"A contract derives its value from the price of an underlying asset, such as a commodity, currency, or share. The contract is a:","options":["Hedge fund","Mutual fund","Mortgage loan","Derivative"],"answer":3,"explain":"derivative = công cụ phái sinh, giá trị phụ thuộc tài sản cơ sở (hàng hóa, tiền tệ, cổ phiếu). 'Hedge fund' và 'Mutual fund' là các loại quỹ đầu tư, 'Mortgage loan' là khoản vay thế chấp.","extra":[{"en":"underlying asset","vi":"tài sản cơ sở"},
{"en":"futures contract","vi":"hợp đồng tương lai"},
{"en":"options trading","vi":"giao dịch quyền chọn"}]},
{"id":"q0341","unit":5,"stem":"A manager refuses to conceal a product defect, even though revealing it may damage the company's short-term reputation. The manager is demonstrating:","options":["Exposure","Integrity","Turnover","Leverage"],"answer":1,"explain":"integrity = sự chính trực: không che giấu lỗi dù có thể tổn hại danh tiếng ngắn hạn. 'Exposure' là mức độ phơi nhiễm/lộ diện, 'Turnover' là doanh thu hoặc tỷ lệ nghỉ việc, 'Leverage' là đòn bẩy.","extra":[{"en":"ethical conduct","vi":"hành vi đạo đức"},
{"en":"transparency","vi":"tính minh bạch"},
{"en":"product recall","vi":"thu hồi sản phẩm"}]},
{"id":"q0342","unit":4,"stem":"An investor borrows shares, sells them immediately, and hopes to buy them back later at a lower price before returning them to the lender. This strategy is called:","options":["A long position","Leverage","An acquisition","Short selling"],"answer":3,"explain":"short selling = bán khống: vay cổ phiếu, bán ngay, hy vọng mua lại giá thấp hơn rồi trả. 'A long position' là mua giữ chờ giá tăng, 'Leverage' là đòn bẩy, 'An acquisition' là thương vụ mua lại công ty.","extra":[{"en":"go short","vi":"đặt cược giá giảm"},
{"en":"go long","vi":"đặt cược giá tăng"},
{"en":"short squeeze","vi":"đợt ép bán khống"}]},
{"id":"q0343","unit":2,"stem":"A factory uses 1,000 units of input and produces 930 acceptable units. The proportion of output meeting the required standard is its:","options":["Production yield","Line efficiency","Output capacity","Value added"],"answer":0,"explain":"production yield = tỷ lệ sản lượng đạt chuẩn trên đầu vào (930/1000 = 93%). 'Line efficiency' là hiệu suất sử dụng thời gian dây chuyền, 'Output capacity' là công suất tối đa, 'Value added' là giá trị gia tăng.","extra":[{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"scrap rate","vi":"tỷ lệ phế phẩm"},
{"en":"first-pass yield","vi":"tỷ lệ đạt ngay lần đầu"}]},
{"id":"q0344","unit":6,"stem":"Applicants who satisfy the income, credit-history, and documentation requirements may qualify for a particular loan. They are:","options":["Entitled of the loan","Eligible for the loan","Suitable to the loan","Accredited by the loan"],"answer":1,"explain":"eligible for = đủ điều kiện (nhận khoản vay). 'Entitled of' sai giới từ (đúng là entitled to), 'Suitable to the loan' không tự nhiên, 'Accredited by' là được công nhận bởi tổ chức.","extra":[{"en":"eligibility requirements","vi":"yêu cầu về điều kiện"},
{"en":"credit history","vi":"lịch sử tín dụng"},
{"en":"qualify for a loan","vi":"đủ điều kiện vay"}]},
{"id":"q0345","unit":7,"stem":"A company's three regional divisions generate 70% of its total revenue. Which phrasal verb correctly completes the sentence: 'These three divisions ___ most of the company's revenue'?","options":["Offset","Complement","Make up","Recoup"],"answer":2,"explain":"make up = chiếm (một tỷ lệ) trong tổng thể. 'Offset' là bù đắp, 'Complement' là bổ sung cho nhau, 'Recoup' là thu hồi; đều không diễn tả tỷ lệ cấu thành doanh thu.","extra":[{"en":"account for","vi":"chiếm"},
{"en":"revenue stream","vi":"nguồn doanh thu"},
{"en":"regional division","vi":"bộ phận theo khu vực"}]},
{"id":"q0346","unit":6,"stem":"A firm's long-standing beliefs have become deeply rooted in everyday decision-making and are difficult to change. The beliefs are:","options":["Standardized","Agile","Embedded","Prospective"],"answer":2,"explain":"embedded = ăn sâu, bám rễ vào cách ra quyết định, khó thay đổi. 'Standardized' là chuẩn hóa, 'Agile' là linh hoạt (trái với khó đổi), 'Prospective' là tiềm năng.","extra":[{"en":"corporate culture","vi":"văn hóa doanh nghiệp"},
{"en":"deep-rooted","vi":"ăn sâu"},
{"en":"change management","vi":"quản lý thay đổi"}]},
{"id":"q0347","unit":3,"stem":"An independent professional examines a company's financial records and statements to assess whether they have been prepared in accordance with relevant standards. This process is:","options":["Auditing","Creative accounting","Forensic accounting","Bookkeeping"],"answer":0,"explain":"auditing = kiểm toán: chuyên gia độc lập kiểm tra sổ sách xem có lập theo chuẩn mực không. 'Creative accounting' là xử lý kế toán lách luật, 'Forensic accounting' là điều tra gian lận, 'Bookkeeping' là ghi chép sổ sách.","extra":[{"en":"external auditor","vi":"kiểm toán viên độc lập"},
{"en":"audit report","vi":"báo cáo kiểm toán"},
{"en":"accounting standards","vi":"chuẩn mực kế toán"}]},
{"id":"q0348","unit":4,"stem":"A corporation purchases another business and incorporates it into its own operations. The purchase is generally described as an:","options":["Bond issue","Acquisition","Due diligence","Bootstrapping"],"answer":1,"explain":"acquisition = thương vụ mua lại và sáp nhập vào hoạt động của mình. 'Bond issue' là phát hành trái phiếu, 'Due diligence' là thẩm định (trước khi mua), 'Bootstrapping' là tự lực khởi nghiệp không vốn ngoài.","extra":[{"en":"merger","vi":"sáp nhập"},
{"en":"take-over bid","vi":"chào mua thâu tóm"},
{"en":"subsidiary","vi":"công ty con"}]},
{"id":"q0349","unit":4,"stem":"A company borrows money from a bank. From the company's perspective, the bank is the party to whom the money is owed: the:","options":["Equity holder","Debtor","Guarantor","Creditor"],"answer":3,"explain":"creditor = chủ nợ, bên mà công ty nợ tiền (ngân hàng). 'Debtor' là con nợ (chính công ty), 'Equity holder' là cổ đông, 'Guarantor' là người bảo lãnh.","extra":[{"en":"debtor","vi":"con nợ"},
{"en":"secured loan","vi":"khoản vay có tài sản bảo đảm"},
{"en":"bank overdraft","vi":"thấu chi ngân hàng"}]},
{"id":"q0350","unit":6,"stem":"A company brings an old product back to the market after redesigning its positioning, updating the campaign, and targeting a new customer segment. It plans to:","options":["Update the product","Upgrade the product","Relaunch the product","Downgrade the product"],"answer":2,"explain":"relaunch = tái tung ra thị trường sau khi định vị lại, đổi chiến dịch, nhắm phân khúc mới. 'Update' chỉ cập nhật nhỏ, 'Upgrade' là nâng cấp tính năng, 'Downgrade' là hạ cấp; đều không bao gồm tái ra mắt cả định vị.","extra":[{"en":"repositioning","vi":"định vị lại"},
{"en":"marketing campaign","vi":"chiến dịch tiếp thị"},
{"en":"target segment","vi":"phân khúc mục tiêu"}]},
{"id":"q0351","unit":4,"stem":"A corporation is considering acquiring a foreign supplier. Before signing the agreement, its advisers examine the target's contracts, tax exposure, outstanding obligations, ownership structure and operational risks. What is this comprehensive investigation called?","options":["Performance measurement","Due diligence","Forensic accounting","Bootstrapping"],"answer":1,"explain":"due diligence = thẩm định toàn diện hợp đồng, thuế, nghĩa vụ, cơ cấu sở hữu, rủi ro trước khi mua. 'Performance measurement' là đo hiệu suất, 'Forensic accounting' là điều tra gian lận kế toán, 'Bootstrapping' là tự lực tài chính.","extra":[{"en":"target company","vi":"công ty mục tiêu"},
{"en":"tax exposure","vi":"rủi ro thuế"},
{"en":"conduct an investigation","vi":"tiến hành điều tra"}]},
{"id":"q0352","unit":3,"stem":"A manufacturer has a present obligation arising from past warranty claims, but the exact amount and timing of future payments remain uncertain. Which accounting classification is most appropriate for the estimated obligation?","options":["Deferred tax","Equity","Provisions","Receivables"],"answer":2,"explain":"provisions = khoản dự phòng cho nghĩa vụ có thể xảy ra, số tiền và thời điểm chưa chắc chắn (như bảo hành). 'Deferred tax' là thuế hoãn lại, 'Equity' là vốn chủ, 'Receivables' là khoản phải thu.","extra":[{"en":"warranty provision","vi":"dự phòng bảo hành"},
{"en":"contingent liability","vi":"nợ tiềm tàng"},
{"en":"estimate obligations","vi":"ước tính nghĩa vụ"}]},
{"id":"q0353","unit":1,"stem":"An electronics producer coordinates deliveries so that components reach the assembly facility shortly before they are required. It seeks to reduce storage costs without interrupting production. Which approach is being applied?","options":["JIT manufacturing","Batch production","Continuous production","Inventory management"],"answer":0,"explain":"JIT (just-in-time) nghĩa là linh kiện đến ngay trước khi cần, giảm chi phí lưu kho mà không làm gián đoạn sản xuất. Batch production là sản xuất theo lô; continuous production là chạy liên tục; inventory management là quản lý tồn kho nói chung, không nhấn mạnh việc giao hàng sát thời điểm cần.","extra":[{"en":"just-in-time delivery","vi":"giao hàng đúng lúc"},
{"en":"stockholding costs","vi":"chi phí lưu kho"},
{"en":"supplier lead time","vi":"thời gian chờ của nhà cung cấp"}]},
{"id":"q0354","unit":1,"stem":"A chemical plant processes a liquid substance through interconnected equipment around the clock. Production is not divided into separate customer-specific lots, and stopping the process is costly. Which production system best describes this operation?","options":["Mass production","Unit production","Batch production","Continuous production"],"answer":3,"explain":"Continuous production là sản xuất liên tục 24/7 (hóa chất, dầu khí), không chia lô và dừng máy rất tốn kém. Batch production chia theo lô; mass production làm hàng loạt sản phẩm riêng lẻ trên dây chuyền; unit production làm từng sản phẩm đơn chiếc.","extra":[{"en":"process industry","vi":"ngành sản xuất quy trình"},
{"en":"round-the-clock operation","vi":"vận hành suốt ngày đêm"},
{"en":"shut down a plant","vi":"đóng/dừng nhà máy"}]},
{"id":"q0355","unit":3,"stem":"A company's accounting profit and taxable profit differ because certain expenses are recognised in different periods for accounting and tax purposes. The resulting future tax consequences may be recorded as:","options":["Deferred tax","Goodwill","Retained earnings","Provisions"],"answer":0,"explain":"Deferred tax (thuế hoãn lại) ghi nhận hệ quả thuế tương lai do chênh lệch về thời điểm ghi nhận giữa kế toán và thuế. Goodwill là lợi thế thương mại; retained earnings là lợi nhuận giữ lại; provisions là khoản dự phòng cho nghĩa vụ chưa chắc chắn.","extra":[{"en":"deferred tax liability","vi":"thuế thu nhập hoãn lại phải trả"},
{"en":"taxable profit","vi":"lợi nhuận chịu thuế"},
{"en":"timing difference","vi":"chênh lệch tạm thời"}]},
{"id":"q0356","unit":5,"stem":"A regional director must decide how to distribute scarce machine hours, skilled technicians and operating funds among three competing production facilities. Which managerial activity is central to this decision?","options":["Resource allocation","Performance measurement","Inventory management","Quality assurance"],"answer":0,"explain":"Resource allocation là việc phân bổ nguồn lực khan hiếm (giờ máy, kỹ thuật viên, vốn) giữa các bộ phận cạnh tranh nhau. Performance measurement là đo hiệu suất; inventory management là quản lý tồn kho; quality assurance là đảm bảo chất lượng, đều không phải việc phân chia nguồn lực.","extra":[{"en":"allocate resources","vi":"phân bổ nguồn lực"},
{"en":"scarce resources","vi":"nguồn lực khan hiếm"},
{"en":"competing priorities","vi":"các ưu tiên cạnh tranh nhau"}]},
{"id":"q0357","unit":1,"stem":"A manufacturer expects demand to double within four years. Before committing to a new factory, it evaluates the future number of machines, workers, production space and operating resources required. This is primarily an exercise in:","options":["Production scheduling","Capacity planning","Line efficiency","Production yield"],"answer":1,"explain":"Capacity planning là lập kế hoạch công suất: xác định máy móc, nhân công, mặt bằng cần thiết cho nhu cầu tương lai. Production scheduling chỉ sắp xếp thời gian cho các công việc; line efficiency đo mức độ sử dụng dây chuyền; production yield là tỷ lệ sản phẩm đạt.","extra":[{"en":"capacity utilisation","vi":"mức sử dụng công suất"},
{"en":"expand capacity","vi":"mở rộng công suất"},
{"en":"peak demand","vi":"nhu cầu cao điểm"}]},
{"id":"q0358","unit":6,"stem":"During the final quarter, a currency exchange rate fluctuates slightly above and below 1.08, without showing a sustained upward or downward trend. The rate is best described as continuing to:","options":["Level off","Flatten out","Hover around 1.08","Accelerate"],"answer":2,"explain":"Hover around 1.08 nghĩa là dao động quanh mức 1,08 mà không có xu hướng rõ rệt. Level off / flatten out nghĩa là ổn định, phẳng dần sau một giai đoạn tăng hoặc giảm, còn accelerate là tăng tốc, đều không mô tả dao động hai chiều quanh một mức.","extra":[{"en":"fluctuate slightly","vi":"dao động nhẹ"},
{"en":"remain stable","vi":"giữ ổn định"},
{"en":"peak at","vi":"đạt đỉnh ở mức"}]},
{"id":"q0359","unit":1,"stem":"A production engineer studies how well individual workstations are balanced and how effectively the available operating time of an assembly line is used. Which measure is the most relevant?","options":["Production yield","Value added","Line efficiency","Inventory turnover"],"answer":2,"explain":"Line efficiency đo mức cân bằng giữa các trạm làm việc và việc sử dụng thời gian vận hành của dây chuyền lắp ráp. Production yield là tỷ lệ sản phẩm đạt chuẩn; value added là giá trị gia tăng; inventory turnover là vòng quay hàng tồn kho.","extra":[{"en":"line balancing","vi":"cân bằng dây chuyền"},
{"en":"idle time","vi":"thời gian chết/nhàn rỗi"},
{"en":"throughput","vi":"năng suất thông qua"}]},
{"id":"q0360","unit":2,"stem":"A food manufacturer introduces common dimensions, ingredients and processing requirements across all its factories. Individual units may differ slightly in appearance, but every product must meet the same established requirements. The products are:","options":["Identical","Standardized","Customized","Intangible"],"answer":1,"explain":"Standardized (được tiêu chuẩn hóa) nghĩa là mọi sản phẩm đáp ứng cùng một bộ yêu cầu thống nhất dù có thể khác nhau chút ít. Identical là giống hệt nhau (đề nói có thể khác nhau về hình thức); customized là làm theo yêu cầu riêng; intangible là vô hình.","extra":[{"en":"standardised procedures","vi":"quy trình chuẩn hóa"},
{"en":"meet the specifications","vi":"đáp ứng thông số kỹ thuật"},
{"en":"quality benchmark","vi":"chuẩn mực chất lượng"}]},
{"id":"q0361","unit":3,"stem":"A listed company buys back some of its own issued shares and retains them rather than immediately cancelling them. In its financial statements, these shares are classified as:","options":["Retained earnings","Treasury shares","Cash equivalents","Receivables"],"answer":1,"explain":"Treasury shares là cổ phiếu quỹ: công ty mua lại cổ phiếu của chính mình và giữ lại chưa hủy. Retained earnings là lợi nhuận giữ lại; cash equivalents là khoản tương đương tiền; receivables là các khoản phải thu.","extra":[{"en":"share buyback","vi":"mua lại cổ phiếu"},
{"en":"issued share capital","vi":"vốn cổ phần đã phát hành"},
{"en":"outstanding shares","vi":"cổ phiếu đang lưu hành"}]},
{"id":"q0362","unit":3,"stem":"An investigator examines suspicious payments, reconstructs transactions, traces missing funds and prepares evidence that may be used in legal proceedings. Which specialist accounting field is involved?","options":["Managerial accounting","Tax accounting","Forensic accounting","Creative accounting"],"answer":2,"explain":"Forensic accounting là kế toán pháp y: điều tra giao dịch đáng ngờ, truy dấu tiền thất thoát và chuẩn bị chứng cứ cho tòa án. Managerial accounting phục vụ ra quyết định nội bộ; tax accounting lo về thuế; creative accounting là thủ thuật làm đẹp số liệu.","extra":[{"en":"fraud investigation","vi":"điều tra gian lận"},
{"en":"trace funds","vi":"truy dấu dòng tiền"},
{"en":"expert witness","vi":"nhân chứng chuyên môn"}]},
{"id":"q0363","unit":3,"stem":"A divisional manager needs internal reports comparing alternative production plans, expected costs and future profitability before deciding whether to discontinue a product. Which accounting discipline is designed to support this kind of internal decision-making?","options":["Financial auditing","Bookkeeping","Managerial accounting","Forensic accounting"],"answer":2,"explain":"Managerial accounting (kế toán quản trị) cung cấp báo cáo nội bộ như so sánh phương án sản xuất, chi phí dự kiến để ra quyết định. Financial auditing là kiểm toán độc lập; bookkeeping chỉ là ghi sổ; forensic accounting là điều tra gian lận.","extra":[{"en":"management accounts","vi":"báo cáo kế toán quản trị"},
{"en":"cost-benefit analysis","vi":"phân tích chi phí - lợi ích"},
{"en":"discontinue a product","vi":"ngừng sản xuất sản phẩm"}]},
{"id":"q0364","unit":3,"stem":"A company holds a short-term investment that can be converted readily into a known amount of cash and carries an insignificant risk of changes in value. How should the investment be classified?","options":["Cash equivalents","Receivables","Goodwill","Treasury shares"],"answer":0,"explain":"Cash equivalents là các khoản đầu tư ngắn hạn dễ quy đổi thành tiền với rủi ro biến động giá không đáng kể. Receivables là khoản phải thu; goodwill là tài sản vô hình; treasury shares là cổ phiếu quỹ.","extra":[{"en":"short-term investment","vi":"khoản đầu tư ngắn hạn"},
{"en":"liquid assets","vi":"tài sản có tính thanh khoản"},
{"en":"money market fund","vi":"quỹ thị trường tiền tệ"}]},
{"id":"q0365","unit":1,"stem":"A factory processes 2,500 units of input, but only 2,275 finished units satisfy all quality requirements. Which indicator captures the proportion of acceptable output relative to the total processed input?","options":["Line efficiency","Capacity planning","Value added","Production yield"],"answer":3,"explain":"Production yield là tỷ lệ sản lượng đạt chuẩn trên tổng đầu vào (2.275/2.500 = 91%). Line efficiency đo mức sử dụng dây chuyền; capacity planning là hoạch định công suất; value added là giá trị gia tăng, không phải tỷ lệ sản phẩm đạt.","extra":[{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"scrap rate","vi":"tỷ lệ phế phẩm"},
{"en":"first-pass yield","vi":"tỷ lệ đạt ngay lần đầu"}]},
{"id":"q0366","unit":1,"stem":"A business converts unprocessed timber into finished furniture. The additional economic worth created through design, processing and assembly is known as:","options":["Value added","Lead time","Downtime","Raw materials"],"answer":0,"explain":"Value added (giá trị gia tăng) là phần giá trị tạo thêm nhờ thiết kế, gia công, lắp ráp từ nguyên liệu thô. Lead time là thời gian chờ từ đặt hàng đến giao; downtime là thời gian ngừng máy; raw materials chính là nguyên liệu đầu vào.","extra":[{"en":"value-added tax (VAT)","vi":"thuế giá trị gia tăng"},
{"en":"finished goods","vi":"thành phẩm"},
{"en":"add value to","vi":"làm tăng giá trị cho"}]},
{"id":"q0367","unit":5,"stem":"Under a new environmental rule, a factory must report its emissions whenever the measured level exceeds a specified limit. What is this limit called?","options":["A pressure group","A provision","A threshold","A loophole"],"answer":2,"explain":"Threshold là ngưỡng: mức giới hạn mà khi vượt qua thì phát sinh nghĩa vụ báo cáo. Pressure group là nhóm gây áp lực; provision là điều khoản/khoản dự phòng; loophole là kẽ hở pháp lý.","extra":[{"en":"exceed the threshold","vi":"vượt ngưỡng"},
{"en":"reporting requirement","vi":"yêu cầu báo cáo"},
{"en":"emission limit","vi":"giới hạn khí thải"}]},
{"id":"q0368","unit":5,"stem":"An industry association arranges meetings with lawmakers and presents research intended to influence the wording of a proposed regulation. The association is attempting to:","options":["Enact legislation","Lobby lawmakers","Comply with legislation","Back down from legislation"],"answer":1,"explain":"Lobby là vận động hành lang: gặp nghị sĩ và trình bày nghiên cứu để tác động nội dung dự luật. Enact là ban hành luật (việc của cơ quan lập pháp); comply là tuân thủ; back down là rút lui trước áp lực.","extra":[{"en":"lobbying group","vi":"nhóm vận động hành lang"},
{"en":"draft legislation","vi":"dự thảo luật"},
{"en":"influence policy","vi":"tác động đến chính sách"}]},
{"id":"q0369","unit":5,"stem":"A company previously claimed that its new service would never involve hidden fees. After evidence reveals several undisclosed charges, it withdraws that earlier statement and acknowledges that it was inaccurate. Which expression best describes this change of position?","options":["Backtrack","Give ground on","Backflip","Offset"],"answer":0,"explain":"Backtrack là rút lại, thu hồi tuyên bố/quan điểm trước đó (ở đây công nhận lời nói sai). Give ground on là nhượng bộ một vấn đề; backflip là đảo ngược lập trường đột ngột (cũng gần nghĩa nhưng nhấn mạnh sự đổi ý hoàn toàn); offset là bù trừ.","extra":[{"en":"backtrack on a promise","vi":"rút lại lời hứa"},
{"en":"issue a retraction","vi":"đăng đính chính"},
{"en":"U-turn","vi":"đổi hướng 180 độ"}],"needsReview":true},
{"id":"q0370","unit":5,"stem":"During negotiations, a government originally demands that all imported products meet an unusually strict local-content requirement. It later accepts a less restrictive provision while maintaining its other objectives. It has agreed to:","options":["Backtrack on its entire policy","Give ground on one issue","Impose a new requirement","Make a take-over"],"answer":1,"explain":"Give ground on one issue là nhượng bộ ở một điểm trong khi vẫn giữ các mục tiêu khác. Backtrack on its entire policy là rút lại toàn bộ chính sách, trái với đề; impose là áp đặt; take-over là thâu tóm doanh nghiệp.","extra":[{"en":"make concessions","vi":"nhượng bộ"},
{"en":"hold firm","vi":"giữ vững lập trường"},
{"en":"local-content requirement","vi":"yêu cầu tỷ lệ nội địa hóa"}]},
{"id":"q0371","unit":5,"stem":"To protect domestic producers, a government introduces an additional customs duty on selected imported products. Which verb most accurately describes the government's action?","options":["Enact","Impose","Offset","Recoup"],"answer":1,"explain":"Impose a duty/tariff là áp đặt thuế nhập khẩu. Enact là ban hành luật, không dùng trực tiếp cho thuế như hành động áp dụng này; offset là bù đắp; recoup là thu hồi lại số tiền đã chi.","extra":[{"en":"impose a tariff","vi":"áp thuế quan"},
{"en":"customs duty","vi":"thuế hải quan"},
{"en":"protect domestic industry","vi":"bảo hộ ngành sản xuất trong nước"}]},
{"id":"q0372","unit":3,"stem":"A pharmaceutical company develops a new drug formulation and obtains an exclusive legal right that prevents other parties from commercially exploiting the invention for the protected period. The right is a:","options":["Trademark","Goodwill","Specification","Patent"],"answer":3,"explain":"Patent (bằng sáng chế) trao quyền độc quyền khai thác phát minh trong thời hạn nhất định. Trademark bảo hộ nhãn hiệu; goodwill là lợi thế thương mại; specification là bản mô tả kỹ thuật.","extra":[{"en":"file a patent","vi":"nộp đơn sáng chế"},
{"en":"patent infringement","vi":"vi phạm bằng sáng chế"},
{"en":"intellectual property","vi":"sở hữu trí tuệ"}]},
{"id":"q0373","unit":4,"stem":"An investor borrows shares from a broker, sells them immediately and expects to repurchase them later at a lower price before returning them. Which investment strategy is being used?","options":["Leverage","Mutual fund investment","Long-term acquisition","Short selling"],"answer":3,"explain":"Short selling là bán khống: vay cổ phiếu, bán ngay, mua lại khi giá giảm rồi trả. Leverage là dùng vốn vay; mutual fund là quỹ tương hỗ; long-term acquisition là mua lại dài hạn.","extra":[{"en":"short position","vi":"vị thế bán khống"},
{"en":"borrow shares","vi":"vay cổ phiếu"},
{"en":"bet against the market","vi":"đặt cược giá giảm"}]},
{"id":"q0374","unit":3,"stem":"A commodity's price changes sharply and unpredictably in response to geopolitical events, supply disruptions and shifts in market expectations. The commodity market is described as:","options":["Standardized","Embedded","Volatile","Agile"],"answer":2,"explain":"Volatile là biến động mạnh và khó đoán trước theo các sự kiện địa chính trị, đứt gãy nguồn cung. Standardized là chuẩn hóa; embedded là ăn sâu; agile là linh hoạt, không mô tả giá cả biến động.","extra":[{"en":"volatile market","vi":"thị trường biến động"},
{"en":"price swings","vi":"biến động giá"},
{"en":"commodity prices","vi":"giá hàng hóa"}]},
{"id":"q0375","unit":4,"stem":"A borrower receives a loan of $750,000 and must repay the original amount in addition to the interest charged by the lender. The $750,000 itself is the:","options":["Creditor","Interest rate","Return on investment","Principal"],"answer":3,"explain":"Principal là số tiền gốc vay (750.000 USD), chưa tính lãi. Creditor là chủ nợ; interest rate là lãi suất; return on investment là tỷ suất sinh lời đầu tư.","extra":[{"en":"repay the principal","vi":"trả nợ gốc"},
{"en":"accrued interest","vi":"lãi tích lũy"},
{"en":"loan term","vi":"kỳ hạn vay"}]},
{"id":"q0376","unit":4,"stem":"Thousands of individual investors contribute money to a professionally managed investment vehicle, which pools their contributions and invests in a portfolio of securities. The vehicle is most likely a:","options":["Mutual fund","Hedge fund","Mortgage loan","Joint venture"],"answer":0,"explain":"Mutual fund (quỹ tương hỗ) gom tiền của nhiều nhà đầu tư nhỏ lẻ và do chuyên gia quản lý đầu tư vào danh mục chứng khoán. Hedge fund dành cho nhà đầu tư đủ điều kiện; mortgage loan là khoản vay thế chấp; joint venture là liên doanh.","extra":[{"en":"fund manager","vi":"quản lý quỹ"},
{"en":"pool resources","vi":"gom vốn"},
{"en":"diversified portfolio","vi":"danh mục đa dạng hóa"}]},
{"id":"q0377","unit":4,"stem":"A private investment partnership limits participation to investors who satisfy specified financial or investment-experience criteria under the relevant rules. Such investors are commonly described as:","options":["Bondholders","Creditors","Receivables","Accredited investors"],"answer":3,"explain":"Accredited investors là nhà đầu tư đủ điều kiện (đạt tiêu chí tài chính hoặc kinh nghiệm theo quy định) được tham gia các quỹ riêng lẻ. Bondholders là người nắm giữ trái phiếu; creditors là chủ nợ; receivables là khoản phải thu.","extra":[{"en":"private placement","vi":"phát hành riêng lẻ"},
{"en":"high-net-worth individual","vi":"cá nhân giá trị tài sản ròng cao"},
{"en":"institutional investor","vi":"nhà đầu tư tổ chức"}]},
{"id":"q0378","unit":3,"stem":"A company registers a distinctive name, logo or symbol so that consumers can identify its goods and distinguish them from competing brands. The protected identifier is a:","options":["Patent","Trademark","Derivative","Provision"],"answer":1,"explain":"Trademark (nhãn hiệu) là tên, logo, biểu tượng đã đăng ký để người tiêu dùng phân biệt sản phẩm. Patent bảo hộ sáng chế; derivative là công cụ phái sinh; provision là khoản dự phòng.","extra":[{"en":"registered trademark","vi":"nhãn hiệu đã đăng ký"},
{"en":"brand identity","vi":"nhận diện thương hiệu"},
{"en":"counterfeit goods","vi":"hàng giả"}]},
{"id":"q0379","unit":5,"stem":"A medicine is legally classified for sale directly to consumers without a prescription from a medical practitioner. It is an:","options":["Accredited medicine","Over-the-counter drug","Deferred tax treatment","Mortgage-backed security"],"answer":1,"explain":"Over-the-counter (OTC) drug là thuốc bán không cần đơn bác sĩ. Accredited medicine không phải thuật ngữ chuẩn; deferred tax treatment và mortgage-backed security thuộc lĩnh vực tài chính, không liên quan.","extra":[{"en":"prescription drug","vi":"thuốc kê đơn"},
{"en":"generic drug","vi":"thuốc generic"},
{"en":"regulatory approval","vi":"phê duyệt của cơ quan quản lý"}]},
{"id":"q0380","unit":6,"stem":"An airline reduces the number of employees and closes several operating units in order to lower its overall size and recurring costs. The company is choosing to:","options":["Decentralize","Relocate","Downsize","Deregulate"],"answer":2,"explain":"Downsize là cắt giảm nhân sự và đóng đơn vị để thu nhỏ quy mô và giảm chi phí thường xuyên. Decentralize là phân quyền; relocate là chuyển địa điểm; deregulate là bỏ quy định.","extra":[{"en":"job cuts","vi":"cắt giảm việc làm"},
{"en":"streamline operations","vi":"tinh gọn hoạt động"},
{"en":"redundancy","vi":"sa thải do dư thừa"}]},
{"id":"q0381","unit":6,"stem":"A corporation changes its reporting relationships, reorganizes business divisions, renegotiates certain obligations and redesigns how its major activities are managed. This broad organisational change is a decision to:","options":["Relaunch","Downsize","Upgrade","Restructure"],"answer":3,"explain":"Restructure là tái cấu trúc toàn diện: đổi quan hệ báo cáo, tổ chức lại các bộ phận, đàm phán lại nghĩa vụ. Downsize chỉ là thu nhỏ; relaunch là tung ra lại sản phẩm; upgrade là nâng cấp.","extra":[{"en":"corporate restructuring","vi":"tái cấu trúc doanh nghiệp"},
{"en":"reorganise divisions","vi":"tổ chức lại các bộ phận"},
{"en":"debt restructuring","vi":"tái cơ cấu nợ"}]},
{"id":"q0382","unit":6,"stem":"A multinational transfers authority over pricing, recruitment and local operations from its headquarters to managers in individual markets. Which strategic change does this represent?","options":["Decentralize","Deregulate","Downgrade","Downsize"],"answer":0,"explain":"Decentralize là phân quyền: chuyển quyền quyết định về giá, tuyển dụng, vận hành từ trụ sở về các thị trường địa phương. Deregulate là bãi bỏ quy định; downgrade là hạ cấp; downsize là cắt giảm quy mô.","extra":[{"en":"devolve authority","vi":"trao quyền"},
{"en":"local autonomy","vi":"quyền tự chủ địa phương"},
{"en":"head office","vi":"trụ sở chính"}]},
{"id":"q0383","unit":6,"stem":"A government removes selected restrictions that previously limited entry into an industry, aiming to allow firms greater freedom to compete. This policy is known as:","options":["Deregulation","Decentralization","Legislation","Restructuring"],"answer":0,"explain":"Deregulation là bãi bỏ quy định hạn chế gia nhập ngành để tăng cạnh tranh. Decentralization là phân quyền trong tổ chức; legislation là việc ban hành luật; restructuring là tái cấu trúc doanh nghiệp.","extra":[{"en":"barriers to entry","vi":"rào cản gia nhập ngành"},
{"en":"liberalise the market","vi":"tự do hóa thị trường"},
{"en":"free competition","vi":"cạnh tranh tự do"}]},
{"id":"q0384","unit":6,"stem":"A retailer returns a discontinued product to the market with redesigned packaging, revised positioning and a new promotional campaign. The retailer plans to:","options":["Relocate the product","Downgrade the product","Restructure the product","Relaunch the product"],"answer":3,"explain":"Relaunch là tung ra lại sản phẩm với bao bì, định vị và chiến dịch mới. Relocate là di dời địa điểm; downgrade là hạ cấp; restructure là tái cơ cấu tổ chức, không dùng cho sản phẩm.","extra":[{"en":"product relaunch","vi":"tái ra mắt sản phẩm"},
{"en":"rebrand","vi":"đổi thương hiệu"},
{"en":"revamp the packaging","vi":"làm mới bao bì"}]},
{"id":"q0385","unit":6,"stem":"A hotel chain and a travel company agree to promote one another's services to their respective customer bases through coordinated campaigns. Their arrangement is an example of:","options":["Cross-promotion","Short selling","Bootstrapping","Resource allocation"],"answer":0,"explain":"Cross-promotion là hai công ty quảng bá chéo cho khách hàng của nhau. Short selling là bán khống; bootstrapping là tự lực khởi nghiệp không vốn ngoài; resource allocation là phân bổ nguồn lực.","extra":[{"en":"joint campaign","vi":"chiến dịch phối hợp"},
{"en":"customer base","vi":"tệp khách hàng"},
{"en":"brand partnership","vi":"hợp tác thương hiệu"}]},
{"id":"q0386","unit":6,"stem":"A specialist manufacturer can charge customers considerably more than the market average because buyers associate its products with superior quality and exclusive service. Customers are willing to pay a:","options":["Principal","Premium","Provision","Threshold"],"answer":1,"explain":"Premium là mức giá cao hơn thị trường mà khách chấp nhận trả vì chất lượng và dịch vụ độc quyền. Principal là tiền gốc; provision là khoản dự phòng; threshold là ngưỡng.","extra":[{"en":"premium price","vi":"giá cao cấp"},
{"en":"command a premium","vi":"có thể bán giá cao hơn"},
{"en":"luxury segment","vi":"phân khúc xa xỉ"}]},
{"id":"q0387","unit":6,"stem":"A company's annual accounts report £18 million generated from its ordinary sales of goods and services during the year. In this context, the word turnover refers to:","options":["The number of employees leaving","The value of unpaid liabilities","The time taken to complete production","Sales revenue"],"answer":3,"explain":"Trong báo cáo thường niên, turnover (Anh-Anh) là doanh thu bán hàng và dịch vụ thông thường. Số nhân viên nghỉ việc là staff turnover (không phải nghĩa trong ngữ cảnh này); khoản nợ chưa trả là liabilities; thời gian hoàn thành sản xuất là lead time.","extra":[{"en":"annual turnover","vi":"doanh thu hằng năm"},
{"en":"sales revenue","vi":"doanh thu bán hàng"},
{"en":"gross profit","vi":"lợi nhuận gộp"}]},
{"id":"q0388","unit":6,"stem":"A retailer experiences a high rate of staff departures and must continually recruit and train replacement workers. The problem is most accurately described as high:","options":["Production yield","Inventory turnover","Employee turnover","Line efficiency"],"answer":2,"explain":"Employee turnover là tỷ lệ nhân viên nghỉ việc và phải thay thế, đúng với tình huống tuyển và đào tạo liên tục. Production yield là tỷ lệ sản phẩm đạt; inventory turnover là vòng quay hàng tồn; line efficiency là hiệu suất dây chuyền.","extra":[{"en":"staff retention","vi":"giữ chân nhân viên"},
{"en":"recruitment costs","vi":"chi phí tuyển dụng"},
{"en":"attrition rate","vi":"tỷ lệ hao hụt nhân sự"}]},
{"id":"q0389","unit":3,"stem":"A profitable company decides to retain part of its earnings rather than distribute the entire amount to shareholders as dividends. The accumulated undistributed profits are recorded as:","options":["Treasury shares","Receivables","Retained earnings","Deferred tax"],"answer":2,"explain":"Retained earnings là lợi nhuận giữ lại, chưa chia cổ tức. Treasury shares là cổ phiếu quỹ; receivables là khoản phải thu; deferred tax là thuế hoãn lại.","extra":[{"en":"dividend payout","vi":"chi trả cổ tức"},
{"en":"reinvest profits","vi":"tái đầu tư lợi nhuận"},
{"en":"distributable reserves","vi":"quỹ có thể phân phối"}]},
{"id":"q0390","unit":3,"stem":"A company pays more to acquire another business than the fair value of the target's identifiable net assets. The excess may be recognised as an intangible asset called:","options":["A provision","Goodwill","A liability","A receivable"],"answer":1,"explain":"Goodwill là phần trả vượt giá trị hợp lý của tài sản ròng có thể xác định, được ghi nhận là tài sản vô hình. Provision là dự phòng; liability là nợ phải trả; receivable là khoản phải thu.","extra":[{"en":"impairment of goodwill","vi":"suy giảm giá trị lợi thế thương mại"},
{"en":"fair value","vi":"giá trị hợp lý"},
{"en":"net assets","vi":"tài sản ròng"}]},
{"id":"q0391","unit":3,"stem":"A company's accounting records show assets of $12 million and liabilities of $7.5 million. The residual interest attributable to the owners is:","options":["$7.5 million in liabilities","$4.5 million in equity","$12 million in receivables","$19.5 million in retained earnings"],"answer":1,"explain":"Equity = tài sản - nợ phải trả = 12 - 7,5 = 4,5 triệu USD, tức phần quyền lợi còn lại của chủ sở hữu. 7,5 triệu là nợ; 12 triệu là tổng tài sản; 19,5 triệu là phép cộng sai.","extra":[{"en":"accounting equation","vi":"phương trình kế toán"},
{"en":"shareholders' equity","vi":"vốn chủ sở hữu"},
{"en":"balance sheet","vi":"bảng cân đối kế toán"}]},
{"id":"q0392","unit":5,"stem":"A trade agreement aims to ensure that foreign and domestic firms compete under comparable rules, rather than granting one group an unjustified regulatory advantage. The agreement seeks to establish:","options":["A cash cow","A strategic vision","A level playing field","A production bottleneck"],"answer":2,"explain":"Level playing field là sân chơi bình đẳng: doanh nghiệp trong và ngoài nước cạnh tranh theo luật tương đương. Cash cow là sản phẩm sinh lời ổn định; strategic vision là tầm nhìn chiến lược; bottleneck là nút thắt sản xuất.","extra":[{"en":"fair competition","vi":"cạnh tranh công bằng"},
{"en":"trade barriers","vi":"rào cản thương mại"},
{"en":"regulatory advantage","vi":"lợi thế về quy định"}]},
{"id":"q0393","unit":6,"stem":"A customer is more likely to buy a printer when purchasing compatible ink cartridges, because the two products are typically used together. In economic terms, the products are:","options":["Complements","Substitutes","Derivatives","Provisions"],"answer":0,"explain":"Complements là sản phẩm bổ trợ: máy in và mực in được dùng cùng nhau nên mua cái này thúc đẩy mua cái kia. Substitutes là sản phẩm thay thế; derivatives là công cụ phái sinh; provisions là khoản dự phòng.","extra":[{"en":"complementary goods","vi":"hàng hóa bổ sung"},
{"en":"go hand in hand","vi":"đi đôi với nhau"},
{"en":"bundle products","vi":"bán gói sản phẩm"}]},
{"id":"q0394","unit":6,"stem":"When the price of one brand of bottled water rises, consumers switch to a competing brand that satisfies essentially the same need. The two brands are functioning as:","options":["Complements","Premium products","Substitutes","Cash equivalents"],"answer":2,"explain":"Substitutes là sản phẩm thay thế: khi giá nhãn này tăng, người mua chuyển sang nhãn khác cùng thỏa mãn nhu cầu. Complements bổ trợ cho nhau; premium products là sản phẩm cao cấp; cash equivalents là tương đương tiền.","extra":[{"en":"close substitute","vi":"sản phẩm thay thế gần"},
{"en":"switch brands","vi":"đổi nhãn hiệu"},
{"en":"price sensitivity","vi":"độ nhạy cảm về giá"}]},
{"id":"q0395","unit":6,"stem":"A bank redesigns its mobile services around the needs of older customers who value in-person assistance and straightforward digital instructions. The bank is attempting to:","options":["Offset its clientele","Recoup its clientele","Cater to this clientele","Downgrade this clientele"],"answer":2,"explain":"Cater to là đáp ứng, phục vụ nhu cầu của một nhóm khách hàng cụ thể (người lớn tuổi). Offset là bù trừ; recoup là thu hồi; downgrade là hạ cấp, không hợp nghĩa đề.","extra":[{"en":"cater to customers' needs","vi":"phục vụ nhu cầu khách hàng"},
{"en":"target audience","vi":"đối tượng mục tiêu"},
{"en":"user-friendly","vi":"dễ sử dụng"}]},
{"id":"q0396","unit":1,"stem":"A manufacturer continuously monitors stock quantities, replenishment points and expected demand to prevent both shortages and excessive holding costs. Which operational function is responsible?","options":["Inventory management","Production scheduling","Machine maintenance","Capacity planning"],"answer":0,"explain":"Inventory management là quản lý tồn kho: theo dõi lượng hàng, điểm đặt hàng lại và dự báo nhu cầu để tránh thiếu hụt và chi phí lưu kho quá mức. Production scheduling lập lịch sản xuất; machine maintenance là bảo trì; capacity planning là hoạch định công suất.","extra":[{"en":"reorder point","vi":"điểm đặt hàng lại"},
{"en":"stock-out","vi":"tình trạng hết hàng"},
{"en":"safety stock","vi":"tồn kho an toàn"}]},
{"id":"q0397","unit":1,"stem":"A factory introduces regular inspections, lubrication and replacement of worn components to reduce the likelihood of equipment failure. These activities constitute:","options":["Production scheduling","Quality assurance","Performance measurement","Machine maintenance"],"answer":3,"explain":"Machine maintenance là bảo trì máy: kiểm tra định kỳ, bôi trơn, thay linh kiện mòn để giảm nguy cơ hỏng hóc. Quality assurance bảo đảm chất lượng sản phẩm; production scheduling là lập lịch; performance measurement là đo hiệu suất.","extra":[{"en":"preventive maintenance","vi":"bảo trì phòng ngừa"},
{"en":"breakdown","vi":"sự cố hỏng máy"},
{"en":"wear and tear","vi":"hao mòn"}]},
{"id":"q0398","unit":2,"stem":"A buyer's contract specifies a product's dimensions, material composition, tolerances and required performance characteristics. These detailed technical requirements are its:","options":["Specifications","Performance metrics","Strategic vision","Production yield"],"answer":0,"explain":"Specifications là bản thông số kỹ thuật: kích thước, vật liệu, dung sai, đặc tính hiệu năng yêu cầu. Performance metrics là chỉ số hiệu suất; strategic vision là tầm nhìn chiến lược; production yield là tỷ lệ đạt.","extra":[{"en":"meet specifications","vi":"đáp ứng thông số"},
{"en":"tolerance level","vi":"mức dung sai"},
{"en":"technical requirements","vi":"yêu cầu kỹ thuật"}]},
{"id":"q0399","unit":6,"stem":"A company is among the first in its industry to introduce a radically new manufacturing process and becomes known for opening up a previously unexplored market opportunity. It is a:","options":["Creditor","Bondholder","Pioneer","Backbench"],"answer":2,"explain":"Pioneer là công ty tiên phong, đi đầu áp dụng quy trình mới và mở ra thị trường chưa khai phá. Creditor là chủ nợ; bondholder là người giữ trái phiếu; backbench là ghế sau trong nghị viện.","extra":[{"en":"first-mover advantage","vi":"lợi thế người đi đầu"},
{"en":"pioneering technology","vi":"công nghệ tiên phong"},
{"en":"untapped market","vi":"thị trường chưa khai thác"}]},
{"id":"q0400","unit":5,"stem":"A manufacturer purchases tradable environmental units representing a defined quantity of greenhouse-gas emissions under a recognised scheme, seeking to balance out emissions that it has not yet eliminated. These units are known as:","options":["Industrial emissions","Pressure groups","Waste disposal","Carbon credits"],"answer":3,"explain":"Carbon credits là tín chỉ carbon: đơn vị giao dịch đại diện cho lượng khí nhà kính, dùng để bù đắp lượng phát thải chưa loại bỏ được. Industrial emissions là khí thải công nghiệp; pressure groups là nhóm gây áp lực; waste disposal là xử lý chất thải.","extra":[{"en":"carbon footprint","vi":"dấu chân carbon"},
{"en":"emissions trading scheme","vi":"cơ chế mua bán phát thải"},
{"en":"net zero","vi":"phát thải ròng bằng không"}]},
{"id":"q0401","unit":1,"stem":"A manufacturer has received several urgent orders but is unsure how to sequence them across its machines and workforce. Which management activity is most directly concerned with deciding when each production task should begin and end?","options":["Capacity planning","Production scheduling","Machine maintenance","Operations management"],"answer":1,"explain":"Production scheduling là lập lịch sản xuất: quyết định khi nào mỗi công việc bắt đầu và kết thúc trên máy và nhân công. Capacity planning là hoạch định công suất dài hạn; machine maintenance là bảo trì; operations management là khái niệm quản lý vận hành rộng hơn.","extra":[{"en":"rush order","vi":"đơn hàng gấp"},
{"en":"meet a deadline","vi":"kịp thời hạn"},
{"en":"work schedule","vi":"lịch làm việc"}]},
{"id":"q0402","unit":2,"stem":"A retailer monitors its warehouse stock continuously. Whenever the quantity of a particular component falls below the predetermined level, the purchasing department orders additional units to restore the stock. Which verb best describes this action?","options":["Recoup","Offset","Incur","Replenish"],"answer":3,"explain":"Replenish là bổ sung hàng tồn kho về mức yêu cầu khi xuống dưới mức định trước. Recoup là thu hồi tiền đã chi; offset là bù trừ; incur là phát sinh (chi phí).","extra":[{"en":"replenish stock","vi":"bổ sung hàng tồn"},
{"en":"reorder level","vi":"mức đặt hàng lại"},
{"en":"restock shelves","vi":"lấp đầy kệ hàng"}]},
{"id":"q0403","unit":2,"stem":"A pharmaceutical company introduces systematic inspections, documented procedures and employee training to prevent defects before products reach customers. Which concept best describes this preventive system?","options":["Quality assurance","Performance measurement","Production yield","Auditing"],"answer":0,"explain":"Quality assurance là đảm bảo chất lượng: hệ thống phòng ngừa lỗi bằng kiểm tra, quy trình văn bản, đào tạo trước khi hàng tới khách. Performance measurement là đo hiệu suất; production yield là tỷ lệ sản phẩm đạt; auditing là kiểm toán.","extra":[{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"defect prevention","vi":"phòng ngừa lỗi"},
{"en":"compliance procedures","vi":"quy trình tuân thủ"}]},
{"id":"q0404","unit":1,"stem":"A factory produces 12,000 units during a month, but only 11,400 satisfy the required specifications. Which performance measure would most directly indicate the proportion of acceptable output?","options":["Line efficiency","Lead time","Production yield","Capacity planning"],"answer":2,"explain":"Production yield là tỷ lệ sản lượng đạt tiêu chuẩn trên tổng sản xuất (11.400/12.000 = 95%). Line efficiency đo sử dụng dây chuyền; lead time là thời gian chờ; capacity planning là hoạch định công suất.","extra":[{"en":"reject rate","vi":"tỷ lệ loại bỏ"},
{"en":"output per hour","vi":"sản lượng mỗi giờ"},
{"en":"meet specifications","vi":"đạt thông số kỹ thuật"}]},
{"id":"q0405","unit":1,"stem":"A critical machine unexpectedly breaks down, forcing the entire production line to stop for six hours while engineers repair it. What is this period of inactivity called?","options":["Bottleneck","Lead time","Downtime","Threshold"],"answer":2,"explain":"Downtime là thời gian ngừng hoạt động do máy hỏng. Bottleneck là nút thắt làm chậm cả quy trình; lead time là thời gian chờ từ đặt hàng đến giao; threshold là ngưỡng.","extra":[{"en":"machine breakdown","vi":"máy hỏng"},
{"en":"unplanned downtime","vi":"thời gian ngừng ngoài kế hoạch"},
{"en":"lost production","vi":"sản lượng bị mất"}]},
{"id":"q0406","unit":2,"stem":"A manufacturing company wants to avoid both excessive stockholding costs and shortages of essential components. It therefore monitors stock levels, records material movements and coordinates replenishment decisions. Which function is responsible for these activities?","options":["Inventory management","Supply chain","Production scheduling","Capacity planning"],"answer":0,"explain":"Inventory management là quản lý tồn kho: theo dõi mức tồn, ghi nhận di chuyển vật tư và điều phối việc bổ sung. Supply chain là cả mạng lưới cung ứng rộng hơn; production scheduling là lập lịch sản xuất; capacity planning là hoạch định công suất.","extra":[{"en":"stock control","vi":"kiểm soát tồn kho"},
{"en":"holding costs","vi":"chi phí tồn trữ"},
{"en":"stock turnover","vi":"vòng quay hàng tồn"}]},
{"id":"q0407","unit":3,"stem":"A company's financial statements classify certain short-term investments as assets because they can be converted into a known amount of cash almost immediately, with insignificant risk of changes in value. Which accounting category is most appropriate?","options":["Receivables","Treasury shares","Goodwill","Cash equivalents"],"answer":3,"explain":"Cash equivalents là khoản đầu tư ngắn hạn chuyển đổi nhanh thành tiền với rủi ro biến động giá không đáng kể. Receivables là phải thu; treasury shares là cổ phiếu quỹ; goodwill là lợi thế thương mại.","extra":[{"en":"cash and cash equivalents","vi":"tiền và các khoản tương đương tiền"},
{"en":"treasury bills","vi":"tín phiếu kho bạc"},
{"en":"current assets","vi":"tài sản ngắn hạn"}]},
{"id":"q0408","unit":3,"stem":"Company A acquires Company B for more than the fair value of B's identifiable net assets. The excess amount is partly attributable to B's established reputation, customer relationships and brand strength. Which intangible asset does this excess primarily represent?","options":["Patent","Goodwill","Deferred tax","Retained earnings"],"answer":1,"explain":"Goodwill là phần chênh lệch trả vượt giá trị hợp lý tài sản ròng, phản ánh uy tín, quan hệ khách hàng, thương hiệu. Patent là bằng sáng chế; deferred tax là thuế hoãn lại; retained earnings là lợi nhuận giữ lại.","extra":[{"en":"acquisition premium","vi":"phần bù khi mua lại"},
{"en":"brand value","vi":"giá trị thương hiệu"},
{"en":"intangible assets","vi":"tài sản vô hình"}]},
{"id":"q0409","unit":3,"stem":"A business deliberately uses questionable accounting treatments to make its financial performance appear more favourable to investors, although the presentation may not reflect the underlying economic reality. Which term best describes this practice?","options":["Creative accounting","Bookkeeping","Forensic accounting","Tax accounting"],"answer":0,"explain":"Creative accounting là kế toán sáng tạo: dùng thủ thuật nghi vấn để báo cáo đẹp hơn thực tế. Bookkeeping là ghi sổ; forensic accounting là điều tra gian lận; tax accounting là kế toán thuế, không có hàm ý đánh lừa.","extra":[{"en":"window dressing","vi":"làm đẹp báo cáo tài chính"},
{"en":"falsify accounts","vi":"làm sai lệch sổ sách"},
{"en":"misstate earnings","vi":"khai sai lợi nhuận"}]},
{"id":"q0410","unit":3,"stem":"A company expects to incur costs from probable warranty claims relating to products already sold. Although the exact timing and amount are uncertain, the obligation can be reasonably estimated. Which accounting term best describes the amount recognized for this expected obligation?","options":["Liabilities","Equity","Receivables","Provisions"],"answer":3,"explain":"Provisions là khoản dự phòng ghi nhận cho nghĩa vụ có thể xảy ra (bảo hành) khi thời điểm và số tiền chưa chắc chắn nhưng ước tính được. Liabilities là nợ phải trả nói chung; equity là vốn chủ; receivables là phải thu.","extra":[{"en":"warranty claims","vi":"yêu cầu bảo hành"},
{"en":"contingent liability","vi":"nợ tiềm tàng"},
{"en":"set aside funds","vi":"trích lập quỹ"}]},
{"id":"q0411","unit":4,"stem":"A company borrows $500,000 from a bank at an agreed interest rate. When calculating the amount on which interest is charged, which term refers specifically to the original amount borrowed, excluding interest?","options":["Security","Return on investment","Principal","Interest"],"answer":2,"explain":"Principal là số tiền gốc đi vay, không gồm lãi. Security là tài sản bảo đảm; return on investment là tỷ suất sinh lời; interest là tiền lãi, trái với yêu cầu 'không gồm lãi'.","extra":[{"en":"outstanding principal","vi":"dư nợ gốc"},
{"en":"repayment schedule","vi":"lịch trả nợ"},
{"en":"fixed interest rate","vi":"lãi suất cố định"}]},
{"id":"q0412","unit":4,"stem":"Before acquiring a competing business, the buyer examines its financial statements, contracts, tax records, legal disputes and operational risks. What is this investigative process called?","options":["Metric","Due diligence","Leverage","Creditor"],"answer":1,"explain":"Due diligence là thẩm định (rà soát tài chính, hợp đồng, thuế, tranh chấp, rủi ro) trước khi mua doanh nghiệp. Metric là chỉ số đo lường; leverage là đòn bẩy; creditor là chủ nợ.","extra":[{"en":"conduct due diligence","vi":"thực hiện thẩm định"},
{"en":"target company","vi":"công ty mục tiêu"},
{"en":"merger and acquisition (M&A)","vi":"sáp nhập và mua lại"}]},
{"id":"q0413","unit":4,"stem":"An investment contract derives its value from the performance of an underlying asset, such as a commodity, stock, interest rate or market index. Which financial instrument is being described?","options":["Hedge fund","Mortgage loan","Bondholder","Derivative"],"answer":3,"explain":"Derivative là công cụ phái sinh: giá trị phụ thuộc vào tài sản cơ sở (hàng hóa, cổ phiếu, lãi suất, chỉ số). Hedge fund là quỹ đầu cơ; mortgage loan là vay thế chấp; bondholder là người giữ trái phiếu.","extra":[{"en":"underlying asset","vi":"tài sản cơ sở"},
{"en":"futures contract","vi":"hợp đồng tương lai"},
{"en":"hedge against risk","vi":"phòng ngừa rủi ro"}]},
{"id":"q0414","unit":4,"stem":"A company finances a major expansion partly through borrowing rather than relying entirely on shareholders' capital. This may increase potential returns but also magnify financial risk. Which financial concept does this illustrate?","options":["Leverage","Bootstrapping","Cash equivalents","Return on investment"],"answer":0,"explain":"Leverage là đòn bẩy tài chính: vay nợ để mở rộng, có thể tăng lợi nhuận nhưng cũng khuếch đại rủi ro. Bootstrapping là tự lực không vay ngoài; cash equivalents là tương đương tiền; ROI là tỷ suất sinh lời.","extra":[{"en":"highly leveraged","vi":"vay nợ nhiều"},
{"en":"debt-to-equity ratio","vi":"tỷ lệ nợ trên vốn chủ"},
{"en":"gearing","vi":"tỷ lệ đòn bẩy (Anh-Anh)"}]},
{"id":"q0415","unit":4,"stem":"Which investment vehicle is most commonly associated with sophisticated strategies such as short selling, derivatives and the use of leverage, and may restrict participation to accredited investors?","options":["Mutual fund","Hedge fund","Joint venture","Financial backer"],"answer":1,"explain":"Hedge fund (quỹ phòng hộ) dùng chiến lược phức tạp như bán khống, phái sinh, đòn bẩy và chỉ nhận nhà đầu tư đủ điều kiện. Mutual fund dành cho công chúng đại trà, ít dùng các chiến lược này; joint venture là liên doanh; financial backer là nhà tài trợ.","extra":[{"en":"accredited investor","vi":"nhà đầu tư đủ điều kiện"},
{"en":"alternative investment","vi":"đầu tư thay thế"},
{"en":"performance fee","vi":"phí thưởng hiệu suất"}]},
{"id":"q0416","unit":4,"stem":"A manufacturing company purchases raw materials on credit from a supplier. Until the invoice is paid, how should the supplier be described from the company's financial perspective?","options":["Bondholder","Borrower","Creditor","Financial backer"],"answer":2,"explain":"Creditor là chủ nợ: bên cho công ty nợ (nhà cung cấp bán chịu) cho tới khi hóa đơn được thanh toán. Bondholder là người giữ trái phiếu; borrower là bên vay (chính công ty); financial backer là nhà tài trợ vốn.","extra":[{"en":"trade credit","vi":"tín dụng thương mại"},
{"en":"accounts payable","vi":"các khoản phải trả"},
{"en":"settle an invoice","vi":"thanh toán hóa đơn"}]},
{"id":"q0417","unit":5,"stem":"A national parliament formally passes a new law establishing stricter requirements for industrial waste disposal. Which verb most accurately describes the process of formally making the law?","options":["Impose","Enact","Lobby","Backtrack"],"answer":1,"explain":"Enact là chính thức ban hành, thông qua một đạo luật. Impose là áp đặt (ví dụ thuế); lobby là vận động hành lang; backtrack là rút lại ý kiến/lời nói.","extra":[{"en":"enact legislation","vi":"ban hành luật"},
{"en":"pass a bill","vi":"thông qua dự luật"},
{"en":"come into force","vi":"có hiệu lực"}]},
{"id":"q0418","unit":5,"stem":"An industry association hires specialists to persuade members of parliament to amend a proposed environmental regulation in ways that would reduce compliance costs for its members. Which action are the specialists primarily undertaking?","options":["Address","Compromise","Form a coalition","Lobby"],"answer":3,"explain":"Lobby là vận động hành lang, thuyết phục nghị sĩ sửa đổi quy định có lợi cho hội viên. Compromise là thỏa hiệp; form a coalition là lập liên minh; address là giải quyết một vấn đề, không mang nghĩa thuyết phục chính trị gia.","extra":[{"en":"lobbyist","vi":"người vận động hành lang"},
{"en":"compliance costs","vi":"chi phí tuân thủ"},
{"en":"amend a bill","vi":"sửa đổi dự luật"}]},
{"id":"q0419","unit":5,"stem":"A factory invests in cleaner technology and purchases carbon credits to compensate for a portion of its remaining emissions. In this context, the credits are intended to ______ the environmental impact of those emissions.","options":["Offset","Recoup","Dump","Impose"],"answer":0,"explain":"Offset là bù đắp: tín chỉ carbon dùng để bù lại tác động của lượng phát thải còn lại. Recoup là thu hồi chi phí; dump là vứt bỏ; impose là áp đặt.","extra":[{"en":"carbon offset","vi":"bù trừ carbon"},
{"en":"reduce emissions","vi":"giảm khí thải"},
{"en":"environmental impact","vi":"tác động môi trường"}]},
{"id":"q0420","unit":5,"stem":"After publicly claiming that its products were entirely environmentally friendly, a company discovers evidence that contradicts the statement. It subsequently withdraws its earlier claim and issues a correction. Which expression best describes this reversal of its previous statement?","options":["Back down","Backflip","Backtrack","Give ground on"],"answer":2,"explain":"Backtrack là rút lại, đính chính tuyên bố trước đó khi có bằng chứng mâu thuẫn. Back down là nhượng bộ trước áp lực; give ground on là nhượng bộ một điểm; backflip là đảo ngược quan điểm đột ngột, cũng khá gần nghĩa.","extra":[{"en":"retract a statement","vi":"rút lại phát ngôn"},
{"en":"issue a correction","vi":"đưa ra đính chính"},
{"en":"greenwashing","vi":"tẩy xanh"}],"needsReview":true},
{"id":"q0421","unit":5,"stem":"An increase in household purchases of food, clothing, electronic devices and services contributes directly to a rise in aggregate demand. Which economic concept is being described?","options":["Consumer confidence","Life expectancy","Return on investment","Consumer spending"],"answer":3,"explain":"Consumer spending là chi tiêu tiêu dùng của hộ gia đình, làm tăng tổng cầu. Consumer confidence là niềm tin người tiêu dùng (tâm lý, không phải chi tiêu thực); life expectancy là tuổi thọ; ROI là tỷ suất sinh lời.","extra":[{"en":"aggregate demand","vi":"tổng cầu"},
{"en":"disposable income","vi":"thu nhập khả dụng"},
{"en":"household spending","vi":"chi tiêu hộ gia đình"}]},
{"id":"q0422","unit":5,"stem":"A company's established product line generates substantial and relatively predictable profits, requiring little additional investment to maintain its market position. Management uses these profits to finance newer business initiatives. The established product line is best described as a:","options":["Cash cow","Venture","Untapped market","Premium product"],"answer":0,"explain":"Cash cow là sản phẩm lâu năm sinh lợi nhuận lớn, ổn định, cần ít đầu tư, dùng để tài trợ cho dự án mới. Venture là dự án mạo hiểm; untapped market là thị trường chưa khai thác; premium product là sản phẩm cao cấp.","extra":[{"en":"steady revenue stream","vi":"nguồn doanh thu ổn định"},
{"en":"fund new ventures","vi":"tài trợ dự án mới"},
{"en":"market share","vi":"thị phần"}]},
{"id":"q0423","unit":5,"stem":"A government introduces an emissions charge that applies only when a factory's annual pollution exceeds a legally specified level. What is this minimum level called?","options":["Norm","Threshold","Specification","Metric"],"answer":1,"explain":"Threshold là ngưỡng tối thiểu mà vượt qua thì áp dụng mức phí phát thải. Norm là chuẩn mực xã hội; specification là thông số kỹ thuật; metric là chỉ số đo.","extra":[{"en":"emissions charge","vi":"phí phát thải"},
{"en":"exceed the limit","vi":"vượt giới hạn"},
{"en":"pollution levels","vi":"mức ô nhiễm"}]},
{"id":"q0424","unit":6,"stem":"Three regional divisions ______ approximately 75% of the company's total workforce, while the remaining employees work at its headquarters.","options":["Complement","Substitute","Make up","Cater"],"answer":2,"explain":"Make up nghĩa là chiếm/cấu thành (một tỷ lệ). Complement là bổ sung; substitute là thay thế; cater là phục vụ (cần 'for/to'), không hợp ngữ pháp và nghĩa.","extra":[{"en":"account for","vi":"chiếm (tỷ lệ)"},
{"en":"make up the majority","vi":"chiếm đa số"},
{"en":"workforce","vi":"lực lượng lao động"}]},
{"id":"q0425","unit":1,"stem":"A multinational manufacturer coordinates suppliers, factories, warehouses and distributors to move components and finished products from their original sources to final customers. Which concept encompasses this entire network?","options":["Supply chain","Assembly line","Linear workflow","Clientele"],"answer":0,"explain":"Supply chain là chuỗi cung ứng: toàn bộ mạng lưới nhà cung cấp, nhà máy, kho, nhà phân phối đưa hàng đến khách. Assembly line là dây chuyền lắp ráp tại một nhà máy; linear workflow là quy trình tuyến tính; clientele là nhóm khách hàng.","extra":[{"en":"supply chain disruption","vi":"đứt gãy chuỗi cung ứng"},
{"en":"logistics network","vi":"mạng lưới hậu cần"},
{"en":"end customer","vi":"khách hàng cuối"}]},
{"id":"q0426","unit":6,"stem":"A software company operates in a rapidly changing market. Its employees can adjust workflows, reorganize teams and respond to customer feedback without lengthy approval procedures. Which adjective best describes this organizational capability?","options":["Rigid","Embedded","Standardized","Agile"],"answer":3,"explain":"Agile là linh hoạt, nhanh nhạy: điều chỉnh quy trình, tổ chức lại nhóm và phản hồi khách hàng mà không cần thủ tục phê duyệt dài. Rigid là cứng nhắc (trái nghĩa); embedded là ăn sâu; standardized là chuẩn hóa.","extra":[{"en":"agile methodology","vi":"phương pháp linh hoạt"},
{"en":"flat structure","vi":"cấu trúc phẳng"},
{"en":"respond quickly","vi":"phản ứng nhanh"}]},
{"id":"q0427","unit":6,"stem":"Faced with declining demand and persistent operating losses, a company reduces its workforce, closes several facilities and permanently decreases the scale of its operations. Which strategic action is it undertaking?","options":["Downgrade","Restructure","Downsize","Relocate"],"answer":2,"explain":"Downsize là thu hẹp quy mô lâu dài: cắt giảm nhân sự, đóng cơ sở. Restructure là tái cấu trúc (không nhất thiết giảm quy mô); downgrade là hạ cấp; relocate là chuyển địa điểm.","extra":[{"en":"scale back operations","vi":"thu hẹp hoạt động"},
{"en":"lay off staff","vi":"sa thải nhân viên"},
{"en":"operating losses","vi":"lỗ hoạt động"}],"needsReview":true},
{"id":"q0428","unit":6,"stem":"A multinational corporation transfers more decision-making authority from its headquarters to regional offices so that local managers can respond more effectively to market conditions. Which organizational change is being implemented?","options":["Upgrade","Decentralize","Deregulate","Relaunch"],"answer":1,"explain":"Decentralize là phân quyền từ trụ sở về văn phòng khu vực để phản ứng nhanh theo thị trường. Upgrade là nâng cấp; deregulate là bãi bỏ quy định; relaunch là tung lại sản phẩm.","extra":[{"en":"delegate decisions","vi":"ủy quyền ra quyết định"},
{"en":"regional offices","vi":"văn phòng khu vực"},
{"en":"flatter hierarchy","vi":"cấu trúc cấp bậc phẳng hơn"}]},
{"id":"q0429","unit":6,"stem":"Following the introduction of automated equipment, employees are provided with new training so that they can perform different and more technically demanding roles. What is the company doing?","options":["Downgrading","Relocating","Relaunching","Retraining"],"answer":3,"explain":"Retraining là đào tạo lại nhân viên để làm vai trò mới đòi hỏi kỹ thuật hơn sau khi tự động hóa. Downgrading là hạ cấp; relocating là chuyển địa điểm; relaunching là tung lại sản phẩm.","extra":[{"en":"upskill","vi":"nâng cao kỹ năng"},
{"en":"reskill","vi":"đào tạo kỹ năng mới"},
{"en":"automation","vi":"tự động hóa"}]},
{"id":"q0430","unit":6,"stem":"A luxury hotel develops exclusive services for its regular customers, tailoring its offers to the preferences of the specific group of people it serves. Which noun refers to this group of customers?","options":["Cross-promotion","Clientele","Exposure","Premium"],"answer":1,"explain":"Clientele là tập khách hàng thường xuyên của một doanh nghiệp. Cross-promotion là quảng bá chéo; exposure là mức độ lộ diện; premium là mức giá cao.","extra":[{"en":"loyal clientele","vi":"khách hàng trung thành"},
{"en":"exclusive services","vi":"dịch vụ độc quyền"},
{"en":"tailor offers","vi":"điều chỉnh ưu đãi theo nhu cầu"}]},
{"id":"q0431","unit":6,"stem":"A sportswear manufacturer and a fitness application agree to promote each other's products to their respective customer bases. The arrangement is intended to increase brand visibility for both parties. Which marketing strategy is this?","options":["Cross-promotion","Complement","Substitute","Exposure"],"answer":0,"explain":"Cross-promotion là hai bên quảng bá sản phẩm của nhau để tăng độ nhận diện. Complement là sản phẩm bổ trợ (khái niệm kinh tế, không phải chiến lược marketing); substitute là thay thế; exposure là sự hiện diện/lộ diện.","extra":[{"en":"brand visibility","vi":"độ nhận diện thương hiệu"},
{"en":"co-branding","vi":"đồng thương hiệu"},
{"en":"joint promotion","vi":"khuyến mãi chung"}]},
{"id":"q0432","unit":6,"stem":"A company introduces a premium delivery service that works particularly well alongside its existing online shopping platform. The two services are designed to support rather than replace one another. The new service is therefore intended to:","options":["Substitute the platform","Cater the platform","Complement the platform","Downgrade the platform"],"answer":2,"explain":"Complement là bổ trợ: dịch vụ mới đi cùng với nền tảng hiện có, hỗ trợ chứ không thay thế. Substitute là thay thế; cater cần giới từ 'to/for'; downgrade là hạ cấp.","extra":[{"en":"complement each other","vi":"bổ trợ cho nhau"},
{"en":"add-on service","vi":"dịch vụ bổ sung"},
{"en":"premium delivery","vi":"giao hàng cao cấp"}]},
{"id":"q0433","unit":3,"stem":"An auditor discovers that several invoices have not yet been paid by the company's customers. In the financial report, these amounts may be described as:","options":["Overdue","Pending","Outstanding","Volatile"],"answer":2,"explain":"Outstanding là còn chưa thanh toán (các hóa đơn khách chưa trả) trong báo cáo tài chính. Overdue là quá hạn (không chắc đã quá hạn); pending là đang chờ xử lý; volatile là biến động.","extra":[{"en":"outstanding invoices","vi":"hóa đơn chưa thanh toán"},
{"en":"accounts receivable","vi":"các khoản phải thu"},
{"en":"bad debt","vi":"nợ xấu"}],"needsReview":true},
{"id":"q0434","unit":6,"stem":"A human resources manager reports that the organization has experienced unusually high employee ______, meaning that many workers have left and had to be replaced during the year.","options":["Turnover","Exposure","Clientele","Lead time"],"answer":0,"explain":"Turnover (employee/staff turnover) là tỷ lệ nhân viên nghỉ và phải thay thế. Exposure là mức rủi ro/lộ diện; clientele là tập khách hàng; lead time là thời gian chờ.","extra":[{"en":"staff turnover","vi":"tỷ lệ nghỉ việc"},
{"en":"high attrition","vi":"tỷ lệ nghỉ việc cao"},
{"en":"replace workers","vi":"thay thế nhân sự"}]},
{"id":"q0435","unit":6,"stem":"A company identifies a customer segment with substantial purchasing potential, but no major competitor has yet developed products specifically for that group. This segment represents an ______ market opportunity.","options":["Embedded","Agile","Premium","Untapped"],"answer":3,"explain":"Untapped market là thị trường chưa khai thác, chưa có đối thủ lớn phục vụ. Embedded là ăn sâu; agile là linh hoạt; premium là cao cấp, không mô tả khoảng trống thị trường.","extra":[{"en":"untapped potential","vi":"tiềm năng chưa khai thác"},
{"en":"niche market","vi":"thị trường ngách"},
{"en":"market gap","vi":"khoảng trống thị trường"}]},
{"id":"q0436","unit":6,"stem":"After withdrawing a poorly performing product, a company redesigns its features, changes its positioning and introduces it to the market again with a new marketing campaign. Which verb best describes this action?","options":["Update","Relaunch","Downgrade","Upgrade"],"answer":1,"explain":"Relaunch là tung ra lại sản phẩm với tính năng, định vị và chiến dịch mới. Update/upgrade là cập nhật/nâng cấp tính năng nhưng không hàm ý đưa ra thị trường lần nữa; downgrade là hạ cấp.","extra":[{"en":"withdraw a product","vi":"thu hồi sản phẩm"},
{"en":"reposition","vi":"tái định vị"},
{"en":"marketing campaign","vi":"chiến dịch marketing"}]},
{"id":"q0437","unit":6,"stem":"Although a multinational corporation has introduced a new code of conduct, some outdated practices remain deeply rooted in its organizational culture. Which word best describes practices that have become firmly established within an organization?","options":["Embedded","Outstanding","Standardized","Tier"],"answer":0,"explain":"Embedded là ăn sâu, bám rễ vững trong văn hóa tổ chức. Outstanding là chưa trả/xuất sắc; standardized là chuẩn hóa; tier là tầng, bậc.","extra":[{"en":"deeply embedded","vi":"ăn sâu"},
{"en":"organisational culture","vi":"văn hóa tổ chức"},
{"en":"code of conduct","vi":"quy tắc ứng xử"}]},
{"id":"q0438","unit":5,"stem":"Several ______ in the national parliament criticize a proposed bill but do not hold ministerial positions or serve as members of the government's frontbench.","options":["Pressure groups","Protagonists","Coalitions","Backbench MPs"],"answer":3,"explain":"Backbench MPs là nghị sĩ ghế sau, không giữ chức bộ trưởng hay ghế hàng đầu của chính phủ. Pressure groups là nhóm gây áp lực bên ngoài nghị viện; protagonists là nhân vật chính; coalitions là liên minh.","extra":[{"en":"frontbench","vi":"ghế hàng đầu (bộ trưởng)"},
{"en":"opposition MP","vi":"nghị sĩ đối lập"},
{"en":"criticise a bill","vi":"phê phán dự luật"}]},
{"id":"q0439","unit":6,"stem":"A telecommunications provider combines internet access, mobile services and digital television into one discounted package. Which expression best describes this marketing approach?","options":["Make up","Bundle into","Complement","Cater"],"answer":1,"explain":"Bundle into là gói nhiều dịch vụ vào một gói giá ưu đãi. Make up là cấu thành; complement là bổ trợ; cater là phục vụ, không mô tả việc đóng gói chung.","extra":[{"en":"bundled package","vi":"gói dịch vụ kết hợp"},
{"en":"discounted deal","vi":"ưu đãi giảm giá"},
{"en":"triple play","vi":"gói ba dịch vụ"}]},
{"id":"q0440","unit":5,"stem":"A start-up invested heavily in developing a new technology. After securing a major commercial contract, it expects to recover the money previously spent on research and development. Which verb best describes this recovery?","options":["Offset","Replenish","Recoup","Incur"],"answer":2,"explain":"Recoup là thu hồi lại số tiền đã chi (chi phí R&D) nhờ hợp đồng mới. Offset là bù trừ; replenish là bổ sung tồn kho; incur là phát sinh chi phí, ngược nghĩa.","extra":[{"en":"recoup an investment","vi":"thu hồi vốn đầu tư"},
{"en":"recoup losses","vi":"bù lại khoản lỗ"},
{"en":"research and development (R&D)","vi":"nghiên cứu và phát triển"}]},
{"id":"q0441","unit":1,"stem":"Which production method is LEAST suitable for a firm whose customers each demand a one-off, tailor-made product?","options":["mass production","unit production","craft production","bespoke production"],"answer":0,"explain":"Mass production (sản xuất hàng loạt) tạo số lượng rất lớn sản phẩm giống hệt nhau nên không phù hợp với đơn hàng độc nhất. Unit production (sản xuất từng cái) và sản xuất theo yêu cầu riêng chính là cách làm phù hợp với nhu cầu này.","extra":[{"en":"one-off order","vi":"đơn hàng đặt riêng một lần"},
{"en":"made-to-order","vi":"sản xuất theo đơn đặt hàng"},
{"en":"economies of scale","vi":"lợi thế kinh tế theo quy mô"}]},
{"id":"q0442","unit":1,"stem":"A bakery makes 500 identical rolls, then cleans the equipment and switches to 300 baguettes before changing again. This is an example of ______.","options":["mass production","batch production","continuous production","unit production"],"answer":1,"explain":"Batch production (sản xuất theo lô) là sản xuất một nhóm sản phẩm giới hạn rồi chuyển sang sản phẩm khác sau khi điều chỉnh thiết bị. Mass và continuous production không dừng để đổi sản phẩm như vậy; unit production chỉ làm từng cái riêng lẻ.","extra":[{"en":"production run","vi":"đợt/lượt sản xuất"},
{"en":"changeover time","vi":"thời gian chuyển đổi dây chuyền"},
{"en":"batch size","vi":"kích cỡ lô"}]},
{"id":"q0443","unit":1,"stem":"An oil refinery operates around the clock, with materials flowing through the plant without interruption, and shutting it down is extremely costly. Which production type does this describe?","options":["batch production","unit production","continuous production","project-based production"],"answer":2,"explain":"Continuous production (sản xuất liên tục) vận hành 24/7, nguyên liệu chảy liên tục qua các công đoạn và việc dừng máy rất tốn kém. Batch production làm theo từng lô có dừng giữa các lô; unit production làm từng sản phẩm riêng.","extra":[{"en":"round-the-clock operation","vi":"vận hành suốt ngày đêm"},
{"en":"process industry","vi":"ngành công nghiệp chế biến"},
{"en":"capital-intensive","vi":"đòi hỏi vốn đầu tư lớn"}]},
{"id":"q0444","unit":1,"stem":"The two components must be ______ so that either one can be fitted to any machine on the line.","options":["identify","identity","identically","identical"],"answer":3,"explain":"Cần tính từ làm vị ngữ sau 'be': identical (giống hệt nhau). Identify là động từ, identity là danh từ (danh tính), identically là trạng từ nên không đứng sau 'be' như vậy.","extra":[{"en":"identical twins","vi":"cặp sinh đôi giống hệt"},
{"en":"interchangeable parts","vi":"linh kiện có thể thay thế cho nhau"},
{"en":"be identical to","vi":"giống hệt với"}]},
{"id":"q0445","unit":1,"stem":"Rising energy costs have forced several ______ to relocate production overseas.","options":["manufacturers","manufacture","manufactured","manufacturer"],"answer":0,"explain":"Sau 'several' cần danh từ đếm được số nhiều chỉ người/công ty: manufacturers (nhà sản xuất). 'Manufacturer' là số ít, 'manufacture' là động từ/danh từ chỉ hành động chế tạo, 'manufactured' là tính từ/quá khứ phân từ.","extra":[{"en":"relocate production","vi":"dời cơ sở sản xuất"},
{"en":"contract manufacturer","vi":"nhà sản xuất theo hợp đồng"},
{"en":"manufacturing base","vi":"cơ sở sản xuất"}]},
{"id":"q0446","unit":1,"stem":"Which statement about processing materials in a factory is correct?","options":["It refers to delivering finished goods to retailers.","It involves transforming inputs such as ores, grains or chemicals into more useful forms by cutting, mixing or heating.","It means keeping materials in a warehouse until they expire.","It is the accounting treatment of materials as liabilities."],"answer":1,"explain":"Process materials (xử lí vật liệu) là biến đổi nguyên liệu đầu vào thành dạng hữu ích hơn bằng cắt, trộn, nung... Giao hàng là khâu phân phối, lưu kho là quản lý tồn kho, còn ghi nhận nợ là vấn đề kế toán, đều không phải xử lí vật liệu.","extra":[{"en":"process raw sugar","vi":"chế biến đường thô"},
{"en":"processing plant","vi":"nhà máy chế biến"},
{"en":"work in progress","vi":"sản phẩm dở dang"}]},
{"id":"q0447","unit":1,"stem":"On a traditional assembly line, ______.","options":["one worker builds the entire product alone from start to finish","each station waits until all other stations have finished","each worker or machine performs a specific task as the product moves past","only finished goods are inspected and nothing is added"],"answer":2,"explain":"Dây chuyền lắp ráp (assembly line) chia công việc thành nhiều công đoạn nhỏ, sản phẩm di chuyển qua từng trạm và mỗi trạm làm một nhiệm vụ. Một người làm cả sản phẩm là unit production; các trạm không chờ nhau hoàn tất mà làm nối tiếp/đồng thời.","extra":[{"en":"division of labour","vi":"phân công lao động"},
{"en":"moving conveyor","vi":"băng chuyền di động"},
{"en":"repetitive task","vi":"công việc lặp đi lặp lại"}]},
{"id":"q0448","unit":1,"stem":"The administration of business practices to create the highest possible level of efficiency in converting inputs into goods or services is known as ______.","options":["financial management","marketing management","human resource management","operations management"],"answer":3,"explain":"Operations management (quản trị vận hành) tập trung vào hiệu quả của quá trình biến đầu vào thành đầu ra. Financial, marketing và HR management lần lượt quản lý tài chính, thị trường và nhân sự, không phải quy trình chuyển đổi sản xuất.","extra":[{"en":"operations manager","vi":"giám đốc/quản lý vận hành"},
{"en":"inputs and outputs","vi":"đầu vào và đầu ra"},
{"en":"streamline operations","vi":"tinh giản hoạt động"}]},
{"id":"q0449","unit":1,"stem":"The planner decides which orders will run on which machines, and in what sequence, over the coming week. She is carrying out ______.","options":["production scheduling","capacity planning","inventory management","quality assurance"],"answer":0,"explain":"Production scheduling (lịch sản xuất) là xác định thứ tự và thời điểm chạy các đơn hàng trên máy. Capacity planning là xác định công suất dài hạn; inventory management là quản lý hàng tồn; quality assurance là đảm bảo chất lượng.","extra":[{"en":"production schedule","vi":"kế hoạch/lịch sản xuất"},
{"en":"meet a deadline","vi":"kịp thời hạn"},
{"en":"rush order","vi":"đơn hàng gấp"}]},
{"id":"q0450","unit":1,"stem":"Holding too much stock ties up cash, while holding too little causes stockouts. Finding the right balance is the aim of ______.","options":["performance measurement","inventory management","cost accounting","equity financing"],"answer":1,"explain":"Inventory management (quản lý hàng tồn kho) cân bằng giữa lượng hàng dự trữ vừa đủ, tránh tồn đọng vốn và tránh hết hàng. Performance measurement là đo lường hiệu suất, cost accounting là kế toán chi phí, equity financing là huy động vốn chủ sở hữu.","extra":[{"en":"stockout","vi":"tình trạng hết hàng"},
{"en":"safety stock","vi":"tồn kho an toàn"},
{"en":"reorder point","vi":"điểm đặt hàng lại"}]},
{"id":"q0451","unit":1,"stem":"Which of the following would NOT normally be classed as a raw material?","options":["Crude oil","Iron ore","A finished engine bought from a subcontractor","Raw cotton"],"answer":2,"explain":"Nguyên liệu thô (raw materials) là vật liệu chưa qua chế biến như dầu thô, quặng sắt, bông. Động cơ hoàn chỉnh mua từ nhà thầu phụ là linh kiện/bán thành phẩm (component), không phải nguyên liệu thô.","extra":[{"en":"components","vi":"linh kiện"},
{"en":"finished goods","vi":"thành phẩm"},
{"en":"raw material costs","vi":"chi phí nguyên liệu thô"}]},
{"id":"q0452","unit":1,"stem":"A strike at a major port delays imported components, so assembly plants, distributors and retailers all suffer. This shows how interconnected the ______ is.","options":["assembly line","value added","specification","supply chain"],"answer":3,"explain":"Supply chain (chuỗi cung ứng) là mạng lưới nhà cung cấp, nhà máy, nhà phân phối và bán lẻ liên kết với nhau, nên một gián đoạn ở cảng ảnh hưởng toàn chuỗi. Assembly line chỉ là dây chuyền trong một nhà máy; value added và specification không phải là mạng lưới.","extra":[{"en":"supply chain disruption","vi":"sự gián đoạn chuỗi cung ứng"},
{"en":"single-source supplier","vi":"nhà cung cấp duy nhất"},
{"en":"logistics","vi":"hậu cần, logistics"}]},
{"id":"q0453","unit":1,"stem":"Maintenance that is carried out at regular intervals in order to avoid breakdowns is known as ______ maintenance.","options":["preventive","corrective","emergency","reactive"],"answer":0,"explain":"Machine maintenance (bảo trì máy) mang tính 'preventive' là bảo trì phòng ngừa theo lịch để tránh hỏng hóc. Corrective, reactive, emergency maintenance đều là sửa chữa SAU khi máy đã hỏng.","extra":[{"en":"predictive maintenance","vi":"bảo trì dự đoán"},
{"en":"breakdown","vi":"sự cố hỏng máy"},
{"en":"service interval","vi":"chu kỳ bảo dưỡng"}]},
{"id":"q0454","unit":1,"stem":"The supplier quoted a lead time of six weeks. This means that ______.","options":["the supplier will keep six weeks of stock in reserve","six weeks will pass between placing the order and receiving the goods","the goods can be returned within six weeks","the supplier's machines will be shut down for six weeks"],"answer":1,"explain":"Lead time (thời gian chờ) là khoảng thời gian từ khi đặt hàng đến khi nhận hàng. Không liên quan đến thời hạn đổi trả, lượng tồn kho dự trữ hay thời gian ngừng máy (downtime).","extra":[{"en":"short lead time","vi":"thời gian giao hàng ngắn"},
{"en":"delivery date","vi":"ngày giao hàng"},
{"en":"place an order","vi":"đặt hàng"}]},
{"id":"q0455","unit":1,"stem":"If demand is forecast to double over the next two years, which activity will determine whether the plant needs an additional production line?","options":["machine maintenance","bookkeeping","capacity planning","inventory valuation"],"answer":2,"explain":"Capacity planning (hoạch định công suất) xác định lượng công suất cần thiết để đáp ứng nhu cầu tương lai, kể cả việc có cần thêm dây chuyền hay không. Machine maintenance giữ máy hoạt động, bookkeeping ghi sổ, inventory valuation định giá hàng tồn kho.","extra":[{"en":"spare capacity","vi":"công suất dư thừa"},
{"en":"expand capacity","vi":"mở rộng công suất"},
{"en":"demand forecast","vi":"dự báo nhu cầu"}]},
{"id":"q0456","unit":1,"stem":"A company buys flour for $1 and sells the bread made from it for $3. The $2 difference, before other costs are considered, represents the ______.","options":["lead time","principal","downtime","value added"],"answer":3,"explain":"Value added (giá trị gia tăng) là chênh lệch giữa giá bán đầu ra và chi phí đầu vào mua ngoài. Lead time là thời gian chờ, principal là tiền gốc khoản vay, downtime là thời gian máy ngừng.","extra":[{"en":"add value","vi":"tạo thêm giá trị"},
{"en":"value-added service","vi":"dịch vụ giá trị gia tăng"},
{"en":"gross margin","vi":"biên lợi nhuận gộp"}]},
{"id":"q0457","unit":1,"stem":"Early firms that introduced the moving assembly line are regarded as ______ of modern manufacturing.","options":["pioneers","pioneer","pioneering","pioneered"],"answer":0,"explain":"Cần danh từ số nhiều sau 'regarded as ... of': pioneers (những người tiên phong). 'Pioneer' số ít không hợp với 'firms'; pioneering là tính từ, pioneered là động từ quá khứ.","extra":[{"en":"pioneer in","vi":"người tiên phong trong"},
{"en":"pioneering work","vi":"công trình tiên phong"},
{"en":"trailblazer","vi":"người mở đường"}]},
{"id":"q0458","unit":1,"stem":"Every hour of unplanned ______ costs the plant a large amount in lost output and idle wages.","options":["lead time","downtime","value added","binding"],"answer":1,"explain":"Downtime (thời gian chết, thời gian máy ngừng hoạt động) gây mất sản lượng và vẫn phải trả lương. Lead time là thời gian chờ giao hàng, value added là giá trị gia tăng, binding là đóng bìa sách.","extra":[{"en":"unplanned downtime","vi":"thời gian dừng máy ngoài kế hoạch"},
{"en":"idle time","vi":"thời gian nhàn rỗi"},
{"en":"breakdown","vi":"hỏng máy"}]},
{"id":"q0459","unit":1,"stem":"The ______ of raw cotton into finished garments adds value at each stage of production.","options":["conversation","convergence","conversion","convention"],"answer":2,"explain":"Conversion (sự chuyển đổi) chỉ quá trình biến nguyên liệu thành thành phẩm. Các từ còn lại có hình thức gần giống nhưng khác nghĩa: conversation (cuộc trò chuyện), convergence (sự hội tụ), convention (quy ước, hội nghị).","extra":[{"en":"conversion process","vi":"quá trình chuyển đổi"},
{"en":"convert into","vi":"chuyển thành"},
{"en":"conversion cost","vi":"chi phí chuyển đổi"}]},
{"id":"q0460","unit":1,"stem":"The new line allows operators to assemble the engine and test the electronics ______.","options":["subsequently","consequently","eventually","simultaneously"],"answer":3,"explain":"Simultaneously (đồng thời, cùng lúc) phù hợp khi hai công việc diễn ra cùng thời điểm. Subsequently (sau đó), consequently (do đó) và eventually (cuối cùng) đều không diễn đạt ý cùng lúc.","extra":[{"en":"concurrently","vi":"đồng thời"},
{"en":"at the same time","vi":"cùng một lúc"},
{"en":"in parallel","vi":"song song"}]},
{"id":"q0461","unit":1,"stem":"In the sentence 'The assembly line brought about a revolution in manufacturing', the word 'revolution' means ______.","options":["a radical and far-reaching change","a minor adjustment","a political uprising against a government","one complete turn of a wheel"],"answer":0,"explain":"Trong ngữ cảnh sản xuất, revolution (cuộc cách mạng) là thay đổi căn bản, sâu rộng. Nghĩa 'cuộc nổi dậy chính trị' hay 'một vòng quay' tuy có thật nhưng không phù hợp ngữ cảnh; 'minor adjustment' trái nghĩa.","extra":[{"en":"industrial revolution","vi":"cách mạng công nghiệp"},
{"en":"revolutionize","vi":"cách mạng hóa"},
{"en":"sweeping change","vi":"thay đổi toàn diện"}]},
{"id":"q0462","unit":1,"stem":"In book publishing, the stage in which the printed pages are fastened together and covered is called ______.","options":["typesetting","binding","proofreading","distribution"],"answer":1,"explain":"Binding (đóng bìa sách) là công đoạn đóng các trang đã in lại và gắn bìa. Typesetting là dàn trang, proofreading là soát lỗi, distribution là phân phối sách.","extra":[{"en":"hardback binding","vi":"bìa cứng"},
{"en":"printing run","vi":"đợt in"},
{"en":"typeset","vi":"dàn trang"}]},
{"id":"q0463","unit":1,"stem":"The client rejected the batch because the dimensions did not meet the agreed ______.","options":["specializations","speculations","specifications","specimens"],"answer":2,"explain":"Specifications (đặc điểm kỹ thuật, yêu cầu chi tiết) là thông số khách hàng thỏa thuận về kích thước, vật liệu. Specializations (chuyên môn hóa), speculations (suy đoán), specimens (mẫu vật) không hợp nghĩa.","extra":[{"en":"meet the specification","vi":"đáp ứng thông số kỹ thuật"},
{"en":"to specification","vi":"theo đúng đặc tả"},
{"en":"technical specification","vi":"thông số kỹ thuật"}]},
{"id":"q0464","unit":1,"stem":"Which statement about over-the-counter (OTC) drugs is correct?","options":["They can only be dispensed by a hospital pharmacist.","They are illegal to advertise.","They require the signature of the patent holder at purchase.","They can be bought without a doctor's prescription."],"answer":3,"explain":"Over-the-counter drug (thuốc không kê đơn) mua được tại quầy mà không cần đơn bác sĩ. Thuốc kê đơn mới hạn chế việc cấp phát; OTC được quảng cáo hợp pháp và không cần chữ ký chủ bằng sáng chế.","extra":[{"en":"prescription drug","vi":"thuốc kê đơn"},
{"en":"pharmaceutical","vi":"dược phẩm"},
{"en":"generic drug","vi":"thuốc generic"}]},
{"id":"q0465","unit":1,"stem":"Because the parts are ______, a component made in one plant will fit a product assembled in another.","options":["standardized","customized","individualized","specialized"],"answer":0,"explain":"Standardized (tiêu chuẩn hóa) nghĩa là các bộ phận được làm theo cùng một chuẩn nên lắp lẫn được. Customized/individualized là làm riêng theo từng khách, trái với ý lắp lẫn; specialized là chuyên biệt cho một mục đích.","extra":[{"en":"standardization","vi":"sự tiêu chuẩn hóa"},
{"en":"interchangeable","vi":"có thể thay thế nhau"},
{"en":"industry standard","vi":"tiêu chuẩn ngành"}]},
{"id":"q0466","unit":1,"stem":"Which word is closest in meaning to 'identical' in the phrase 'identical units'?","options":["comparable","indistinguishable","related","adjacent"],"answer":1,"explain":"Identical (giống hệt nhau) gần nghĩa nhất với indistinguishable (không thể phân biệt). Comparable chỉ là có thể so sánh, related là có liên quan, adjacent là kề bên.","extra":[{"en":"exactly the same","vi":"y hệt nhau"},
{"en":"uniform","vi":"đồng nhất"},
{"en":"a carbon copy","vi":"bản sao y hệt"}]},
{"id":"q0467","unit":1,"stem":"Which statement correctly distinguishes mass production from batch production?","options":["Batch production requires a separate assembly line for every product, but mass production does not.","Mass production is always customized to each buyer, whereas batch production is standardized.","Mass production makes very large volumes of one standardized product, whereas batch production makes limited quantities in groups before switching to another product.","Batch production makes only one item at a time, whereas mass production makes batches."],"answer":2,"explain":"Mass production (sản xuất hàng loạt) là khối lượng rất lớn một sản phẩm tiêu chuẩn; batch production (sản xuất theo lô) là từng nhóm giới hạn rồi đổi sang sản phẩm khác. Các phương án còn lại đảo ngược hoặc sai bản chất hai phương pháp.","extra":[{"en":"economies of scale","vi":"lợi thế quy mô"},
{"en":"product variety","vi":"sự đa dạng sản phẩm"},
{"en":"production volume","vi":"sản lượng"}]},
{"id":"q0468","unit":1,"stem":"The factory plans to ______ part of its warehouse into an assembly area.","options":["conversion","converted","converting","convert"],"answer":3,"explain":"Sau 'plans to' cần động từ nguyên mẫu: convert (chuyển đổi). Conversion là danh từ, converted là quá khứ, converting là dạng -ing đều sai ngữ pháp ở đây.","extra":[{"en":"convert into","vi":"chuyển thành"},
{"en":"conversion of the plant","vi":"việc chuyển đổi nhà máy"},
{"en":"refit","vi":"trang bị lại"}]},
{"id":"q0469","unit":1,"stem":"Customers value suppliers that offer short ______ for urgent orders.","options":["lead times","lead spans","lead delays","lead durations"],"answer":0,"explain":"'Lead time' là cụm cố định, số nhiều lead times (thời gian chờ từ lúc đặt đến lúc giao hàng). Các tổ hợp lead span/delay/duration không phải collocation chuẩn.","extra":[{"en":"reduce lead times","vi":"rút ngắn thời gian chờ"},
{"en":"order lead time","vi":"thời gian xử lí đơn hàng"},
{"en":"turnaround time","vi":"thời gian hoàn thành"}]},
{"id":"q0470","unit":1,"stem":"The plant is running at full ______, so any new order will require extra shifts or a new line.","options":["capability","capacity","ability","measure"],"answer":1,"explain":"'Full capacity' (hết công suất) là collocation chuẩn trong sản xuất. Capability là năng lực làm được gì, ability dùng cho người, measure là biện pháp/số đo.","extra":[{"en":"run at full capacity","vi":"hoạt động hết công suất"},
{"en":"capacity utilization","vi":"tỷ lệ sử dụng công suất"},
{"en":"extra shift","vi":"ca làm thêm"}]},
{"id":"q0471","unit":1,"stem":"Which of the following is the most likely cause of PLANNED downtime?","options":["A sudden power cut","A broken conveyor belt","Scheduled machine maintenance","An unexpected shortage of raw materials"],"answer":2,"explain":"Downtime có kế hoạch xảy ra khi doanh nghiệp chủ động dừng máy, ví dụ bảo trì định kỳ (scheduled machine maintenance). Mất điện đột ngột, băng chuyền hỏng, thiếu nguyên liệu bất ngờ đều là downtime ngoài kế hoạch.","extra":[{"en":"planned shutdown","vi":"dừng máy theo kế hoạch"},
{"en":"routine servicing","vi":"bảo dưỡng định kỳ"},
{"en":"power outage","vi":"mất điện"}]},
{"id":"q0472","unit":1,"stem":"Which product is most likely to be made by unit production?","options":["A bottle of soft drink","A packet of biscuits","A mass-market smartphone","A custom-built road bridge"],"answer":3,"explain":"Unit production (sản xuất từng cái) dùng cho sản phẩm độc nhất, quy mô lớn, thiết kế riêng như cây cầu. Nước ngọt, bánh quy, điện thoại đại trà là sản phẩm tiêu chuẩn làm hàng loạt.","extra":[{"en":"one-off project","vi":"dự án đơn lẻ"},
{"en":"bespoke","vi":"làm theo yêu cầu riêng"},
{"en":"tailor-made","vi":"may đo riêng"}]},
{"id":"q0473","unit":1,"stem":"Which product is typically made in batches?","options":["A seasonal clothing range produced in specific sizes and colours","Tap water from a municipal treatment plant","Petrol from an oil refinery","A single hand-built racing yacht"],"answer":0,"explain":"Hàng thời trang theo mùa thường sản xuất theo lô, mỗi lô một kiểu/màu/cỡ rồi đổi. Nước máy và xăng là continuous production; du thuyền đặt riêng là unit production.","extra":[{"en":"small batch","vi":"lô nhỏ"},
{"en":"batch size","vi":"quy mô lô"},
{"en":"limited edition","vi":"phiên bản giới hạn"}]},
{"id":"q0474","unit":1,"stem":"Which of the following is NOT a feature of continuous production?","options":["Round-the-clock operation","Frequent changeovers between different products","A high degree of automation","Very high volumes of standardized output"],"answer":1,"explain":"Continuous production (sản xuất liên tục) chạy không ngừng, tự động hóa cao, sản lượng lớn, sản phẩm tiêu chuẩn; việc đổi sản phẩm liên tục là đặc trưng của batch production, không phải của sản xuất liên tục.","extra":[{"en":"automation","vi":"tự động hóa"},
{"en":"high throughput","vi":"thông lượng cao"},
{"en":"changeover","vi":"chuyển đổi sản phẩm"}]},
{"id":"q0475","unit":1,"stem":"The assembly line is highly ______; each station depends on the output of the one before it.","options":["independent","interdependence","interdependent","dependently"],"answer":2,"explain":"Cần tính từ: interdependent (phụ thuộc lẫn nhau). Independent (độc lập) trái nghĩa; interdependence là danh từ; dependently không phải cách dùng tự nhiên.","extra":[{"en":"be dependent on","vi":"phụ thuộc vào"},
{"en":"workstation","vi":"trạm làm việc"},
{"en":"sequential process","vi":"quy trình tuần tự"}]},
{"id":"q0476","unit":1,"stem":"Which task falls within the remit of operations management?","options":["Preparing the company's annual external audit","Negotiating a mortgage loan with a bank","Designing the corporate logo","Deciding how to convert inputs into goods efficiently, including scheduling and inventory"],"answer":3,"explain":"Operations management (quản trị vận hành) phụ trách chuyển đổi đầu vào thành sản phẩm hiệu quả, gồm lịch sản xuất và tồn kho. Kiểm toán, vay thế chấp, thiết kế logo thuộc về kế toán/tài chính/marketing.","extra":[{"en":"remit","vi":"phạm vi trách nhiệm"},
{"en":"procurement","vi":"mua sắm, thu mua"},
{"en":"logistics","vi":"hậu cần"}]},
{"id":"q0477","unit":1,"stem":"Which problem is production scheduling primarily designed to prevent?","options":["Orders being delayed because machines and workers are not allocated in the right sequence","Customers failing to pay their invoices","Competitors copying a registered trademark","Volatility in the company's share price"],"answer":0,"explain":"Production scheduling (lịch sản xuất) sắp xếp máy móc, nhân công, thứ tự công việc để tránh giao hàng trễ. Khách không trả tiền thuộc tín dụng, sao chép nhãn hiệu thuộc pháp lý, biến động giá cổ phiếu thuộc tài chính.","extra":[{"en":"delivery deadline","vi":"hạn giao hàng"},
{"en":"allocate resources","vi":"phân bổ nguồn lực"},
{"en":"on schedule","vi":"đúng tiến độ"}]},
{"id":"q0478","unit":1,"stem":"A firm holding excessive finished goods in its warehouse is most likely to face ______.","options":["shorter lead times from its suppliers","high storage costs and a risk of obsolescence","automatic reductions in tax liabilities","insufficient production capacity"],"answer":1,"explain":"Tồn kho quá mức (poor inventory management) làm tăng chi phí lưu kho và nguy cơ hàng lỗi thời. Không làm ngắn lead time nhà cung cấp, không tự giảm thuế, và cũng không phản ánh thiếu công suất.","extra":[{"en":"holding cost","vi":"chi phí lưu kho"},
{"en":"obsolete stock","vi":"hàng tồn lỗi thời"},
{"en":"overstocking","vi":"tồn kho quá mức"}]},
{"id":"q0479","unit":1,"stem":"Which of the following would NOT normally be called a raw material?","options":["Timber","Rubber latex","A ready-made gearbox purchased from another manufacturer","Copper ore"],"answer":2,"explain":"Raw materials (nguyên liệu thô) là vật liệu tự nhiên chưa chế biến như gỗ, mủ cao su, quặng đồng. Hộp số đã làm sẵn là bán thành phẩm/linh kiện nên không được gọi là raw material.","extra":[{"en":"intermediate goods","vi":"hàng trung gian"},
{"en":"commodity","vi":"hàng hóa cơ bản"},
{"en":"sourcing","vi":"tìm nguồn cung"}]},
{"id":"q0480","unit":1,"stem":"The pandemic caused severe ______ in the global supply chain.","options":["disruptive","disrupt","disrupted","disruptions"],"answer":3,"explain":"Sau tính từ 'severe' cần danh từ số nhiều: disruptions (sự gián đoạn). Disruptive là tính từ, disrupt là động từ, disrupted là quá khứ phân từ nên không hợp.","extra":[{"en":"supply chain disruption","vi":"gián đoạn chuỗi cung ứng"},
{"en":"bottleneck","vi":"điểm nghẽn"},
{"en":"shortage","vi":"tình trạng thiếu hụt"}]},
{"id":"q0481","unit":1,"stem":"The plant introduced predictive maintenance in order to ______ unplanned downtime.","options":["minimize","maximize","accelerate","multiply"],"answer":0,"explain":"Mục tiêu của bảo trì dự đoán là minimize (giảm đến mức tối thiểu) downtime ngoài kế hoạch. Maximize, accelerate, multiply đều mang nghĩa tăng, trái logic.","extra":[{"en":"minimize losses","vi":"giảm thiểu tổn thất"},
{"en":"equipment failure","vi":"sự cố thiết bị"},
{"en":"monitoring sensors","vi":"cảm biến giám sát"}]},
{"id":"q0482","unit":1,"stem":"A company halves its lead time. What is the most direct benefit?","options":["It must hire more accountants.","It can respond to customer orders faster and hold less stock.","It increases the principal on its loans.","It no longer needs any suppliers."],"answer":1,"explain":"Rút ngắn lead time (thời gian chờ) giúp đáp ứng đơn hàng nhanh hơn và giảm nhu cầu dự trữ tồn kho. Không liên quan đến thuê kế toán, tiền gốc khoản vay, hay việc bỏ nhà cung cấp.","extra":[{"en":"responsiveness","vi":"khả năng đáp ứng nhanh"},
{"en":"order fulfilment","vi":"hoàn tất đơn hàng"},
{"en":"stock levels","vi":"mức tồn kho"}]},
{"id":"q0483","unit":1,"stem":"Underestimating demand during capacity planning is most likely to lead to ______.","options":["idle machinery and unused floor space","an excess of raw materials in the warehouse","an inability to fill orders on time","a lower lead time for customers"],"answer":2,"explain":"Nếu đánh giá thấp nhu cầu, công suất sẽ thiếu, dẫn đến không giao kịp đơn hàng. Máy móc nhàn rỗi và nguyên liệu dư thừa xảy ra khi đánh giá quá cao nhu cầu; lead time không giảm.","extra":[{"en":"overcapacity","vi":"dư thừa công suất"},
{"en":"fill an order","vi":"thực hiện đơn hàng"},
{"en":"lost sales","vi":"doanh thu bị mất"}]},
{"id":"q0484","unit":1,"stem":"Which activity adds value from the customer's point of view?","options":["Storing the leather for six months","Moving materials between two warehouses","Waiting for a delayed delivery","Converting raw leather into a finished handbag"],"answer":3,"explain":"Hoạt động tạo giá trị gia tăng (value added) là biến đổi mà khách hàng sẵn sàng trả tiền, như chuyển da thô thành túi. Lưu kho, di chuyển và chờ đợi tốn chi phí nhưng không làm thay đổi sản phẩm.","extra":[{"en":"non-value-adding","vi":"không tạo giá trị"},
{"en":"waste","vi":"lãng phí"},
{"en":"customer value","vi":"giá trị khách hàng"}]},
{"id":"q0485","unit":1,"stem":"When a company pioneers a manufacturing technique, it ______.","options":["is one of the first to develop or use it","improves on a technique invented by its competitors","sells the technique under licence only","discontinues the technique after a short trial"],"answer":0,"explain":"Pioneer (làm người tiên phong) nghĩa là một trong những bên đầu tiên phát triển hoặc áp dụng điều gì đó. Cải tiến cái đã có, chỉ bán giấy phép hay ngừng sử dụng đều không phải nghĩa của 'pioneer'.","extra":[{"en":"pioneer a technique","vi":"tiên phong một kỹ thuật"},
{"en":"first-mover","vi":"người đi đầu"},
{"en":"cutting-edge","vi":"tiên tiến"}]},
{"id":"q0486","unit":1,"stem":"The introduction of robots has ______ the way cars are assembled.","options":["revolution","revolutionized","revolutionary","revolutionize"],"answer":1,"explain":"Sau 'has' cần quá khứ phân từ: revolutionized (đã làm cách mạng hóa). Revolution là danh từ, revolutionary là tính từ, revolutionize là động từ nguyên mẫu nên không đúng thì hiện tại hoàn thành.","extra":[{"en":"revolutionary","vi":"mang tính cách mạng"},
{"en":"robotics","vi":"công nghệ robot"},
{"en":"automate","vi":"tự động hóa"}]},
{"id":"q0487","unit":1,"stem":"______ production of several models on one line saves time otherwise lost in changeovers.","options":["Simultaneously","Simultaneity","Simultaneous","Simultaneousness"],"answer":2,"explain":"Cần tính từ bổ nghĩa cho danh từ 'production': Simultaneous (đồng thời). Simultaneously là trạng từ nên không đứng trước danh từ; Simultaneity và Simultaneousness là danh từ hiếm.","extra":[{"en":"simultaneous production","vi":"sản xuất đồng thời"},
{"en":"multi-model line","vi":"dây chuyền đa mẫu"},
{"en":"flexible manufacturing","vi":"sản xuất linh hoạt"}]},
{"id":"q0488","unit":1,"stem":"The printer finished printing on time but the ______ was delayed because the covers had not arrived.","options":["specification","conversion","downtime","binding"],"answer":3,"explain":"Binding (đóng bìa) là công đoạn gắn bìa vào các trang đã in nên bị trễ khi chưa có bìa. Specification là đặc tả kỹ thuật, conversion là chuyển đổi, downtime là thời gian ngừng máy, đều không phải công đoạn này.","extra":[{"en":"bookbinder","vi":"thợ đóng sách"},
{"en":"paperback","vi":"sách bìa mềm"},
{"en":"print run","vi":"số lượng in"}]},
{"id":"q0489","unit":1,"stem":"Which product is an over-the-counter drug?","options":["Paracetamol tablets sold on a supermarket shelf","Chemotherapy infusions given in hospital","Antibiotics dispensed only on prescription","An experimental drug in a clinical trial"],"answer":0,"explain":"Over-the-counter drug là thuốc không kê đơn, bán thẳng cho người tiêu dùng như thuốc giảm đau thông thường. Hóa trị, kháng sinh kê đơn và thuốc thử nghiệm đều bị kiểm soát chặt.","extra":[{"en":"clinical trial","vi":"thử nghiệm lâm sàng"},
{"en":"dosage","vi":"liều dùng"},
{"en":"pharmacy","vi":"hiệu thuốc"}]},
{"id":"q0490","unit":1,"stem":"Cough syrups are made in huge volumes to identical specifications and sold to millions of consumers. Which production type does this best describe?","options":["unit production","mass production","bespoke production","job production"],"answer":1,"explain":"Sản phẩm bán cho hàng triệu người với đặc tả giống nhau là mass production (sản xuất hàng loạt). Unit, bespoke và job production là làm riêng từng sản phẩm hoặc theo yêu cầu đặc biệt.","extra":[{"en":"high-volume","vi":"khối lượng lớn"},
{"en":"standard product","vi":"sản phẩm tiêu chuẩn"},
{"en":"consumer goods","vi":"hàng tiêu dùng"}]},
{"id":"q0491","unit":1,"stem":"Which is a major drawback of standardization?","options":["It raises unit costs because parts are not interchangeable.","It lengthens lead times because every item needs unique tooling.","It reduces variety and makes it harder to meet individual customer preferences.","It makes it impossible to use an assembly line."],"answer":2,"explain":"Tiêu chuẩn hóa (standardization) giảm chi phí nhưng làm giảm sự đa dạng, khó đáp ứng sở thích từng khách. Các phương án khác sai: tiêu chuẩn hóa giúp linh kiện lắp lẫn, giảm chi phí và rất hợp dây chuyền.","extra":[{"en":"customization","vi":"tùy biến theo khách"},
{"en":"one-size-fits-all","vi":"một cỡ cho tất cả"},
{"en":"niche market","vi":"thị trường ngách"}]},
{"id":"q0492","unit":1,"stem":"The more units a factory produces, the lower the cost per unit becomes, because fixed costs are spread over more output. This advantage is called ______.","options":["diseconomies of scale","value added","economies of scope","economies of scale"],"answer":3,"explain":"Economies of scale (lợi thế kinh tế theo quy mô) là chi phí đơn vị giảm khi sản lượng tăng. Diseconomies of scale là điều ngược lại; value added là giá trị gia tăng; economies of scope là lợi thế do đa dạng sản phẩm.","extra":[{"en":"fixed costs","vi":"chi phí cố định"},
{"en":"unit cost","vi":"chi phí đơn vị"},
{"en":"variable costs","vi":"chi phí biến đổi"}]},
{"id":"q0493","unit":1,"stem":"Which is a disadvantage of continuous production?","options":["It requires heavy capital investment and stopping the process is very costly.","It can only make very low volumes.","It leads to very high labour costs per unit.","It cannot make standardized goods."],"answer":0,"explain":"Continuous production (sản xuất liên tục) cần vốn đầu tư lớn và dừng quy trình rất tốn kém. Nó phù hợp sản lượng cao, hàng tiêu chuẩn, nhân công ít nên các phương án khác sai.","extra":[{"en":"capital-intensive","vi":"thâm dụng vốn"},
{"en":"shutdown cost","vi":"chi phí ngừng máy"},
{"en":"inflexible","vi":"thiếu linh hoạt"}]},
{"id":"q0494","unit":1,"stem":"Which sentence uses 'manufacture' correctly?","options":["The company manufactures of electric scooters in three countries.","The company manufactures electric scooters in three countries.","The company manufactured to electric scooters in three countries.","The company manufacture electric scooters in three countries."],"answer":1,"explain":"'Manufacture' là động từ ngoại động, theo sau là tân ngữ trực tiếp, và chủ ngữ số ít ở thì hiện tại cần 'manufactures'. Các câu còn lại thừa giới từ hoặc sai chia động từ.","extra":[{"en":"manufacture under licence","vi":"sản xuất theo giấy phép"},
{"en":"mass-manufactured","vi":"sản xuất hàng loạt"},
{"en":"manufacturing plant","vi":"nhà máy sản xuất"}]},
{"id":"q0495","unit":1,"stem":"Which pair is correctly matched?","options":["Lead time - the period during which a machine is out of service","Downtime - the period between placing an order and its delivery","Binding - the stage in book production in which pages are fastened inside a cover","Value added - the total cost of the raw materials purchased"],"answer":2,"explain":"Binding là đóng bìa sách. Lead time là khoảng thời gian từ khi đặt hàng đến khi nhận hàng; downtime là thời gian máy ngừng; value added là chênh lệch giữa giá bán và chi phí đầu vào, nên các cặp còn lại bị ghép sai.","extra":[{"en":"publishing","vi":"ngành xuất bản"},
{"en":"print run","vi":"số lượng in"},
{"en":"hardback","vi":"sách bìa cứng"}]},
{"id":"q0496","unit":1,"stem":"Which statement about operations management is correct?","options":["It deals only with raising finance for factories.","It applies only to manufacturing and never to services.","It is concerned solely with advertising and promotion.","It covers the planning, organizing and supervising of processes that turn inputs into goods or services."],"answer":3,"explain":"Quản trị vận hành (operations management) bao gồm hoạch định, tổ chức và giám sát quá trình chuyển đầu vào thành hàng hóa HOẶC dịch vụ. Nó không chỉ lo huy động vốn, không giới hạn ở sản xuất và không chỉ là quảng cáo.","extra":[{"en":"service operations","vi":"vận hành dịch vụ"},
{"en":"process improvement","vi":"cải tiến quy trình"},
{"en":"throughput","vi":"thông lượng"}]},
{"id":"q0497","unit":1,"stem":"A retailer insists that suppliers deliver within 48 hours of an order. Its main concern is ______.","options":["lead time","downtime","specification","revolution"],"answer":0,"explain":"Yêu cầu giao hàng trong 48 giờ kể từ khi đặt là liên quan đến lead time (thời gian chờ). Downtime là thời gian dừng máy, specification là đặc tả, revolution là cuộc cách mạng.","extra":[{"en":"on-time delivery","vi":"giao hàng đúng hạn"},
{"en":"supplier performance","vi":"hiệu quả nhà cung cấp"},
{"en":"service level","vi":"mức độ dịch vụ"}]},
{"id":"q0498","unit":1,"stem":"After a fire destroyed the only supplier of a key chemical, production stopped for three weeks. The company's mistake was ______.","options":["carrying out too much machine maintenance","depending on a single source in its supply chain","adopting continuous production","selling over-the-counter drugs"],"answer":1,"explain":"Sai lầm là phụ thuộc vào duy nhất một nguồn trong chuỗi cung ứng (supply chain), nên khi nhà cung cấp gặp sự cố thì dừng sản xuất. Bảo trì máy, sản xuất liên tục hay bán thuốc không kê đơn không gây ra tình huống này.","extra":[{"en":"single sourcing","vi":"chỉ dùng một nguồn cung"},
{"en":"diversify suppliers","vi":"đa dạng hóa nhà cung cấp"},
{"en":"contingency plan","vi":"kế hoạch dự phòng"}]},
{"id":"q0499","unit":3,"stem":"In a company's accounts, inventory includes raw materials, work in progress and ______.","options":["receivables","goodwill","finished goods","retained earnings"],"answer":2,"explain":"Hàng tồn kho (inventory) gồm nguyên liệu thô, sản phẩm dở dang và thành phẩm (finished goods). Receivables là khoản phải thu, goodwill là lợi thế thương mại, retained earnings là lợi nhuận giữ lại, đều không phải hàng tồn kho.","extra":[{"en":"stock valuation","vi":"định giá hàng tồn kho"},
{"en":"current asset","vi":"tài sản ngắn hạn"},
{"en":"stock-taking","vi":"kiểm kê"}]},
{"id":"q0500","unit":1,"stem":"Items that have started the production process but are not yet complete are called ______.","options":["raw materials","finished goods","overheads","work in progress"],"answer":3,"explain":"Work in progress (sản phẩm dở dang) là hàng đã bắt đầu sản xuất nhưng chưa hoàn thành. Raw materials chưa vào sản xuất, finished goods đã xong, overheads là chi phí chung gián tiếp.","extra":[{"en":"WIP","vi":"sản phẩm dở dang"},
{"en":"semi-finished goods","vi":"bán thành phẩm"},
{"en":"overheads","vi":"chi phí chung"}]},
{"id":"q0501","unit":1,"stem":"What was the key innovation of the moving assembly line?","options":["Bringing the work to workers, each of whom repeats one specialized task","Having each worker build a whole product alone","Producing only to order for individual customers","Replacing every worker with a machine"],"answer":0,"explain":"Dây chuyền lắp ráp di động mang sản phẩm đến từng công nhân, mỗi người lặp lại một nhiệm vụ chuyên biệt, giúp tăng năng suất. Mỗi người làm toàn bộ sản phẩm hay làm theo đơn riêng là unit production; không thay thế toàn bộ nhân công.","extra":[{"en":"specialization","vi":"chuyên môn hóa"},
{"en":"conveyor belt","vi":"băng chuyền"},
{"en":"throughput","vi":"thông lượng"}]},
{"id":"q0502","unit":1,"stem":"Overall equipment effectiveness falls whenever ______ increases.","options":["output per hour","downtime","value added","line speed"],"answer":1,"explain":"Hiệu suất thiết bị tổng thể giảm khi downtime (thời gian máy ngừng) tăng vì máy hoạt động ít giờ hơn. Output per hour, value added và tốc độ dây chuyền tăng thì hiệu suất tăng.","extra":[{"en":"equipment effectiveness","vi":"hiệu suất thiết bị"},
{"en":"uptime","vi":"thời gian máy chạy"},
{"en":"breakdown rate","vi":"tỷ lệ hỏng hóc"}]},
{"id":"q0503","unit":1,"stem":"In operations, the 'conversion process' refers to ______.","options":["exchanging one currency for another when paying suppliers","turning website visitors into buyers","transforming inputs such as materials and labour into outputs","changing a company's legal form"],"answer":2,"explain":"Trong vận hành, conversion process (quá trình chuyển đổi) là biến đầu vào như nguyên liệu, lao động thành đầu ra. Đổi tiền, biến khách truy cập thành người mua (marketing) hay đổi hình thức pháp lý là các nghĩa khác của 'conversion'.","extra":[{"en":"inputs","vi":"đầu vào"},
{"en":"outputs","vi":"đầu ra"},
{"en":"transformation process","vi":"quá trình chuyển hóa"}]},
{"id":"q0504","unit":1,"stem":"Which of these is an example of tasks done simultaneously?","options":["One team finishes the chassis before another starts the interior.","The line is stopped for a day for a refit.","Parts are inspected after the product has shipped.","Two teams assemble the chassis and the interior at the same time."],"answer":3,"explain":"Simultaneously nghĩa là cùng lúc, nên hai nhóm lắp khung gầm và nội thất song song là ví dụ. Các phương án còn lại diễn ra nối tiếp hoặc ở thời điểm khác nhau.","extra":[{"en":"in parallel","vi":"song song"},
{"en":"concurrent engineering","vi":"kỹ thuật đồng thời"},
{"en":"sequentially","vi":"tuần tự"}]},
{"id":"q0505","unit":1,"stem":"The arrival of robotics has led to a quiet ______ on factory floors.","options":["revolution","revolt","rotation","resolution"],"answer":0,"explain":"Revolution (cuộc cách mạng) là sự thay đổi lớn, hợp với 'quiet revolution' nói về robot. Revolt là cuộc nổi loạn, rotation là sự xoay vòng, resolution là quyết định/độ phân giải.","extra":[{"en":"quiet revolution","vi":"cuộc cách mạng thầm lặng"},
{"en":"digital revolution","vi":"cách mạng số"},
{"en":"factory floor","vi":"sàn nhà máy"}]},
{"id":"q0506","unit":1,"stem":"The company was a ______ in the use of robots, introducing them a decade before its rivals.","options":["pioneering","pioneer","pioneered","pioneers"],"answer":1,"explain":"Sau mạo từ 'a' cần danh từ số ít: pioneer (người tiên phong). Pioneering là tính từ, pioneered là quá khứ, pioneers là số nhiều nên không hợp với 'a'.","extra":[{"en":"pioneer in","vi":"tiên phong trong"},
{"en":"early adopter","vi":"người áp dụng sớm"},
{"en":"ahead of its time","vi":"đi trước thời đại"}]},
{"id":"q0507","unit":1,"stem":"Customers can buy these tablets ______ without a prescription.","options":["under the counter","behind closed doors","over the counter","off the record"],"answer":2,"explain":"'Over the counter' nghĩa là mua trực tiếp tại quầy, không cần đơn thuốc. 'Under the counter' hàm ý giao dịch lén lút, bất hợp pháp; hai cụm còn lại không thuộc ngữ cảnh mua thuốc.","extra":[{"en":"OTC","vi":"không kê đơn"},
{"en":"prescription-only","vi":"chỉ bán theo đơn"},
{"en":"dispense","vi":"cấp phát (thuốc)"}]},
{"id":"q0508","unit":1,"stem":"A key risk for a mass producer is ______.","options":["being unable to benefit from economies of scale","unlimited flexibility to change designs","higher unit costs whenever volumes rise","heavy investment in specialized equipment that is difficult to adapt to new products"],"answer":3,"explain":"Mass producer đầu tư lớn vào máy móc chuyên dụng, rất khó điều chỉnh khi nhu cầu hoặc thiết kế thay đổi. Họ hưởng lợi thế quy mô, kém linh hoạt và chi phí đơn vị giảm khi sản lượng tăng, nên các phương án khác sai.","extra":[{"en":"sunk cost","vi":"chi phí chìm"},
{"en":"inflexibility","vi":"thiếu linh hoạt"},
{"en":"tooling","vi":"dụng cụ/khuôn mẫu"}]},
{"id":"q0509","unit":2,"stem":"Just-in-time manufacturing aims to ______.","options":["reduce inventory by receiving materials only when they are needed","stockpile materials well in advance of demand","maximize the lead time of each order","run machines continuously regardless of orders"],"answer":0,"explain":"JIT (sản xuất tức thời) nhằm giảm tồn kho bằng cách chỉ nhận nguyên liệu khi cần. Tích trữ trước là điều ngược lại; JIT muốn rút ngắn lead time và chỉ sản xuất theo nhu cầu.","extra":[{"en":"just-in-time delivery","vi":"giao hàng đúng lúc"},
{"en":"kanban","vi":"hệ thống kanban"},
{"en":"stockholding cost","vi":"chi phí giữ hàng"}]},
{"id":"q0510","unit":2,"stem":"On a four-stage line, three stages can each process 60 units an hour but one stage, the bottleneck, can process only 40 units an hour. What is the maximum hourly output of the whole line?","options":["60 units","40 units","100 units","50 units"],"answer":1,"explain":"Dây chuyền chỉ nhanh bằng khâu chậm nhất: khâu thắt cổ chai (bottleneck) 40 đơn vị/giờ quyết định sản lượng tối đa. 60 là tốc độ khâu nhanh, 100 và 50 không tính được từ dữ kiện.","extra":[{"en":"throughput","vi":"thông lượng"},
{"en":"constraint","vi":"điểm ràng buộc"},
{"en":"balance the line","vi":"cân bằng dây chuyền"}]},
{"id":"q0511","unit":1,"stem":"A plant can make 1,000 units a day but is currently producing 750. Its capacity utilization is ______.","options":["25%","133%","75%","750%"],"answer":2,"explain":"Capacity utilization (mức sử dụng công suất) = sản lượng thực / công suất tối đa = 750/1000 = 75%. 25% là phần công suất dư; 133% và 750% là phép tính sai.","extra":[{"en":"spare capacity","vi":"công suất dự phòng"},
{"en":"utilization rate","vi":"tỷ lệ sử dụng"},
{"en":"actual output","vi":"sản lượng thực tế"}]},
{"id":"q0512","unit":1,"stem":"An order is placed on Monday 1st. The supplier needs nine days to produce the goods and five days to ship them. The lead time from order to delivery is ______.","options":["9 days","5 days","4 days","14 days"],"answer":3,"explain":"Lead time (thời gian chờ) tính từ lúc đặt hàng đến khi nhận hàng, gồm cả sản xuất và vận chuyển: 9 + 5 = 14 ngày. 9 hoặc 5 chỉ là một phần, 4 là hiệu hai số.","extra":[{"en":"production time","vi":"thời gian sản xuất"},
{"en":"transit time","vi":"thời gian vận chuyển"},
{"en":"delivery schedule","vi":"lịch giao hàng"}]},
{"id":"q0513","unit":1,"stem":"Which word is closest in meaning to 'downtime' in the sentence 'Downtime on the packing line cost us two shifts'?","options":["a period of inactivity","overtime","a peak period","a payback period"],"answer":0,"explain":"Downtime (thời gian chết) là khoảng thời gian thiết bị không hoạt động, tức 'a period of inactivity'. Overtime là giờ làm thêm, peak period là giai đoạn cao điểm, payback period là thời gian hoàn vốn.","extra":[{"en":"idle time","vi":"thời gian nhàn rỗi"},
{"en":"outage","vi":"sự ngừng hoạt động"},
{"en":"uptime","vi":"thời gian hoạt động"}]},
{"id":"q0514","unit":1,"stem":"Which statement about machine maintenance is correct?","options":["Breakdown maintenance is planned in advance, whereas preventive maintenance follows a failure.","Preventive maintenance is planned in advance, whereas breakdown maintenance is carried out after a machine has failed.","Preventive maintenance is only needed for office equipment.","Both types of maintenance increase downtime equally."],"answer":1,"explain":"Bảo trì phòng ngừa (preventive) được lên kế hoạch trước, còn bảo trì sau hỏng (breakdown) chỉ làm khi máy đã hỏng. Phương án đầu tiên bị đảo ngược; bảo trì phòng ngừa dành cho máy sản xuất và giúp GIẢM downtime.","extra":[{"en":"breakdown maintenance","vi":"bảo trì sau hỏng"},
{"en":"service schedule","vi":"lịch bảo dưỡng"},
{"en":"wear and tear","vi":"hao mòn"}]},
{"id":"q0515","unit":1,"stem":"Which strategy lets a firm meet seasonal peak demand without adding permanent capacity?","options":["Cutting prices during the peak months","Reducing lead time to zero","Building up inventory in the off-peak months","Outsourcing the accounting function"],"answer":2,"explain":"Dự trữ hàng (inventory) trong mùa thấp điểm giúp đáp ứng nhu cầu cao điểm mà không phải tăng công suất cố định. Giảm giá làm tăng cầu, lead time bằng 0 là không thực tế, thuê ngoài kế toán không liên quan.","extra":[{"en":"seasonal demand","vi":"nhu cầu theo mùa"},
{"en":"peak season","vi":"mùa cao điểm"},
{"en":"stockpile","vi":"tích trữ"}]},
{"id":"q0516","unit":1,"stem":"The company has ______ its procedures across all of its plants, so every site now follows the same method.","options":["standard","standardization","standardizing","standardized"],"answer":3,"explain":"Sau 'has' cần quá khứ phân từ: standardized (đã tiêu chuẩn hóa). Standard là tính từ/danh từ, standardization là danh từ, standardizing là dạng -ing nên không đúng.","extra":[{"en":"standard operating procedure","vi":"quy trình vận hành chuẩn"},
{"en":"uniformity","vi":"tính đồng nhất"},
{"en":"roll out","vi":"triển khai"}]},
{"id":"q0517","unit":1,"stem":"The final ______ of the vehicles takes place at a plant in northern Vietnam.","options":["assembly","assemble","assembled","assembling"],"answer":0,"explain":"Sau mạo từ 'the' + tính từ 'final' cần danh từ: assembly (sự lắp ráp). Assemble là động từ, assembled là quá khứ/tính từ, assembling là dạng -ing nên sai trong cấu trúc 'the final ... of'.","extra":[{"en":"final assembly","vi":"công đoạn lắp ráp cuối"},
{"en":"assembly plant","vi":"nhà máy lắp ráp"},
{"en":"knock-down kit","vi":"bộ linh kiện lắp ráp"}]},
{"id":"q0518","unit":1,"stem":"Output per worker per hour is a measure of ______.","options":["production","productivity","producer","productive"],"answer":1,"explain":"Productivity (năng suất) đo lượng đầu ra trên mỗi đơn vị đầu vào như một giờ lao động. Production là hoạt động sản xuất/sản lượng, producer là nhà sản xuất, productive là tính từ.","extra":[{"en":"labour productivity","vi":"năng suất lao động"},
{"en":"boost productivity","vi":"tăng năng suất"},
{"en":"output per hour","vi":"sản lượng mỗi giờ"}]},
{"id":"q0519","unit":1,"stem":"The COO is responsible for ______, which include managing plants, logistics and procurement.","options":["operators","operatives","operations","operatic"],"answer":2,"explain":"Operations (hoạt động vận hành) gồm quản lý nhà máy, hậu cần, mua sắm, thuộc trách nhiệm của COO (giám đốc vận hành). Operators là người vận hành máy, operatives là công nhân, operatic không liên quan.","extra":[{"en":"chief operating officer","vi":"giám đốc vận hành"},
{"en":"day-to-day operations","vi":"hoạt động hằng ngày"},
{"en":"procurement","vi":"thu mua"}]},
{"id":"q0520","unit":1,"stem":"Soaring prices of ______ squeezed the margins of many manufacturers last year.","options":["crude materials","rough materials","bare materials","raw materials"],"answer":3,"explain":"'Raw materials' là collocation chuẩn chỉ nguyên liệu thô. Crude, rough, bare đều có nghĩa gần 'thô/trần' nhưng không tạo thành cụm cố định này.","extra":[{"en":"squeeze margins","vi":"làm co hẹp biên lợi nhuận"},
{"en":"commodity prices","vi":"giá hàng hóa"},
{"en":"input costs","vi":"chi phí đầu vào"}]},
{"id":"q0521","unit":1,"stem":"The quality team rejected the entire ______ after a sample failed inspection.","options":["batch","bundle","pile","bunch"],"answer":0,"explain":"'Batch' (lô hàng) là cụm chuẩn trong sản xuất: một nhóm sản phẩm làm cùng lúc. Bundle, pile, bunch là bó/đống/chùm, không dùng trong ngữ cảnh kiểm tra chất lượng.","extra":[{"en":"batch number","vi":"số lô"},
{"en":"defective batch","vi":"lô hàng lỗi"},
{"en":"sample inspection","vi":"kiểm tra mẫu"}]},
{"id":"q0522","unit":1,"stem":"The firm outsources the ______ of its products to a specialist company in Vietnam.","options":["manufacturer","manufacture","manufactured","manufactures"],"answer":1,"explain":"Sau 'the' và trước 'of' cần danh từ chỉ hành động: manufacture (việc chế tạo). Manufacturer là nhà sản xuất (người/công ty), manufactured là quá khứ, manufactures là động từ chia ngôi thứ ba.","extra":[{"en":"outsource","vi":"thuê ngoài"},
{"en":"contract manufacturing","vi":"gia công theo hợp đồng"},
{"en":"offshore","vi":"ở nước ngoài"}]},
{"id":"q0523","unit":1,"stem":"Which of the following best describes a supply chain?","options":["The sequence of workstations on a single factory floor","A series of loans taken from several creditors","The network of organizations and activities that move a product from raw materials to the customer","The hierarchy of managers in a company"],"answer":2,"explain":"Supply chain (chuỗi cung ứng) là toàn bộ mạng lưới tổ chức và hoạt động đưa sản phẩm từ nguyên liệu thô đến khách hàng. Dãy trạm làm việc là assembly line, chuỗi khoản vay thuộc tài chính, cấp bậc quản lý là cơ cấu tổ chức.","extra":[{"en":"supplier","vi":"nhà cung cấp"},
{"en":"distributor","vi":"nhà phân phối"},
{"en":"end consumer","vi":"người tiêu dùng cuối cùng"}]},
{"id":"q0524","unit":1,"stem":"Which statement is correct?","options":["Lead time is the period when equipment is not operating, whereas downtime is the delay between ordering and receiving.","Lead time and downtime both mean the total cost of raw materials.","Downtime is the time a customer waits for a refund, and lead time is the time a machine takes to warm up.","Lead time is the delay between placing an order and receiving it, whereas downtime is a period when equipment is not operating."],"answer":3,"explain":"Lead time là thời gian chờ từ đặt hàng đến nhận hàng; downtime là thời gian thiết bị không hoạt động. Phương án đầu tiên ngược lại; hai phương án còn lại gán nghĩa không có thật.","extra":[{"en":"turnaround","vi":"thời gian hoàn tất"},
{"en":"idle equipment","vi":"thiết bị nhàn rỗi"},
{"en":"delay","vi":"sự chậm trễ"}]},
{"id":"q0525","unit":1,"stem":"Which sentence defines 'value added' correctly?","options":["It is the difference between the selling price of output and the cost of the inputs bought in.","It is the total cost of purchasing all raw materials.","It is the sales tax charged to the customer at the till.","It is the profit remaining after tax and dividends."],"answer":0,"explain":"Value added (giá trị gia tăng) là chênh lệch giữa giá bán sản phẩm đầu ra và chi phí đầu vào mua ngoài. Tổng chi phí nguyên liệu, thuế bán hàng hay lợi nhuận sau thuế và cổ tức là các khái niệm khác.","extra":[{"en":"VAT","vi":"thuế giá trị gia tăng"},
{"en":"gross profit","vi":"lợi nhuận gộp"},
{"en":"input cost","vi":"chi phí đầu vào"}]},
{"id":"q0526","unit":1,"stem":"The firm leased a second plant ahead of expected growth in orders. This decision belongs to ______.","options":["production scheduling","capacity planning","machine maintenance","inventory replenishment"],"answer":1,"explain":"Thuê thêm nhà máy để đáp ứng nhu cầu tăng là quyết định về công suất dài hạn, tức capacity planning. Production scheduling là xếp lịch hằng ngày; machine maintenance là bảo trì; replenishment là bổ sung hàng.","extra":[{"en":"lease","vi":"thuê (dài hạn)"},
{"en":"growth in orders","vi":"đơn hàng tăng"},
{"en":"scale up","vi":"mở rộng quy mô"}]},
{"id":"q0527","unit":1,"stem":"Which is an advantage of unit production?","options":["The lowest cost per unit of any method","Very fast output of thousands of items an hour","High flexibility to meet the individual requirements of a customer","Little skill is required of the workforce"],"answer":2,"explain":"Unit production (sản xuất từng cái) rất linh hoạt, đáp ứng yêu cầu riêng của từng khách. Chi phí đơn vị thường CAO, sản lượng thấp, và cần công nhân tay nghề cao, nên các phương án còn lại sai.","extra":[{"en":"skilled labour","vi":"lao động tay nghề cao"},
{"en":"customized product","vi":"sản phẩm tùy chỉnh"},
{"en":"premium price","vi":"giá cao cấp"}]},
{"id":"q0528","unit":1,"stem":"A key disadvantage of batch production is ______.","options":["the impossibility of any product variety","continuous machine operation without stoppages","the huge capital investment required for a refinery","time lost cleaning and resetting equipment between batches"],"answer":3,"explain":"Batch production tốn thời gian dọn dẹp, chỉnh máy giữa các lô (changeover), làm giảm hiệu suất. Nó cho phép đa dạng sản phẩm; máy chạy không ngừng và đầu tư lớn như nhà máy lọc dầu là đặc điểm của continuous production.","extra":[{"en":"setup time","vi":"thời gian chuẩn bị máy"},
{"en":"changeover cost","vi":"chi phí chuyển đổi"},
{"en":"machine idle","vi":"máy nhàn rỗi"}]},
{"id":"q0529","unit":1,"stem":"Which condition most favours mass production?","options":["Stable, high demand for a standardized product","Highly unpredictable demand in very small quantities","Frequent changes to the product design","Each customer needing a personalized item"],"answer":0,"explain":"Mass production hiệu quả khi nhu cầu lớn, ổn định, sản phẩm tiêu chuẩn để tận dụng lợi thế quy mô. Nhu cầu nhỏ lẻ khó đoán, thiết kế thay đổi thường xuyên và nhu cầu cá nhân hóa phù hợp unit/batch production hơn.","extra":[{"en":"stable demand","vi":"nhu cầu ổn định"},
{"en":"high volume","vi":"khối lượng lớn"},
{"en":"design change","vi":"thay đổi thiết kế"}]},
{"id":"q0530","unit":2,"stem":"Which word is closest in meaning to 'pioneer' in 'She was a pioneer of lean manufacturing'?","options":["follower","trailblazer","imitator","supplier"],"answer":1,"explain":"Pioneer (người tiên phong) gần nghĩa nhất với trailblazer (người mở đường). Follower và imitator là người đi sau/bắt chước, supplier là nhà cung cấp.","extra":[{"en":"groundbreaking","vi":"đột phá"},
{"en":"innovator","vi":"nhà đổi mới"},
{"en":"trendsetter","vi":"người dẫn đầu xu hướng"}]},
{"id":"q0531","unit":1,"stem":"Which word is closest in meaning to 'simultaneously'?","options":["sequentially","subsequently","concurrently","alternately"],"answer":2,"explain":"Simultaneously (đồng thời) tương đương concurrently. Sequentially (lần lượt), subsequently (sau đó) và alternately (luân phiên) đều nghĩa là không cùng lúc.","extra":[{"en":"concurrent","vi":"đồng thời xảy ra"},
{"en":"in tandem","vi":"cùng nhau"},
{"en":"at once","vi":"ngay một lúc"}]},
{"id":"q0532","unit":1,"stem":"The introduction of the assembly line caused a revolution ______ manufacturing.","options":["on","for","at","in"],"answer":3,"explain":"Collocation đúng là 'a revolution in + lĩnh vực' (cuộc cách mạng trong sản xuất). Các giới từ on, for, at không dùng với revolution trong nghĩa này.","extra":[{"en":"revolution in","vi":"cuộc cách mạng trong"},
{"en":"breakthrough in","vi":"bước đột phá trong"},
{"en":"advance in","vi":"tiến bộ trong"}]},
{"id":"q0533","unit":1,"stem":"Which sequence correctly lists the stages of book production?","options":["Printing, binding, distribution","Binding, printing, distribution","Distribution, binding, printing","Distribution, printing, binding"],"answer":0,"explain":"Trong xuất bản, sách phải được in (printing) trước, sau đó đóng bìa (binding) rồi mới phân phối (distribution). Các thứ tự khác phi logic vì không thể đóng bìa trước khi in hoặc phân phối trước khi hoàn tất sách.","extra":[{"en":"publisher","vi":"nhà xuất bản"},
{"en":"proofread","vi":"soát lỗi"},
{"en":"print run","vi":"đợt in"}]},
{"id":"q0534","unit":1,"stem":"Why are over-the-counter drugs usually made to strict specifications even though no prescription is needed?","options":["Because they are recorded as liabilities in the accounts.","Because consumers take them without professional supervision, so safety and consistency are essential.","Because they are made by unit production.","Because they contain no active ingredients."],"answer":1,"explain":"Thuốc không kê đơn dùng mà không có bác sĩ giám sát nên phải đạt đặc tả nghiêm ngặt để đảm bảo an toàn, đồng đều. Chúng không bị ghi là nợ, không làm theo unit production mà hàng loạt, và có thành phần hoạt tính.","extra":[{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"regulatory approval","vi":"phê duyệt của cơ quan quản lý"},
{"en":"active ingredient","vi":"hoạt chất"}]},
{"id":"q0535","unit":2,"stem":"A manufacturer wants to cut both lead time and downtime. Which pair of actions is most consistent with both aims?","options":["Larger stocks of finished goods and longer production runs","A switch to unit production and an end to maintenance","Preventive machine maintenance and closer coordination with suppliers","Higher prices and reduced capacity"],"answer":2,"explain":"Bảo trì phòng ngừa giảm downtime, phối hợp chặt với nhà cung cấp giảm lead time. Tăng tồn kho và chạy lô dài không giảm hai chỉ số này; unit production bỏ bảo trì làm tăng hỏng máy; tăng giá và giảm công suất không liên quan.","extra":[{"en":"supplier coordination","vi":"phối hợp với nhà cung cấp"},
{"en":"continuous improvement","vi":"cải tiến liên tục"},
{"en":"responsiveness","vi":"sự đáp ứng nhanh"}]},
{"id":"q0536","unit":2,"stem":"The quality team wants to ______ the exact stage at which defective units first appear, so that the fault can be traced to its source.","options":["overlook","multiply","pinpoint","replenish"],"answer":2,"explain":"Pinpoint = xác định chính xác (vị trí/nguyên nhân). Overlook là bỏ sót, multiply là tăng nhanh về số lượng, replenish là bổ sung hàng - đều không hợp ngữ cảnh truy tìm lỗi.","extra":[{"en":"pinpoint the cause","vi":"xác định chính xác nguyên nhân"},
{"en":"trace a fault to its source","vi":"truy lỗi về nguồn gốc"}]},
{"id":"q0537","unit":2,"stem":"Which statement about a production bottleneck is correct?","options":["It is the slowest stage of a process and limits the output of the whole process.","It is a stage where output is always higher than customer demand.","It is a budget set aside for emergency repairs.","It disappears as soon as more raw materials are ordered."],"answer":0,"explain":"Bottleneck (tắc nghẽn sản xuất) là công đoạn chậm nhất, quyết định công suất tối đa của cả dây chuyền. Đặt thêm nguyên liệu không giải quyết được nó, và nó không liên quan đến ngân sách sửa chữa.","extra":[{"en":"relieve a bottleneck","vi":"giải tỏa điểm nghẽn"},
{"en":"throughput","vi":"sản lượng thông qua"}]},
{"id":"q0538","unit":2,"stem":"The auditor found a serious ______ in the plant's safety documentation: several mandatory records were simply missing.","options":["tier","yield","metric","deficiency"],"answer":3,"explain":"Deficiency = sự thiếu hụt/thiếu sót, hợp với 'records were missing'. Tier là tầng lớp, yield là sản lượng đạt chuẩn, metric là thước đo - không chỉ một thiếu sót.","extra":[{"en":"a serious deficiency","vi":"một thiếu sót nghiêm trọng"},
{"en":"safety audit","vi":"kiểm tra an toàn"}]},
{"id":"q0539","unit":2,"stem":"Under a JIT system, the warehouse is ______ automatically whenever stock falls to a pre-agreed minimum.","options":["overseen","replenished","complied","aligned"],"answer":1,"explain":"Replenish = bổ sung lại hàng đã dùng. Oversee là giám sát, comply là tuân thủ (đi với with), align là căn chỉnh - không hợp nghĩa với 'stock falls to a minimum'.","extra":[{"en":"replenish stock","vi":"bổ sung hàng tồn"},
{"en":"reorder point","vi":"điểm đặt hàng lại"}]},
{"id":"q0540","unit":2,"stem":"The fault in the batch is ______, so the company can correct it without scrapping the products.","options":["remediation","remediable","remediate","remediably"],"answer":1,"explain":"Sau 'is' cần tính từ: remediable = có thể sửa chữa được. Remediation là danh từ, remediate là động từ, remediably là trạng từ.","extra":[{"en":"scrap the batch","vi":"loại bỏ cả lô"},
{"en":"rework","vi":"làm lại sản phẩm lỗi"}]},
{"id":"q0541","unit":2,"stem":"A method of production that aims to eliminate waste while still delivering value to the customer is called ______.","options":["batch production","mass production","quality assurance","lean manufacturing"],"answer":3,"explain":"Lean manufacturing = sản xuất tinh gọn, loại bỏ lãng phí. Batch/mass production nói về quy mô, cách tổ chức sản xuất; quality assurance là đảm bảo chất lượng, không phải phương pháp loại bỏ lãng phí.","extra":[{"en":"eliminate waste","vi":"loại bỏ lãng phí"},
{"en":"continuous improvement","vi":"cải tiến liên tục"}]},
{"id":"q0542","unit":2,"stem":"Managers must ______ with environmental regulations or the plant may be fined.","options":["comply","obey","follow","respect"],"answer":0,"explain":"Comply đi với giới từ 'with' (comply with sth = tuân thủ). Obey, follow, respect đi thẳng với tân ngữ, không dùng 'with' trong cấu trúc này.","extra":[{"en":"comply with regulations","vi":"tuân thủ quy định"},
{"en":"regulatory compliance","vi":"tuân thủ pháp lý"}]},
{"id":"q0543","unit":2,"stem":"Which word is closest in meaning to 'enhance'?","options":["reduce","monitor","improve","postpone"],"answer":2,"explain":"Enhance = làm tăng/nâng cao, gần nghĩa nhất với improve. Reduce là giảm, monitor là theo dõi, postpone là hoãn.","extra":[{"en":"enhance quality","vi":"nâng cao chất lượng"},
{"en":"boost productivity","vi":"thúc đẩy năng suất"}]},
{"id":"q0544","unit":2,"stem":"The firm tracks defect rate, on-time delivery and machine utilization. These are examples of its ______.","options":["performance metrics","strategic visions","square roots","linear workflows"],"answer":0,"explain":"Performance metrics = các chỉ số đo lường hiệu quả công việc, như tỷ lệ lỗi, giao đúng hạn. Strategic vision là tầm nhìn dài hạn, linear workflow là quy trình tuần tự.","extra":[{"en":"key performance indicators (KPIs)","vi":"chỉ số hiệu suất chính"},
{"en":"track performance","vi":"theo dõi hiệu suất"}]},
{"id":"q0545","unit":2,"stem":"Which sentence uses 'oversee' correctly?","options":["The warehouse was oversee by rain last night.","He overseen the report yesterday.","She oversees a team of twelve inspectors across three shifts.","They oversee to the schedule changes."],"answer":2,"explain":"Oversee là ngoại động từ (giám sát + tân ngữ): oversees a team. Các câu khác sai dạng từ (overseen thiếu trợ động từ) hoặc dùng sai giới từ.","extra":[{"en":"oversee operations","vi":"giám sát vận hành"},
{"en":"supervisor","vi":"người giám sát"}]},
{"id":"q0546","unit":2,"stem":"Customer complaints began to ______ after the company switched to a cheaper, less reliable supplier.","options":["align","multiply","utilize","enhance"],"answer":1,"explain":"Multiply = tăng nhanh về số lượng, hợp với số lượng khiếu nại. Enhance là làm tốt hơn (không hợp vì khiếu nại là điều xấu), align và utilize không đi với chủ ngữ này.","extra":[{"en":"complaints multiply","vi":"khiếu nại tăng nhanh"},
{"en":"switch supplier","vi":"đổi nhà cung cấp"}]},
{"id":"q0547","unit":2,"stem":"The supplier network is organised in three ______; the first-level suppliers deliver directly to the assembly plant.","options":["yields","metrics","bottlenecks","tiers"],"answer":3,"explain":"Tier = tầng, lớp; 'first-tier supplier' là nhà cung cấp cấp 1. Yield, metric, bottleneck không dùng để chia cấp nhà cung cấp.","extra":[{"en":"first-tier supplier","vi":"nhà cung cấp cấp 1"},
{"en":"multi-tiered structure","vi":"cấu trúc nhiều tầng"}]},
{"id":"q0548","unit":2,"stem":"The bonus scheme is designed to ______ individual targets with the company's strategic vision.","options":["pinpoint","oversee","replenish","align"],"answer":3,"explain":"Align sth with sth = làm cho thống nhất/khớp với. Pinpoint là xác định, oversee là giám sát, replenish là bổ sung - không đi với 'with' theo nghĩa khớp mục tiêu.","extra":[{"en":"align with goals","vi":"khớp với mục tiêu"},
{"en":"strategic vision","vi":"tầm nhìn chiến lược"}]},
{"id":"q0549","unit":2,"stem":"A ______ client has shown interest in our products but has not yet signed a contract.","options":["remediable","prospective","linear","lean"],"answer":1,"explain":"Prospective = có triển vọng, tiềm năng (sắp trở thành). Remediable là có thể sửa chữa, linear là tuyến tính, lean là tinh gọn.","extra":[{"en":"prospective customer","vi":"khách hàng tiềm năng"},
{"en":"sign a contract","vi":"ký hợp đồng"}]},
{"id":"q0550","unit":2,"stem":"The amount of acceptable output obtained from a given quantity of inputs is called the ______.","options":["lead time","downtime","production yield","resources allocation"],"answer":2,"explain":"Production yield = năng suất/tỷ lệ sản phẩm đạt chuẩn trên đầu vào. Lead time là thời gian chờ, downtime là thời gian máy dừng, resources allocation là phân bổ nguồn lực.","extra":[{"en":"yield rate","vi":"tỷ lệ thành phẩm"},
{"en":"defect rate","vi":"tỷ lệ lỗi"}]},
{"id":"q0551","unit":2,"stem":"Which statement about quality assurance is correct?","options":["It focuses on preventing defects by improving the processes used to make a product.","It consists only of inspecting finished goods at the loading dock.","It is the process of buying materials at the lowest possible price.","It refers to measuring the company's performance on the stock market."],"answer":0,"explain":"Quality assurance (đảm bảo chất lượng) hướng đến phòng ngừa lỗi thông qua cải tiến quy trình, không chỉ kiểm tra sản phẩm cuối. Hai phương án còn lại thuộc mua hàng và tài chính.","extra":[{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"defect prevention","vi":"phòng ngừa lỗi"}]},
{"id":"q0552","unit":2,"stem":"Expensive machines stand idle at night, so managers want to ______ existing equipment more fully before buying new machines.","options":["pinpoint","comply","utilize","multiply"],"answer":2,"explain":"Utilize = sử dụng (tận dụng) có hiệu quả. Comply cần 'with', pinpoint là xác định, multiply là tăng nhanh số lượng.","extra":[{"en":"capacity utilization","vi":"mức tận dụng công suất"},
{"en":"idle equipment","vi":"thiết bị nhàn rỗi"}]},
{"id":"q0553","unit":2,"stem":"The company ______ a new inventory control system last quarter, and waste has fallen since then.","options":["pinpointed","multiplied","complied","implemented"],"answer":3,"explain":"Implement = thực hiện, triển khai (hệ thống, kế hoạch). Comply phải có 'with'; pinpoint và multiply không hợp nghĩa 'triển khai hệ thống'.","extra":[{"en":"implement a system","vi":"triển khai hệ thống"},
{"en":"roll out","vi":"triển khai trên diện rộng"}]},
{"id":"q0554","unit":2,"stem":"A fair ______ of resources between departments requires clear priorities.","options":["allocation","alliance","alternation","allowance"],"answer":0,"explain":"Allocation of resources (resources allocation) = phân bổ nguồn lực. Alliance là liên minh, alternation là sự luân phiên, allowance là khoản trợ cấp.","extra":[{"en":"allocate budget","vi":"phân bổ ngân sách"},
{"en":"set priorities","vi":"đặt thứ tự ưu tiên"}]},
{"id":"q0555","unit":2,"stem":"Lean methods make the production process more ______ without lowering quality.","options":["efficiency","efficient","efficiently","efficiencies"],"answer":1,"explain":"Sau 'more' + bổ nghĩa cho 'process' cần tính từ: efficient. Efficiency/efficiencies là danh từ, efficiently là trạng từ.","extra":[{"en":"cost-efficient","vi":"tiết kiệm chi phí"},
{"en":"efficiency gains","vi":"lợi ích về hiệu quả"}]},
{"id":"q0556","unit":2,"stem":"Which word is closest in meaning to 'deficiency'?","options":["surplus","shortfall","replacement","alignment"],"answer":1,"explain":"Deficiency = sự thiếu hụt, tương đương shortfall. Surplus là thặng dư (trái nghĩa), replacement là sự thay thế, alignment là sự căn chỉnh.","extra":[{"en":"a shortfall in supply","vi":"thiếu hụt nguồn cung"},
{"en":"surplus","vi":"thặng dư"}]},
{"id":"q0557","unit":2,"stem":"Which statement about a linear workflow is correct?","options":["Each task is completed before the next one begins, following a fixed sequence.","Tasks are performed at random by whoever is free.","Tasks are repeated in a circle indefinitely.","Every task is carried out at the same time by all employees."],"answer":0,"explain":"Linear workflow = quy trình tuyến tính, các bước nối tiếp theo thứ tự cố định. Các phương án khác mô tả làm ngẫu nhiên, lặp vòng hoặc làm đồng thời.","extra":[{"en":"sequential process","vi":"quy trình tuần tự"},
{"en":"step-by-step","vi":"từng bước một"}]},
{"id":"q0558","unit":2,"stem":"In some stock-control formulas, the economic order quantity involves the ______ of annual demand.","options":["tier","metric","yield","square root"],"answer":3,"explain":"Công thức EOQ có dùng căn bậc hai (square root) của nhu cầu hằng năm. Tier, metric, yield không phải đại lượng toán học dùng theo cách này.","extra":[{"en":"economic order quantity","vi":"lượng đặt hàng kinh tế"},
{"en":"safety stock","vi":"tồn kho an toàn"}]},
{"id":"q0559","unit":2,"stem":"The CEO's ______ describes where the firm wants to be in ten years and guides every operational decision.","options":["line efficiency","performance measurement","strategic vision","production bottleneck"],"answer":2,"explain":"Strategic vision = tầm nhìn chiến lược dài hạn. Line efficiency là hiệu suất dây chuyền, performance measurement là đo lường hoạt động, bottleneck là điểm nghẽn.","extra":[{"en":"long-term vision","vi":"tầm nhìn dài hạn"},
{"en":"mission statement","vi":"tuyên bố sứ mệnh"}]},
{"id":"q0560","unit":2,"stem":"Which statement about JIT manufacturing is correct?","options":["It requires large buffer stocks of every component.","It means producing goods well in advance of any customer order.","It is used only by service companies, never by manufacturers.","It reduces the cost of holding stock but makes the firm dependent on reliable suppliers."],"answer":3,"explain":"JIT (just-in-time) giảm chi phí lưu kho nhưng phụ thuộc vào nhà cung cấp đáng tin cậy. Nó ngược với việc giữ tồn kho lớn hay sản xuất trước đơn hàng, và chủ yếu dùng trong sản xuất.","extra":[{"en":"hold stock","vi":"giữ hàng tồn"},
{"en":"supplier reliability","vi":"độ tin cậy của nhà cung cấp"}]},
{"id":"q0561","unit":2,"stem":"Following the inspection, the firm must ______ the faults in its wiring before the factory can reopen.","options":["remediate","replenish","multiply","utilize"],"answer":0,"explain":"Remediate = khắc phục (lỗi, vấn đề). Replenish là bổ sung hàng, multiply là tăng nhanh số lượng, utilize là sử dụng - không hợp với 'faults'.","extra":[{"en":"remedial action","vi":"hành động khắc phục"},
{"en":"safety inspection","vi":"kiểm tra an toàn"}]},
{"id":"q0562","unit":2,"stem":"Which expression is closest in meaning to 'pinpoint'?","options":["approximate roughly","dismiss completely","identify exactly","postpone indefinitely"],"answer":2,"explain":"Pinpoint = xác định chính xác. Approximate là ước chừng, dismiss là gạt bỏ, postpone là hoãn lại.","extra":[{"en":"identify the root cause","vi":"xác định nguyên nhân gốc"},
{"en":"root cause analysis","vi":"phân tích nguyên nhân gốc"}]},
{"id":"q0563","unit":2,"stem":"Poor ______ such as unreliable electricity and badly maintained roads reduces the plant's efficiency.","options":["yield","infrastructure","tiers","metrics"],"answer":1,"explain":"Infrastructure = cơ sở hạ tầng (điện, đường, mạng). Yield, tier, metric không chỉ hệ thống vật chất hỗ trợ hoạt động.","extra":[{"en":"transport infrastructure","vi":"hạ tầng giao thông"},
{"en":"invest in infrastructure","vi":"đầu tư hạ tầng"}]},
{"id":"q0564","unit":2,"stem":"Going ______, all suppliers will be required to meet the new quality standards.","options":["forward","backward","sideways","upward"],"answer":0,"explain":"'Going forward' = từ nay về sau, trong tương lai. Các lựa chọn còn lại không tạo thành cụm quen thuộc với nghĩa này.","extra":[{"en":"going forward","vi":"từ nay trở đi"},
{"en":"moving forward","vi":"tiến lên phía trước"}]},
{"id":"q0565","unit":2,"stem":"Without proper ______, managers cannot tell whether efficiency targets are being met.","options":["downtime","production bottleneck","performance measurement","infrastructure"],"answer":2,"explain":"Performance measurement = đo lường hiệu suất; không đo thì không biết đạt mục tiêu hay chưa. Downtime là thời gian máy dừng, bottleneck là điểm nghẽn, infrastructure là hạ tầng.","extra":[{"en":"meet targets","vi":"đạt mục tiêu"},
{"en":"measure results","vi":"đo lường kết quả"}]},
{"id":"q0566","unit":2,"stem":"A line designed to make 1,000 units an hour that actually makes 850 has a ______ of 85 per cent.","options":["lead time","line efficiency","tier","square root"],"answer":1,"explain":"Line efficiency = hiệu quả dây chuyền, tính bằng sản lượng thực tế / thiết kế. Lead time là thời gian chờ, tier là tầng lớp, square root là căn bậc hai.","extra":[{"en":"designed capacity","vi":"công suất thiết kế"},
{"en":"actual output","vi":"sản lượng thực tế"}]},
{"id":"q0567","unit":2,"stem":"Her team is responsible for the ______ of the new safety procedures across all sites.","options":["implement","implemented","implements","implementation"],"answer":3,"explain":"Sau 'the' và trước 'of' cần danh từ: implementation = việc thực hiện/triển khai. Các dạng còn lại là động từ.","extra":[{"en":"implementation plan","vi":"kế hoạch triển khai"},
{"en":"safety procedures","vi":"quy trình an toàn"}]},
{"id":"q0568","unit":2,"stem":"Non-______ with safety rules can lead to heavy fines and the suspension of production.","options":["complying","complied","compliance","compliant"],"answer":2,"explain":"Sau 'Non-' và trước 'with' cần danh từ: non-compliance with = việc không tuân thủ. Compliant là tính từ, complying/complied là dạng động từ.","extra":[{"en":"regulatory compliance","vi":"tuân thủ quy định"},
{"en":"compliance officer","vi":"cán bộ tuân thủ"}]},
{"id":"q0569","unit":2,"stem":"Which phrase collocates best with the verb 'enhance'?","options":["a deficiency","the reputation of the brand","a bottleneck","a defect"],"answer":1,"explain":"Enhance đi với thứ tích cực được nâng lên: enhance reputation/quality. Deficiency, bottleneck, defect đều là điều tiêu cực nên không dùng với enhance.","extra":[{"en":"enhance the reputation","vi":"nâng cao danh tiếng"},
{"en":"enhance efficiency","vi":"nâng cao hiệu quả"}]},
{"id":"q0570","unit":2,"stem":"Which verb means 'to fill up a supply of something that has been used'?","options":["oversee","align","remediate","replenish"],"answer":3,"explain":"Replenish = bổ sung, làm đầy lại nguồn cung. Oversee là giám sát, align là căn chỉnh, remediate là khắc phục.","extra":[{"en":"replenish supplies","vi":"bổ sung nguồn cung"},
{"en":"restock","vi":"nhập lại hàng"}]},
{"id":"q0571","unit":2,"stem":"The cost of rework can ______ quickly if faults are not detected early in the process.","options":["multiply","align","oversee","comply"],"answer":0,"explain":"Multiply = tăng nhanh về số lượng/mức độ, hợp với chi phí tăng nhanh. Align cần 'with', oversee là giám sát, comply cần 'with'.","extra":[{"en":"costs multiply","vi":"chi phí tăng vọt"},
{"en":"detect faults early","vi":"phát hiện lỗi sớm"}]},
{"id":"q0572","unit":2,"stem":"Which word is closest in meaning to 'prospective'?","options":["past","potential","current","former"],"answer":1,"explain":"Prospective = có khả năng xảy ra/trở thành trong tương lai, gần nghĩa potential. Past, current, former nói về quá khứ hoặc hiện tại.","extra":[{"en":"prospective buyer","vi":"người mua tiềm năng"},
{"en":"potential customer","vi":"khách hàng tiềm năng"}]},
{"id":"q0573","unit":2,"stem":"A fault that is ______ can be corrected at reasonable cost.","options":["irremediable","remedying","remediation","remediable"],"answer":3,"explain":"Remediable = có thể sửa chữa, cứu vãn được. Irremediable là trái nghĩa (không thể sửa), remedying và remediation không phải tính từ.","extra":[{"en":"irremediable damage","vi":"thiệt hại không thể khắc phục"},
{"en":"beyond repair","vi":"không thể sửa chữa"}]},
{"id":"q0574","unit":2,"stem":"The factory switched to lean manufacturing in order to ______.","options":["increase stock levels","lengthen lead times","eliminate waste in its processes","enlarge every batch"],"answer":2,"explain":"Lean manufacturing nhằm loại bỏ lãng phí. Tăng tồn kho, kéo dài lead time hay tăng cỡ lô đều đi ngược nguyên tắc tinh gọn.","extra":[{"en":"cut waste","vi":"giảm lãng phí"},
{"en":"lead time","vi":"thời gian chờ"}]},
{"id":"q0575","unit":2,"stem":"Orders pile up at the paint shop while the assembly and packing stations wait for work. The managers should first ______.","options":["hire more packers","buy more raw materials","lengthen the assembly line","increase the capacity of the paint shop"],"answer":3,"explain":"Paint shop là bottleneck (điểm nghẽn) nên tăng năng lực ở đó mới tăng được sản lượng toàn bộ. Thêm người đóng gói hay nguyên liệu không giải quyết điểm nghẽn.","extra":[{"en":"increase capacity","vi":"tăng công suất"},
{"en":"constraint","vi":"điểm thắt/ràng buộc"}]},
{"id":"q0576","unit":2,"stem":"Which word is closest in meaning to 'oversee'?","options":["ignore","fund","supervise","design"],"answer":2,"explain":"Oversee = giám sát, tương đương supervise. Ignore là phớt lờ, fund là tài trợ, design là thiết kế.","extra":[{"en":"supervise staff","vi":"giám sát nhân viên"},
{"en":"be in charge of","vi":"phụ trách"}]},
{"id":"q0577","unit":2,"stem":"The incentive system is poorly ______ with the company's goals, so staff focus on the wrong priorities.","options":["aligned","alienated","aligning","alignments"],"answer":0,"explain":"Be aligned with = khớp với, thống nhất với (bị động, cần quá khứ phân từ). Alienated là xa lánh, aligning/alignments không đúng cấu trúc.","extra":[{"en":"in line with","vi":"phù hợp với"},
{"en":"conflicting priorities","vi":"ưu tiên mâu thuẫn"}]},
{"id":"q0578","unit":2,"stem":"Machine ______ rose to 92 per cent after the new shift schedule was introduced.","options":["utilize","utilization","utilizing","utilized"],"answer":1,"explain":"Sau danh từ 'Machine' và trước 'rose' cần danh từ: utilization = mức độ sử dụng. Các dạng còn lại là động từ.","extra":[{"en":"capacity utilization","vi":"tận dụng công suất"},
{"en":"shift schedule","vi":"lịch ca"}]},
{"id":"q0579","unit":2,"stem":"Which term describes quantifiable measures used to track how well a process or team is performing?","options":["Strategic visions","Resource allocations","Performance metrics","Linear workflows"],"answer":2,"explain":"Performance metrics = chỉ số đo lường hiệu quả công việc. Strategic vision là tầm nhìn, resource allocation là phân bổ nguồn lực, linear workflow là quy trình tuần tự.","extra":[{"en":"measurable targets","vi":"mục tiêu đo lường được"},
{"en":"benchmark","vi":"điểm chuẩn"}]},
{"id":"q0580","unit":2,"stem":"Which statement about 'deficiency' is correct?","options":["It is a bonus paid for high efficiency.","It describes a very efficient process.","It is the final stage of a production line.","It means a lack of something that is needed."],"answer":3,"explain":"Deficiency = sự thiếu hụt, thiếu sót. Nó không phải khoản thưởng, cũng không mô tả quy trình hiệu quả hay công đoạn cuối.","extra":[{"en":"nutritional deficiency","vi":"thiếu hụt dinh dưỡng"},
{"en":"make good a deficiency","vi":"bù đắp thiếu sót"}]},
{"id":"q0581","unit":2,"stem":"A rise in production yield means ______.","options":["more acceptable output from the same inputs","longer waiting time between orders","greater machine downtime","a larger number of supplier tiers"],"answer":0,"explain":"Yield tăng nghĩa là cùng lượng đầu vào cho ra nhiều thành phẩm đạt chuẩn hơn. Các phương án khác nói về thời gian chờ, downtime, tầng nhà cung cấp.","extra":[{"en":"improve yield","vi":"cải thiện năng suất"},
{"en":"input and output","vi":"đầu vào và đầu ra"}]},
{"id":"q0582","unit":2,"stem":"The basic physical systems, such as roads, power supply and networks, that a business needs in order to operate are known as its ______.","options":["performance metrics","infrastructure","resources allocation","production yield"],"answer":1,"explain":"Infrastructure = cơ sở hạ tầng. Performance metrics là chỉ số, resources allocation là phân bổ nguồn lực, yield là sản lượng đạt chuẩn.","extra":[{"en":"digital infrastructure","vi":"hạ tầng số"},
{"en":"public utilities","vi":"tiện ích công cộng"}]},
{"id":"q0583","unit":2,"stem":"Although the new scheduling software was costly, the plant manager argued that it would ______ output without the need for extra staff.","options":["replenish","enhance","comply","pinpoint"],"answer":1,"explain":"Enhance = làm tăng/nâng cao (sản lượng). Replenish là bổ sung hàng, comply cần 'with', pinpoint là xác định chính xác.","extra":[{"en":"boost output","vi":"tăng sản lượng"},
{"en":"without extra staff","vi":"không cần thêm nhân sự"}]},
{"id":"q0584","unit":2,"stem":"The inspector noted that, although the defects were serious, they were ______, and the batch could be reworked rather than scrapped.","options":["prospective","linear","remediable","strategic"],"answer":2,"explain":"Remediable = có thể khắc phục/sửa chữa được, hợp với 'could be reworked'. Prospective là tiềm năng, linear là tuyến tính, strategic là mang tính chiến lược.","extra":[{"en":"rework","vi":"làm lại"},
{"en":"scrap","vi":"loại bỏ phế phẩm"}]},
{"id":"q0585","unit":2,"stem":"Which sentence is grammatically correct?","options":["The manager ordered the team to comply with the new standards.","The manager ordered the team to comply the new standards.","The manager ordered the team to comply for the new standards.","The manager ordered the team to comply on the new standards."],"answer":0,"explain":"Comply luôn đi với 'with': comply with the new standards. Các câu còn lại dùng sai hoặc thiếu giới từ.","extra":[{"en":"comply with the law","vi":"tuân thủ luật"},
{"en":"set standards","vi":"đặt ra tiêu chuẩn"}]},
{"id":"q0586","unit":2,"stem":"A company that moves to JIT production should expect ______.","options":["higher warehouse rents","larger safety stocks","longer delivery times to customers","tighter coordination with its suppliers"],"answer":3,"explain":"JIT đòi hỏi phối hợp chặt chẽ với nhà cung cấp vì nguyên liệu đến đúng lúc cần. Kho bãi và tồn kho an toàn lớn là đặc trưng của mô hình tồn kho lớn, ngược với JIT.","extra":[{"en":"tight coordination","vi":"phối hợp chặt chẽ"},
{"en":"safety stock","vi":"tồn kho an toàn"}]},
{"id":"q0587","unit":2,"stem":"In a JIT system, the ______ of stock is triggered by actual consumption rather than by forecasts.","options":["replenishment","replenisher","replenished","replenish"],"answer":0,"explain":"Sau 'the' và trước 'of' cần danh từ: replenishment = việc bổ sung hàng. Replenish là động từ, replenished là phân từ.","extra":[{"en":"stock replenishment","vi":"bổ sung hàng"},
{"en":"demand-driven","vi":"dựa trên nhu cầu thực"}]},
{"id":"q0588","unit":2,"stem":"Last year, the head of operations ______ the migration to the new production system.","options":["overseed","overseen","overseeing","oversaw"],"answer":3,"explain":"Oversee bất quy tắc: oversee - oversaw - overseen. Câu ở quá khứ đơn nên dùng oversaw. Overseen cần have/has, overseeing cần trợ động từ.","extra":[{"en":"oversee the migration","vi":"giám sát việc chuyển đổi"},
{"en":"head of operations","vi":"trưởng bộ phận vận hành"}]},
{"id":"q0589","unit":2,"stem":"Which statement correctly contrasts lean manufacturing with mass production?","options":["Lean manufacturing aims to build large stocks, whereas mass production aims to avoid them.","Lean manufacturing prioritizes eliminating waste, whereas mass production prioritizes making large volumes at low unit cost.","Lean manufacturing never uses standardized parts, whereas mass production always does.","Lean manufacturing is used only for one-off products, whereas mass production is used for services."],"answer":1,"explain":"Lean tập trung vào loại bỏ lãng phí, còn mass production nhắm đến sản lượng lớn với chi phí đơn vị thấp. Lean không nhằm tích trữ tồn kho.","extra":[{"en":"economies of scale","vi":"lợi thế quy mô"},
{"en":"standardized parts","vi":"linh kiện tiêu chuẩn hóa"}]},
{"id":"q0590","unit":2,"stem":"Safety incidents have ______ since the maintenance budget was cut, so the board is reconsidering the decision.","options":["aligned","complied","overseen","multiplied"],"answer":3,"explain":"Multiply = tăng nhanh về số lượng: sự cố tăng vọt sau khi cắt ngân sách. Aligned/complied/overseen không hợp với chủ ngữ 'incidents' và nghĩa câu.","extra":[{"en":"maintenance budget","vi":"ngân sách bảo trì"},
{"en":"reconsider a decision","vi":"xem xét lại quyết định"}]},
{"id":"q0591","unit":2,"stem":"Managers often rely on key performance ______ to judge whether a department is meeting its goals.","options":["tiers","indicators","yields","bottlenecks"],"answer":1,"explain":"Key performance indicators (KPIs) là cụm cố định = chỉ số hiệu suất chính. Tier, yield, bottleneck không tạo thành cụm này.","extra":[{"en":"KPIs","vi":"chỉ số hiệu suất chính"},
{"en":"meet goals","vi":"đạt mục tiêu"}]},
{"id":"q0592","unit":2,"stem":"In a three-tier supply chain, tier-two suppliers provide parts to ______.","options":["first-tier suppliers","the end customers","the regulators","the shareholders"],"answer":0,"explain":"Cấp 2 (tier-two) bán linh kiện cho nhà cung cấp cấp 1, cấp 1 bán cho nhà sản xuất. Khách hàng cuối, cơ quan quản lý, cổ đông không nằm trong chuỗi này.","extra":[{"en":"tier-one supplier","vi":"nhà cung cấp cấp 1"},
{"en":"component","vi":"linh kiện"}]},
{"id":"q0593","unit":2,"stem":"The plant's ______ improved noticeably after it adopted lean methods, with less waste and shorter set-up times.","options":["efficient","efficiently","efficiency","inefficient"],"answer":2,"explain":"Sau 'The plant's' cần danh từ: efficiency = hiệu quả. Efficient/inefficient là tính từ, efficiently là trạng từ.","extra":[{"en":"set-up time","vi":"thời gian chuẩn bị máy"},
{"en":"operational efficiency","vi":"hiệu quả vận hành"}]},
{"id":"q0594","unit":2,"stem":"Which phrase is closest in meaning to 'pinpoint the cause of the delay'?","options":["identify exactly why the delay occurred","ignore why the delay occurred","regret that the delay occurred","predict future delays"],"answer":0,"explain":"Pinpoint = xác định chính xác. Do đó 'pinpoint the cause' = tìm ra chính xác nguyên nhân.","extra":[{"en":"root cause","vi":"nguyên nhân gốc"},
{"en":"cause of delay","vi":"nguyên nhân chậm trễ"}]},
{"id":"q0595","unit":2,"stem":"The report highlighted a serious deficiency ______ the safety procedures.","options":["on","at","in","by"],"answer":2,"explain":"Collocation: a deficiency in sth = sự thiếu sót trong cái gì. Các giới từ khác không dùng.","extra":[{"en":"a deficiency in training","vi":"thiếu sót trong đào tạo"},
{"en":"safety procedures","vi":"quy trình an toàn"}]},
{"id":"q0596","unit":2,"stem":"A weakness of a linear workflow is that ______.","options":["tasks cannot be arranged in any order","a delay at one step holds up every later step","it can never be measured","it needs no supervision at all"],"answer":1,"explain":"Quy trình tuyến tính nối tiếp nên chậm trễ ở một bước làm kẹt các bước sau. Các lựa chọn khác không đúng với đặc điểm tuyến tính.","extra":[{"en":"sequential steps","vi":"các bước tuần tự"},
{"en":"hold up","vi":"làm chậm trễ"}]},
{"id":"q0597","unit":2,"stem":"A firm gave its best machines to its least profitable product line. This is an example of poor ______.","options":["quality assurance","line efficiency","performance measurement","allocation of resources"],"answer":3,"explain":"Phân bổ máy tốt nhất cho dòng sản phẩm kém lợi nhuận là phân bổ nguồn lực kém. Các khái niệm còn lại không mô tả việc chia nguồn lực.","extra":[{"en":"allocate resources","vi":"phân bổ nguồn lực"},
{"en":"profitability","vi":"khả năng sinh lời"}]},
{"id":"q0598","unit":2,"stem":"Digital tools can bring significant ______ to production planning.","options":["enhance","enhancement","enhanced","enhancing"],"answer":1,"explain":"Sau 'significant' cần danh từ: enhancement = sự nâng cao/cải thiện. Các dạng còn lại là động từ hoặc phân từ.","extra":[{"en":"technical enhancement","vi":"cải tiến kỹ thuật"},
{"en":"production planning","vi":"lập kế hoạch sản xuất"}]},
{"id":"q0599","unit":2,"stem":"The firm intends to utilize its spare capacity. Here, 'utilize' means ______.","options":["sell off","reduce","measure","make use of"],"answer":3,"explain":"Utilize = make use of (tận dụng). Sell off là bán tháo, reduce là giảm, measure là đo.","extra":[{"en":"spare capacity","vi":"công suất dư"},
{"en":"make full use of","vi":"tận dụng tối đa"}]},
{"id":"q0600","unit":2,"stem":"Which of the following would a quality assurance manager be LEAST likely to be responsible for?","options":["designing inspection procedures","reviewing suppliers' quality standards","negotiating the chief executive's salary","auditing production records"],"answer":2,"explain":"QA lo thiết kế quy trình kiểm tra, rà soát tiêu chuẩn nhà cung cấp, kiểm toán hồ sơ sản xuất. Đàm phán lương CEO thuộc nhân sự/hội đồng quản trị.","extra":[{"en":"audit records","vi":"kiểm tra hồ sơ"},
{"en":"inspection procedure","vi":"quy trình kiểm tra"}]},
{"id":"q0601","unit":2,"stem":"Complaints rose after the firm cut its inspection stage, which suggests that quality ______ had been weakened.","options":["assurance","yield","tier","forward"],"answer":0,"explain":"Quality assurance = đảm bảo chất lượng; cắt khâu kiểm tra làm suy yếu nó. Yield, tier, forward không ghép với 'quality' theo nghĩa này.","extra":[{"en":"quality standards","vi":"tiêu chuẩn chất lượng"},
{"en":"cut corners","vi":"làm ẩu, cắt giảm"}]},
{"id":"q0602","unit":2,"stem":"Which word is the opposite of 'enhance'?","options":["undermine","strengthen","improve","boost"],"answer":0,"explain":"Enhance = nâng cao; trái nghĩa là undermine (làm suy yếu). Strengthen, improve, boost đồng nghĩa với enhance.","extra":[{"en":"undermine confidence","vi":"làm suy giảm niềm tin"},
{"en":"boost morale","vi":"nâng cao tinh thần"}]},
{"id":"q0603","unit":2,"stem":"Which situation best explains low line efficiency?","options":["Operators are given extra training.","Frequent stoppages reduce the actual output compared with the designed output.","The line runs exactly at its design speed all day.","Preventive maintenance is carried out at weekends."],"answer":1,"explain":"Line efficiency thấp khi sản lượng thực tế thấp hơn thiết kế, thường do dừng máy. Đào tạo, chạy đúng tốc độ, bảo trì phòng ngừa đều giúp tăng hiệu quả.","extra":[{"en":"stoppage","vi":"sự dừng máy"},
{"en":"preventive maintenance","vi":"bảo trì phòng ngừa"}]},
{"id":"q0604","unit":2,"stem":"The new director will ______ the company's lean programme and report to the board every month.","options":["multiply","replenish","pinpoint","oversee"],"answer":3,"explain":"Oversee = giám sát, phụ trách chương trình. Multiply, replenish, pinpoint không hợp với tân ngữ 'programme'.","extra":[{"en":"report to the board","vi":"báo cáo với hội đồng quản trị"},
{"en":"lean programme","vi":"chương trình tinh gọn"}]},
{"id":"q0605","unit":2,"stem":"Many manufacturers ______ JIT manufacturing in order to reduce inventory costs.","options":["adopt","adapt","adept","adhere"],"answer":0,"explain":"Adopt = áp dụng (phương pháp, hệ thống): adopt JIT manufacturing. Adapt là điều chỉnh, adept là tính từ (thành thạo), adhere cần 'to'.","extra":[{"en":"adopt a strategy","vi":"áp dụng chiến lược"},
{"en":"reduce inventory costs","vi":"giảm chi phí tồn kho"}]},
{"id":"q0606","unit":2,"stem":"Parts that fail to ______ the specifications are returned to the supplier.","options":["fill","hold","catch","meet"],"answer":3,"explain":"Collocation: meet specifications = đáp ứng thông số kỹ thuật. Fill, hold, catch không đi với specifications.","extra":[{"en":"technical specifications","vi":"thông số kỹ thuật"},
{"en":"meet requirements","vi":"đáp ứng yêu cầu"}]},
{"id":"q0607","unit":2,"stem":"The new inspection routine helps to ______ product quality before goods leave the factory.","options":["insure","ensure","assume","insist"],"answer":1,"explain":"Ensure = đảm bảo (ensure product quality). Insure là bảo hiểm, assume là cho rằng, insist là khăng khăng.","extra":[{"en":"ensure quality","vi":"đảm bảo chất lượng"},
{"en":"insure against","vi":"mua bảo hiểm cho"}]},
{"id":"q0608","unit":2,"stem":"Which statement about just-in-time delivery is correct?","options":["Goods are delivered a month in advance to avoid shortages.","Goods are delivered only to customers who pay in cash.","Goods arrive just as they are needed for production.","Goods are delivered late on purpose to save money."],"answer":2,"explain":"JIT delivery = giao hàng đúng thời điểm cần cho sản xuất, giảm lưu kho. Giao trước cả tháng sẽ đi ngược nguyên tắc JIT.","extra":[{"en":"just-in-time delivery","vi":"giao hàng đúng lúc"},
{"en":"lean supply chain","vi":"chuỗi cung ứng tinh gọn"}]},
{"id":"q0609","unit":2,"stem":"Which action would most directly reduce inventory costs?","options":["Stockpiling three months of raw materials","Buying in bulk to fill the warehouse","Ordering smaller quantities more frequently, close to the time of use","Holding safety stock for every single item"],"answer":2,"explain":"Đặt hàng nhỏ, thường xuyên sát lúc dùng giảm chi phí lưu kho. Tích trữ, mua số lượng lớn hay giữ tồn kho an toàn cho mọi mặt hàng làm tăng chi phí.","extra":[{"en":"holding costs","vi":"chi phí lưu kho"},
{"en":"order in small lots","vi":"đặt hàng lô nhỏ"}]},
{"id":"q0610","unit":2,"stem":"The client rejected the delivery because the goods did not match the agreed technical ______.","options":["metrics","specifications","tiers","yields"],"answer":1,"explain":"Technical specifications = thông số kỹ thuật đã thỏa thuận. Metric là thước đo, tier là tầng, yield là sản lượng.","extra":[{"en":"reject a delivery","vi":"từ chối lô hàng"},
{"en":"agreed specifications","vi":"thông số đã thỏa thuận"}]},
{"id":"q0611","unit":2,"stem":"Which of the following would most likely reduce line efficiency?","options":["Frequent unplanned stoppages","Regular preventive maintenance","Balanced workloads between stations","Well-trained operators"],"answer":0,"explain":"Dừng máy ngoài kế hoạch làm giảm sản lượng thực tế và hiệu quả dây chuyền. Bảo trì phòng ngừa, cân bằng khối lượng việc và đào tạo đều giúp tăng hiệu quả.","extra":[{"en":"unplanned downtime","vi":"thời gian dừng ngoài kế hoạch"},
{"en":"balanced line","vi":"dây chuyền cân bằng"}]},
{"id":"q0612","unit":2,"stem":"Performance measurement is the process of ______.","options":["producing goods in advance of orders","raising capital on the stock market","hiring new production staff","collecting data to assess how well something is working"],"answer":3,"explain":"Performance measurement = thu thập dữ liệu để đánh giá hiệu quả hoạt động. Các lựa chọn khác nói về sản xuất, huy động vốn, tuyển dụng.","extra":[{"en":"assess performance","vi":"đánh giá hiệu suất"},
{"en":"benchmarking","vi":"so sánh chuẩn"}]},
{"id":"q0613","unit":2,"stem":"A production yield of 92 per cent means that ______.","options":["92 per cent of workers were present","92 per cent of the units produced met quality standards","92 per cent of orders were delivered late","the line worked for 92 per cent of the year"],"answer":1,"explain":"Yield = tỷ lệ sản phẩm đạt chuẩn trên tổng số sản xuất. Không liên quan đến số công nhân, giao trễ hay thời gian chạy máy.","extra":[{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"first-pass yield","vi":"tỷ lệ đạt ngay lần đầu"}]},
{"id":"q0614","unit":2,"stem":"Which of the following best describes a 'strategic vision'?","options":["A long-term picture of what the company wants to become","A list of this week's production orders","A record of last year's expenses","A rule for storing raw materials"],"answer":0,"explain":"Strategic vision = tầm nhìn chiến lược, bức tranh dài hạn về điều công ty muốn đạt. Các lựa chọn khác là việc ngắn hạn hoặc quy định chi tiết.","extra":[{"en":"long-term goals","vi":"mục tiêu dài hạn"},
{"en":"set a vision","vi":"đặt ra tầm nhìn"}]},
{"id":"q0615","unit":2,"stem":"The company took urgent steps to remediate ______.","options":["a surplus of orders","a rise in share price","a successful merger","the contamination at the site"],"answer":3,"explain":"Remediate đi với vấn đề cần khắc phục: contamination (ô nhiễm). Dư đơn hàng, tăng giá cổ phiếu, sáp nhập thành công không phải thứ cần khắc phục.","extra":[{"en":"environmental remediation","vi":"khắc phục môi trường"},
{"en":"take urgent steps","vi":"thực hiện biện pháp khẩn cấp"}]},
{"id":"q0616","unit":2,"stem":"At the end of each shift, operators ______ the bins with fasteners and small parts.","options":["oversee","multiply","replenish","comply"],"answer":2,"explain":"Replenish = bổ sung đầy lại (bins). Oversee là giám sát, multiply là tăng nhanh, comply cần 'with'.","extra":[{"en":"restock the bins","vi":"bổ sung thùng chứa"},
{"en":"end of shift","vi":"cuối ca"}]},
{"id":"q0617","unit":2,"stem":"Data analysis helped the team to ______ the bottleneck in the packing section.","options":["multiply","comply","replenish","pinpoint"],"answer":3,"explain":"Pinpoint = xác định chính xác vị trí điểm nghẽn. Multiply, comply, replenish không hợp với tân ngữ 'bottleneck'.","extra":[{"en":"data analysis","vi":"phân tích dữ liệu"},
{"en":"identify constraints","vi":"xác định điểm hạn chế"}]},
{"id":"q0618","unit":2,"stem":"The restructuring removed a ______ of middle management, so decisions now reach the board faster.","options":["yield","metric","tier","vision"],"answer":2,"explain":"Tier = tầng/lớp (a tier of management). Yield, metric, vision không đếm theo tầng quản lý.","extra":[{"en":"management tier","vi":"tầng quản lý"},
{"en":"flatten the hierarchy","vi":"giảm cấp bậc"}]},
{"id":"q0619","unit":2,"stem":"Which sentence is correct?","options":["The plant utilizes recycled water in its cooling system.","The plant utilizes to recycled water in its cooling system.","The plant is utilizing of recycled water in its cooling system.","The plant utilizes with recycled water in its cooling system."],"answer":0,"explain":"Utilize là ngoại động từ, đi trực tiếp với tân ngữ: utilizes recycled water. Các câu khác thêm giới từ không cần thiết.","extra":[{"en":"recycled water","vi":"nước tái chế"},
{"en":"cooling system","vi":"hệ thống làm mát"}]},
{"id":"q0620","unit":2,"stem":"Who is most likely to oversee production on the shop floor?","options":["A prospective customer","A production supervisor","An external auditor","A raw-material supplier"],"answer":1,"explain":"Oversee = giám sát; người giám sát sản xuất tại xưởng là production supervisor. Khách hàng tiềm năng, kiểm toán ngoài, nhà cung cấp không giám sát sản xuất hằng ngày.","extra":[{"en":"shop floor","vi":"khu vực sản xuất"},
{"en":"line manager","vi":"quản lý dây chuyền"}]},
{"id":"q0621","unit":2,"stem":"She put ______ a proposal to cut downtime by redesigning the factory layout.","options":["up","on","forward","over"],"answer":2,"explain":"Put forward a proposal = đưa ra đề xuất. Put up/on/over không tạo thành cụm với 'proposal' có nghĩa này.","extra":[{"en":"put forward an idea","vi":"đưa ra ý kiến"},
{"en":"factory layout","vi":"bố trí nhà xưởng"}]},
{"id":"q0622","unit":2,"stem":"Which action would most likely enhance product quality?","options":["Cutting the number of inspectors","Training operators in quality assurance procedures","Increasing line speed regardless of errors","Switching to the cheapest available materials"],"answer":1,"explain":"Đào tạo vận hành viên về quy trình QA giúp nâng cao chất lượng. Cắt kiểm tra, tăng tốc bất chấp lỗi, dùng nguyên liệu rẻ nhất đều hạ chất lượng.","extra":[{"en":"quality procedures","vi":"quy trình chất lượng"},
{"en":"train operators","vi":"đào tạo vận hành viên"}]},
{"id":"q0623","unit":2,"stem":"The inspector listed several ______ in the report, including out-of-date safety signs and missing fire exits.","options":["deficient","deficiently","deficit","deficiencies"],"answer":3,"explain":"Sau 'several' cần danh từ số nhiều: deficiencies = các thiếu sót. Deficient là tính từ, deficiently là trạng từ, deficit thường là thâm hụt tài chính.","extra":[{"en":"fire exit","vi":"lối thoát hiểm"},
{"en":"safety signs","vi":"biển báo an toàn"}]},
{"id":"q0624","unit":2,"stem":"Which word is closest in meaning to 'comply with' in the sentence 'The firm failed to comply with the regulations'?","options":["obey","challenge","draft","amend"],"answer":0,"explain":"Comply with = tuân theo, gần nghĩa obey. Challenge là thách thức, draft là soạn thảo, amend là sửa đổi.","extra":[{"en":"fail to comply","vi":"không tuân thủ"},
{"en":"breach regulations","vi":"vi phạm quy định"}]},
{"id":"q0625","unit":2,"stem":"Which phrase has the same meaning as 'prospective customers'?","options":["customers who may buy in the future","customers who have just complained","customers who always pay late","customers who are leaving the market"],"answer":0,"explain":"Prospective = có triển vọng; prospective customers là khách hàng tiềm năng sẽ mua trong tương lai.","extra":[{"en":"potential customers","vi":"khách hàng tiềm năng"},
{"en":"leads","vi":"khách hàng tiềm năng (thông tin liên hệ)"}]},
{"id":"q0626","unit":2,"stem":"Which sentence uses 'multiply' correctly?","options":["The machine multiplies to the end of the line.","The firm multiplies with its safety rules.","Quality was multiplied by the supervisor's smile.","Warehouse errors multiplied once the new, untrained staff arrived."],"answer":3,"explain":"Multiply (nội động từ) = tăng nhanh về số lượng: errors multiplied. Các câu khác dùng sai cấu trúc hoặc nghĩa.","extra":[{"en":"errors multiply","vi":"lỗi tăng nhanh"},
{"en":"untrained staff","vi":"nhân viên chưa được đào tạo"}]},
{"id":"q0627","unit":2,"stem":"Which pair of words has a similar meaning?","options":["replenish - deplete","enhance - damage","pinpoint - identify","oversee - neglect"],"answer":2,"explain":"Pinpoint và identify đều là xác định chính xác. Replenish-deplete, enhance-damage, oversee-neglect là các cặp trái nghĩa.","extra":[{"en":"deplete stocks","vi":"làm cạn kho"},
{"en":"neglect","vi":"bỏ bê"}]},
{"id":"q0628","unit":3,"stem":"A retailer holds $400,000 in government treasury bills that mature in 60 days and can be converted to cash almost immediately. In its accounts, these would most likely be classed as ______.","options":["cash equivalents","intangible assets","deferred tax","provisions"],"answer":0,"explain":"Cash equivalents là các khoản đầu tư ngắn hạn, thanh khoản cao, dễ quy đổi thành tiền. Intangible assets là tài sản vô hình (bằng sáng chế...), còn provisions là khoản dự phòng cho nghĩa vụ trong tương lai - đều không phải khoản dễ đổi ra tiền.","extra":[{"en":"short-term investment","vi":"đầu tư ngắn hạn"},
{"en":"liquid asset","vi":"tài sản có tính thanh khoản cao"},
{"en":"marketable securities","vi":"chứng khoán có thể bán ngay"}]},
{"id":"q0629","unit":3,"stem":"Amounts owed to a company by customers who have received goods on credit but not yet paid are recorded as ______.","options":["liabilities","receivables","retained earnings","treasury shares"],"answer":1,"explain":"Receivables (các khoản phải thu) là tiền khách hàng còn nợ công ty, xếp vào tài sản lưu động. Liabilities là nghĩa vụ công ty phải trả cho người khác - ngược lại với receivables.","extra":[{"en":"accounts receivable","vi":"các khoản phải thu"},
{"en":"bad debt","vi":"nợ xấu"},
{"en":"trade credit","vi":"tín dụng thương mại"}]},
{"id":"q0630","unit":3,"stem":"Profits that a company has kept in the business over the years, rather than paying them out as dividends, are known as ______.","options":["provisions","goodwill","retained earnings","current liabilities"],"answer":2,"explain":"Retained earnings là lợi nhuận giữ lại để tái đầu tư thay vì chia cổ tức. Goodwill là giá trị thương hiệu/uy tín phát sinh khi mua lại công ty, không phải lợi nhuận tích lũy.","extra":[{"en":"pay out dividends","vi":"chi trả cổ tức"},
{"en":"plough back profits","vi":"tái đầu tư lợi nhuận"},
{"en":"shareholders' equity","vi":"vốn chủ sở hữu"}]},
{"id":"q0631","unit":3,"stem":"Having bought back some of its own stock from the market, the company now holds ______, which are not entitled to dividends.","options":["receivables","patents","cash equivalents","treasury shares"],"answer":3,"explain":"Treasury shares là cổ phiếu quỹ do công ty mua lại, không được hưởng cổ tức hay quyền biểu quyết. Patents là bằng sáng chế (tài sản vô hình) nên không liên quan đến cổ phiếu.","extra":[{"en":"share buyback","vi":"mua lại cổ phiếu"},
{"en":"issued share capital","vi":"vốn cổ phần đã phát hành"},
{"en":"outstanding shares","vi":"cổ phiếu đang lưu hành"}]},
{"id":"q0632","unit":3,"stem":"When a firm acquires a rival for more than the fair value of its net identifiable assets, the excess payment is recorded as ______.","options":["goodwill","inventory","a provision","retained earnings"],"answer":0,"explain":"Goodwill là phần chênh lệch giữa giá mua và giá trị hợp lý của tài sản ròng có thể xác định, phản ánh thương hiệu, quan hệ khách hàng. Inventory là hàng tồn kho, không phát sinh từ việc mua lại.","extra":[{"en":"impairment of goodwill","vi":"suy giảm giá trị lợi thế thương mại"},
{"en":"acquisition cost","vi":"chi phí mua lại"},
{"en":"net assets","vi":"tài sản ròng"}]},
{"id":"q0633","unit":3,"stem":"The company has set aside $2 million to cover a probable legal settlement whose exact amount is still uncertain. This amount is a ______.","options":["receivable","provision","treasury share","trademark"],"answer":1,"explain":"Provision là khoản dự phòng cho nghĩa vụ có khả năng xảy ra nhưng chưa rõ số tiền hoặc thời điểm. Receivable là khoản được nhận, không phải khoản phải chi.","extra":[{"en":"make a provision for","vi":"trích lập dự phòng cho"},
{"en":"contingent liability","vi":"nợ tiềm tàng"},
{"en":"legal settlement","vi":"thỏa thuận giải quyết kiện tụng"}]},
{"id":"q0634","unit":3,"stem":"Which of the following is an example of an intangible asset?","options":["A delivery van","Stock held in the warehouse","A registered trademark","Cash in a bank account"],"answer":2,"explain":"Trademark (nhãn hiệu đã đăng ký) không có hình thái vật chất nên là tài sản vô hình. Xe tải là tài sản hữu hình, hàng tồn kho là tài sản lưu động, tiền gửi là tài sản tài chính.","extra":[{"en":"intellectual property","vi":"sở hữu trí tuệ"},
{"en":"amortise","vi":"khấu hao tài sản vô hình"},
{"en":"brand value","vi":"giá trị thương hiệu"}]},
{"id":"q0635","unit":3,"stem":"A tax authority allows a firm to pay part of this year's tax bill in future years. The amount owed later appears on the balance sheet as ______.","options":["retained earnings","bookkeeping","cost accounting","deferred tax"],"answer":3,"explain":"Deferred tax (thuế hoãn lại) là khoản thuế chưa phải nộp ngay mà hoãn sang kỳ sau. Retained earnings là lợi nhuận giữ lại, không phải khoản thuế.","extra":[{"en":"tax liability","vi":"nghĩa vụ thuế"},
{"en":"tax relief","vi":"giảm thuế"},
{"en":"tax return","vi":"tờ khai thuế"}]},
{"id":"q0636","unit":3,"stem":"Which item would normally be classified as a current liability?","options":["A supplier invoice due in 30 days","A 15-year mortgage on the head office","Goodwill from a past acquisition","Ordinary share capital"],"answer":0,"explain":"Current liability là nợ phải trả trong vòng 12 tháng, như hóa đơn nhà cung cấp đến hạn sau 30 ngày. Khoản vay thế chấp 15 năm là nợ dài hạn; vốn cổ phần thuộc equity.","extra":[{"en":"accounts payable","vi":"các khoản phải trả"},
{"en":"long-term liabilities","vi":"nợ dài hạn"},
{"en":"accrued expenses","vi":"chi phí phải trả"}]},
{"id":"q0637","unit":3,"stem":"The finance director explained that the loss in the subsidiary was ______ the one-off write-down of an old plant.","options":["contrary to","attributable to","subject to","prior to"],"answer":1,"explain":"Attributable to = có thể quy cho, do (nguyên nhân). Subject to nghĩa là phụ thuộc/chịu sự điều chỉnh; prior to là trước khi - đều sai nghĩa nguyên nhân-kết quả.","extra":[{"en":"write-down","vi":"ghi giảm giá trị tài sản"},
{"en":"one-off cost","vi":"chi phí một lần"},
{"en":"profit attributable to shareholders","vi":"lợi nhuận thuộc về cổ đông"}]},
{"id":"q0638","unit":3,"stem":"Which asset is most likely to be listed as a current asset rather than a non-current one?","options":["A patent with 12 years left","Factory machinery","Finished goods awaiting sale","A long-term investment in a subsidiary"],"answer":2,"explain":"Current asset là tài sản dự kiến chuyển thành tiền trong vòng một năm, như thành phẩm chờ bán. Bằng sáng chế, máy móc và đầu tư dài hạn được giữ lâu dài nên là tài sản không lưu động.","extra":[{"en":"fixed asset","vi":"tài sản cố định"},
{"en":"work in progress","vi":"sản phẩm dở dang"},
{"en":"working capital","vi":"vốn lưu động"}]},
{"id":"q0639","unit":3,"stem":"An accountant who records every day's sales, purchases and payments in the company's ledgers is doing ______.","options":["forensic accounting","auditing","creative accounting","bookkeeping"],"answer":3,"explain":"Bookkeeping là việc ghi chép hằng ngày các giao dịch tài chính. Auditing là kiểm toán độc lập kiểm tra sổ sách đó, còn forensic accounting là điều tra gian lận.","extra":[{"en":"double-entry bookkeeping","vi":"ghi sổ kép"},
{"en":"general ledger","vi":"sổ cái"},
{"en":"keep the books","vi":"giữ sổ sách"}]},
{"id":"q0640","unit":3,"stem":"Police asked an accountant to trace missing funds and find evidence of fraud for use in court. Her work is best described as ______.","options":["forensic accounting","tax accounting","managerial accounting","cost accounting"],"answer":0,"explain":"Forensic accounting là kế toán pháp y: điều tra gian lận và cung cấp bằng chứng cho tòa án. Managerial accounting phục vụ quyết định nội bộ của ban quản lý, không phục vụ điều tra.","extra":[{"en":"embezzlement","vi":"biển thủ công quỹ"},
{"en":"paper trail","vi":"dấu vết giấy tờ"},
{"en":"fraud investigation","vi":"điều tra gian lận"}]},
{"id":"q0641","unit":3,"stem":"The production manager wants to know exactly how much each unit of output costs in materials, labour and overheads. Which branch of accounting would help most?","options":["Tax accounting","Cost accounting","Forensic accounting","Financial auditing"],"answer":1,"explain":"Cost accounting phân tích chi phí sản xuất (vật liệu, nhân công, chi phí chung) cho từng đơn vị sản phẩm. Tax accounting tập trung vào nghĩa vụ thuế, không tính giá thành.","extra":[{"en":"unit cost","vi":"chi phí đơn vị"},
{"en":"overheads","vi":"chi phí chung"},
{"en":"cost per unit","vi":"chi phí mỗi đơn vị"}]},
{"id":"q0642","unit":3,"stem":"Managers receive monthly reports that help them decide whether to launch a new product line. This information is produced by ______.","options":["tax accounting","external auditing","managerial accounting","bookkeeping"],"answer":2,"explain":"Managerial accounting cung cấp thông tin nội bộ để ban quản lý ra quyết định. External auditing là kiểm toán độc lập cho bên ngoài, không phải báo cáo quản trị hằng tháng.","extra":[{"en":"management accounts","vi":"báo cáo quản trị"},
{"en":"budget variance","vi":"chênh lệch ngân sách"},
{"en":"decision-making","vi":"ra quyết định"}]},
{"id":"q0643","unit":3,"stem":"An accountant whose main job is to minimise a client's legal tax payments and prepare returns is working in ______.","options":["creative accounting","forensic accounting","cost accounting","tax accounting"],"answer":3,"explain":"Tax accounting tập trung vào việc lập tờ khai và tối ưu nghĩa vụ thuế một cách hợp pháp. Creative accounting là thao túng sổ sách để trông đẹp hơn, nghiêng về không trung thực.","extra":[{"en":"tax avoidance","vi":"tránh thuế hợp pháp"},
{"en":"tax evasion","vi":"trốn thuế (phạm pháp)"},
{"en":"tax allowance","vi":"khoản miễn thuế"}]},
{"id":"q0644","unit":3,"stem":"The auditors discovered that management had used 'creative accounting' to make profits look higher than they really were. This means the accounts were ______.","options":["misleading","well documented","audited externally","fully compliant"],"answer":0,"explain":"Creative accounting là cách trình bày số liệu gây hiểu nhầm, tạo ấn tượng sai về tình hình tài chính. Fully compliant (tuân thủ hoàn toàn) trái nghĩa với hàm ý trong câu.","extra":[{"en":"window dressing","vi":"tô vẽ báo cáo tài chính"},
{"en":"cook the books","vi":"làm giả sổ sách"},
{"en":"financial statements","vi":"báo cáo tài chính"}]},
{"id":"q0645","unit":3,"stem":"An executive was dismissed after he deliberately ______ the sales figures to qualify for a bonus.","options":["audited","falsified","flattened","incurred"],"answer":1,"explain":"Falsify = làm giả, sửa số liệu một cách cố ý. Audit là kiểm toán, incur là chịu (chi phí) - không dùng với nghĩa làm sai lệch số liệu.","extra":[{"en":"falsify records","vi":"làm giả hồ sơ"},
{"en":"fraudulent accounts","vi":"báo cáo gian lận"},
{"en":"whistleblower","vi":"người tố giác"}]},
{"id":"q0646","unit":3,"stem":"After the scandal, the firm struggled to regain its ______ with investors, who no longer trusted its published figures.","options":["bootstrapping","goodwill account","credibility","volatility"],"answer":2,"explain":"Credibility là độ tin cậy, tính đáng tin. Volatility là sự biến động mạnh của giá, không nói về lòng tin.","extra":[{"en":"lose credibility","vi":"mất uy tín"},
{"en":"restore confidence","vi":"khôi phục niềm tin"},
{"en":"reliable data","vi":"dữ liệu đáng tin"}]},
{"id":"q0647","unit":3,"stem":"A fashion label registers its logo and brand name so that no competitor can legally copy them. It has protected its ______.","options":["provision","receivables","retained earnings","trademark"],"answer":3,"explain":"Trademark là nhãn hiệu - dấu hiệu, tên, logo được bảo hộ pháp lý. Provisions và receivables là các khoản mục kế toán, không phải quyền bảo hộ thương hiệu.","extra":[{"en":"infringe a trademark","vi":"vi phạm nhãn hiệu"},
{"en":"registered brand","vi":"thương hiệu đã đăng ký"},
{"en":"counterfeit goods","vi":"hàng giả"}]},
{"id":"q0648","unit":3,"stem":"A pharmaceutical firm obtains a 20-year exclusive right to manufacture a new drug that it has invented. This right is called a ______.","options":["patent","trademark","treasury share","provision"],"answer":0,"explain":"Patent là bằng sáng chế, trao quyền độc quyền khai thác một phát minh trong thời hạn nhất định. Trademark bảo hộ tên/logo, không bảo hộ phát minh.","extra":[{"en":"file a patent","vi":"nộp đơn đăng ký sáng chế"},
{"en":"patent expires","vi":"bằng sáng chế hết hạn"},
{"en":"generic drug","vi":"thuốc generic"}]},
{"id":"q0649","unit":3,"stem":"Entrepreneurs with no external investors often use 'bootstrapping'. This means that they ______.","options":["borrow heavily from commercial banks","finance the business from their own savings and early revenue","sell part of the company to venture capitalists","buy back shares from the market"],"answer":1,"explain":"Bootstrapping là tự xoay xở vốn bằng tiền tiết kiệm cá nhân và doanh thu ban đầu, không dựa vào nhà đầu tư ngoài. Vay ngân hàng hay bán cổ phần cho quỹ mạo hiểm đều là huy động vốn bên ngoài.","extra":[{"en":"self-funded","vi":"tự tài trợ"},
{"en":"seed capital","vi":"vốn khởi nghiệp ban đầu"},
{"en":"start-up costs","vi":"chi phí khởi sự"}]},
{"id":"q0650","unit":3,"stem":"The share price has been very ______ this year, rising 30% in March and then falling by half in June.","options":["stable","deferred","volatile","intangible"],"answer":2,"explain":"Volatile = biến động mạnh, thất thường. Stable là ổn định - trái nghĩa với ví dụ tăng/giảm mạnh. Deferred và intangible không mô tả giá cổ phiếu.","extra":[{"en":"volatile market","vi":"thị trường biến động"},
{"en":"market volatility","vi":"sự biến động thị trường"},
{"en":"fluctuate","vi":"dao động"}]},
{"id":"q0651","unit":3,"stem":"Which accounting item represents what the owners of a business have left after all liabilities have been deducted from assets?","options":["Provisions","Receivables","Deferred tax","Equity"],"answer":3,"explain":"Equity (vốn chủ sở hữu) = tài sản - nợ phải trả, tức phần còn lại thuộc về chủ sở hữu. Provisions là khoản dự phòng cho nghĩa vụ trong tương lai nên là một dạng nợ.","extra":[{"en":"accounting equation","vi":"phương trình kế toán"},
{"en":"net worth","vi":"giá trị ròng"},
{"en":"owner's equity","vi":"vốn chủ sở hữu"}]},
{"id":"q0652","unit":3,"stem":"Sales rose steadily until June, but since then they have ______ at around 5,000 units a month, with no further growth.","options":["levelled off","taken off","fallen through","picked up"],"answer":0,"explain":"Level off = ngừng tăng/giảm và ổn định ở một mức. Take off là tăng vọt, pick up là cải thiện trở lại, fall through nghĩa là thất bại - không phù hợp với 'ổn định ở 5,000'.","extra":[{"en":"level out","vi":"đi ngang"},
{"en":"plateau","vi":"đạt mức bình ổn"},
{"en":"remain steady","vi":"giữ ổn định"}]},
{"id":"q0653","unit":3,"stem":"The graph shows that the unemployment rate ______ around 6% for most of the year before dropping slightly in December.","options":["soared","hovered","plunged","accelerated"],"answer":1,"explain":"Hover around = dao động quanh một mức, ít thay đổi. Soar (vọt lên), plunge (lao dốc) và accelerate (tăng tốc) đều mô tả thay đổi lớn, trái với 'quanh 6%'.","extra":[{"en":"hover around","vi":"dao động quanh"},
{"en":"fluctuate between","vi":"dao động giữa"},
{"en":"marginal change","vi":"thay đổi nhỏ"}]},
{"id":"q0654","unit":3,"stem":"After a period of rapid expansion, the company's revenue began to ______, showing almost no change from one quarter to the next.","options":["shoot up","slump","flatten out","take off"],"answer":2,"explain":"Flatten out = trở nên bằng phẳng, tăng trưởng chậm lại gần như không đổi. Shoot up là tăng vọt, slump là sụt giảm mạnh - đều khác với 'gần như không đổi'.","extra":[{"en":"flat growth","vi":"tăng trưởng đi ngang"},
{"en":"peak","vi":"đạt đỉnh"},
{"en":"steady state","vi":"trạng thái ổn định"}]},
{"id":"q0655","unit":3,"stem":"Economic growth is expected to ______ next year as consumer spending slows, falling from 3.2% to 2.1%.","options":["accelerate","hover","fluctuate","decelerate"],"answer":3,"explain":"Decelerate = giảm tốc, chậm lại. Accelerate là tăng tốc - ngược nghĩa với việc tăng trưởng giảm từ 3.2% xuống 2.1%. Hover là dao động quanh một mức.","extra":[{"en":"slowdown","vi":"sự chậm lại"},
{"en":"gain momentum","vi":"lấy đà"},
{"en":"growth rate","vi":"tốc độ tăng trưởng"}]},
{"id":"q0656","unit":3,"stem":"Which verb is closest in meaning to 'accelerate' in this sentence? 'Falling interest rates could accelerate the recovery.'","options":["speed up","hold back","level out","cut down"],"answer":0,"explain":"Accelerate = đẩy nhanh, đồng nghĩa với speed up. Hold back (kìm hãm) và cut down (cắt giảm) có nghĩa ngược hoặc khác.","extra":[{"en":"boost recovery","vi":"thúc đẩy phục hồi"},
{"en":"economic recovery","vi":"sự phục hồi kinh tế"},
{"en":"step up","vi":"tăng cường"}]},
{"id":"q0657","unit":3,"stem":"The firm ______ heavy costs when it had to recall thousands of faulty products from stores.","options":["attributed","incurred","deferred","falsified"],"answer":1,"explain":"Incur costs = chịu/phát sinh chi phí (thường không mong muốn). Defer là hoãn lại, falsify là làm giả - không đi với 'costs' theo nghĩa phát sinh chi phí.","extra":[{"en":"incur a loss","vi":"chịu lỗ"},
{"en":"incur expenses","vi":"phát sinh chi phí"},
{"en":"product recall","vi":"thu hồi sản phẩm"}]},
{"id":"q0658","unit":3,"stem":"Auditors found a ______ in the tax rules which allowed the company to avoid paying tax on overseas profits without breaking the law.","options":["provision","bookkeeping","loophole","patent"],"answer":2,"explain":"Loophole là kẽ hở trong luật/quy định mà người ta khai thác để tránh nghĩa vụ mà không vi phạm trực tiếp. Provision ở đây là khoản dự phòng hoặc điều khoản, không hàm ý kẽ hở.","extra":[{"en":"close a loophole","vi":"bịt kẽ hở"},
{"en":"exploit a loophole","vi":"lợi dụng kẽ hở"},
{"en":"tax haven","vi":"thiên đường thuế"}]},
{"id":"q0659","unit":3,"stem":"Choose the correct word form: 'The ______ of the company's accounts took three weeks and revealed several errors.'","options":["auditor","audited","auditable","auditing"],"answer":3,"explain":"Sau 'The' và trước 'of' cần danh từ chỉ hành động: auditing (việc kiểm toán). Auditor là người kiểm toán (không đi với 'took three weeks'), audited là tính từ/quá khứ.","extra":[{"en":"external audit","vi":"kiểm toán độc lập"},
{"en":"internal audit","vi":"kiểm toán nội bộ"},
{"en":"audit trail","vi":"dấu vết kiểm toán"}]},
{"id":"q0660","unit":3,"stem":"Choose the correct word form: 'Investors lost faith in the company because its financial statements were ______.'","options":["misleading","mislead","misled","misleadingly"],"answer":0,"explain":"Sau 'were' cần tính từ: misleading (gây hiểu nhầm). Misleadingly là trạng từ, misled là phân từ quá khứ dùng cho người bị đánh lừa, không dùng cho 'statements'.","extra":[{"en":"mislead investors","vi":"làm nhà đầu tư hiểu sai"},
{"en":"false impression","vi":"ấn tượng sai"},
{"en":"transparent reporting","vi":"báo cáo minh bạch"}]},
{"id":"q0661","unit":3,"stem":"Choose the correct word form: 'The ______ of the figures was questioned after several mistakes were found.'","options":["credible","credibility","credibly","credit"],"answer":1,"explain":"Sau 'The' và trước 'of' cần danh từ: credibility (độ tin cậy). Credible là tính từ, credibly là trạng từ, còn credit nghĩa là tín dụng nên khác nghĩa.","extra":[{"en":"credible source","vi":"nguồn đáng tin"},
{"en":"damage credibility","vi":"làm tổn hại uy tín"},
{"en":"reputation","vi":"danh tiếng"}]},
{"id":"q0662","unit":3,"stem":"Choose the correct word form: 'The ______ of the company's profit figures led to the director's arrest.'","options":["falsify","falsified","falsification","falsely"],"answer":2,"explain":"Sau 'The' và trước 'of' cần danh từ: falsification (hành vi làm giả số liệu). Falsify là động từ, falsified là quá khứ/tính từ, falsely là trạng từ.","extra":[{"en":"forge documents","vi":"làm giả giấy tờ"},
{"en":"commit fraud","vi":"phạm tội gian lận"},
{"en":"accounting scandal","vi":"bê bối kế toán"}]},
{"id":"q0663","unit":3,"stem":"Choose the correct word form: 'The company's ______ profit fell by 12% because of rising raw material prices.'","options":["attribute","attributably","attributed","attributable"],"answer":3,"explain":"Cụm 'profit attributable to shareholders' dùng tính từ attributable (có thể quy cho). Attribute là động từ/danh từ; attributed chỉ nghĩa 'được cho là', không chuẩn trong cụm này.","extra":[{"en":"be attributed to","vi":"được cho là do"},
{"en":"owing to","vi":"do bởi"},
{"en":"net profit","vi":"lợi nhuận ròng"}]},
{"id":"q0664","unit":3,"stem":"Which word is closest in meaning to 'volatile' in 'volatile exchange rates'?","options":["unpredictable","fixed","gradual","favourable"],"answer":0,"explain":"Volatile = dễ thay đổi, khó đoán, biến động nhanh. Fixed (cố định) và gradual (từ từ) là trái ngược, còn favourable (thuận lợi) không nói về mức độ biến động.","extra":[{"en":"exchange rate","vi":"tỷ giá"},
{"en":"swing","vi":"dao động mạnh"},
{"en":"stable currency","vi":"đồng tiền ổn định"}]},
{"id":"q0665","unit":3,"stem":"Which word is closest in meaning to 'falsify'?","options":["verify","forge","inspect","approve"],"answer":1,"explain":"Falsify = làm giả, gần nghĩa với forge (giả mạo). Verify (xác minh) và inspect (kiểm tra) có nghĩa ngược về mục đích, còn approve là phê duyệt.","extra":[{"en":"verify figures","vi":"xác minh số liệu"},
{"en":"tamper with","vi":"can thiệp, sửa đổi trái phép"},
{"en":"manipulate data","vi":"thao túng dữ liệu"}]},
{"id":"q0666","unit":3,"stem":"A new accounting rule closes a ______ that companies used to hide debts from their balance sheets.","options":["goodwill","patent","loophole","provision"],"answer":2,"explain":"Close a loophole = bịt kẽ hở. Goodwill và patent là tài sản vô hình, không kết hợp với 'close' theo nghĩa này; provision là khoản dự phòng.","extra":[{"en":"off-balance-sheet","vi":"ngoài bảng cân đối kế toán"},
{"en":"hide debts","vi":"che giấu nợ"},
{"en":"tighten regulations","vi":"siết chặt quy định"}]},
{"id":"q0667","unit":3,"stem":"Sales of the new smartphone ______ after launch, climbing from 10,000 to 90,000 units in a single month.","options":["levelled off","hovered","fell through","took off"],"answer":3,"explain":"Take off = cất cánh, tăng vọt nhanh chóng sau khi ra mắt. Level off và hover nghĩa là ổn định, fall through là thất bại nên đều ngược với việc tăng 10,000 lên 90,000.","extra":[{"en":"sales surge","vi":"doanh số tăng vọt"},
{"en":"skyrocket","vi":"tăng vọt"},
{"en":"rapid growth","vi":"tăng trưởng nhanh"}]},
{"id":"q0668","unit":3,"stem":"The share price ______ around $12 for several weeks, neither rising nor falling significantly.","options":["hovered","accelerated","plummeted","rocketed"],"answer":0,"explain":"Hover around = ở quanh một mức. Plummet (lao dốc) và rocket (tăng vọt) là thay đổi mạnh, accelerate là tăng tốc - đều không khớp với 'neither rising nor falling'.","extra":[{"en":"trade at","vi":"giao dịch ở mức"},
{"en":"stagnant","vi":"trì trệ"},
{"en":"marginal fluctuation","vi":"dao động nhẹ"}]},
{"id":"q0669","unit":3,"stem":"A company's decision to use creative accounting to hide losses is unethical mainly because it ______.","options":["reduces the amount of tax owed legally","misleads people who rely on the accounts","lowers the cost of production","increases the number of treasury shares"],"answer":1,"explain":"Vấn đề đạo đức của creative accounting là gây hiểu sai cho người sử dụng báo cáo (nhà đầu tư, chủ nợ). Giảm thuế hợp pháp hay giảm chi phí sản xuất không phải bản chất vấn đề.","extra":[{"en":"ethical standards","vi":"chuẩn mực đạo đức"},
{"en":"stakeholders","vi":"các bên liên quan"},
{"en":"corporate governance","vi":"quản trị công ty"}]},
{"id":"q0670","unit":3,"stem":"The accounts department says the cash flow problem is ______ late payments by two large customers.","options":["in spite of","regardless of","due to","apart from"],"answer":2,"explain":"Due to = do, bởi vì, chỉ nguyên nhân. In spite of và regardless of chỉ sự nhượng bộ, apart from là ngoại trừ nên làm sai logic câu.","extra":[{"en":"late payment","vi":"thanh toán trễ"},
{"en":"cash flow problem","vi":"vấn đề dòng tiền"},
{"en":"chase payment","vi":"đòi tiền"}]},
{"id":"q0671","unit":3,"stem":"Which of the following best describes an 'intangible asset'?","options":["A building owned by the company","Money held in a bank","Goods waiting to be shipped","A valuable resource with no physical form, such as a brand"],"answer":3,"explain":"Intangible asset là tài sản có giá trị nhưng không có hình thái vật chất, như thương hiệu hay bằng sáng chế. Tòa nhà là tài sản hữu hình, tiền gửi là tài sản tài chính, hàng chờ gửi là hàng tồn kho.","extra":[{"en":"tangible asset","vi":"tài sản hữu hình"},
{"en":"brand recognition","vi":"độ nhận diện thương hiệu"},
{"en":"software licence","vi":"giấy phép phần mềm"}]},
{"id":"q0672","unit":3,"stem":"Because the company shows very little variation in monthly profit, its earnings are described as ______.","options":["stable","volatile","deferred","misleading"],"answer":0,"explain":"Stable = ổn định, ít thay đổi. Volatile là ngược nghĩa (biến động mạnh). Deferred (hoãn lại) và misleading (gây hiểu nhầm) không mô tả mức độ biến động.","extra":[{"en":"steady income","vi":"thu nhập ổn định"},
{"en":"consistent earnings","vi":"thu nhập đều đặn"},
{"en":"predictable","vi":"có thể dự đoán"}]},
{"id":"q0673","unit":3,"stem":"A student asks: 'What is the difference between a liability and an expense?' Which answer is most accurate?","options":["A liability is a cost of daily operations, while an expense is money owed to creditors","A liability is an amount owed, while an expense is a cost incurred in running the business","They are the same item shown in two different reports","A liability is always long-term, while an expense is always short-term"],"answer":1,"explain":"Liability là khoản nợ phải trả; expense là chi phí phát sinh trong hoạt động kinh doanh. Đáp án đảo ngược hai khái niệm là sai, và liability không phải lúc nào cũng dài hạn (có current liabilities).","extra":[{"en":"operating expenses","vi":"chi phí hoạt động"},
{"en":"amount owed","vi":"khoản nợ"},
{"en":"settle a debt","vi":"thanh toán nợ"}]},
{"id":"q0674","unit":3,"stem":"Which of the following statements about treasury shares is correct?","options":["They are shares that the company plans to issue next year.","They are government bonds held by the company.","They have been repurchased by the issuing company and do not receive dividends.","They represent profits kept for reinvestment."],"answer":2,"explain":"Treasury shares là cổ phiếu do chính công ty mua lại, không nhận cổ tức. Trái phiếu chính phủ là khác; lợi nhuận giữ lại là retained earnings.","extra":[{"en":"buy back shares","vi":"mua lại cổ phiếu"},
{"en":"cancel shares","vi":"hủy cổ phiếu"},
{"en":"earnings per share","vi":"lãi trên mỗi cổ phiếu"}]},
{"id":"q0675","unit":3,"stem":"Rather than waiting until the end of the year, the firm's accountants prepare a statement every quarter to check that the company is meeting its targets. This shows the importance of ______ reporting.","options":["fraudulent","creative","forensic","regular financial"],"answer":3,"explain":"Regular financial reporting là báo cáo tài chính định kỳ để theo dõi mục tiêu. Fraudulent và creative hàm ý gian lận/thao túng, còn forensic là điều tra sau sự cố.","extra":[{"en":"quarterly results","vi":"kết quả hằng quý"},
{"en":"annual report","vi":"báo cáo thường niên"},
{"en":"meet targets","vi":"đạt mục tiêu"}]},
{"id":"q0676","unit":3,"stem":"If a company's current assets are $500,000 and its current liabilities are $200,000, its working capital is ______.","options":["$300,000","$700,000","$200,000","$500,000"],"answer":0,"explain":"Working capital = current assets trừ current liabilities = 500,000 - 200,000 = 300,000. 700,000 là tổng, còn 200,000 và 500,000 chỉ là từng thành phần.","extra":[{"en":"liquidity ratio","vi":"tỷ số thanh khoản"},
{"en":"current ratio","vi":"hệ số thanh toán hiện hành"},
{"en":"net current assets","vi":"tài sản lưu động ròng"}]},
{"id":"q0677","unit":3,"stem":"A company has total assets of $1.2 million and total liabilities of $0.7 million. Its equity is ______.","options":["$1.9 million","$0.5 million","$0.7 million","$1.2 million"],"answer":1,"explain":"Equity = assets - liabilities = 1.2 - 0.7 = 0.5 triệu USD. 1.9 triệu là cộng nhầm hai khoản; 0.7 và 1.2 chỉ là các thành phần riêng.","extra":[{"en":"balance sheet","vi":"bảng cân đối kế toán"},
{"en":"net assets","vi":"tài sản ròng"},
{"en":"solvent","vi":"có khả năng thanh toán"}]},
{"id":"q0678","unit":3,"stem":"The company reported strong profit in the year, yet its bank balance fell sharply because customers were slow to pay. The main problem lies in its ______.","options":["goodwill","trademarks","receivables","treasury shares"],"answer":2,"explain":"Lợi nhuận cao nhưng tiền giảm do khách trả chậm - vấn đề nằm ở receivables (khoản phải thu) chưa thu được. Goodwill, trademarks và treasury shares không liên quan đến việc thu tiền.","extra":[{"en":"profit versus cash","vi":"lợi nhuận và tiền mặt"},
{"en":"credit control","vi":"kiểm soát tín dụng"},
{"en":"overdue invoices","vi":"hóa đơn quá hạn"}]},
{"id":"q0679","unit":3,"stem":"Which situation would most likely require the company to record a provision?","options":["It has received an order from a new customer.","It has bought new office furniture for cash.","It has issued new shares to investors.","It expects to pay compensation after losing a lawsuit."],"answer":3,"explain":"Provision ghi nhận khi công ty có nghĩa vụ có thể xảy ra như bồi thường sau vụ kiện thua. Nhận đơn hàng, mua đồ nội thất bằng tiền hay phát hành cổ phiếu không tạo nghĩa vụ chưa chắc chắn.","extra":[{"en":"compensation","vi":"tiền bồi thường"},
{"en":"lawsuit","vi":"vụ kiện"},
{"en":"warranty provision","vi":"dự phòng bảo hành"}]},
{"id":"q0680","unit":3,"stem":"A software company spends several years developing a new program and then registers it to prevent copying. Which two items from the list are most directly involved?","options":["Intangible assets and patents","Receivables and inventory","Treasury shares and equity","Deferred tax and provisions"],"answer":0,"explain":"Phần mềm tự phát triển và được đăng ký bảo hộ là tài sản vô hình liên quan đến patent/bản quyền. Các cặp còn lại là khoản phải thu/hàng tồn, cổ phiếu quỹ/vốn, thuế hoãn lại/dự phòng - không liên quan đến sở hữu trí tuệ.","extra":[{"en":"copyright","vi":"bản quyền"},
{"en":"research and development","vi":"nghiên cứu và phát triển"},
{"en":"licence fee","vi":"phí cấp phép"}]},
{"id":"q0681","unit":3,"stem":"During an audit, the independent auditors noticed that the closing stock figure could not be supported by any records. They are likely to ______.","options":["approve the accounts without comment","qualify their opinion on the accounts","stop all bookkeeping at the firm","issue new shares in the company"],"answer":1,"explain":"Khi không có bằng chứng cho số liệu, kiểm toán viên thường đưa ra ý kiến kiểm toán ngoại trừ (qualify their opinion). Chấp thuận không bình luận là trái với phát hiện; kiểm toán viên không có quyền dừng ghi sổ hay phát hành cổ phiếu.","extra":[{"en":"qualified opinion","vi":"ý kiến kiểm toán ngoại trừ"},
{"en":"unqualified opinion","vi":"ý kiến chấp nhận toàn phần"},
{"en":"audit report","vi":"báo cáo kiểm toán"}]},
{"id":"q0682","unit":3,"stem":"The CFO said the group's rapid growth was ______ aggressive use of bootstrapping in its early years.","options":["regardless of","in contrast to","partly due to","far from"],"answer":2,"explain":"Partly due to = một phần do, chỉ nguyên nhân. In contrast to (trái với) và far from (xa mới là) làm câu mâu thuẫn về nghĩa; regardless of là bất kể.","extra":[{"en":"early-stage company","vi":"công ty giai đoạn đầu"},
{"en":"lean budget","vi":"ngân sách tinh gọn"},
{"en":"grow organically","vi":"tăng trưởng tự thân"}]},
{"id":"q0683","unit":3,"stem":"Which of these is an example of an expense rather than an asset?","options":["A newly registered patent","Cash in the safe","Unsold inventory","Monthly staff wages"],"answer":3,"explain":"Wages (lương) là chi phí phát sinh trong kỳ, không tạo ra tài sản lâu dài. Bằng sáng chế, tiền mặt và hàng tồn kho đều là tài sản.","extra":[{"en":"payroll","vi":"bảng lương"},
{"en":"running costs","vi":"chi phí vận hành"},
{"en":"capital expenditure","vi":"chi đầu tư vốn"}]},
{"id":"q0684","unit":3,"stem":"An entrepreneur says that a lack of capital forced her to 'bootstrap' her start-up. Which of the following best fits this approach?","options":["Reinvesting early sales income and keeping costs low","Floating the company on the stock exchange","Taking out a large loan from a venture fund","Merging with a larger competitor"],"answer":0,"explain":"Bootstrapping = tự lực, dùng doanh thu ban đầu để tái đầu tư và kiềm chế chi phí. Niêm yết, vay quỹ lớn hoặc sáp nhập đều là phụ thuộc vốn hoặc lực lượng bên ngoài.","extra":[{"en":"float on the stock exchange","vi":"niêm yết chứng khoán"},
{"en":"venture capital","vi":"vốn đầu tư mạo hiểm"},
{"en":"minimise costs","vi":"giảm thiểu chi phí"}]},
{"id":"q0685","unit":3,"stem":"The manager was found guilty of ______ the company's accounts to hide his personal expenses.","options":["auditing","falsifying","amortising","decelerating"],"answer":1,"explain":"Falsify the accounts = làm giả sổ sách để che giấu chi tiêu cá nhân. Auditing và amortising là hoạt động hợp pháp, decelerate là làm chậm lại.","extra":[{"en":"personal expenses","vi":"chi phí cá nhân"},
{"en":"found guilty of","vi":"bị kết tội"},
{"en":"misappropriate funds","vi":"chiếm dụng quỹ"}]},
{"id":"q0686","unit":3,"stem":"Auditors use ______ to describe the paper or electronic records that let them trace a transaction from beginning to end.","options":["a loophole","goodwill","an audit trail","a provision"],"answer":2,"explain":"Audit trail là chuỗi chứng từ giúp truy vết một giao dịch từ đầu đến cuối. Loophole là kẽ hở, goodwill là lợi thế thương mại, provision là dự phòng - không dùng để truy vết.","extra":[{"en":"trace transactions","vi":"truy vết giao dịch"},
{"en":"supporting documents","vi":"chứng từ"},
{"en":"internal controls","vi":"kiểm soát nội bộ"}]},
{"id":"q0687","unit":3,"stem":"The company's share price has become less ______ since it announced a stable dividend policy: day-to-day changes are now much smaller.","options":["profitable","attributable","tangible","volatile"],"answer":3,"explain":"Less volatile = ít biến động hơn. Profitable (sinh lời), attributable (quy cho), tangible (hữu hình) không nói về mức biến động.","extra":[{"en":"dividend policy","vi":"chính sách cổ tức"},
{"en":"share price","vi":"giá cổ phiếu"},
{"en":"risk-averse investors","vi":"nhà đầu tư ngại rủi ro"}]},
{"id":"q0688","unit":3,"stem":"Revenue growth at the firm has ______ and is now expected to stay at about 2% a year.","options":["flattened out","taken off","fluctuated wildly","gone through the roof"],"answer":0,"explain":"Flatten out = chậm lại và ổn định ở mức thấp (2% mỗi năm). Take off và go through the roof là tăng vọt; fluctuate wildly là dao động mạnh nên đều sai.","extra":[{"en":"annual growth","vi":"tăng trưởng hằng năm"},
{"en":"modest growth","vi":"tăng trưởng khiêm tốn"},
{"en":"stay constant","vi":"giữ nguyên"}]},
{"id":"q0689","unit":3,"stem":"Which sentence uses 'incur' correctly?","options":["The airline incurred its passengers a free meal.","The airline incurred a large fine for breaking safety rules.","The airline incurred new aircraft from the manufacturer.","The airline incurred to reduce its fuel costs."],"answer":1,"explain":"Incur đi với danh từ chỉ điều bất lợi như fine, cost, loss, debt. Các câu còn lại dùng sai cấu trúc: không có tân ngữ kép, không đi với 'to' hay dùng với nghĩa mua.","extra":[{"en":"incur a fine","vi":"chịu phạt"},
{"en":"incur debts","vi":"phát sinh nợ"},
{"en":"bear the cost","vi":"chịu chi phí"}]},
{"id":"q0690","unit":3,"stem":"Which of the following would a forensic accountant be least likely to do?","options":["Trace funds that were secretly transferred abroad","Examine invoices for signs of fraud","Prepare routine monthly management reports","Give expert evidence in a court case"],"answer":2,"explain":"Forensic accountant điều tra gian lận và đưa bằng chứng tại tòa; báo cáo quản trị hằng tháng là việc của managerial accounting nên là đáp án ít khả năng nhất.","extra":[{"en":"expert witness","vi":"chuyên gia làm chứng"},
{"en":"money laundering","vi":"rửa tiền"},
{"en":"suspicious transaction","vi":"giao dịch đáng ngờ"}]},
{"id":"q0691","unit":3,"stem":"The finance team wants to understand why the cost of making a product has risen, so it analyses materials, labour and overheads in detail. The most useful tool is ______.","options":["tax accounting","creative accounting","forensic accounting","cost accounting"],"answer":3,"explain":"Cost accounting phân tích chi phí vật liệu, nhân công và chi phí chung để hiểu giá thành tăng. Creative accounting liên quan đến cách trình bày số liệu, không giải thích nguyên nhân chi phí.","extra":[{"en":"variance analysis","vi":"phân tích chênh lệch"},
{"en":"cost-cutting","vi":"cắt giảm chi phí"},
{"en":"break-even point","vi":"điểm hòa vốn"}]},
{"id":"q0692","unit":3,"stem":"The company's new accounting software is designed to ______ the errors that occur when staff enter figures manually.","options":["reduce","incur","falsify","defer"],"answer":0,"explain":"Reduce errors = giảm lỗi. Incur errors nghĩa là chịu lỗi (không hợp), falsify là làm giả, defer là hoãn - đều không hợp ngữ cảnh phần mềm giúp giảm sai sót.","extra":[{"en":"manual entry","vi":"nhập liệu thủ công"},
{"en":"automate","vi":"tự động hóa"},
{"en":"human error","vi":"lỗi do con người"}]},
{"id":"q0693","unit":3,"stem":"An investor is concerned because the firm's profits 'swing wildly from year to year'. The investor is worried about the firm's ______.","options":["liquidity","volatility","credibility","patent"],"answer":1,"explain":"Profit dao động mạnh từ năm này sang năm khác thể hiện volatility (tính biến động). Liquidity là khả năng chuyển đổi thành tiền, credibility là độ tin cậy, patent là bằng sáng chế.","extra":[{"en":"risk","vi":"rủi ro"},
{"en":"earnings stability","vi":"độ ổn định thu nhập"},
{"en":"fluctuate","vi":"biến động"}]},
{"id":"q0694","unit":3,"stem":"Which of these terms is used for an owner's investment in a company plus the profits it has kept over time?","options":["Current liabilities","Receivables","Shareholders' equity","Deferred tax"],"answer":2,"explain":"Shareholders' equity gồm vốn góp cộng lợi nhuận giữ lại. Current liabilities là nợ ngắn hạn, receivables là khoản phải thu, deferred tax là thuế hoãn lại.","extra":[{"en":"share capital","vi":"vốn cổ phần"},
{"en":"reserves","vi":"các quỹ dự trữ"},
{"en":"return on equity","vi":"tỷ suất lợi nhuận trên vốn"}]},
{"id":"q0695","unit":3,"stem":"A company's accounts show a large amount of 'goodwill' after it bought a smaller rival. A sceptical analyst warns that if the rival's performance disappoints, the company may have to record an ______.","options":["audit trail","amortisation of stock","dividend","impairment"],"answer":3,"explain":"Impairment = ghi giảm giá trị tài sản (như goodwill) khi giá trị thực thấp hơn giá trị sổ sách. Dividend là cổ tức nên không liên quan đến việc ghi giảm tài sản.","extra":[{"en":"impairment loss","vi":"lỗ do suy giảm giá trị"},
{"en":"write off","vi":"xóa sổ"},
{"en":"carrying value","vi":"giá trị ghi sổ"}]},
{"id":"q0696","unit":3,"stem":"Which of the following is NOT normally included in current assets?","options":["A factory building","Cash equivalents","Inventory","Trade receivables"],"answer":0,"explain":"Nhà xưởng là tài sản cố định (non-current), dùng lâu dài. Cash equivalents, inventory và trade receivables đều dự kiến chuyển thành tiền trong vòng một năm.","extra":[{"en":"non-current asset","vi":"tài sản dài hạn"},
{"en":"depreciation","vi":"khấu hao"},
{"en":"liquid assets","vi":"tài sản thanh khoản"}]},
{"id":"q0697","unit":3,"stem":"A supermarket chain keeps accurate records of the goods it holds in its warehouses and shops. In the balance sheet, this item appears as ______.","options":["provisions","inventory","deferred tax","equity"],"answer":1,"explain":"Inventory (hàng tồn kho) là hàng hóa nắm giữ để bán hoặc sản xuất, thuộc tài sản lưu động. Provisions và deferred tax là các nghĩa vụ chưa phát sinh; equity là vốn chủ sở hữu.","extra":[{"en":"stock turnover","vi":"vòng quay hàng tồn"},
{"en":"obsolete stock","vi":"hàng tồn lỗi thời"},
{"en":"stocktaking","vi":"kiểm kê"}]},
{"id":"q0698","unit":3,"stem":"After years of fast expansion, the firm's market share has ______ at around 18% as competitors catch up.","options":["rocketed","been falsified","levelled off","incurred"],"answer":2,"explain":"Level off = dừng tăng và đi ngang tại một mức (khoảng 18%). Rocket là tăng vọt - trái với việc đối thủ bắt kịp; falsified và incurred sai từ loại hoặc nghĩa.","extra":[{"en":"market share","vi":"thị phần"},
{"en":"catch up with","vi":"bắt kịp"},
{"en":"saturate the market","vi":"bão hòa thị trường"}]},
{"id":"q0699","unit":3,"stem":"The CFO described the quarterly results as 'flat', meaning that profits ______.","options":["fell sharply","rose by more than 20%","were falsified","showed little or no change"],"answer":3,"explain":"Flat = gần như không thay đổi. Rơi mạnh hay tăng trên 20% là thay đổi lớn; falsified (bị làm giả) là hành vi gian lận chứ không phải mô tả xu hướng.","extra":[{"en":"flat results","vi":"kết quả đi ngang"},
{"en":"year-on-year","vi":"so với cùng kỳ năm trước"},
{"en":"quarter-on-quarter","vi":"so với quý trước"}]},
{"id":"q0700","unit":3,"stem":"Which verb best completes the sentence? 'Inflation is expected to ______ to 6% by the end of the year as energy prices climb.'","options":["accelerate","decelerate","level off","hover below"],"answer":0,"explain":"Accelerate to 6% = tăng tốc lên 6% khi giá năng lượng leo thang. Decelerate là giảm tốc - ngược nghĩa; level off và hover below không phù hợp với 'as prices climb'.","extra":[{"en":"inflation rate","vi":"tỷ lệ lạm phát"},
{"en":"consumer prices","vi":"giá tiêu dùng"},
{"en":"energy costs","vi":"chi phí năng lượng"}]},
{"id":"q0701","unit":3,"stem":"Which of the following is the best example of 'tax avoidance' as opposed to 'tax evasion'?","options":["Hiding income from the tax authority","Investing in a government-approved tax-free savings scheme","Falsifying invoices to claim deductions","Not filing a tax return at all"],"answer":1,"explain":"Tax avoidance là giảm thuế hợp pháp bằng cách dùng các ưu đãi, như quỹ tiết kiệm miễn thuế. Giấu thu nhập, làm giả hóa đơn và không khai thuế đều là trốn thuế (evasion) trái luật.","extra":[{"en":"tax-free","vi":"miễn thuế"},
{"en":"tax deduction","vi":"khoản khấu trừ thuế"},
{"en":"tax authority","vi":"cơ quan thuế"}]},
{"id":"q0702","unit":3,"stem":"An accountant is asked to explain the difference between 'profit' and 'retained earnings'. Which statement is correct?","options":["Retained earnings are the total sales for the year.","Profit is the amount a company owes to its creditors.","Retained earnings are the part of profit that has not been paid out as dividends.","Retained earnings are shares bought back from investors."],"answer":2,"explain":"Retained earnings là phần lợi nhuận chưa chia cổ tức mà giữ lại. Doanh thu tổng không phải lợi nhuận; khoản nợ chủ nợ là liability; cổ phiếu mua lại là treasury shares.","extra":[{"en":"net income","vi":"thu nhập ròng"},
{"en":"dividend payout","vi":"tỷ lệ chi trả cổ tức"},
{"en":"reinvest","vi":"tái đầu tư"}]},
{"id":"q0703","unit":3,"stem":"A small bakery has a patent for its unique oven design and a trademark for its brand name. Together, these are examples of ______.","options":["current liabilities","treasury shares","deferred tax","intangible assets"],"answer":3,"explain":"Patent và trademark đều là tài sản vô hình được pháp luật bảo hộ. Current liabilities là nợ ngắn hạn; treasury shares và deferred tax không phải sở hữu trí tuệ.","extra":[{"en":"intellectual property rights","vi":"quyền sở hữu trí tuệ"},
{"en":"licensing","vi":"cấp phép"},
{"en":"unique design","vi":"thiết kế độc đáo"}]},
{"id":"q0704","unit":3,"stem":"The company reported a pre-tax profit of $8 million, but its ______ profit, after paying tax, was only $5.6 million.","options":["net","gross","retained","deferred"],"answer":0,"explain":"Net profit là lợi nhuận ròng sau khi trừ thuế và các chi phí. Gross profit là lợi nhuận gộp trước các chi phí hoạt động; retained và deferred không dùng để chỉ lợi nhuận sau thuế.","extra":[{"en":"gross profit","vi":"lợi nhuận gộp"},
{"en":"operating profit","vi":"lợi nhuận hoạt động"},
{"en":"corporate tax","vi":"thuế thu nhập doanh nghiệp"}]},
{"id":"q0705","unit":3,"stem":"Which word can complete the phrase: 'The share price has been ______ ever since news of the investigation broke'?","options":["intangible","volatile","attributable","bookkeeping"],"answer":1,"explain":"Volatile là tính từ chỉ giá biến động mạnh, hợp ngữ cảnh tin điều tra. Intangible và attributable không mô tả giá; bookkeeping là danh từ (ghi sổ).","extra":[{"en":"investigation","vi":"cuộc điều tra"},
{"en":"jittery markets","vi":"thị trường bất ổn"},
{"en":"sell-off","vi":"bán tháo"}]},
{"id":"q0706","unit":3,"stem":"A new CFO wants to rebuild the firm's ______ after the previous management was found to have manipulated the accounts.","options":["provisions","bookkeeping","credibility","receivables"],"answer":2,"explain":"Rebuild credibility = xây dựng lại uy tín, lòng tin sau khi ban quản lý cũ thao túng sổ sách. Provisions và receivables là khoản mục kế toán; bookkeeping là ghi sổ, không phải uy tín.","extra":[{"en":"restore trust","vi":"khôi phục lòng tin"},
{"en":"transparency","vi":"tính minh bạch"},
{"en":"manipulated accounts","vi":"sổ sách bị thao túng"}]},
{"id":"q0707","unit":3,"stem":"Which of the following best describes 'window dressing' in financial reporting?","options":["Updating the company's website with new products","Selling treasury shares to employees","Preparing a detailed audit report","Arranging the figures so that the company looks healthier than it is"],"answer":3,"explain":"Window dressing là chỉnh trang số liệu để báo cáo trông đẹp hơn thực tế. Cập nhật website, bán cổ phiếu quỹ cho nhân viên hay lập báo cáo kiểm toán không phải trò tô vẽ số liệu.","extra":[{"en":"cosmetic","vi":"bề ngoài"},
{"en":"flatter the figures","vi":"làm đẹp số liệu"},
{"en":"financial health","vi":"sức khỏe tài chính"}]},
{"id":"q0708","unit":3,"stem":"Which of the following is a typical duty of an internal auditor?","options":["Checking that company procedures and controls are being followed","Registering patents for new inventions","Issuing treasury shares","Setting the tax rate for the country"],"answer":0,"explain":"Internal auditor kiểm tra tuân thủ quy trình và kiểm soát nội bộ của công ty. Đăng ký sáng chế, phát hành cổ phiếu quỹ và ấn định thuế suất không thuộc nhiệm vụ này.","extra":[{"en":"internal controls","vi":"kiểm soát nội bộ"},
{"en":"compliance","vi":"sự tuân thủ"},
{"en":"risk assessment","vi":"đánh giá rủi ro"}]},
{"id":"q0709","unit":3,"stem":"The share of net profit that belongs to the parent company's owners, excluding minority interests, is called profit ______ the parent's shareholders.","options":["regardless of","attributable to","in spite of","apart from"],"answer":1,"explain":"Profit attributable to shareholders = lợi nhuận thuộc về cổ đông. Các cụm còn lại không có nghĩa 'thuộc về' trong báo cáo kết quả.","extra":[{"en":"minority interest","vi":"lợi ích cổ đông thiểu số"},
{"en":"parent company","vi":"công ty mẹ"},
{"en":"consolidated accounts","vi":"báo cáo hợp nhất"}]},
{"id":"q0710","unit":3,"stem":"The CEO was careful to avoid making the results sound better than they were. She wanted to avoid any ______ impression.","options":["reliable","transparent","misleading","accurate"],"answer":2,"explain":"Misleading impression = ấn tượng gây hiểu sai. Reliable, transparent và accurate đều mang nghĩa tích cực nên trái với 'avoid' trong ngữ cảnh này.","extra":[{"en":"give a false impression","vi":"tạo ấn tượng sai"},
{"en":"honest reporting","vi":"báo cáo trung thực"},
{"en":"full disclosure","vi":"công bố đầy đủ"}]},
{"id":"q0711","unit":3,"stem":"A start-up's founder says: 'We had no investors, so we were bootstrapping for the first two years.' Which phrase is closest in meaning?","options":["borrowing from a large bank","selling shares to the public","outsourcing production","funding the business ourselves"],"answer":3,"explain":"Bootstrapping = tự tài trợ cho doanh nghiệp. Vay ngân hàng, bán cổ phiếu ra công chúng đều là huy động vốn bên ngoài; thuê ngoài sản xuất là việc khác.","extra":[{"en":"self-financing","vi":"tự tài trợ"},
{"en":"outside investors","vi":"nhà đầu tư bên ngoài"},
{"en":"initial public offering","vi":"phát hành cổ phiếu lần đầu"}]},
{"id":"q0712","unit":3,"stem":"The accountant explained that part of the tax due this year can be postponed, so the balance sheet shows a ______.","options":["deferred tax liability","current asset","treasury share","trademark"],"answer":0,"explain":"Deferred tax liability là khoản thuế phải nộp trong tương lai do hoãn nộp. Current asset là tài sản; treasury share và trademark không liên quan đến thuế.","extra":[{"en":"defer payment","vi":"hoãn thanh toán"},
{"en":"tax timing difference","vi":"chênh lệch thời điểm thuế"},
{"en":"postpone","vi":"hoãn lại"}]},
{"id":"q0713","unit":3,"stem":"The research department's discoveries are protected by 20 patents. If a competitor copies the technology without permission, the company can sue for ______.","options":["accounting","infringement","bootstrapping","goodwill"],"answer":1,"explain":"Infringement = vi phạm quyền (bằng sáng chế, nhãn hiệu). Accounting và bootstrapping không phải hành vi vi phạm pháp lý; goodwill là lợi thế thương mại.","extra":[{"en":"patent infringement","vi":"vi phạm sáng chế"},
{"en":"sue for damages","vi":"kiện đòi bồi thường"},
{"en":"legal action","vi":"hành động pháp lý"}]},
{"id":"q0714","unit":3,"stem":"Production at the plant reached full capacity in March and has since remained at about 95%. Which verb describes this trend?","options":["soared","plummeted","hovered","slumped"],"answer":2,"explain":"Hover around 95% = ở quanh mức 95%. Soar (vọt lên), plummet (lao dốc) và slump (sụt mạnh) đều mô tả thay đổi lớn nên không đúng.","extra":[{"en":"capacity utilisation","vi":"mức sử dụng công suất"},
{"en":"full capacity","vi":"hết công suất"},
{"en":"operate at","vi":"vận hành ở mức"}]},
{"id":"q0715","unit":3,"stem":"An ethical accountant would refuse a request to ______ expenses so that the company could report a larger profit.","options":["verify","record","disclose","understate"],"answer":3,"explain":"Understate expenses = khai thấp chi phí để lợi nhuận trông cao hơn, là hành vi gian lận. Verify, record, disclose là hành vi chính đáng nên không bị từ chối.","extra":[{"en":"overstate","vi":"khai khống"},
{"en":"accurate records","vi":"hồ sơ chính xác"},
{"en":"professional ethics","vi":"đạo đức nghề nghiệp"}]},
{"id":"q0716","unit":3,"stem":"Which accounting document is used to show a company's assets, liabilities and equity at a particular date?","options":["The balance sheet","The cash flow forecast","The invoice","The audit trail"],"answer":0,"explain":"Balance sheet cho thấy tài sản, nợ và vốn chủ tại một thời điểm. Cash flow forecast là dự báo dòng tiền tương lai, invoice là hóa đơn, audit trail là dấu vết kiểm toán.","extra":[{"en":"income statement","vi":"báo cáo kết quả kinh doanh"},
{"en":"cash flow statement","vi":"báo cáo lưu chuyển tiền tệ"},
{"en":"financial position","vi":"tình hình tài chính"}]},
{"id":"q0717","unit":3,"stem":"Which is the correct sentence?","options":["The accounts were auditing by an independent firm.","The accounts were audited by an independent firm.","The accounts were audit by an independent firm.","The accounts were auditor by an independent firm."],"answer":1,"explain":"Câu bị động cần 'were + phân từ quá khứ': were audited. Auditing, audit và auditor sai cấu trúc bị động (audit là nguyên mẫu/danh từ; auditor là danh từ chỉ người).","extra":[{"en":"independent audit","vi":"kiểm toán độc lập"},
{"en":"audited accounts","vi":"báo cáo đã kiểm toán"},
{"en":"audit firm","vi":"công ty kiểm toán"}]},
{"id":"q0718","unit":3,"stem":"Despite high sales volumes, the company's ______ margin is shrinking because the cost of raw materials has risen.","options":["audit","patent","profit","equity"],"answer":2,"explain":"Profit margin = biên lợi nhuận, thu hẹp khi chi phí nguyên liệu tăng. Audit margin, patent margin, equity margin không phải cụm collocation chuẩn.","extra":[{"en":"narrow margins","vi":"biên lợi nhuận mỏng"},
{"en":"raw materials","vi":"nguyên vật liệu"},
{"en":"squeeze","vi":"bóp chặt (biên lợi nhuận)"}]},
{"id":"q0719","unit":3,"stem":"The firm's debts to suppliers, banks and tax authorities, taken together, form its ______.","options":["receivables","inventory","goodwill","liabilities"],"answer":3,"explain":"Liabilities là tổng các khoản nợ phải trả như nợ nhà cung cấp, ngân hàng, thuế. Receivables, inventory, goodwill đều là tài sản nên ngược lại với nợ.","extra":[{"en":"total liabilities","vi":"tổng nợ phải trả"},
{"en":"creditors","vi":"chủ nợ"},
{"en":"settle liabilities","vi":"thanh toán nợ"}]},
{"id":"q0720","unit":3,"stem":"Investors criticised the company's accounts as ______ because key debts were not mentioned in the main statements.","options":["misleading","volatile","intangible","deferred"],"answer":0,"explain":"Accounts bỏ sót khoản nợ quan trọng là misleading (gây hiểu lầm). Volatile là biến động, intangible là vô hình, deferred là hoãn - không mô tả sự thiếu trung thực của báo cáo.","extra":[{"en":"disclose","vi":"công bố"},
{"en":"omission","vi":"sự bỏ sót"},
{"en":"accounting standards","vi":"chuẩn mực kế toán"}]},
{"id":"q0721","unit":3,"stem":"A company's balance sheet shows it owns a delivery fleet worth $3 million that it expects to use for ten years. Which classification is correct?","options":["Current liability","Non-current tangible asset","Intangible asset","Provision"],"answer":1,"explain":"Đội xe dùng lâu dài (10 năm) là tài sản cố định hữu hình (non-current tangible asset). Intangible là tài sản vô hình; current liability và provision là nghĩa vụ nợ, không phải tài sản.","extra":[{"en":"fleet","vi":"đội xe"},
{"en":"useful life","vi":"thời gian sử dụng hữu ích"},
{"en":"straight-line depreciation","vi":"khấu hao đường thẳng"}]},
{"id":"q0722","unit":3,"stem":"The finance director warned that the accounts could not be relied upon because they had been prepared by an unqualified clerk and never checked. Which process was missing?","options":["bootstrapping","patenting","auditing","decelerating"],"answer":2,"explain":"Auditing là quá trình kiểm tra độc lập tính chính xác và độ tin cậy của sổ sách, đúng điều còn thiếu. Bootstrapping là tự tài trợ, patenting là đăng ký sáng chế, decelerating là chậm lại.","extra":[{"en":"rely on","vi":"dựa vào, tin cậy"},
{"en":"independent check","vi":"kiểm tra độc lập"},
{"en":"sign off","vi":"phê duyệt"}]},
{"id":"q0723","unit":4,"stem":"A young software firm cannot obtain a bank loan, so it approaches private individuals who will provide capital in return for a share of future profits. These individuals are the firm's ______.","options":["financial backers","creditors","bondholders","auditors"],"answer":0,"explain":"Financial backer là người/tổ chức cung cấp vốn cho một dự án hoặc công ty để đổi lấy lợi nhuận hay cổ phần. Creditor và bondholder là chủ nợ cho vay và chỉ nhận lại lãi cùng tiền gốc, không chia sẻ lợi nhuận tương lai; auditor là kiểm toán viên, không cung cấp vốn.","extra":[{"en":"seed funding","vi":"vốn khởi nghiệp ban đầu"},
{"en":"venture capitalist","vi":"nhà đầu tư mạo hiểm"},
{"en":"angel investor","vi":"nhà đầu tư thiên thần"}]},
{"id":"q0724","unit":4,"stem":"Thousands of small savers pool their money, which a professional manager invests in a diversified portfolio of shares and bonds. This arrangement is known as a ______.","options":["joint venture","mutual fund","mortgage loan","take-over"],"answer":1,"explain":"Mutual fund (quỹ tương hỗ) gom tiền của nhiều nhà đầu tư nhỏ để một nhà quản lý đầu tư vào danh mục đa dạng. Joint venture là liên doanh giữa các công ty; mortgage loan là khoản vay thế chấp bất động sản.","extra":[{"en":"diversified portfolio","vi":"danh mục đầu tư đa dạng"},
{"en":"fund manager","vi":"nhà quản lý quỹ"},
{"en":"management fee","vi":"phí quản lý"}]},
{"id":"q0725","unit":4,"stem":"Smaller manufacturers complained that the new subsidy scheme favoured their larger rivals. They demanded a ______ so that all firms could compete on equal terms.","options":["hostile bid","default clause","level playing field","cash cow"],"answer":2,"explain":"Level playing field là môi trường cạnh tranh công bằng, nơi mọi bên có điều kiện như nhau, khớp với yêu cầu 'compete on equal terms'. Hostile bid là đề nghị thâu tóm thù địch; default clause là điều khoản về vỡ nợ, không liên quan đến sự công bằng cạnh tranh.","extra":[{"en":"fair competition","vi":"cạnh tranh công bằng"},
{"en":"barriers to entry","vi":"rào cản gia nhập thị trường"},
{"en":"state subsidy","vi":"trợ cấp nhà nước"}]},
{"id":"q0726","unit":4,"stem":"The couple borrowed a large sum to buy their home, and the bank can seize the property if they stop paying. This is a ______.","options":["derivative","hedge fund","joint venture","mortgage loan"],"answer":3,"explain":"Mortgage loan là khoản vay thế chấp, trong đó tài sản (nhà) là vật đảm bảo và ngân hàng có quyền xử lý nếu người vay không trả được. Derivative là công cụ tài chính phái sinh; hedge fund là quỹ đầu tư rủi ro, đều không phải khoản vay mua nhà.","extra":[{"en":"fixed-rate mortgage","vi":"vay thế chấp lãi suất cố định"},
{"en":"foreclose on a property","vi":"phát mãi tài sản thế chấp"},
{"en":"down payment","vi":"tiền đặt cọc trả trước"}]},
{"id":"q0727","unit":4,"stem":"When the central bank raised interest rates, the firm's variable-rate debt became more expensive. Which consequence is most likely?","options":["Its borrowing costs will rise","Its principal will fall automatically","Its bondholders will become shareholders","Its security will be cancelled"],"answer":0,"explain":"Lãi suất tăng làm chi phí vay với lãi suất thả nổi tăng, tức borrowing costs rise. Tiền gốc (principal) không tự giảm, trái chủ không tự thành cổ đông, và vật đảm bảo không bị hủy chỉ vì lãi suất thay đổi.","extra":[{"en":"variable-rate loan","vi":"khoản vay lãi suất thả nổi"},
{"en":"base rate","vi":"lãi suất cơ bản"},
{"en":"debt servicing costs","vi":"chi phí trả nợ"}]},
{"id":"q0728","unit":4,"stem":"An investor spent 200,000 on a project and earned a net gain of 30,000. The ratio of the gain to the cost, expressed as a percentage, is the ______.","options":["principal","return on investment","default rate","interest-free period"],"answer":1,"explain":"Return on investment (ROI) là tỷ suất hoàn vốn = lợi nhuận ròng chia cho chi phí đầu tư, ở đây 15%. Principal là tiền gốc; default rate là tỷ lệ vỡ nợ, không dùng để đo mức sinh lời của khoản đầu tư.","extra":[{"en":"yield on investment","vi":"lợi suất đầu tư"},
{"en":"payback period","vi":"thời gian hoàn vốn"},
{"en":"break even","vi":"hòa vốn"}]},
{"id":"q0729","unit":4,"stem":"Unlike a typical mutual fund, a ______ often uses aggressive strategies such as leverage and short selling and is open mainly to wealthy investors.","options":["savings account","bond issue","hedge fund","mortgage"],"answer":2,"explain":"Hedge fund (quỹ phòng hộ) dùng chiến lược mạo hiểm như đòn bẩy, bán khống và thường chỉ dành cho nhà đầu tư giàu có. Savings account và mortgage là sản phẩm ngân hàng thông thường; bond issue là việc phát hành trái phiếu.","extra":[{"en":"accredited investor","vi":"nhà đầu tư đủ điều kiện/chuyên nghiệp"},
{"en":"absolute return","vi":"lợi nhuận tuyệt đối"},
{"en":"high-net-worth individual","vi":"cá nhân có tài sản ròng lớn"}]},
{"id":"q0730","unit":4,"stem":"Share prices on the ______ fell sharply after the unexpected profit warning, wiping billions off the value of listed companies.","options":["labour market","mortgage market","grey market","stock market"],"answer":3,"explain":"Stock market (thị trường chứng khoán) là nơi cổ phiếu của các công ty niêm yết được giao dịch, nên giá cổ phiếu giảm xảy ra ở đó. Labour market là thị trường lao động; mortgage market là thị trường cho vay thế chấp; grey market là thị trường xám, không phù hợp.","extra":[{"en":"stock exchange","vi":"sàn giao dịch chứng khoán"},
{"en":"bull market","vi":"thị trường giá lên"},
{"en":"market capitalisation","vi":"vốn hóa thị trường"}]},
{"id":"q0731","unit":4,"stem":"The board adopted customer retention rate as the key ______ for judging the success of the loyalty programme.","options":["metric","security","derivative","principal"],"answer":0,"explain":"Metric là thước đo, chỉ số dùng để đánh giá hiệu quả, ví dụ tỷ lệ giữ chân khách hàng. Security là chứng khoán/vật bảo đảm; derivative là công cụ phái sinh; principal là tiền gốc, không dùng để đánh giá thành công.","extra":[{"en":"key performance indicator (KPI)","vi":"chỉ số đo lường hiệu quả chính"},
{"en":"benchmark","vi":"mốc chuẩn so sánh"},
{"en":"track performance","vi":"theo dõi hiệu suất"}]},
{"id":"q0732","unit":4,"stem":"The family-owned brewer took out a loan to buy back shares in order to ______ a hostile take-over bid from a larger competitor.","options":["hand over","fend off","bring about","set up"],"answer":1,"explain":"Fend off nghĩa là chống lại, ngăn chặn, thường dùng với take-over bid hay đối thủ. Hand over là giao nộp, bring about là gây ra, set up là thành lập; không có nghĩa phòng thủ trước một cuộc thâu tóm.","extra":[{"en":"hostile bid","vi":"đề nghị thâu tóm thù địch"},
{"en":"white knight","vi":"hiệp sĩ trắng (bên mua thiện chí giải cứu)"},
{"en":"poison pill","vi":"chiến lược thuốc độc chống thâu tóm"}]},
{"id":"q0733","unit":4,"stem":"Two airlines agreed to establish a separate company, jointly owned and managed, to operate flights on one new route. This is a ______.","options":["leveraged buyout","short sale","joint venture","mortgage"],"answer":2,"explain":"Joint venture là liên doanh, trong đó hai hay nhiều bên cùng góp vốn lập pháp nhân mới và chia sẻ quyền sở hữu, quản lý cho một mục tiêu cụ thể. Leveraged buyout là mua lại bằng vốn vay; short sale là bán khống.","extra":[{"en":"strategic alliance","vi":"liên minh chiến lược"},
{"en":"equity stake","vi":"phần vốn sở hữu"},
{"en":"joint venture agreement","vi":"hợp đồng liên doanh"}]},
{"id":"q0734","unit":4,"stem":"When the retailer collapsed, the supplier that was owed 400,000 for delivered goods joined a long queue of ______.","options":["shareholders","regulators","partners","creditors"],"answer":3,"explain":"Creditor là chủ nợ, bên được con nợ nợ tiền; nhà cung cấp chưa được thanh toán là chủ nợ. Shareholder là cổ đông (chủ sở hữu), regulator là cơ quan quản lý, partner là đối tác, không ai trong số đó được 'nợ tiền' theo nghĩa này.","extra":[{"en":"unsecured creditor","vi":"chủ nợ không có bảo đảm"},
{"en":"go into liquidation","vi":"đi vào thanh lý"},
{"en":"settle a debt","vi":"thanh toán dứt điểm khoản nợ"}]},
{"id":"q0735","unit":4,"stem":"As ______ for the loan, the company offered its warehouse, which the bank could sell if repayments stopped.","options":["security","leverage","legislation","metric"],"answer":0,"explain":"Security (vật bảo đảm, tài sản thế chấp) là tài sản người vay cam kết để ngân hàng xử lý khi không trả nợ. Leverage là đòn bẩy tài chính, legislation là luật, metric là thước đo; không có nghĩa là tài sản bảo đảm.","extra":[{"en":"collateral","vi":"tài sản thế chấp"},
{"en":"secured loan","vi":"khoản vay có bảo đảm"},
{"en":"pledge assets","vi":"cầm cố tài sản"}]},
{"id":"q0736","unit":4,"stem":"If the borrower fails to make the scheduled payments and breaks the terms of the loan agreement, it is said to be in ______.","options":["surplus","default","arrears of profit","credit"],"answer":1,"explain":"Default là tình trạng vỡ nợ, không trả được nợ theo cam kết hoặc vi phạm điều khoản vay. Surplus là thặng dư, credit là có số dư có/tín dụng; còn 'arrears of profit' không phải cụm chuẩn.","extra":[{"en":"default on a loan","vi":"không trả được khoản vay"},
{"en":"default risk","vi":"rủi ro vỡ nợ"},
{"en":"in arrears","vi":"nợ quá hạn"}]},
{"id":"q0737","unit":4,"stem":"Each monthly repayment consists partly of interest and partly of a reduction in the ______, the amount originally borrowed.","options":["yield","premium","principal","dividend"],"answer":2,"explain":"Principal là tiền gốc, số tiền đã vay ban đầu, mỗi kỳ trả nợ gồm lãi và phần giảm gốc. Yield là lợi suất, premium là phí bảo hiểm/phần chênh lệch, dividend là cổ tức; không phải khoản vay ban đầu.","extra":[{"en":"outstanding balance","vi":"dư nợ còn lại"},
{"en":"repayment schedule","vi":"lịch trả nợ"},
{"en":"amortisation","vi":"khấu hao/trả dần nợ gốc"}]},
{"id":"q0738","unit":4,"stem":"Following the ______ of its main rival, the pharmaceutical group gained a 40% share of the domestic market.","options":["default","derivative","legislation","acquisition"],"answer":3,"explain":"Acquisition là việc mua lại một công ty khác, giúp tập đoàn nhận thêm thị phần của đối thủ. Default là vỡ nợ, derivative là công cụ phái sinh, legislation là luật; không dẫn trực tiếp tới việc nhận thị phần như vậy.","extra":[{"en":"merger and acquisition (M&A)","vi":"sáp nhập và mua lại"},
{"en":"acquire a stake","vi":"mua một phần vốn"},
{"en":"integrate operations","vi":"hợp nhất hoạt động"}]},
{"id":"q0739","unit":4,"stem":"Anyone who owns the company's 10-year corporate bonds is a ______ and is entitled to regular interest payments.","options":["bondholder","shareholder","stakeholder","policyholder"],"answer":0,"explain":"Bondholder là người nắm giữ trái phiếu, được nhận lãi định kỳ và hoàn gốc khi đáo hạn. Shareholder nắm cổ phiếu và nhận cổ tức; stakeholder là bên liên quan; policyholder là người mua bảo hiểm.","extra":[{"en":"coupon payment","vi":"lãi coupon trái phiếu"},
{"en":"maturity date","vi":"ngày đáo hạn"},
{"en":"issue bonds","vi":"phát hành trái phiếu"}]},
{"id":"q0740","unit":4,"stem":"Before agreeing to buy the supplier, the buyer's lawyers and accountants spent six weeks investigating its contracts, debts and litigation. This investigation is called ______.","options":["market segmentation","due diligence","cross-selling","asset stripping"],"answer":1,"explain":"Due diligence là quá trình thẩm định kỹ lưỡng tài chính, pháp lý và rủi ro trước khi mua hay đầu tư. Cross-selling là bán chéo sản phẩm, asset stripping là xả tài sản của công ty bị mua; không phải việc điều tra trước thương vụ.","extra":[{"en":"conduct due diligence","vi":"tiến hành thẩm định"},
{"en":"disclosure","vi":"sự công bố thông tin"},
{"en":"warranties and indemnities","vi":"cam kết và bồi thường"}]},
{"id":"q0741","unit":4,"stem":"Some investors use a ______, such as an option or futures contract, whose value depends on the price of an underlying asset like oil or a currency.","options":["mortgage","creditor","derivative","premium"],"answer":2,"explain":"Derivative là công cụ phái sinh có giá trị phụ thuộc vào tài sản cơ sở như dầu, tiền tệ; option và futures là ví dụ. Mortgage là khoản vay thế chấp, creditor là chủ nợ, premium là phí; không có đặc điểm phụ thuộc tài sản cơ sở.","extra":[{"en":"futures contract","vi":"hợp đồng tương lai"},
{"en":"underlying asset","vi":"tài sản cơ sở"},
{"en":"hedge against risk","vi":"phòng ngừa rủi ro"}]},
{"id":"q0742","unit":4,"stem":"New ______ requires banks to hold more capital in reserve, which should reduce the risk of another financial crisis.","options":["metric","security","funding","legislation"],"answer":3,"explain":"Legislation là luật pháp, quy định do nhà nước ban hành, như yêu cầu ngân hàng giữ vốn dự trữ. Metric là thước đo, security là chứng khoán, funding là nguồn vốn; chúng không thể 'require' ngân hàng làm gì.","extra":[{"en":"capital adequacy","vi":"an toàn vốn"},
{"en":"regulatory compliance","vi":"tuân thủ quy định"},
{"en":"financial regulator","vi":"cơ quan quản lý tài chính"}]},
{"id":"q0743","unit":4,"stem":"By financing 80% of the purchase with borrowed money, the buyer increased its potential gains but also its exposure to losses. This strategy is called using ______.","options":["leverage","dividends","goodwill","collateral"],"answer":0,"explain":"Leverage (đòn bẩy) là dùng vốn vay để tăng khả năng sinh lời nhưng cũng khuếch đại rủi ro thua lỗ. Dividend là cổ tức, goodwill là lợi thế thương mại; collateral là tài sản bảo đảm chứ không phải chiến lược dùng vốn vay.","extra":[{"en":"gearing ratio","vi":"hệ số nợ trên vốn"},
{"en":"highly leveraged","vi":"vay nợ rất nhiều"},
{"en":"debt-to-equity ratio","vi":"tỷ lệ nợ trên vốn chủ sở hữu"}]},
{"id":"q0744","unit":4,"stem":"A trader borrows shares, sells them immediately and plans to buy them back later at a lower price. This practice is called ______.","options":["profit sharing","short selling","stock splitting","share buy-back"],"answer":1,"explain":"Short selling là bán khống: vay cổ phiếu để bán, hy vọng giá giảm rồi mua lại rẻ hơn để trả. Stock split là chia tách cổ phiếu, share buy-back là công ty mua lại cổ phiếu của chính mình, không liên quan đến vay để bán.","extra":[{"en":"bearish outlook","vi":"triển vọng giá giảm"},
{"en":"cover a short position","vi":"đóng vị thế bán khống"},
{"en":"speculate on price falls","vi":"đầu cơ giá giảm"}]},
{"id":"q0745","unit":4,"stem":"The board unanimously rejected the ______ offer, arguing that the price undervalued the company's long-term prospects.","options":["stock-in-trade","loan-to-value","take-over","paid-up"],"answer":2,"explain":"Take-over offer là đề nghị mua lại/thâu tóm công ty, hội đồng quản trị có thể từ chối vì giá quá thấp. Stock-in-trade là hàng tồn kho, loan-to-value là tỷ lệ vay trên giá trị tài sản, paid-up là đã thanh toán; không hợp ngữ cảnh.","extra":[{"en":"make an offer for","vi":"đưa ra đề nghị mua"},
{"en":"undervalue","vi":"định giá thấp"},
{"en":"friendly take-over","vi":"thâu tóm thiện chí"}]},
{"id":"q0746","unit":4,"stem":"Which word is closest in meaning to 'fend off' in the sentence: 'The firm managed to fend off a challenge from a larger rival'?","options":["welcome","ignore","finance","repel"],"answer":3,"explain":"Fend off nghĩa là đẩy lùi, chống lại, gần nghĩa nhất với repel. Welcome là chào đón, ignore là phớt lờ, finance là cấp vốn; không có nghĩa phòng vệ trước sự thách thức.","extra":[{"en":"ward off","vi":"ngăn chặn"},
{"en":"stave off","vi":"trì hoãn/đẩy lùi"},
{"en":"hold off a challenge","vi":"cầm cự trước thách thức"}]},
{"id":"q0747","unit":4,"stem":"Choose the correct word form: 'The ______ of the loan was delayed because the company could not provide enough security.'","options":["approval","approve","approving","approvable"],"answer":0,"explain":"Sau 'The' và trước 'of' cần một danh từ, nên dùng approval (sự phê duyệt). Approve là động từ, approving là dạng V-ing/tính từ, approvable là tính từ nên không đúng vị trí.","extra":[{"en":"loan approval","vi":"phê duyệt khoản vay"},
{"en":"credit check","vi":"kiểm tra tín dụng"},
{"en":"loan application","vi":"hồ sơ xin vay"}]},
{"id":"q0748","unit":4,"stem":"A manufacturer needs 5 million to build a new plant. Which option would NOT increase its debt?","options":["Issuing corporate bonds","Selling new shares to existing shareholders","Taking out a mortgage loan on the site","Borrowing from a syndicate of banks"],"answer":1,"explain":"Bán cổ phiếu mới là huy động vốn chủ sở hữu (equity), không tạo thêm nợ. Phát hành trái phiếu, vay thế chấp và vay hợp vốn đều là các hình thức vay nợ phải hoàn trả cả gốc lẫn lãi.","extra":[{"en":"rights issue","vi":"phát hành quyền mua cổ phiếu ưu đãi"},
{"en":"equity financing","vi":"huy động vốn chủ sở hữu"},
{"en":"debt financing","vi":"huy động vốn vay"}]},
{"id":"q0749","unit":4,"stem":"The fund's annual report says its ______ was 7.2%, which means it earned 7.2 cents of profit for every dollar invested.","options":["interest rate","level of default","return on investment","mortgage ratio"],"answer":2,"explain":"Return on investment (ROI) đo lợi nhuận thu được trên mỗi đồng vốn đầu tư, như 7,2 xu trên mỗi đô la. Interest rate là lãi suất vay, còn hai cụm còn lại không phải thước đo sinh lời cho nhà đầu tư.","extra":[{"en":"annualised return","vi":"lợi suất quy năm"},
{"en":"rate of return","vi":"tỷ suất sinh lời"},
{"en":"net of fees","vi":"sau khi trừ phí"}]},
{"id":"q0750","unit":4,"stem":"The directors insisted that the merger would create a level playing field. What does this suggest about their aim?","options":["They plan to sell the company's securities","They intend to lower interest rates","They aim to acquire a majority stake secretly","They want to remove the competitors' unfair advantages"],"answer":3,"explain":"Level playing field nghĩa là môi trường cạnh tranh công bằng, nên mục tiêu là xóa bỏ lợi thế không công bằng của đối thủ. Các đáp án còn lại nói về bán chứng khoán, lãi suất hay mua bí mật, không liên quan đến sự công bằng.","extra":[{"en":"even the odds","vi":"cân bằng cơ hội"},
{"en":"equal footing","vi":"vị thế ngang nhau"},
{"en":"anti-competitive practices","vi":"hành vi phản cạnh tranh"}]},
{"id":"q0751","unit":4,"stem":"After the credit rating agency downgraded the company, bondholders demanded a higher yield. The most likely reason is that they perceived a greater ______.","options":["default risk","brand loyalty","operating margin","tax allowance"],"answer":0,"explain":"Hạ bậc tín nhiệm làm tăng rủi ro vỡ nợ, vì thế trái chủ đòi lợi suất cao hơn để bù đắp. Brand loyalty, operating margin và tax allowance không liên quan trực tiếp đến khả năng trả nợ của công ty.","extra":[{"en":"credit rating","vi":"xếp hạng tín nhiệm"},
{"en":"risk premium","vi":"phần bù rủi ro"},
{"en":"junk bond","vi":"trái phiếu rác"}]},
{"id":"q0752","unit":4,"stem":"A pension fund is described as 'risk-averse'. Which investment is it most likely to choose?","options":["Short-selling positions","Government bonds","Highly leveraged derivatives","Early-stage start-ups"],"answer":1,"explain":"Risk-averse là ngại rủi ro, nên quỹ hưu trí ưu tiên trái phiếu chính phủ có độ an toàn cao. Bán khống, phái sinh đòn bẩy cao và start-up giai đoạn đầu đều rủi ro lớn.","extra":[{"en":"risk tolerance","vi":"mức chịu đựng rủi ro"},
{"en":"safe haven","vi":"nơi trú ẩn an toàn"},
{"en":"blue-chip shares","vi":"cổ phiếu blue-chip"}]},
{"id":"q0753","unit":4,"stem":"The entrepreneur was reluctant to give up control, so she chose to finance expansion with a bank loan rather than by bringing in new ______.","options":["creditors","mortgage brokers","financial backers who want equity","bond underwriters"],"answer":2,"explain":"Nhà đầu tư tài chính lấy cổ phần (equity backers) sẽ chia sẻ quyền kiểm soát, còn vay ngân hàng thì không. Creditor chỉ là chủ nợ không có quyền kiểm soát; môi giới thế chấp và bảo lãnh phát hành không phải bên góp vốn sở hữu.","extra":[{"en":"dilute ownership","vi":"pha loãng quyền sở hữu"},
{"en":"retain control","vi":"giữ quyền kiểm soát"},
{"en":"equity stake","vi":"tỷ lệ cổ phần"}]},
{"id":"q0754","unit":4,"stem":"The two firms agreed to ______ a new company for developing electric vehicle batteries, each contributing capital and engineers.","options":["default on","fend off","write off","set up"],"answer":3,"explain":"Set up a company nghĩa là thành lập công ty, đúng với liên doanh góp vốn và kỹ sư. Default on là không trả nợ, fend off là chống lại, write off là xóa nợ; không hợp nghĩa.","extra":[{"en":"incorporate a company","vi":"thành lập pháp nhân"},
{"en":"pool resources","vi":"góp chung nguồn lực"},
{"en":"equity split","vi":"tỷ lệ chia vốn"}]},
{"id":"q0755","unit":4,"stem":"The investor's trade lost money because the share price rose sharply after she had sold short. Which statement best explains this?","options":["She expected the price to fall","She had bought the shares as a long-term holding","She had received a dividend","She had refinanced her mortgage"],"answer":0,"explain":"Bán khống chỉ có lãi khi giá giảm; bà ấy kỳ vọng giá giảm nhưng giá lại tăng nên lỗ. Mua cổ phiếu dài hạn, nhận cổ tức hay tái cấp vốn vay không phải là bản chất của bán khống.","extra":[{"en":"short squeeze","vi":"bóp nghẹt bán khống"},
{"en":"margin call","vi":"yêu cầu bổ sung ký quỹ"},
{"en":"unlimited losses","vi":"thua lỗ không giới hạn"}]},
{"id":"q0756","unit":4,"stem":"Which of the following is a derivative?","options":["A corporate bond","An option to buy shares at a fixed price in six months","A common share","A savings deposit"],"answer":1,"explain":"Quyền chọn mua cổ phiếu ở mức giá cố định là công cụ phái sinh vì giá trị phụ thuộc vào giá cổ phiếu cơ sở. Trái phiếu, cổ phiếu thường và tiền gửi tiết kiệm là công cụ gốc, không phải phái sinh.","extra":[{"en":"call option","vi":"quyền chọn mua"},
{"en":"put option","vi":"quyền chọn bán"},
{"en":"strike price","vi":"giá thực hiện"}]},
{"id":"q0757","unit":4,"stem":"Choose the correct form: 'The central bank is expected to ______ interest rates by a quarter of a percentage point next month.'","options":["raising","raised","raise","raises"],"answer":2,"explain":"Sau 'is expected to' cần động từ nguyên mẫu nên raise là đúng. Các dạng raising, raised, raises sai ngữ pháp trong cấu trúc 'be expected to + V'.","extra":[{"en":"base rate","vi":"lãi suất cơ bản"},
{"en":"cut interest rates","vi":"hạ lãi suất"},
{"en":"monetary policy","vi":"chính sách tiền tệ"}]},
{"id":"q0758","unit":4,"stem":"Choose the best word: 'The ______ of the debt took the company almost ten years because the interest was very high.'","options":["repay","repayable","repaying of","repayment"],"answer":3,"explain":"Sau 'The' cần danh từ chỉ việc trả nợ, repayment là phù hợp, đi với 'of the debt'. Repay là động từ, repayable là tính từ, 'repaying of' sai cấu trúc.","extra":[{"en":"repayment period","vi":"thời hạn trả nợ"},
{"en":"lump-sum repayment","vi":"trả nợ một lần"},
{"en":"early repayment penalty","vi":"phí phạt trả nợ trước hạn"}]},
{"id":"q0759","unit":4,"stem":"Which word is closest in meaning to 'acquisition' in: 'The acquisition of the rival chain doubled the group's revenue'?","options":["purchase","liquidation","default","dividend"],"answer":0,"explain":"Acquisition ở đây là việc mua lại công ty khác, gần nghĩa nhất với purchase. Liquidation là thanh lý, default là vỡ nợ, dividend là cổ tức.","extra":[{"en":"takeover target","vi":"mục tiêu bị thâu tóm"},
{"en":"buy out","vi":"mua đứt"},
{"en":"absorb a competitor","vi":"thâu tóm đối thủ"}]},
{"id":"q0760","unit":4,"stem":"A borrower pledges shares as ______ for a margin loan. If their price falls too far, the lender can sell them.","options":["principal","security","yield","metric"],"answer":1,"explain":"Security/collateral là tài sản bảo đảm; nếu giá giảm quá nhiều bên cho vay có thể bán để thu hồi nợ. Principal là tiền gốc, yield là lợi suất, metric là thước đo, không phải vật bảo đảm.","extra":[{"en":"margin loan","vi":"khoản vay ký quỹ"},
{"en":"loan-to-value ratio","vi":"tỷ lệ cho vay trên giá trị tài sản"},
{"en":"liquidate a position","vi":"thanh lý vị thế"}]},
{"id":"q0761","unit":4,"stem":"The company's high ______ means that a small fall in sales could make it impossible to cover interest payments.","options":["goodwill","liquidity","gearing","turnover"],"answer":2,"explain":"Gearing (hay leverage) cao nghĩa là vay nợ nhiều so với vốn chủ, nên doanh thu giảm nhẹ cũng khó trả lãi. Goodwill là lợi thế thương mại, liquidity là tính thanh khoản, turnover là doanh thu; không nói về mức vay nợ.","extra":[{"en":"interest cover","vi":"khả năng thanh toán lãi"},
{"en":"debt burden","vi":"gánh nặng nợ"},
{"en":"overleveraged","vi":"vay nợ quá mức"}]},
{"id":"q0762","unit":4,"stem":"Which of the following would a bondholder be LEAST likely to receive?","options":["Regular interest payments","Repayment of principal at maturity","Priority over shareholders if the firm is liquidated","A vote at the annual general meeting"],"answer":3,"explain":"Trái chủ là chủ nợ nên không có quyền biểu quyết tại đại hội cổ đông; đó là quyền của cổ đông. Họ nhận lãi, hoàn gốc khi đáo hạn và được ưu tiên hơn cổ đông khi công ty thanh lý.","extra":[{"en":"voting rights","vi":"quyền biểu quyết"},
{"en":"order of priority","vi":"thứ tự ưu tiên thanh toán"},
{"en":"annual general meeting (AGM)","vi":"đại hội cổ đông thường niên"}]},
{"id":"q0763","unit":4,"stem":"The retailer resisted the take-over by arguing that the offer did not reflect its true value. Which expression is closest to 'resisted'?","options":["fended off","paid off","wrote off","bought into"],"answer":0,"explain":"Fend off là chống lại, tương đương resist trong ngữ cảnh bị thâu tóm. Pay off là trả hết nợ, write off là xóa sổ khoản nợ hay tài sản, buy into là mua cổ phần.","extra":[{"en":"reject a bid","vi":"bác bỏ đề nghị mua"},
{"en":"defend against","vi":"phòng thủ trước"},
{"en":"shareholder approval","vi":"sự chấp thuận của cổ đông"}]},
{"id":"q0764","unit":4,"stem":"A start-up's founders say they need 'patient capital'. What do they most likely want from financial backers?","options":["A mortgage loan with immediate repayment","Long-term funding without demanding quick returns","Short selling opportunities","Daily trading profits"],"answer":1,"explain":"Patient capital là vốn đầu tư dài hạn, nhà đầu tư không đòi lợi nhuận nhanh. Vay thế chấp trả ngay, bán khống và lợi nhuận giao dịch hàng ngày đều ngược với tính kiên nhẫn dài hạn.","extra":[{"en":"long-term horizon","vi":"tầm nhìn dài hạn"},
{"en":"exit strategy","vi":"chiến lược thoái vốn"},
{"en":"follow-on funding","vi":"vòng gọi vốn tiếp theo"}]},
{"id":"q0765","unit":4,"stem":"The 'cost of capital' for a company usually refers to ______.","options":["the market price of its raw materials","the tax paid on its profits","the return required by those who finance its operations","the amount spent on advertising"],"answer":2,"explain":"Chi phí vốn là mức sinh lời tối thiểu mà các bên cấp vốn (chủ nợ và cổ đông) đòi hỏi. Giá nguyên liệu, thuế lợi nhuận và chi phí quảng cáo là các loại chi phí khác.","extra":[{"en":"weighted average cost of capital","vi":"chi phí vốn bình quân gia quyền"},
{"en":"hurdle rate","vi":"tỷ suất sinh lời tối thiểu"},
{"en":"raise capital","vi":"huy động vốn"}]},
{"id":"q0766","unit":4,"stem":"Which of the following is a typical source of funding for a small business?","options":["A balance sheet","A trademark","A bottleneck","A crowdfunding campaign"],"answer":3,"explain":"Crowdfunding là một nguồn vốn (source of funding) huy động từ nhiều người nhỏ lẻ. Bảng cân đối kế toán, nhãn hiệu và nút thắt cổ chai không phải nguồn cấp vốn.","extra":[{"en":"bootstrapping","vi":"tự thân khởi nghiệp, không gọi vốn"},
{"en":"business angel","vi":"nhà đầu tư thiên thần"},
{"en":"initial public offering (IPO)","vi":"phát hành cổ phiếu lần đầu ra công chúng"}]},
{"id":"q0767","unit":4,"stem":"Choose the best word form: 'Analysts remain ______ about the fund's performance, despite strong returns last year.'","options":["sceptical","sceptic","scepticism","sceptically"],"answer":0,"explain":"Sau 'remain' cần tính từ nên sceptical (hoài nghi) là đúng. Sceptic là danh từ chỉ người, scepticism là danh từ trừu tượng, sceptically là trạng từ.","extra":[{"en":"performance fee","vi":"phí thưởng hiệu suất"},
{"en":"track record","vi":"thành tích trong quá khứ"},
{"en":"beat the market","vi":"vượt thị trường"}]},
{"id":"q0768","unit":4,"stem":"The shareholders were told that the take-over would only go ahead if the bank agreed to provide ______ of 300 million.","options":["fund","funding","funded","funds are"],"answer":1,"explain":"Sau 'provide' và trước 'of 300 million' cần danh từ, funding (nguồn vốn) là đúng. Fund và funded sai loại từ hoặc sai nghĩa, 'funds are' không đúng cấu trúc.","extra":[{"en":"bridging loan","vi":"khoản vay bắc cầu"},
{"en":"underwrite an offer","vi":"bảo lãnh phát hành"},
{"en":"committed financing","vi":"cam kết cấp vốn"}]},
{"id":"q0769","unit":4,"stem":"A trader who buys shares hoping prices will rise, rather than borrowing them to sell, is said to be taking a ______ position.","options":["short","hedged","long","neutral-debt"],"answer":2,"explain":"Long position là vị thế mua, kỳ vọng giá tăng. Short position là bán khống ngược lại; hedged là phòng hộ rủi ro; 'neutral-debt' không phải thuật ngữ chuẩn.","extra":[{"en":"go long","vi":"mua vào kỳ vọng giá tăng"},
{"en":"hedge a position","vi":"phòng hộ vị thế"},
{"en":"open a position","vi":"mở vị thế"}]},
{"id":"q0770","unit":4,"stem":"The investor said that, since returns on cash were negligible, she moved into the ______ in search of higher gains, accepting greater risk.","options":["money lender","default","principal","stock market"],"answer":3,"explain":"Chuyển sang stock market (thị trường chứng khoán) để tìm lợi nhuận cao hơn với rủi ro lớn hơn là hợp lý. Money lender là người cho vay, default là vỡ nợ, principal là tiền gốc; không thể 'move into' như một thị trường.","extra":[{"en":"equity market","vi":"thị trường cổ phiếu"},
{"en":"search for yield","vi":"tìm kiếm lợi suất"},
{"en":"cash holdings","vi":"tiền mặt nắm giữ"}]},
{"id":"q0771","unit":4,"stem":"Following the financial crisis, ______ was introduced to stop banks from trading with their own money in risky markets.","options":["legislation","leverage","acquisition","default"],"answer":0,"explain":"Legislation là luật pháp được ban hành để hạn chế ngân hàng giao dịch rủi ro bằng vốn riêng. Leverage, acquisition và default đều không phải thứ 'được ban hành' để ngăn cấm điều gì.","extra":[{"en":"proprietary trading","vi":"giao dịch tự doanh"},
{"en":"ring-fence","vi":"tách biệt, cô lập hoạt động"},
{"en":"tighten regulation","vi":"siết chặt quy định"}]},
{"id":"q0772","unit":4,"stem":"A food company wants to enter a foreign market but lacks local knowledge. It forms a partnership with a local distributor in which both parties share costs, risks and profits for a single project. This is best described as a ______.","options":["hostile take-over","joint venture","leveraged loan","sale of securities"],"answer":1,"explain":"Joint venture là liên doanh, hai bên cùng chia sẻ chi phí, rủi ro và lợi nhuận cho một dự án chung. Hostile take-over là thâu tóm thù địch, leveraged loan là khoản vay đòn bẩy, sale of securities là bán chứng khoán.","extra":[{"en":"local partner","vi":"đối tác địa phương"},
{"en":"market entry strategy","vi":"chiến lược thâm nhập thị trường"},
{"en":"share the risk","vi":"chia sẻ rủi ro"}]},
{"id":"q0773","unit":4,"stem":"A consumer who takes out a mortgage loan at a fixed rate for 25 years is protected if ______.","options":["property prices rise","the lender increases the principal","market interest rates rise","the borrower earns a higher salary"],"answer":2,"explain":"Lãi suất cố định giúp người vay không bị ảnh hưởng khi lãi suất thị trường tăng. Giá bất động sản, mức lương hay việc ngân hàng tăng gốc không liên quan đến sự bảo vệ của lãi suất cố định.","extra":[{"en":"fixed rate","vi":"lãi suất cố định"},
{"en":"tracker mortgage","vi":"vay thế chấp lãi suất bám sát lãi suất cơ bản"},
{"en":"remortgage","vi":"tái thế chấp"}]},
{"id":"q0774","unit":4,"stem":"A venture capital firm has agreed to provide 2 million in return for 25% of the company. The firm is acting as a ______.","options":["creditor","bondholder","regulator","financial backer"],"answer":3,"explain":"Quỹ đầu tư mạo hiểm góp vốn để đổi lấy 25% cổ phần là financial backer. Creditor và bondholder cho vay lấy lãi, không có cổ phần; regulator là cơ quan quản lý, không đầu tư.","extra":[{"en":"equity stake","vi":"phần vốn góp"},
{"en":"valuation","vi":"định giá doanh nghiệp"},
{"en":"term sheet","vi":"bản điều khoản đầu tư"}]},
{"id":"q0775","unit":4,"stem":"The hedge fund made a 'bearish bet' on the retailer. What did it most likely do?","options":["Sold short the retailer's shares","Bought bonds issued by the retailer","Agreed a mortgage loan to the retailer","Merged with the retailer"],"answer":0,"explain":"Bearish bet là đặt cược giá giảm, thường bằng cách bán khống cổ phiếu. Mua trái phiếu, cho vay thế chấp hay sáp nhập đều không phải cược giá giảm.","extra":[{"en":"bearish / bullish","vi":"bi quan / lạc quan về giá"},
{"en":"place a bet against","vi":"đặt cược chống lại"},
{"en":"short interest","vi":"khối lượng bán khống"}]},
{"id":"q0776","unit":4,"stem":"Investors prefer a company with a low debt-to-equity ratio because it is less exposed to ______.","options":["goodwill","default","patents","legislation"],"answer":1,"explain":"Tỷ lệ nợ trên vốn thấp nghĩa là ít vay nợ, nên ít rủi ro vỡ nợ khi lãi suất tăng hay doanh thu giảm. Goodwill, patent và legislation không liên quan trực tiếp đến tỷ lệ này.","extra":[{"en":"solvency","vi":"khả năng thanh toán nợ dài hạn"},
{"en":"financial stability","vi":"ổn định tài chính"},
{"en":"debt covenant","vi":"điều khoản ràng buộc nợ"}]},
{"id":"q0777","unit":4,"stem":"Before approving a loan, the bank asks the applicant to prove that the business can generate enough cash to meet repayments. This assessment is part of the bank's ______.","options":["cross-selling","brand audit","credit appraisal","dividend policy"],"answer":2,"explain":"Credit appraisal là thẩm định tín dụng, đánh giá khả năng trả nợ của người vay. Cross-selling là bán chéo, brand audit là kiểm tra thương hiệu, dividend policy là chính sách cổ tức; không liên quan tới việc cho vay.","extra":[{"en":"creditworthiness","vi":"mức độ tín nhiệm"},
{"en":"cash flow forecast","vi":"dự báo dòng tiền"},
{"en":"loan covenant","vi":"cam kết điều khoản vay"}]},
{"id":"q0778","unit":4,"stem":"Which of the following sentences uses 'default' as a verb correctly?","options":["The developer defaulted its loan a large profit.","The developer's default the principal is high.","The developer will default with bonds issued.","The developer defaulted on its loan after sales collapsed."],"answer":3,"explain":"Default on a loan là cấu trúc đúng, nghĩa là không trả được khoản vay. Các câu còn lại sai giới từ hoặc cấu trúc ngữ pháp.","extra":[{"en":"loan default","vi":"vỡ nợ vay"},
{"en":"sovereign default","vi":"vỡ nợ quốc gia"},
{"en":"restructure debt","vi":"tái cơ cấu nợ"}]},
{"id":"q0779","unit":4,"stem":"A company's shares are listed on the stock market. This means that ______.","options":["anyone can buy them through an exchange","they cannot be sold","only directors can trade them","they are guaranteed to rise in value"],"answer":0,"explain":"Niêm yết nghĩa là cổ phiếu được giao dịch công khai trên sàn, ai cũng có thể mua qua sàn. Không có chuyện cổ phiếu không thể bán, chỉ giám đốc được giao dịch hay đảm bảo tăng giá.","extra":[{"en":"float on the stock exchange","vi":"niêm yết lên sàn"},
{"en":"go public","vi":"đưa công ty ra công chúng"},
{"en":"delist","vi":"hủy niêm yết"}]},
{"id":"q0780","unit":4,"stem":"The firm uses revenue per employee as a ______ to measure productivity across its branches.","options":["security","metric","derivative","creditor"],"answer":1,"explain":"Metric là thước đo, chỉ số định lượng; doanh thu trên mỗi nhân viên là chỉ số năng suất. Security, derivative và creditor không phải công cụ đo lường.","extra":[{"en":"performance indicator","vi":"chỉ số hiệu suất"},
{"en":"productivity gains","vi":"mức tăng năng suất"},
{"en":"measure against targets","vi":"đo lường so với mục tiêu"}]},
{"id":"q0781","unit":4,"stem":"A founder explains that an acquisition is preferable to organic growth because it ______.","options":["avoids all legal risk","requires no financing","gives immediate access to customers and technology","eliminates the need for due diligence"],"answer":2,"explain":"Mua lại giúp có ngay khách hàng và công nghệ, nhanh hơn tăng trưởng tự thân. Nó không loại bỏ rủi ro pháp lý, thường cần vốn lớn và càng đòi hỏi due diligence.","extra":[{"en":"organic growth","vi":"tăng trưởng tự thân"},
{"en":"inorganic growth","vi":"tăng trưởng qua mua bán sáp nhập"},
{"en":"synergy","vi":"hiệu ứng cộng hưởng"}]},
{"id":"q0782","unit":4,"stem":"If a bank lends 10 million at 5% simple annual interest for one year, the interest paid on the principal is ______.","options":["50,000","5 million","10.5 million","500,000"],"answer":3,"explain":"Lãi đơn một năm = 10 triệu x 5% = 500.000. 10,5 triệu là tổng gốc cộng lãi chứ không phải lãi; 5 triệu và 50.000 tính sai tỷ lệ.","extra":[{"en":"simple vs compound interest","vi":"lãi đơn và lãi kép"},
{"en":"annual percentage rate (APR)","vi":"lãi suất năm quy đổi"},
{"en":"accrued interest","vi":"lãi tích lũy"}]},
{"id":"q0783","unit":4,"stem":"A start-up's founders ask a fund for 3 million but receive an offer of only 1.5 million in return for a larger stake. They decide to ______ the offer.","options":["turn down","take on","fall back","cut off"],"answer":0,"explain":"Turn down nghĩa là từ chối, hợp với việc không hài lòng với mức vốn thấp mà cổ phần đòi hỏi lớn. Take on là đảm nhận, fall back là lùi lại, cut off là cắt đứt; không đúng nghĩa từ chối đề nghị.","extra":[{"en":"negotiate terms","vi":"đàm phán điều khoản"},
{"en":"counter-offer","vi":"đề nghị đáp lại"},
{"en":"walk away from a deal","vi":"rút khỏi thương vụ"}]},
{"id":"q0784","unit":4,"stem":"Which is the most likely reason a company would issue bonds rather than shares?","options":["To avoid paying any interest","To raise funds without diluting existing ownership","To give investors voting rights","To reduce its debt burden immediately"],"answer":1,"explain":"Phát hành trái phiếu giúp huy động vốn mà không pha loãng cổ phần của chủ sở hữu hiện tại. Công ty vẫn phải trả lãi, trái chủ không có quyền biểu quyết và nợ tăng chứ không giảm.","extra":[{"en":"dilution","vi":"sự pha loãng cổ phần"},
{"en":"corporate bond","vi":"trái phiếu doanh nghiệp"},
{"en":"fixed interest","vi":"lãi cố định"}]},
{"id":"q0785","unit":4,"stem":"The term 'security' in finance can refer to ______.","options":["a guard protecting the bank","an insurance on business premises","a tradable financial instrument such as a share or bond","a rule that limits interest rates"],"answer":2,"explain":"Trong tài chính, security là chứng khoán, công cụ có thể giao dịch như cổ phiếu hay trái phiếu. Bảo vệ ngân hàng, bảo hiểm cơ sở và quy tắc giới hạn lãi suất là các nghĩa khác không liên quan.","extra":[{"en":"securities market","vi":"thị trường chứng khoán"},
{"en":"issue securities","vi":"phát hành chứng khoán"},
{"en":"government securities","vi":"chứng khoán chính phủ"}]},
{"id":"q0786","unit":4,"stem":"Which of the following best describes 'a hostile take-over'?","options":["A joint venture agreed by both boards","A friendly merger approved by regulators","A sale of shares to employees","An acquisition attempted against the wishes of the target's board"],"answer":3,"explain":"Hostile take-over là thâu tóm thù địch, bên mua tiến hành dù ban giám đốc mục tiêu phản đối. Liên doanh, sáp nhập thiện chí và bán cổ phiếu cho nhân viên đều có sự đồng thuận.","extra":[{"en":"tender offer","vi":"chào mua công khai"},
{"en":"proxy fight","vi":"cuộc chiến ủy quyền biểu quyết"},
{"en":"golden parachute","vi":"gói bồi thường hậu hĩnh cho lãnh đạo"}]},
{"id":"q0787","unit":4,"stem":"Choose the best word: 'The new regulation will make the market more ______ by preventing large banks from receiving special treatment.'","options":["competitive","competition","compete","competitively"],"answer":0,"explain":"Sau 'more' và trước 'by' cần tính từ nên competitive là đúng. Competition là danh từ, compete là động từ, competitively là trạng từ.","extra":[{"en":"fair competition","vi":"cạnh tranh công bằng"},
{"en":"market distortion","vi":"sự méo mó thị trường"},
{"en":"regulatory framework","vi":"khung pháp lý"}]},
{"id":"q0788","unit":4,"stem":"When a country's government cannot repay its debts to foreign creditors, it is described as being in ______.","options":["level playing field","sovereign default","mutual fund","short position"],"answer":1,"explain":"Sovereign default là quốc gia vỡ nợ, không trả được nợ cho chủ nợ nước ngoài. Level playing field, mutual fund và short position không mô tả tình trạng không trả được nợ của chính phủ.","extra":[{"en":"national debt","vi":"nợ quốc gia"},
{"en":"bail out","vi":"giải cứu tài chính"},
{"en":"debt relief","vi":"xóa/giảm nợ"}]},
{"id":"q0789","unit":4,"stem":"Which phrase means 'to use borrowed capital in order to increase potential returns'?","options":["fend off a bid","default on interest","leverage an investment","spread a portfolio"],"answer":2,"explain":"Leverage an investment là dùng vốn vay để khuếch đại lợi nhuận tiềm năng. Fend off a bid là chống lại đề nghị thâu tóm, default on interest là không trả lãi, spread a portfolio là đa dạng hóa danh mục.","extra":[{"en":"borrow to invest","vi":"vay để đầu tư"},
{"en":"amplify returns","vi":"khuếch đại lợi nhuận"},
{"en":"magnify losses","vi":"khuếch đại thua lỗ"}]},
{"id":"q0790","unit":4,"stem":"An investor owns shares in many unrelated industries so that a fall in one sector will not ruin her portfolio. She is following the principle of ______.","options":["consolidation","acquisition","capitalisation","diversification"],"answer":3,"explain":"Diversification là đa dạng hóa danh mục để giảm rủi ro khi một ngành giảm. Consolidation là hợp nhất, acquisition là mua lại, capitalisation là vốn hóa; không phải nguyên tắc phân tán rủi ro.","extra":[{"en":"asset allocation","vi":"phân bổ tài sản"},
{"en":"spread risk","vi":"phân tán rủi ro"},
{"en":"portfolio manager","vi":"quản lý danh mục"}]},
{"id":"q0791","unit":4,"stem":"The bank said it would only lend to the developer if the project were approved by planning authorities, and the loan had to be secured on the land. The word 'secured' here means ______.","options":["backed by an asset the lender can claim","protected from theft","immediately repaid","guaranteed by the government"],"answer":0,"explain":"Secured loan là khoản vay có bảo đảm bằng tài sản mà bên cho vay có quyền thu giữ khi không trả được. Không phải bảo vệ khỏi trộm cắp, trả ngay hay chính phủ bảo lãnh.","extra":[{"en":"unsecured loan","vi":"khoản vay không bảo đảm"},
{"en":"charge over assets","vi":"quyền thế chấp trên tài sản"},
{"en":"repossess","vi":"thu hồi tài sản"}]},
{"id":"q0792","unit":4,"stem":"Which of the following is a financial backer's most likely concern before investing?","options":["Whether the office has a modern logo","Whether the business can deliver a satisfactory return on investment","How many staff attend the annual party","The colour of the company's bonds"],"answer":1,"explain":"Nhà đầu tư quan tâm chính đến khả năng doanh nghiệp mang lại tỷ suất hoàn vốn thỏa đáng. Logo, tiệc nhân viên hay màu sắc trái phiếu không phải mối quan tâm tài chính chính.","extra":[{"en":"business plan","vi":"kế hoạch kinh doanh"},
{"en":"investment case","vi":"luận điểm đầu tư"},
{"en":"projected returns","vi":"lợi nhuận dự kiến"}]},
{"id":"q0793","unit":4,"stem":"A takeover by a company in the same industry that results in fewer competitors is often reviewed to prevent ______.","options":["a default","a mortgage","a monopoly","a metric"],"answer":2,"explain":"Thương vụ làm giảm số đối thủ trong ngành thường bị xem xét để ngăn độc quyền. Default, mortgage và metric không phải hệ quả của việc giảm cạnh tranh.","extra":[{"en":"competition authority","vi":"cơ quan cạnh tranh"},
{"en":"antitrust law","vi":"luật chống độc quyền"},
{"en":"market dominance","vi":"vị thế thống lĩnh thị trường"}]},
{"id":"q0794","unit":4,"stem":"The finance director warned that ______ in the lending agreement could allow the bank to demand immediate repayment if profit fell below a set level.","options":["a dividend","a derivative","a stock split","a covenant"],"answer":3,"explain":"Covenant là điều khoản ràng buộc trong hợp đồng vay, vi phạm có thể cho phép ngân hàng đòi nợ ngay. Dividend là cổ tức, derivative là công cụ phái sinh, stock split là chia tách cổ phiếu; không phải điều khoản của hợp đồng vay.","extra":[{"en":"breach a covenant","vi":"vi phạm điều khoản vay"},
{"en":"demand repayment","vi":"yêu cầu hoàn trả"},
{"en":"loan agreement","vi":"hợp đồng vay"}]},
{"id":"q0795","unit":4,"stem":"A regional bank is struggling because many of its mortgage borrowers have stopped paying. Its most urgent problem is a high rate of ______.","options":["loan defaults","dividend payments","cross-promotions","patent filings"],"answer":0,"explain":"Khi nhiều người vay thế chấp ngừng trả nợ, ngân hàng gặp tỷ lệ vỡ nợ (loan defaults) cao. Dividend payments là chi trả cổ tức, cross-promotion là khuyến mãi chéo, patent filings là nộp bằng sáng chế; không liên quan đến việc người vay không trả.","extra":[{"en":"non-performing loan","vi":"nợ xấu"},
{"en":"bad debt provision","vi":"dự phòng nợ xấu"},
{"en":"foreclosure","vi":"phát mãi tài sản thế chấp"}]},
{"id":"q0796","unit":4,"stem":"The mutual fund charges an annual fee of 1.5% of assets. This fee is deducted from ______.","options":["the bank's principal","the investors' returns","the creditor's security","the government's legislation"],"answer":1,"explain":"Phí quản lý quỹ được trừ vào lợi nhuận của nhà đầu tư, làm giảm lợi suất thực nhận. Các đáp án còn lại (gốc của ngân hàng, vật bảo đảm, luật pháp) không phải nơi phí quỹ được khấu trừ.","extra":[{"en":"expense ratio","vi":"tỷ lệ chi phí quỹ"},
{"en":"net asset value (NAV)","vi":"giá trị tài sản ròng"},
{"en":"index fund","vi":"quỹ chỉ số"}]},
{"id":"q0797","unit":4,"stem":"Which of the following is NOT a method of raising finance for business expansion?","options":["Retaining profits","Issuing shares","Writing off bad debts","Taking a bank loan"],"answer":2,"explain":"Xóa nợ xấu (write off) là xử lý kế toán, không mang lại vốn mới. Giữ lại lợi nhuận, phát hành cổ phiếu và vay ngân hàng đều là các cách huy động vốn mở rộng.","extra":[{"en":"retained earnings","vi":"lợi nhuận giữ lại"},
{"en":"bank overdraft","vi":"thấu chi ngân hàng"},
{"en":"venture capital","vi":"vốn đầu tư mạo hiểm"}]},
{"id":"q0798","unit":4,"stem":"Analysts say the shares are 'overvalued'. The most likely implication is that ______.","options":["the company has defaulted on its bonds","the dividend is too low to be paid","the firm has no creditors","the price is higher than the company's fundamentals justify"],"answer":3,"explain":"Overvalued nghĩa là giá cổ phiếu cao hơn mức nền tảng cơ bản của công ty biện minh. Điều này không nhất thiết có nghĩa là vỡ nợ, không trả cổ tức hay không có chủ nợ.","extra":[{"en":"price-to-earnings ratio","vi":"hệ số giá trên thu nhập"},
{"en":"fundamentals","vi":"các yếu tố cơ bản"},
{"en":"market bubble","vi":"bong bóng thị trường"}]},
{"id":"q0799","unit":4,"stem":"The treasurer explained that the firm would prefer a ______ loan, where the interest rate stays the same throughout the term, to make budgeting easier.","options":["fixed-rate","floating-rate","interest-only","overdraft-based"],"answer":0,"explain":"Fixed-rate loan có lãi suất không đổi suốt kỳ hạn nên dễ lập ngân sách. Floating-rate thay đổi theo thị trường, interest-only chỉ trả lãi, còn overdraft-based là thấu chi; không đảm bảo lãi suất cố định.","extra":[{"en":"floating rate","vi":"lãi suất thả nổi"},
{"en":"loan term","vi":"kỳ hạn vay"},
{"en":"hedge against rate rises","vi":"phòng ngừa lãi suất tăng"}]},
{"id":"q0800","unit":4,"stem":"What is the main purpose of due diligence before a take-over?","options":["To advertise the bid to competitors","To verify the target's real financial and legal position","To increase the target's share price","To avoid paying any tax"],"answer":1,"explain":"Due diligence nhằm xác minh tình hình tài chính và pháp lý thực tế của mục tiêu trước khi mua. Mục đích không phải quảng bá, đẩy giá hay trốn thuế.","extra":[{"en":"red flag","vi":"dấu hiệu cảnh báo"},
{"en":"hidden liabilities","vi":"nợ tiềm ẩn"},
{"en":"walk away from a deal","vi":"rút khỏi thương vụ"}]},
{"id":"q0801","unit":4,"stem":"Which of these statements about creditors and shareholders is correct?","options":["Shareholders must be repaid before creditors","Creditors own part of the company","Creditors are repaid before shareholders if a company is wound up","Shareholders always receive fixed interest"],"answer":2,"explain":"Khi công ty bị thanh lý, chủ nợ được trả trước cổ đông. Cổ đông là chủ sở hữu, nhận cổ tức biến động; chủ nợ không sở hữu công ty.","extra":[{"en":"wound up / liquidated","vi":"bị thanh lý"},
{"en":"residual claim","vi":"quyền đòi phần còn lại"},
{"en":"ordinary shares","vi":"cổ phiếu phổ thông"}]},
{"id":"q0802","unit":4,"stem":"The word 'fund' can be used as a verb. Which sentence is correct?","options":["The government will funding the research programme.","The government will funded research programme.","The government will fund of the research programme.","The government will fund the research programme."],"answer":3,"explain":"Fund là động từ nghĩa là cấp vốn, đi với tân ngữ trực tiếp: fund the research programme. Các câu khác sai dạng từ hoặc thừa giới từ.","extra":[{"en":"publicly funded","vi":"do nhà nước tài trợ"},
{"en":"underfunded","vi":"thiếu kinh phí"},
{"en":"fund-raising","vi":"gây quỹ"}]},
{"id":"q0803","unit":4,"stem":"A bank agrees to lend only if the borrower can show a strong ______, meaning the ability to generate enough cash to meet repayments.","options":["cash flow","brand image","patent","supply chain"],"answer":0,"explain":"Cash flow (dòng tiền) mạnh chứng minh khả năng trả nợ đều đặn. Brand image, patent và supply chain không trực tiếp thể hiện khả năng tạo tiền để trả nợ.","extra":[{"en":"free cash flow","vi":"dòng tiền tự do"},
{"en":"liquidity","vi":"tính thanh khoản"},
{"en":"working capital","vi":"vốn lưu động"}]},
{"id":"q0804","unit":4,"stem":"The fund manager told investors that the ______ for success would be a 12% return net of fees over three years.","options":["security","benchmark","default","creditor"],"answer":1,"explain":"Benchmark là mốc, tiêu chuẩn để đánh giá thành công, ở đây là lợi nhuận 12% sau phí. Security, default và creditor không phải mốc đánh giá.","extra":[{"en":"outperform the benchmark","vi":"vượt mốc chuẩn"},
{"en":"net of fees","vi":"sau khi trừ phí"},
{"en":"target return","vi":"lợi suất mục tiêu"}]},
{"id":"q0805","unit":4,"stem":"Which word best completes: 'The company took on too much debt and became ______ when sales dropped.'","options":["solvent","liquid","insolvent","profitable"],"answer":2,"explain":"Insolvent là mất khả năng thanh toán nợ, hợp với việc vay quá nhiều rồi doanh số giảm. Solvent, liquid và profitable đều mang nghĩa tích cực, trái ngược với tình huống.","extra":[{"en":"insolvency","vi":"sự mất khả năng thanh toán"},
{"en":"go bankrupt","vi":"phá sản"},
{"en":"administration","vi":"quản lý tài sản (thủ tục tiền phá sản)"}]},
{"id":"q0806","unit":4,"stem":"An investor sells a derivative contract to protect herself against a fall in the value of her shares. She is using it as a ______.","options":["dividend","principal","liability","hedge"],"answer":3,"explain":"Hedge là công cụ phòng ngừa rủi ro giá giảm bằng cách dùng phái sinh để bù đắp thua lỗ. Dividend là cổ tức, principal là tiền gốc, liability là nợ phải trả.","extra":[{"en":"hedge against","vi":"phòng ngừa"},
{"en":"downside protection","vi":"bảo vệ rủi ro giảm giá"},
{"en":"forward contract","vi":"hợp đồng kỳ hạn"}]},
{"id":"q0807","unit":4,"stem":"A company that has paid its debts in full, including interest, is said to have ______ the loan.","options":["repaid","defaulted","leveraged","enacted"],"answer":0,"explain":"Repay là trả hết nợ gồm cả lãi. Default là không trả được, leverage là dùng vốn vay, enact là ban hành luật.","extra":[{"en":"pay off a debt","vi":"trả hết khoản nợ"},
{"en":"clear a loan","vi":"tất toán khoản vay"},
{"en":"settle in full","vi":"thanh toán đầy đủ"}]},
{"id":"q0808","unit":4,"stem":"Which of the following is the best synonym for 'principal' in: 'The principal must be repaid in full at the end of the term'?","options":["annual interest","capital sum borrowed","tax charge","credit score"],"answer":1,"explain":"Principal ở đây là số tiền vốn gốc đã vay. Lãi hàng năm, thuế và điểm tín dụng là những khái niệm khác.","extra":[{"en":"bullet repayment","vi":"trả gốc một lần khi đáo hạn"},
{"en":"interest-only loan","vi":"khoản vay chỉ trả lãi"},
{"en":"outstanding principal","vi":"gốc còn nợ"}]},
{"id":"q0809","unit":4,"stem":"What distinguishes a mutual fund from a hedge fund?","options":["Mutual funds always use short selling","Hedge funds are only for the government","Mutual funds are generally more regulated and open to ordinary investors","Hedge funds cannot make profits"],"answer":2,"explain":"Quỹ tương hỗ chịu quản lý chặt hơn và mở cho nhà đầu tư thông thường, còn hedge fund thường dành cho nhà đầu tư giàu. Mutual fund không luôn bán khống, hedge fund không dành riêng cho chính phủ và vẫn có thể sinh lời.","extra":[{"en":"retail investor","vi":"nhà đầu tư nhỏ lẻ"},
{"en":"institutional investor","vi":"nhà đầu tư tổ chức"},
{"en":"minimum investment","vi":"mức đầu tư tối thiểu"}]},
{"id":"q0810","unit":4,"stem":"The finance minister announced that new ______ would limit the interest that lenders can charge on short-term consumer loans.","options":["leverage","acquisitions","bondholders","legislation"],"answer":3,"explain":"Legislation là luật pháp giới hạn lãi suất cho vay. Leverage, acquisition và bondholder không phải thứ có thể 'giới hạn' lãi suất theo nghĩa quy định.","extra":[{"en":"interest rate cap","vi":"trần lãi suất"},
{"en":"payday loan","vi":"khoản vay ngắn hạn lãi cao"},
{"en":"consumer protection","vi":"bảo vệ người tiêu dùng"}]},
{"id":"q0811","unit":4,"stem":"Which of the following is the best example of 'fending off' a take-over?","options":["Buying back shares and seeking a friendly investor","Selling more shares to the bidder","Announcing a merger with the bidder","Cancelling the annual report"],"answer":0,"explain":"Mua lại cổ phiếu và tìm nhà đầu tư thân thiện là cách chống thâu tóm. Bán thêm cổ phiếu cho bên mua hay sáp nhập với họ là tạo điều kiện cho thâu tóm; hủy báo cáo thường niên không giúp ích.","extra":[{"en":"white knight","vi":"hiệp sĩ trắng"},
{"en":"share buy-back","vi":"mua lại cổ phiếu quỹ"},
{"en":"defence strategy","vi":"chiến lược phòng thủ"}]},
{"id":"q0812","unit":4,"stem":"A retailer announces plans to buy several smaller chains in order to expand quickly. The sentence 'The company is on an acquisition spree' means it ______.","options":["is selling off its stores","is buying many businesses in a short period","is facing a legal investigation","is renegotiating its loans"],"answer":1,"explain":"Acquisition spree là đợt mua lại hàng loạt công ty trong thời gian ngắn. Không có nghĩa bán cửa hàng, bị điều tra hay đàm phán lại các khoản vay.","extra":[{"en":"buying spree","vi":"đợt mua sắm ồ ạt"},
{"en":"roll up smaller rivals","vi":"gom các đối thủ nhỏ"},
{"en":"integration costs","vi":"chi phí hợp nhất"}]},
{"id":"q0813","unit":4,"stem":"Investors are considering a joint venture in a new market. Which is a typical advantage?","options":["Complete control over the project","No need for any legal agreement","Shared costs and local expertise","Immediate guaranteed profits"],"answer":2,"explain":"Liên doanh cho phép chia sẻ chi phí và tận dụng chuyên môn địa phương. Bạn không có toàn quyền kiểm soát, vẫn cần hợp đồng pháp lý và không có lợi nhuận được bảo đảm.","extra":[{"en":"shared control","vi":"đồng kiểm soát"},
{"en":"local know-how","vi":"kinh nghiệm địa phương"},
{"en":"exit clause","vi":"điều khoản thoái vốn"}]},
{"id":"q0814","unit":4,"stem":"What does it mean if a company 'services its debt'?","options":["It sells its debt to the public","It cancels its debt unilaterally","It increases its dividends","It makes the regular interest and principal payments"],"answer":3,"explain":"Service a debt là thực hiện thanh toán lãi và gốc theo định kỳ. Không phải bán nợ ra công chúng, hủy nợ đơn phương hay tăng cổ tức.","extra":[{"en":"debt servicing","vi":"trả nợ định kỳ"},
{"en":"refinance debt","vi":"tái tài trợ nợ"},
{"en":"debt maturity","vi":"kỳ đáo hạn nợ"}]},
{"id":"q0815","unit":4,"stem":"An analyst praises a firm for having 'a strong balance sheet and low leverage'. What can be inferred?","options":["It depends little on borrowed money","It has no shareholders","It has no assets","It is in default"],"answer":0,"explain":"Low leverage nghĩa là công ty phụ thuộc ít vào vốn vay, tài chính vững. Không suy ra được là không có cổ đông, không tài sản hay đang vỡ nợ.","extra":[{"en":"financial resilience","vi":"khả năng chống chịu tài chính"},
{"en":"debt-free","vi":"không nợ"},
{"en":"capital structure","vi":"cơ cấu vốn"}]},
{"id":"q0816","unit":4,"stem":"Choose the correct word form: 'Several ______ have lent the company money, and they expect repayment on time.'","options":["credits","creditors","creditable","crediting"],"answer":1,"explain":"Sau 'Several' cần danh từ số nhiều chỉ người; creditors là chủ nợ cho vay. Credits là các khoản tín dụng, creditable là tính từ (đáng khen), crediting là V-ing; không đúng nghĩa/ngữ pháp.","extra":[{"en":"debtor","vi":"con nợ"},
{"en":"extend credit","vi":"cấp tín dụng"},
{"en":"credit terms","vi":"điều khoản tín dụng"}]},
{"id":"q0817","unit":4,"stem":"A bank considers whether an applicant can afford repayments at higher interest rates. This is called a ______ test.","options":["bonus","patent","stress","promotion"],"answer":2,"explain":"Stress test là kiểm tra khả năng chịu đựng trong các kịch bản bất lợi như lãi suất tăng. Bonus, patent và promotion không phải bài kiểm tra tài chính.","extra":[{"en":"affordability check","vi":"kiểm tra khả năng chi trả"},
{"en":"worst-case scenario","vi":"kịch bản xấu nhất"},
{"en":"capital buffer","vi":"đệm vốn"}]},
{"id":"q0818","unit":5,"stem":"A member of parliament who holds no ministerial post and sits in the rows of seats behind the front benches is known as a ______.","options":["backbencher","protagonist","lobbyist","commissioner"],"answer":0,"explain":"Backbencher là nghị sĩ không giữ chức vụ trong chính phủ hoặc ban lãnh đạo phe đối lập, ngồi ở hàng ghế sau. Protagonist là người đi đầu ủng hộ một chủ trương; lobbyist là người vận động hành lang bên ngoài quốc hội.","extra":[{"en":"backbench revolt","vi":"cuộc nổi dậy của các nghị sĩ hàng ghế sau"},
{"en":"front bench","vi":"hàng ghế đầu (lãnh đạo)"},
{"en":"member of parliament","vi":"nghị sĩ"}]},
{"id":"q0819","unit":5,"stem":"After weeks of public criticism, the minister completely reversed her earlier position on the fuel levy. Commentators called it a political ______.","options":["cash cow","backflip","threshold","coalition"],"answer":1,"explain":"Backflip là việc đảo ngược hoàn toàn lập trường đã công bố trước đó. Cash cow là mảng kinh doanh sinh lời đều; threshold là ngưỡng; coalition là liên minh, đều không diễn tả việc đổi ý.","extra":[{"en":"do a backflip on","vi":"đảo ngược lập trường về"},
{"en":"U-turn","vi":"sự quay ngoắt chính sách"},
{"en":"policy reversal","vi":"sự đảo ngược chính sách"}]},
{"id":"q0820","unit":5,"stem":"Because neither party won an outright majority, the two agreed to form a ______ government.","options":["backbench","protagonist","coalition","commission"],"answer":2,"explain":"Coalition government là chính phủ liên minh do nhiều đảng lập nên khi không đảng nào chiếm đa số. Commission là ủy ban điều tra; backbench và protagonist không đi với government theo nghĩa này.","extra":[{"en":"coalition partner","vi":"đối tác trong liên minh"},
{"en":"minority government","vi":"chính phủ thiểu số"},
{"en":"hung parliament","vi":"quốc hội không đảng nào chiếm đa số"}]},
{"id":"q0821","unit":5,"stem":"The government has decided to ______ a levy on industrial emissions above the agreed limit.","options":["dump","enact","compromise","impose"],"answer":3,"explain":"Impose a levy/tax/ban nghĩa là áp đặt một khoản thuế hay lệnh cấm lên ai đó. Enact dùng cho đạo luật (enact legislation), không đi trực tiếp với levy; dump là xả/đổ bỏ; compromise là thỏa hiệp.","extra":[{"en":"impose sanctions","vi":"áp đặt trừng phạt"},
{"en":"levy a fine","vi":"phạt tiền"},
{"en":"impose restrictions on","vi":"áp đặt hạn chế đối với"}]},
{"id":"q0822","unit":5,"stem":"Parliament ______ the Clean Air Act last year, turning the proposal into law.","options":["enacted","impacted","addressed","dumped"],"answer":0,"explain":"Enact nghĩa là ban hành, thông qua thành luật, thường đi với law/legislation/act. Impacted là tác động; addressed là giải quyết/phát biểu trước; dumped là vứt bỏ.","extra":[{"en":"enact legislation","vi":"ban hành luật"},
{"en":"come into force","vi":"có hiệu lực"},
{"en":"pass a bill","vi":"thông qua dự luật"}]},
{"id":"q0823","unit":5,"stem":"A product or business unit that earns steady profits with little new investment, helping to fund other ventures, is called a ______.","options":["protagonist","cash cow","backpacker","threshold"],"answer":1,"explain":"Cash cow là mảng/sản phẩm đã trưởng thành, mang lại dòng tiền ổn định mà cần ít vốn đầu tư thêm. Threshold là ngưỡng; protagonist là người ủng hộ chính; backpacker là khách du lịch bụi.","extra":[{"en":"milk a cash cow","vi":"vắt kiệt một mảng sinh lời"},
{"en":"market leader","vi":"doanh nghiệp dẫn đầu thị trường"},
{"en":"steady cash flow","vi":"dòng tiền ổn định"}]},
{"id":"q0824","unit":5,"stem":"The airline hopes that higher ticket sales will allow it to ______ the cost of its new fleet within three years.","options":["impose","backtrack","recoup","lobby"],"answer":2,"explain":"Recoup nghĩa là thu hồi lại khoản tiền đã bỏ ra hoặc bị mất. Impose là áp đặt, backtrack là rút lại lời nói, lobby là vận động hành lang, không hợp với chi phí đầu tư.","extra":[{"en":"recoup losses","vi":"bù lại khoản lỗ"},
{"en":"recover costs","vi":"thu hồi chi phí"},
{"en":"break even","vi":"hòa vốn"}]},
{"id":"q0825","unit":5,"stem":"The company planted thousands of trees in order to ______ its carbon emissions.","options":["recoup","impose","dump","offset"],"answer":3,"explain":"Offset nghĩa là bù đắp/cân bằng một tác động xấu bằng một tác động tốt (carbon offset). Recoup là thu hồi tiền; impose là áp đặt; dump là xả thải.","extra":[{"en":"carbon offset","vi":"bù trừ carbon"},
{"en":"offset losses against profits","vi":"bù lỗ vào lợi nhuận"},
{"en":"net-zero emissions","vi":"phát thải ròng bằng không"}]},
{"id":"q0826","unit":5,"stem":"Employees were ______ to learn that the plant would close, despite earlier assurances from management.","options":["dismayed","eligible","blatant","opposed"],"answer":0,"explain":"Dismayed nghĩa là thất vọng, bàng hoàng, thường đi với 'to learn/hear'. Eligible là đủ điều kiện; blatant là trắng trợn (không dùng cho người); opposed cần 'to + danh từ'.","extra":[{"en":"dismayed at the news","vi":"bàng hoàng trước tin tức"},
{"en":"to one's dismay","vi":"trước sự thất vọng của ai"},
{"en":"plant closure","vi":"việc đóng cửa nhà máy"}]},
{"id":"q0827","unit":5,"stem":"Staff become ______ for the company pension scheme once they have completed two years of service.","options":["suitable","eligible","acceptable","reasonable"],"answer":1,"explain":"Eligible for nghĩa là đủ điều kiện/tiêu chuẩn để được hưởng. Suitable for chỉ sự phù hợp về tính chất, không nói về điều kiện được hưởng quyền lợi; acceptable và reasonable không đi với 'for' theo nghĩa này.","extra":[{"en":"eligible for a grant","vi":"đủ điều kiện nhận trợ cấp"},
{"en":"eligibility criteria","vi":"tiêu chí đủ điều kiện"},
{"en":"entitlement","vi":"quyền được hưởng"}]},
{"id":"q0828","unit":5,"stem":"In Australia, employers must pay a percentage of each worker's salary into a ______ fund to provide income after retirement.","options":["commission","consumer","superannuation","carbon"],"answer":2,"explain":"Superannuation là quỹ hưu trí bắt buộc do chủ lao động đóng cho người lao động (Úc). Commission là hoa hồng; consumer và carbon không tạo thành cụm 'fund' mang nghĩa hưu trí.","extra":[{"en":"pension fund","vi":"quỹ hưu trí"},
{"en":"retirement savings","vi":"tiền tiết kiệm hưu trí"},
{"en":"employer contribution","vi":"khoản đóng góp của chủ lao động"}]},
{"id":"q0829","unit":5,"stem":"The CEO refused to ______ that merger talks were already under way, even when journalists pressed her.","options":["make up","give ground","bundle into","let on"],"answer":3,"explain":"Let on (that) nghĩa là để lộ, tiết lộ điều bí mật. Make up là bịa/trang điểm/hòa giải; give ground là nhượng bộ; bundle into là gộp vào.","extra":[{"en":"keep something under wraps","vi":"giữ kín điều gì"},
{"en":"leak information","vi":"làm rò rỉ thông tin"},
{"en":"go public","vi":"công bố công khai"}]},
{"id":"q0830","unit":5,"stem":"Under pressure from the unions, management finally ______ on overtime pay by accepting part of their demands.","options":["gave ground","let on","dumped","enacted"],"answer":0,"explain":"Give ground nghĩa là nhượng bộ một phần trong tranh chấp/đàm phán. Let on là tiết lộ; dump là vứt/xả; enact là ban hành luật.","extra":[{"en":"stand one's ground","vi":"giữ vững lập trường"},
{"en":"meet someone halfway","vi":"nhượng bộ nhau một nửa"},
{"en":"concede a point","vi":"nhượng một điểm"}]},
{"id":"q0831","unit":5,"stem":"The ______ to the new tax was led mainly by small business owners.","options":["opposed","opposition","oppositely","oppose"],"answer":1,"explain":"Sau 'the' cần danh từ: opposition (to) nghĩa là sự phản đối. Opposed là tính từ/quá khứ phân từ; oppose là động từ; oppositely là trạng từ.","extra":[{"en":"be opposed to","vi":"phản đối"},
{"en":"vocal opposition","vi":"sự phản đối ầm ĩ"},
{"en":"face opposition","vi":"vấp phải sự phản đối"}]},
{"id":"q0832","unit":5,"stem":"The government set up an independent ______ to investigate how the water contract had been awarded.","options":["threshold","protagonist","commission","coalition"],"answer":2,"explain":"Commission là ủy ban được lập ra để điều tra hoặc nghiên cứu một vấn đề (royal commission). Coalition là liên minh chính trị; threshold là ngưỡng; protagonist là người ủng hộ chính.","extra":[{"en":"commission of inquiry","vi":"ủy ban điều tra"},
{"en":"set up a commission","vi":"thành lập ủy ban"},
{"en":"report back to","vi":"báo cáo lại cho"}]},
{"id":"q0833","unit":5,"stem":"Strong growth in exports helped to ______ for the fall in domestic consumer spending.","options":["backtrack","give ground","dump","make up"],"answer":3,"explain":"Make up for nghĩa là bù đắp cho sự thiếu hụt. Backtrack là rút lại lời nói; give ground là nhượng bộ; dump là vứt bỏ, đều không đi với 'for' theo nghĩa bù đắp.","extra":[{"en":"make up for lost time","vi":"bù lại thời gian đã mất"},
{"en":"make up the shortfall","vi":"bù phần thiếu hụt"},
{"en":"compensate for","vi":"bù đắp cho"}]},
{"id":"q0834","unit":5,"stem":"To speed up approval, the minister ______ three separate proposals into one bill.","options":["bundled","dumped","recouped","enacted"],"answer":0,"explain":"Bundle into nghĩa là gộp nhiều thứ vào một gói duy nhất. Dumped là bỏ/xả; recouped là thu hồi; enacted là ban hành (luật, không phải 'đề xuất' đưa vào một dự luật).","extra":[{"en":"omnibus bill","vi":"dự luật gộp nhiều nội dung"},
{"en":"package deal","vi":"thỏa thuận trọn gói"},
{"en":"bundle together","vi":"gói chung lại"}]},
{"id":"q0835","unit":5,"stem":"Having promised no new taxes, the leader was accused of ______ when she announced a new levy.","options":["lobbying","backtracking","enacting","compromising"],"answer":1,"explain":"Backtrack (on a promise) là rút lại lời hứa hoặc lập trường trước đó. Lobbying là vận động chính sách; enacting là ban hành luật; compromising không diễn tả việc nuốt lời.","extra":[{"en":"backtrack on a promise","vi":"nuốt lời hứa"},
{"en":"go back on one's word","vi":"thất hứa"},
{"en":"election pledge","vi":"cam kết khi tranh cử"}]},
{"id":"q0836","unit":5,"stem":"The inspectors were shocked by the company's ______ disregard for basic safety rules.","options":["subtle","reluctant","blatant","minor"],"answer":2,"explain":"Blatant nghĩa là trắng trợn, lộ liễu, không che giấu. Subtle là tinh tế/khó nhận ra (trái nghĩa); reluctant là miễn cưỡng; minor là nhỏ nhặt, không hợp với ngữ cảnh gây sốc.","extra":[{"en":"blatant lie","vi":"lời nói dối trắng trợn"},
{"en":"flagrant breach","vi":"sự vi phạm trắng trợn"},
{"en":"blatant disregard for","vi":"sự coi thường trắng trợn đối với"}]},
{"id":"q0837","unit":5,"stem":"The auditor's reputation for ______ meant that nobody doubted her findings.","options":["threshold","legislation","commission","integrity"],"answer":3,"explain":"Integrity là sự trung thực, chính trực, có nguyên tắc đạo đức. Threshold là ngưỡng; legislation là luật; commission là hoa hồng/ủy ban, không nói về phẩm chất.","extra":[{"en":"a person of integrity","vi":"người chính trực"},
{"en":"professional integrity","vi":"đạo đức nghề nghiệp"},
{"en":"compromise one's integrity","vi":"đánh mất sự chính trực"}]},
{"id":"q0838","unit":5,"stem":"The report urges governments to ______ the problem of rising industrial emissions before it is too late.","options":["address","dump","recoup","bundle"],"answer":0,"explain":"Address a problem nghĩa là giải quyết/xử lý một vấn đề. Dump là xả bỏ; recoup là thu hồi; bundle là gộp lại, không ăn khớp với 'problem'.","extra":[{"en":"address an issue","vi":"giải quyết vấn đề"},
{"en":"tackle the problem","vi":"xử lý vấn đề"},
{"en":"take steps to","vi":"thực hiện các bước để"}]},
{"id":"q0839","unit":5,"stem":"Improved healthcare has increased average ______, which puts additional pressure on state pension systems.","options":["consumer spending","life expectancy","waste disposal","global warming"],"answer":1,"explain":"Life expectancy là tuổi thọ trung bình, tăng lên làm quỹ hưu trí phải chi trả lâu hơn. Consumer spending là chi tiêu tiêu dùng; waste disposal là xử lý rác; global warming là nóng lên toàn cầu.","extra":[{"en":"ageing population","vi":"dân số già hóa"},
{"en":"retirement age","vi":"tuổi nghỉ hưu"},
{"en":"pension liability","vi":"nghĩa vụ chi trả lương hưu"}]},
{"id":"q0840","unit":5,"stem":"Councils are facing rising costs for ______ because landfill sites are almost full.","options":["carbon credits","communications technology","waste disposal","consumer spending"],"answer":2,"explain":"Waste disposal là việc xử lý/chôn lấp rác thải; bãi chôn lấp đầy làm chi phí tăng. Carbon credits là tín chỉ carbon; communications technology là công nghệ truyền thông; consumer spending là chi tiêu.","extra":[{"en":"landfill site","vi":"bãi chôn lấp"},
{"en":"recycling rate","vi":"tỷ lệ tái chế"},
{"en":"hazardous waste","vi":"chất thải nguy hại"}]},
{"id":"q0841","unit":5,"stem":"A factory that emits less than its permitted allowance can sell the unused amount to other firms as ______.","options":["superannuation","commissions","thresholds","carbon credits"],"answer":3,"explain":"Carbon credits là tín chỉ carbon, giấy phép cho phép phát thải một lượng nhất định và có thể mua bán. Superannuation là quỹ hưu; commissions là hoa hồng; thresholds là các ngưỡng.","extra":[{"en":"emissions trading scheme","vi":"chương trình mua bán phát thải"},
{"en":"cap and trade","vi":"giới hạn và trao đổi"},
{"en":"buy carbon credits","vi":"mua tín chỉ carbon"}]},
{"id":"q0842","unit":5,"stem":"Environmental ______ campaigned for years to persuade ministers to ban the chemical.","options":["pressure groups","backbenchers","protagonists","backpackers"],"answer":0,"explain":"Pressure groups là các nhóm vận động tìm cách tác động đến chính sách của chính phủ. Backbenchers là nghị sĩ hàng ghế sau; protagonists là người ủng hộ chính; backpackers là khách du lịch bụi.","extra":[{"en":"interest group","vi":"nhóm lợi ích"},
{"en":"public campaign","vi":"chiến dịch vận động công chúng"},
{"en":"campaign for a ban","vi":"vận động cấm"}]},
{"id":"q0843","unit":5,"stem":"Fishing companies are spending heavily to ______ MPs against the proposed new quotas.","options":["compromise","lobby","impose","offset"],"answer":1,"explain":"Lobby nghĩa là vận động hành lang, tìm cách thuyết phục nhà lập pháp. Compromise là thỏa hiệp; impose là áp đặt; offset là bù trừ, không hợp với việc tác động lên nghị sĩ.","extra":[{"en":"lobby against","vi":"vận động hành lang chống lại"},
{"en":"lobbyist","vi":"người vận động hành lang"},
{"en":"industry lobby","vi":"nhóm vận động của ngành"}]},
{"id":"q0844","unit":5,"stem":"The gradual rise in the Earth's average temperature, believed to be caused by greenhouse gases, is known as ______.","options":["waste disposal","life expectancy","global warming","consumer spending"],"answer":2,"explain":"Global warming là hiện tượng nóng lên toàn cầu do khí nhà kính. Waste disposal là xử lý rác; life expectancy là tuổi thọ; consumer spending là chi tiêu tiêu dùng.","extra":[{"en":"greenhouse gas","vi":"khí nhà kính"},
{"en":"climate change","vi":"biến đổi khí hậu"},
{"en":"rising sea levels","vi":"mực nước biển dâng"}]},
{"id":"q0845","unit":5,"stem":"The rapid spread of ______ has allowed small firms to serve customers abroad without opening local branches.","options":["carbon credits","waste disposal","industrial emissions","communications technology"],"answer":3,"explain":"Communications technology là công nghệ truyền thông (internet, video call...), giúp doanh nghiệp nhỏ phục vụ khách hàng từ xa. Các lựa chọn còn lại liên quan môi trường nên không giải thích được việc phục vụ khách nước ngoài.","extra":[{"en":"video conferencing","vi":"họp trực tuyến"},
{"en":"remote working","vi":"làm việc từ xa"},
{"en":"digital platform","vi":"nền tảng số"}]},
{"id":"q0846","unit":5,"stem":"Strict limits on ______ have forced cement producers to install expensive filters.","options":["industrial emissions","consumer spending","life expectancy","pressure groups"],"answer":0,"explain":"Industrial emissions là khí thải công nghiệp; giới hạn khí thải buộc nhà máy lắp bộ lọc. Consumer spending, life expectancy, pressure groups không liên quan đến bộ lọc nhà máy.","extra":[{"en":"emission limit","vi":"giới hạn phát thải"},
{"en":"air pollution","vi":"ô nhiễm không khí"},
{"en":"comply with regulations","vi":"tuân thủ quy định"}]},
{"id":"q0847","unit":5,"stem":"Companies with annual turnover below a certain ______ are exempt from the new reporting rules.","options":["protagonist","threshold","coalition","commission"],"answer":1,"explain":"Threshold là ngưỡng, mức tối thiểu mà từ đó quy định bắt đầu áp dụng. Protagonist là người ủng hộ; coalition là liên minh; commission là hoa hồng/ủy ban, không chỉ mức số liệu.","extra":[{"en":"tax threshold","vi":"ngưỡng chịu thuế"},
{"en":"exceed the threshold","vi":"vượt ngưỡng"},
{"en":"be exempt from","vi":"được miễn"}]},
{"id":"q0848","unit":5,"stem":"Neither side got everything it wanted, but the ______ allowed the long strike to end.","options":["backflip","backdown","compromise","dumping"],"answer":2,"explain":"Compromise (danh từ) là sự thỏa hiệp khi hai bên đều nhượng bộ. Backflip và backdown chỉ một bên đảo ngược/rút lui; dumping là bán phá giá hoặc xả thải.","extra":[{"en":"reach a compromise","vi":"đạt được thỏa hiệp"},
{"en":"meet halfway","vi":"gặp nhau ở giữa"},
{"en":"settle a dispute","vi":"dàn xếp tranh chấp"}]},
{"id":"q0849","unit":5,"stem":"The retailer's ______ came after thousands of customers complained: it withdrew the price rise entirely.","options":["compromise","protagonist","threshold","backdown"],"answer":3,"explain":"Backdown là việc một bên rút lui hẳn khỏi yêu cầu/quyết định sau áp lực. Ở đây hãng rút hoàn toàn nên không phải compromise (cả hai bên nhượng bộ); protagonist và threshold không phù hợp.","extra":[{"en":"climbdown","vi":"sự nhượng bộ hoàn toàn"},
{"en":"back down","vi":"lùi bước"},
{"en":"customer backlash","vi":"phản ứng dữ dội của khách hàng"}]},
{"id":"q0850","unit":5,"stem":"The leading ______ of the carbon pricing scheme is the environment minister, who first proposed it.","options":["protagonist","backbencher","backpacker","commissioner"],"answer":0,"explain":"Protagonist ở đây là người đi đầu ủng hộ/chủ xướng một chủ trương. Backbencher là nghị sĩ không giữ chức vụ; backpacker là khách du lịch bụi; commissioner là ủy viên.","extra":[{"en":"advocate","vi":"người ủng hộ"},
{"en":"champion a cause","vi":"đi đầu bảo vệ một chủ trương"},
{"en":"key player","vi":"nhân vật chủ chốt"}]},
{"id":"q0851","unit":5,"stem":"Regulators fined the firm for illegally ______ toxic waste into the river.","options":["offsetting","dumping","enacting","recouping"],"answer":1,"explain":"Dump toxic waste nghĩa là xả/đổ chất thải độc hại bất hợp pháp. Offsetting là bù trừ; enacting là ban hành luật; recouping là thu hồi tiền.","extra":[{"en":"illegal dumping","vi":"xả thải trái phép"},
{"en":"pollute the environment","vi":"gây ô nhiễm môi trường"},
{"en":"face a heavy fine","vi":"bị phạt nặng"}]},
{"id":"q0852","unit":5,"stem":"Local steelmakers accused overseas rivals of ______, selling steel in their market at prices below the cost of production.","options":["lobbying","backtracking","dumping","bundling"],"answer":2,"explain":"Dumping trong thương mại là bán phá giá: bán hàng ở thị trường nước ngoài thấp hơn giá thành hoặc giá nội địa. Lobbying là vận động; backtracking là rút lại lời; bundling là bán gộp.","extra":[{"en":"anti-dumping duty","vi":"thuế chống bán phá giá"},
{"en":"sell below cost","vi":"bán dưới giá thành"},
{"en":"trade barrier","vi":"rào cản thương mại"}]},
{"id":"q0853","unit":5,"stem":"The government plans to ______ against excessive packaging by the end of next year.","options":["legislation","legislative","legislator","legislate"],"answer":3,"explain":"Sau 'to' cần động từ nguyên mẫu: legislate (against) nghĩa là ban hành luật chống lại. Legislation là danh từ (luật); legislative là tính từ; legislator là nhà lập pháp.","extra":[{"en":"legislate against","vi":"ra luật cấm"},
{"en":"legislative body","vi":"cơ quan lập pháp"},
{"en":"packaging waste","vi":"rác thải bao bì"}]},
{"id":"q0854","unit":5,"stem":"The ______ of the new law is expected to take place in April.","options":["enactment","enacted","enact","enactive"],"answer":0,"explain":"Sau 'the' và trước 'of' cần danh từ: enactment là việc ban hành/thông qua luật. Enacted là quá khứ/tính từ; enact là động từ; enactive không dùng đúng ngữ cảnh.","extra":[{"en":"come into effect","vi":"có hiệu lực"},
{"en":"implementation of a law","vi":"việc thi hành luật"},
{"en":"statute","vi":"đạo luật"}]},
{"id":"q0855","unit":5,"stem":"Which word is closest in meaning to 'blatant' in the sentence: 'The firm showed a blatant disregard for the rules'?","options":["hidden","flagrant","accidental","minor"],"answer":1,"explain":"Blatant đồng nghĩa với flagrant: lộ liễu, trắng trợn. Hidden là che giấu (trái nghĩa); accidental là vô tình; minor là nhỏ nhặt, đều sai.","extra":[{"en":"flagrant violation","vi":"vi phạm trắng trợn"},
{"en":"open defiance","vi":"sự thách thức công khai"},
{"en":"wilful neglect","vi":"sự bỏ bê cố ý"}]},
{"id":"q0856","unit":5,"stem":"Which word is closest in meaning to 'dismayed' in the sentence: 'Investors were dismayed by the profit warning'?","options":["delighted","indifferent","distressed","puzzled"],"answer":2,"explain":"Dismayed nghĩa là lo lắng, thất vọng, tương đương distressed/disappointed. Delighted là vui mừng (trái nghĩa); indifferent là thờ ơ; puzzled là bối rối chứ không buồn lòng.","extra":[{"en":"profit warning","vi":"cảnh báo lợi nhuận"},
{"en":"disheartened","vi":"nản lòng"},
{"en":"shocked and upset","vi":"sốc và buồn"}]},
{"id":"q0857","unit":5,"stem":"Which word is closest in meaning to 'recoup' in the sentence: 'The studio hopes to recoup its investment'?","options":["waste","borrow","invest","recover"],"answer":3,"explain":"Recoup = recover: lấy lại số tiền đã bỏ ra. Waste là lãng phí; borrow là vay; invest là đầu tư, đều không có nghĩa lấy lại.","extra":[{"en":"return on investment","vi":"tỷ suất sinh lời"},
{"en":"make good a loss","vi":"bù lại khoản lỗ"},
{"en":"payback period","vi":"thời gian hoàn vốn"}]},
{"id":"q0858","unit":5,"stem":"Which expression is closest in meaning to 'impose' in the sentence: 'The council plans to impose a congestion charge'?","options":["enforce","reject","postpone","reduce"],"answer":0,"explain":"Impose a charge nghĩa là áp đặt/buộc phải thực hiện một khoản phí hay quy định, gần với enforce. Reject là bác bỏ; postpone là hoãn; reduce là giảm.","extra":[{"en":"congestion charge","vi":"phí chống ùn tắc"},
{"en":"introduce a measure","vi":"đưa ra một biện pháp"},
{"en":"levy a tax","vi":"thu thuế"}]},
{"id":"q0859","unit":5,"stem":"Which word is closest in meaning to 'backtrack' in the sentence: 'The minister was forced to backtrack on her promise'?","options":["persevere","reverse","expand","announce"],"answer":1,"explain":"Backtrack on = rút lại, đảo ngược lập trường hoặc lời hứa, gần với reverse. Persevere là kiên trì (trái nghĩa); expand là mở rộng; announce là thông báo.","extra":[{"en":"go back on","vi":"nuốt lời"},
{"en":"reverse a decision","vi":"đảo ngược quyết định"},
{"en":"stick to one's guns","vi":"giữ vững lập trường"}]},
{"id":"q0860","unit":5,"stem":"Which of the following is the best example of a 'cash cow'?","options":["A start-up burning cash to build market share","A new product still in testing","A mature brand with a dominant market share that produces steady profits","A loss-making division awaiting sale"],"answer":2,"explain":"Cash cow là mảng đã trưởng thành, chiếm thị phần lớn, tạo lợi nhuận đều với ít đầu tư thêm. Ba lựa chọn còn lại đều là các mảng đang tiêu tiền hoặc thua lỗ.","extra":[{"en":"market share","vi":"thị phần"},
{"en":"mature market","vi":"thị trường bão hòa"},
{"en":"steady profits","vi":"lợi nhuận ổn định"}]},
{"id":"q0861","unit":5,"stem":"Which statement best explains why a self-employed person might not be eligible for a particular unemployment benefit?","options":["They do not meet the conditions that the scheme sets for claimants.","They have recouped the benefit in advance.","They have lobbied against the scheme.","They have been dismayed by the scheme."],"answer":0,"explain":"Eligible for nghĩa là thỏa các điều kiện để được hưởng; not eligible nghĩa là không đáp ứng điều kiện. Các lựa chọn còn lại dùng sai nghĩa của recoup, lobby và dismay.","extra":[{"en":"eligibility requirements","vi":"yêu cầu về điều kiện"},
{"en":"claim a benefit","vi":"xin hưởng trợ cấp"},
{"en":"means-tested","vi":"xét theo thu nhập"}]},
{"id":"q0862","unit":5,"stem":"Which expression is closest in meaning to 'made up of' in the sentence: 'The committee is made up of industry, union and government representatives'?","options":["divided into","composed of","responsible for","opposed to"],"answer":1,"explain":"Be made up of = be composed of: được cấu thành từ. Divided into nói về việc chia nhỏ; responsible for là chịu trách nhiệm; opposed to là phản đối.","extra":[{"en":"consist of","vi":"bao gồm"},
{"en":"comprise","vi":"bao gồm"},
{"en":"make-up of the board","vi":"cơ cấu hội đồng"}]},
{"id":"q0863","unit":5,"stem":"Employees knew about the layoffs but did not 'let on' to the press. Here 'let on' means ______.","options":["pretend","permit","reveal","suspect"],"answer":2,"explain":"Let on (to) là tiết lộ/để lộ điều bí mật. Pretend là giả vờ; permit là cho phép; suspect là nghi ngờ, đều không đúng nghĩa.","extra":[{"en":"spill the beans","vi":"để lộ bí mật"},
{"en":"off the record","vi":"không chính thức"},
{"en":"gag order","vi":"lệnh cấm tiết lộ"}]},
{"id":"q0864","unit":5,"stem":"In the sentence 'The CEO will address the shareholders at the annual meeting', 'address' means ______.","options":["write to","listen to","avoid","speak formally to"],"answer":3,"explain":"Address (to a group) nghĩa là phát biểu chính thức trước một nhóm người. Write to là viết thư; listen to là lắng nghe; avoid là tránh né.","extra":[{"en":"annual general meeting","vi":"đại hội cổ đông thường niên"},
{"en":"keynote speech","vi":"bài phát biểu chính"},
{"en":"address the audience","vi":"phát biểu trước khán giả"}]},
{"id":"q0865","unit":5,"stem":"A government wants to cut plastic waste without banning plastic bags outright. Which measure is a market-based approach?","options":["Charging a levy on every single-use bag","Making all plastic bags illegal","Issuing a public apology for past pollution","Opening a new landfill site"],"answer":0,"explain":"Biện pháp dựa vào thị trường dùng giá cả để thay đổi hành vi, ví dụ đánh phí (levy) lên túi dùng một lần. Cấm hoàn toàn là mệnh lệnh hành chính; xin lỗi và mở bãi rác không tạo động lực giảm rác.","extra":[{"en":"market-based instrument","vi":"công cụ dựa vào thị trường"},
{"en":"single-use plastics","vi":"đồ nhựa dùng một lần"},
{"en":"financial incentive","vi":"khuyến khích tài chính"}]},
{"id":"q0866","unit":5,"stem":"A carbon credit scheme is designed to cut pollution mainly because it ______.","options":["forces every firm to emit exactly the same amount","gives firms a financial incentive to emit less than their allowance","bans all industrial activity","reduces taxes on fuel"],"answer":1,"explain":"Hãng thải ít hơn hạn mức có thể bán phần dư thành tín chỉ, tạo động lực kinh tế để giảm phát thải. Hệ thống không bắt mọi hãng thải bằng nhau, không cấm sản xuất và không liên quan đến giảm thuế nhiên liệu.","extra":[{"en":"emissions allowance","vi":"hạn mức phát thải"},
{"en":"polluter pays principle","vi":"nguyên tắc người gây ô nhiễm phải trả tiền"},
{"en":"reduce the carbon footprint","vi":"giảm dấu chân carbon"}]},
{"id":"q0867","unit":5,"stem":"Which of the following is a likely consequence of a rise in average life expectancy?","options":["Smaller pension liabilities","Lower demand for healthcare","Greater pressure on pension schemes","A higher birth rate"],"answer":2,"explain":"Sống lâu hơn nghĩa là lương hưu phải chi trả trong thời gian dài hơn nên áp lực lên quỹ hưu trí tăng. Các lựa chọn còn lại đi ngược lại logic này.","extra":[{"en":"pension deficit","vi":"thâm hụt quỹ hưu"},
{"en":"dependency ratio","vi":"tỷ lệ phụ thuộc"},
{"en":"raise the retirement age","vi":"nâng tuổi nghỉ hưu"}]},
{"id":"q0868","unit":5,"stem":"A sharp fall in consumer spending is most likely to damage ______.","options":["a pension fund's actuary","a coal mine's regulator","a government commission","a high-street retailer"],"answer":3,"explain":"Consumer spending là chi tiêu của người tiêu dùng; khi giảm, doanh thu của nhà bán lẻ bị ảnh hưởng trực tiếp nhất. Các lựa chọn còn lại không sống bằng doanh thu bán lẻ.","extra":[{"en":"consumer confidence","vi":"niềm tin người tiêu dùng"},
{"en":"disposable income","vi":"thu nhập khả dụng"},
{"en":"retail sales","vi":"doanh số bán lẻ"}]},
{"id":"q0869","unit":5,"stem":"Which statement about a backbencher is true?","options":["They are not part of the leadership of the government or of the opposition.","They run government departments.","They chair meetings of the cabinet.","They are appointed as senior judges."],"answer":0,"explain":"Backbencher là nghị sĩ ngồi hàng ghế sau, không giữ chức vụ lãnh đạo. Điều hành bộ và chủ trì nội các là việc của bộ trưởng (front bench); thẩm phán không do nghị sĩ hàng ghế sau đảm nhiệm.","extra":[{"en":"cabinet minister","vi":"bộ trưởng nội các"},
{"en":"party whip","vi":"người điều phối kỷ luật đảng"},
{"en":"cross the floor","vi":"chuyển sang đảng khác"}]},
{"id":"q0870","unit":5,"stem":"Which of the following is a likely disadvantage of a coalition government?","options":["All decisions are made by a single leader.","Policies may have to be watered down to satisfy all partners.","Elections are no longer necessary.","All taxes are abolished."],"answer":1,"explain":"Trong liên minh, các đảng phải thỏa hiệp nên chính sách thường bị làm nhạt đi. Các lựa chọn khác mô tả chế độ độc tài hoặc những điều không xảy ra.","extra":[{"en":"water down a proposal","vi":"làm nhẹ đi một đề xuất"},
{"en":"reach a consensus","vi":"đạt đồng thuận"},
{"en":"political deadlock","vi":"bế tắc chính trị"}]},
{"id":"q0871","unit":5,"stem":"What is the main aim of a pressure group?","options":["To win a majority in parliament","To collect taxes","To influence government policy without seeking to govern","To draft laws as civil servants"],"answer":2,"explain":"Pressure group nhằm tác động đến chính sách mà không tranh cử để cầm quyền. Giành đa số là việc của đảng chính trị; thu thuế và soạn luật là chức năng của cơ quan nhà nước.","extra":[{"en":"campaign for change","vi":"vận động thay đổi"},
{"en":"raise public awareness","vi":"nâng cao nhận thức công chúng"},
{"en":"sign a petition","vi":"ký kiến nghị"}]},
{"id":"q0872","unit":5,"stem":"A mining company hires lobbyists primarily because it wants to ______.","options":["avoid paying its staff","buy shares in competitors","audit its own accounts","influence upcoming legislation in its favour"],"answer":3,"explain":"Lobbyist vận động hành lang để tác động lên các nhà làm luật theo hướng có lợi cho doanh nghiệp. Ba lựa chọn còn lại không phải việc của vận động hành lang.","extra":[{"en":"in its favour","vi":"theo hướng có lợi cho nó"},
{"en":"vested interest","vi":"lợi ích cá nhân/nhóm"},
{"en":"regulatory framework","vi":"khung pháp lý"}]},
{"id":"q0873","unit":5,"stem":"Parliament is expected to ______ the legislation before the summer recess.","options":["enlarge","enact","entrust","engage"],"answer":1,"explain":"Enact the legislation nghĩa là thông qua/ban hành đạo luật. Enlarge là mở rộng; entrust là giao phó; engage là thuê/tham gia, đều không đi với legislation.","extra":[{"en":"summer recess","vi":"kỳ nghỉ hè của quốc hội"},
{"en":"pass into law","vi":"trở thành luật"},
{"en":"repeal a law","vi":"bãi bỏ luật"}]},
{"id":"q0874","unit":5,"stem":"In the sentence 'Neither company was willing to give ground in the dispute', 'give ground' means ______.","options":["to buy land","to behave generously","to concede part of its position","to win the argument"],"answer":2,"explain":"Give ground nghĩa là nhượng bộ, lùi một phần lập trường. Nghĩa đen 'đưa đất' không đúng; generous là hào phóng; 'win' là thắng, trái với ý không chịu nhượng bộ.","extra":[{"en":"hold one's ground","vi":"giữ vững lập trường"},
{"en":"meet demands","vi":"đáp ứng yêu cầu"},
{"en":"dispute resolution","vi":"giải quyết tranh chấp"}]},
{"id":"q0875","unit":5,"stem":"Hostels in coastal towns depend heavily on ______, who travel cheaply with rucksacks.","options":["commissioners","protagonists","backbenchers","backpackers"],"answer":3,"explain":"Backpacker là khách du lịch bụi, đi với ba lô và chi tiêu tiết kiệm, thường ở hostel. Commissioners là ủy viên; protagonists là người ủng hộ; backbenchers là nghị sĩ hàng ghế sau.","extra":[{"en":"budget accommodation","vi":"chỗ ở giá rẻ"},
{"en":"tourist industry","vi":"ngành du lịch"},
{"en":"seasonal demand","vi":"nhu cầu theo mùa"}]},
{"id":"q0876","unit":5,"stem":"Which of the following best describes superannuation?","options":["Money set aside during working life to provide an income in retirement","A tax on carbon emissions","A fee charged for waste collection","A loan to help students"],"answer":0,"explain":"Superannuation là quỹ/tiền tích lũy trong thời gian làm việc để có thu nhập khi nghỉ hưu. Ba lựa chọn còn lại là thuế, phí và khoản vay, không phải quỹ hưu.","extra":[{"en":"retire on a pension","vi":"nghỉ hưu có lương hưu"},
{"en":"contribute to a fund","vi":"đóng góp vào quỹ"},
{"en":"lump sum","vi":"khoản tiền trả một lần"}]},
{"id":"q0877","unit":5,"stem":"A sales representative who earns 5% of the value of every deal she closes is paid a ______.","options":["threshold","commission","levy","coalition"],"answer":1,"explain":"Commission trong bán hàng là hoa hồng tính theo phần trăm giá trị giao dịch. Threshold là ngưỡng; levy là khoản thuế/phí nhà nước thu; coalition là liên minh.","extra":[{"en":"commission-based pay","vi":"trả lương theo hoa hồng"},
{"en":"basic salary","vi":"lương cơ bản"},
{"en":"sales target","vi":"chỉ tiêu bán hàng"}]},
{"id":"q0878","unit":5,"stem":"Which phrase best explains the meaning of 'integrity' in 'a person of integrity'?","options":["wealth and influence","fame and popularity","honesty and strong moral principles","speed and efficiency"],"answer":2,"explain":"Integrity là sự trung thực và có nguyên tắc đạo đức vững vàng. Giàu có, nổi tiếng hay nhanh nhẹn không phải là nghĩa của từ này.","extra":[{"en":"ethical standards","vi":"chuẩn mực đạo đức"},
{"en":"uphold values","vi":"giữ vững giá trị"},
{"en":"reputation for honesty","vi":"danh tiếng trung thực"}]},
{"id":"q0879","unit":5,"stem":"Several unpopular measures were 'bundled into' one budget bill. This means they were ______.","options":["separated from the budget","hidden by the opposition","cancelled by the government","combined within one package"],"answer":3,"explain":"Bundle into nghĩa là gộp nhiều mục vào một gói duy nhất để thông qua cùng lúc. Separated là tách ra, hidden là giấu, cancelled là hủy, đều trái nghĩa với 'gộp'.","extra":[{"en":"package of measures","vi":"gói biện pháp"},
{"en":"budget bill","vi":"dự luật ngân sách"},
{"en":"pass in one go","vi":"thông qua một lượt"}]},
{"id":"q0880","unit":5,"stem":"The airline offered free vouchers to 'make up for' the long delay. Here 'make up for' means ______.","options":["compensate for","account for","object to","insist on"],"answer":0,"explain":"Make up for = compensate for: bù đắp cho một điều bất tiện. Account for là giải thích/chiếm tỷ lệ; object to là phản đối; insist on là khăng khăng.","extra":[{"en":"make amends","vi":"đền bù"},
{"en":"goodwill gesture","vi":"cử chỉ thiện chí"},
{"en":"flight disruption","vi":"sự gián đoạn chuyến bay"}]},
{"id":"q0881","unit":5,"stem":"To the ______ of local farmers, the government cut the subsidy in half.","options":["dismayed","dismay","dismaying","dismayingly"],"answer":1,"explain":"'To the + danh từ + of' nên cần danh từ dismay (sự thất vọng). Dismayed là tính từ/quá khứ phân từ; dismaying là tính từ hiện tại phân từ; dismayingly là trạng từ.","extra":[{"en":"to one's surprise","vi":"trước sự ngạc nhiên của ai"},
{"en":"farm subsidy","vi":"trợ cấp nông nghiệp"},
{"en":"cut by half","vi":"cắt giảm một nửa"}]},
{"id":"q0882","unit":5,"stem":"Scientists have linked the increase in extreme weather events to ______.","options":["sales growth","price controls","global warming","brand loyalty"],"answer":2,"explain":"Global warming được nhiều nhà khoa học liên hệ với thời tiết cực đoan. Sales growth, price controls và brand loyalty là khái niệm kinh doanh, không phải nguyên nhân khí hậu.","extra":[{"en":"extreme weather","vi":"thời tiết cực đoan"},
{"en":"melting ice caps","vi":"băng tan"},
{"en":"reduce greenhouse gas emissions","vi":"giảm khí thải nhà kính"}]},
{"id":"q0883","unit":5,"stem":"Governments often face a dilemma: tougher environmental rules protect nature, but they may also ______.","options":["eliminate all pollution immediately","lower every tax rate","guarantee higher exports","raise costs for businesses and discourage investment"],"answer":3,"explain":"Quy định chặt hơn thường làm tăng chi phí tuân thủ và có thể làm nản lòng nhà đầu tư, đó là thế lưỡng nan. Các lựa chọn khác quá tuyệt đối hoặc không có cơ sở.","extra":[{"en":"compliance cost","vi":"chi phí tuân thủ"},
{"en":"regulatory burden","vi":"gánh nặng quy định"},
{"en":"strike a balance","vi":"cân bằng giữa"}]},
{"id":"q0884","unit":5,"stem":"A factory emits more than its permitted limit. Under a carbon credit scheme, it would most likely have to ______.","options":["buy additional carbon credits","sell its own shares","dump waste elsewhere","lobby for superannuation"],"answer":0,"explain":"Phát thải vượt hạn mức thì phải mua thêm tín chỉ carbon để bù phần vượt. Bán cổ phiếu, xả rác ở nơi khác hay vận động về hưu trí đều không giải quyết vấn đề hạn mức.","extra":[{"en":"exceed the limit","vi":"vượt giới hạn"},
{"en":"emissions permit","vi":"giấy phép phát thải"},
{"en":"pay a penalty","vi":"chịu phạt"}]},
{"id":"q0885","unit":5,"stem":"The ______ of hazardous waste is strictly regulated in most countries.","options":["dispose","disposal","disposable","disposed"],"answer":1,"explain":"Sau 'the' và trước 'of' cần danh từ: disposal là việc xử lý, tiêu hủy. Dispose là động từ; disposable là tính từ (dùng một lần); disposed là quá khứ.","extra":[{"en":"dispose of waste","vi":"xử lý rác thải"},
{"en":"disposable income","vi":"thu nhập khả dụng"},
{"en":"waste management","vi":"quản lý chất thải"}]},
{"id":"q0886","unit":5,"stem":"Which of the following is an example of communications technology?","options":["A coal-fired boiler","A landfill site","Video-conferencing software","A pension fund"],"answer":2,"explain":"Communications technology là công nghệ truyền thông, ví dụ phần mềm họp video. Lò hơi, bãi rác và quỹ hưu trí không phải công nghệ truyền thông.","extra":[{"en":"instant messaging","vi":"nhắn tin tức thời"},
{"en":"broadband network","vi":"mạng băng thông rộng"},
{"en":"digital communication","vi":"giao tiếp kỹ thuật số"}]},
{"id":"q0887","unit":5,"stem":"A government cuts income tax. What is the most likely effect on consumer spending?","options":["It falls sharply.","It stays exactly the same.","It becomes impossible to measure.","It tends to rise because households have more disposable income."],"answer":3,"explain":"Giảm thuế thu nhập tăng thu nhập khả dụng nên chi tiêu tiêu dùng thường tăng. Các lựa chọn khác trái logic kinh tế.","extra":[{"en":"disposable income","vi":"thu nhập khả dụng"},
{"en":"stimulate demand","vi":"kích cầu"},
{"en":"tax cut","vi":"cắt giảm thuế"}]},
{"id":"q0888","unit":5,"stem":"Which word is closest in meaning to 'protagonist' in the sentence: 'She is the leading protagonist of tougher emissions rules'?","options":["advocate","opponent","regulator","critic"],"answer":0,"explain":"Protagonist ở đây nghĩa là người đi đầu ủng hộ một chủ trương, gần với advocate. Opponent và critic là người phản đối; regulator là cơ quan quản lý.","extra":[{"en":"champion","vi":"người đi đầu bảo vệ"},
{"en":"spearhead a campaign","vi":"dẫn dắt chiến dịch"},
{"en":"supporter","vi":"người ủng hộ"}]},
{"id":"q0889","unit":5,"stem":"Which phrase describes a politician who retreats from a position after public pressure?","options":["makes a stand","backs down","moves ahead","takes over"],"answer":1,"explain":"Back down nghĩa là lùi bước, rút lại yêu cầu. Make a stand là kiên quyết giữ lập trường; move ahead là tiến lên; take over là tiếp quản.","extra":[{"en":"climb down","vi":"nhượng bộ"},
{"en":"stand firm","vi":"giữ vững lập trường"},
{"en":"yield to pressure","vi":"chịu khuất phục trước áp lực"}]},
{"id":"q0890","unit":5,"stem":"In the phrase 'tax threshold', the word 'threshold' means ______.","options":["a penalty for late payment","a refund of overpaid tax","the level at which something begins to apply","an average rate of tax"],"answer":2,"explain":"Threshold là ngưỡng, mức mà từ đó một quy định (như thuế) bắt đầu áp dụng. Penalty là tiền phạt; refund là hoàn tiền; average rate là mức bình quân.","extra":[{"en":"income threshold","vi":"ngưỡng thu nhập"},
{"en":"reach the threshold","vi":"đạt tới ngưỡng"},
{"en":"cut-off point","vi":"điểm giới hạn"}]},
{"id":"q0891","unit":5,"stem":"Which noun is most commonly used with the verb 'impose'?","options":["a profit","a hint","a bonus","a ban"],"answer":3,"explain":"Impose a ban/tax/restrictions là collocation chuẩn: áp đặt lệnh cấm. Impose a profit, a hint, a bonus không tự nhiên vì không phải điều áp đặt lên người khác.","extra":[{"en":"impose a fine","vi":"áp mức phạt"},
{"en":"lift a ban","vi":"dỡ bỏ lệnh cấm"},
{"en":"tighten restrictions","vi":"siết chặt hạn chế"}]},
{"id":"q0892","unit":5,"stem":"Retailers 'dumped' unsold winter stock at the end of the season. Here 'dumped' means ______.","options":["sold off cheaply to get rid of it","stockpiled for the future","audited carefully","insured against loss"],"answer":0,"explain":"Dump hàng nghĩa là bán tháo với giá rất rẻ để thanh lý. Stockpile là tích trữ; audit là kiểm toán; insure là mua bảo hiểm.","extra":[{"en":"clearance sale","vi":"bán thanh lý"},
{"en":"excess stock","vi":"hàng tồn dư"},
{"en":"write off stock","vi":"xóa sổ hàng tồn"}]},
{"id":"q0893","unit":5,"stem":"A ______ is a person whose job is to make laws.","options":["legislation","legislator","legislative","legislature"],"answer":1,"explain":"Legislator là nhà lập pháp, người làm luật. Legislation là luật nói chung; legislative là tính từ; legislature là cơ quan lập pháp (quốc hội), không phải một người.","extra":[{"en":"legislature","vi":"cơ quan lập pháp"},
{"en":"lawmaker","vi":"nhà làm luật"},
{"en":"legislative reform","vi":"cải cách lập pháp"}]},
{"id":"q0894","unit":5,"stem":"Workers over 60 will become ______ for early retirement benefits next year.","options":["eligibility","eligibly","eligible","eligibles"],"answer":2,"explain":"Sau 'become' cần tính từ: eligible (for) nghĩa là đủ điều kiện. Eligibility là danh từ; eligibly và eligibles không đúng ngữ pháp.","extra":[{"en":"early retirement","vi":"nghỉ hưu sớm"},
{"en":"eligibility age","vi":"độ tuổi đủ điều kiện"},
{"en":"qualify for","vi":"đủ điều kiện để"}]},
{"id":"q0895","unit":5,"stem":"In the sentence 'The government must address the problem of unemployment', 'address' is closest in meaning to ______.","options":["ignore","postpone","mention","tackle"],"answer":3,"explain":"Address a problem = tackle/deal with: giải quyết vấn đề. Ignore là phớt lờ; postpone là hoãn; mention chỉ là nhắc đến, chưa giải quyết.","extra":[{"en":"deal with an issue","vi":"xử lý một vấn đề"},
{"en":"take action on","vi":"hành động về"},
{"en":"youth unemployment","vi":"thất nghiệp thanh niên"}]},
{"id":"q0896","unit":5,"stem":"Neither side was prepared to compromise ______ the key issue of wages.","options":["on","at","by","for"],"answer":0,"explain":"Compromise on (an issue) là cụm cố định: thỏa hiệp về một vấn đề. At, by, for không đi với compromise trong nghĩa này.","extra":[{"en":"compromise on price","vi":"thỏa hiệp về giá"},
{"en":"reach a compromise with","vi":"đạt thỏa hiệp với"},
{"en":"wage dispute","vi":"tranh chấp tiền lương"}]},
{"id":"q0897","unit":5,"stem":"The inquiry questioned the ______ of the figures, suspecting they had been altered.","options":["integral","integrity","integrate","integrally"],"answer":1,"explain":"Sau 'the' và trước 'of' cần danh từ: integrity ở đây là tính toàn vẹn/đáng tin cậy của số liệu. Integral là tính từ (không thể thiếu); integrate là động từ; integrally là trạng từ.","extra":[{"en":"data integrity","vi":"tính toàn vẹn dữ liệu"},
{"en":"reliable figures","vi":"số liệu đáng tin"},
{"en":"tamper with","vi":"can thiệp làm sai lệch"}]},
{"id":"q0898","unit":5,"stem":"The firm ______ ignored the regulator's repeated warnings.","options":["blatant","blatancy","blatantly","blatants"],"answer":2,"explain":"Cần trạng từ bổ nghĩa cho động từ 'ignored': blatantly (một cách trắng trợn). Blatant là tính từ; blatancy là danh từ hiếm; blatants không tồn tại.","extra":[{"en":"blatantly obvious","vi":"rõ ràng một cách trắng trợn"},
{"en":"flout the rules","vi":"coi thường quy định"},
{"en":"repeated warnings","vi":"những cảnh báo lặp đi lặp lại"}]},
{"id":"q0899","unit":5,"stem":"'Nobody let on that the deal had collapsed.' This means that nobody ______ that the deal had collapsed.","options":["believed","forgot","asked","revealed"],"answer":3,"explain":"Let on that nghĩa là tiết lộ, để lộ. Believed là tin; forgot là quên; asked là hỏi, đều không giữ đúng nghĩa 'không ai để lộ'.","extra":[{"en":"keep quiet about","vi":"giữ im lặng về"},
{"en":"deal collapses","vi":"thỏa thuận đổ vỡ"},
{"en":"confidential","vi":"bí mật"}]},
{"id":"q0900","unit":5,"stem":"Carbon credits are criticised mainly because ______.","options":["wealthy firms can pay to keep polluting instead of cutting emissions","they ban all trade between countries","they raise average life expectancy","they reduce every company's tax bill"],"answer":0,"explain":"Chỉ trích chính là công ty giàu có thể mua tín chỉ để tiếp tục gây ô nhiễm thay vì giảm phát thải thật. Ba lựa chọn còn lại không phải lập luận của giới phê bình.","extra":[{"en":"loophole","vi":"kẽ hở"},
{"en":"greenwashing","vi":"tô vẽ hình ảnh xanh"},
{"en":"cut emissions at source","vi":"giảm phát thải tại nguồn"}]},
{"id":"q0901","unit":5,"stem":"A city raises waste disposal fees, and residents begin to recycle more. This is an example of ______.","options":["a cash cow","a price incentive","a protagonist","a threshold"],"answer":1,"explain":"Tăng phí xử lý rác khuyến khích dân tái chế, đó là khuyến khích bằng giá (price incentive). Cash cow là mảng sinh lời đều; protagonist là người ủng hộ; threshold là ngưỡng.","extra":[{"en":"recycling scheme","vi":"chương trình tái chế"},
{"en":"pay-as-you-throw","vi":"trả phí theo lượng rác"},
{"en":"change behaviour","vi":"thay đổi hành vi"}]},
{"id":"q0902","unit":5,"stem":"The average number of years a person is expected to live is called ______.","options":["consumer spending","retirement age","life expectancy","birth rate"],"answer":2,"explain":"Life expectancy là tuổi thọ kỳ vọng. Consumer spending là chi tiêu; retirement age là tuổi nghỉ hưu; birth rate là tỷ lệ sinh.","extra":[{"en":"life expectancy at birth","vi":"tuổi thọ lúc sinh"},
{"en":"population growth","vi":"tăng trưởng dân số"},
{"en":"healthcare spending","vi":"chi tiêu y tế"}]},
{"id":"q0903","unit":5,"stem":"Which action is most typical of a pressure group?","options":["Auditing a company's accounts","Issuing new shares","Setting interest rates","Organising a petition and a public campaign"],"answer":3,"explain":"Pressure group thường dùng kiến nghị và chiến dịch công khai để tạo sức ép lên chính sách. Kiểm toán, phát hành cổ phiếu và quyết định lãi suất là hoạt động tài chính, không phải của nhóm vận động.","extra":[{"en":"launch a campaign","vi":"phát động chiến dịch"},
{"en":"public pressure","vi":"sức ép dư luận"},
{"en":"grassroots movement","vi":"phong trào cơ sở"}]},
{"id":"q0904","unit":5,"stem":"A company's main cash cow is starting to decline. What is the most sensible response?","options":["Find new sources of income before profits fall further","Ignore the decline completely","Borrow heavily to pay larger dividends","Dump the product on the market immediately"],"answer":0,"explain":"Khi cash cow suy giảm, doanh nghiệp nên chủ động tìm nguồn thu mới trước khi lợi nhuận giảm thêm. Phớt lờ, vay để chia cổ tức hay bán tháo ngay đều rủi ro.","extra":[{"en":"diversify","vi":"đa dạng hóa"},
{"en":"product life cycle","vi":"vòng đời sản phẩm"},
{"en":"declining revenue","vi":"doanh thu giảm"}]},
{"id":"q0905","unit":5,"stem":"The company backtracked ______ its earlier claims about the product's safety.","options":["of","on","to","for"],"answer":1,"explain":"Backtrack on (a claim/promise) là cụm cố định: rút lại điều đã tuyên bố. Of, to, for không đi với backtrack trong nghĩa này.","extra":[{"en":"retract a statement","vi":"rút lại tuyên bố"},
{"en":"product safety","vi":"an toàn sản phẩm"},
{"en":"issue a correction","vi":"đưa ra cải chính"}]},
{"id":"q0906","unit":5,"stem":"The opposite of 'give ground' is to ______.","options":["back down","compromise","hold one's ground","backtrack"],"answer":2,"explain":"Give ground là nhượng bộ; hold one's ground là giữ vững lập trường, trái nghĩa. Back down, compromise và backtrack đều là các kiểu nhượng bộ/lùi bước.","extra":[{"en":"stand firm","vi":"đứng vững"},
{"en":"dig one's heels in","vi":"cứng đầu không nhượng bộ"},
{"en":"refuse to budge","vi":"không chịu lùi"}]},
{"id":"q0907","unit":5,"stem":"Mounting ______ pressure forced the party leader to reconsider her plan to raise fuel duty.","options":["commission","protagonist","threshold","backbench"],"answer":3,"explain":"Backbench pressure là sức ép từ các nghị sĩ hàng ghế sau trong chính đảng. Commission là ủy ban/hoa hồng; protagonist là người ủng hộ; threshold là ngưỡng, không đi với pressure theo nghĩa này.","extra":[{"en":"backbench rebellion","vi":"cuộc nổi loạn hàng ghế sau"},
{"en":"party leader","vi":"lãnh đạo đảng"},
{"en":"fuel duty","vi":"thuế nhiên liệu"}]},
{"id":"q0908","unit":5,"stem":"Investors were dismayed ______ the news of the profit warning.","options":["at","for","of","in"],"answer":0,"explain":"Dismayed at/by (news) là cách dùng chuẩn: thất vọng trước tin tức. For, of, in không đi với dismayed.","extra":[{"en":"shocked by","vi":"sốc bởi"},
{"en":"disappointed with","vi":"thất vọng với"},
{"en":"profit warning","vi":"cảnh báo lợi nhuận"}]},
{"id":"q0909","unit":5,"stem":"Which pair of terms both describe environmental concerns?","options":["superannuation and commission","industrial emissions and global warming","backbencher and coalition","cash cow and threshold"],"answer":1,"explain":"Industrial emissions (khí thải công nghiệp) và global warming (nóng lên toàn cầu) đều là vấn đề môi trường. Các cặp còn lại thuộc về hưu trí, bán hàng, chính trị hoặc kinh doanh.","extra":[{"en":"air quality","vi":"chất lượng không khí"},
{"en":"carbon footprint","vi":"dấu chân carbon"},
{"en":"environmental impact","vi":"tác động môi trường"}]},
{"id":"q0910","unit":5,"stem":"Which statement shows a government giving ground?","options":["The minister rejected every proposal from industry.","The minister doubled the carbon levy overnight.","The minister accepted a smaller carbon levy after protests from industry.","The minister refused to meet any industry leaders."],"answer":2,"explain":"Giving ground là nhượng bộ một phần; chấp nhận mức phí carbon nhỏ hơn sau phản đối là nhượng bộ. Ba lựa chọn còn lại thể hiện thái độ cứng rắn, không nhượng bộ.","extra":[{"en":"scale back","vi":"thu hẹp lại"},
{"en":"water down","vi":"làm nhẹ đi"},
{"en":"concession","vi":"sự nhượng bộ"}]},
{"id":"q0911","unit":6,"stem":"Facing falling sales, the board decided to reduce the workforce by 15% and close two underperforming branches. The company is choosing to ______.","options":["downsize","upgrade","relaunch","decentralize"],"answer":0,"explain":"Downsize nghĩa là giảm quy mô (cắt nhân sự, đóng chi nhánh) để giảm chi phí. Upgrade là nâng cấp/thăng chức, relaunch là tái phát động sản phẩm, decentralize là phân quyền - đều không liên quan đến việc cắt giảm nhân sự.","extra":[{"en":"lay off staff","vi":"sa thải nhân viên"},
{"en":"cost-cutting measures","vi":"các biện pháp cắt giảm chi phí"},
{"en":"streamline operations","vi":"tinh gọn hoạt động"}]},
{"id":"q0912","unit":6,"stem":"The government decided to ______ the energy sector, removing many of the rules that had restricted competition between suppliers.","options":["restructure","deregulate","downgrade","reassess"],"answer":1,"explain":"Deregulate là bãi bỏ/nới lỏng quy định của nhà nước đối với một ngành, tạo điều kiện cạnh tranh. Restructure là tái cơ cấu nội bộ doanh nghiệp; downgrade là hạ cấp; reassess là đánh giá lại - không có nghĩa bỏ quy định.","extra":[{"en":"red tape","vi":"thủ tục rườm rà"},
{"en":"free-market competition","vi":"cạnh tranh thị trường tự do"},
{"en":"lift restrictions","vi":"dỡ bỏ hạn chế"}]},
{"id":"q0913","unit":6,"stem":"Which of the following best defines to 'decentralize' an organization?","options":["To close regional offices and manage everything from one place","To reduce the number of products it sells","To give local units more authority to make their own decisions","To replace managers with automated systems"],"answer":2,"explain":"Decentralize là phân quyền, trao quyền ra quyết định cho các đơn vị địa phương. Đáp án 2 là mô tả của centralize (tập trung hóa) - nghĩa ngược lại. Các đáp án còn lại nói về thu hẹp sản phẩm và tự động hóa, không phải phân quyền.","extra":[{"en":"delegate authority","vi":"ủy quyền"},
{"en":"chain of command","vi":"chuỗi mệnh lệnh"},
{"en":"regional autonomy","vi":"quyền tự chủ khu vực"}]},
{"id":"q0914","unit":6,"stem":"After the merger, duplicate departments were combined and reporting lines were redrawn. This reorganization is best described as ______.","options":["relocation","exposure","turnover","restructuring"],"answer":3,"explain":"Restructuring là tái cơ cấu: thay đổi cấu trúc tổ chức, hợp nhất bộ phận, vẽ lại tuyến báo cáo. Relocation là di dời địa điểm; exposure là sự quảng bá; turnover là tỷ lệ nhân viên nghỉ việc - đều không mô tả việc tổ chức lại cơ cấu.","extra":[{"en":"reporting line","vi":"tuyến báo cáo"},
{"en":"flatten the hierarchy","vi":"làm phẳng cấp bậc quản lý"},
{"en":"organizational overhaul","vi":"cải tổ toàn diện tổ chức"}]},
{"id":"q0915","unit":6,"stem":"To cut rent costs, the firm plans to ______ its call centre from the capital to a smaller city with cheaper premises.","options":["relocate","retrain","reassess","upgrade"],"answer":0,"explain":"Relocate là di dời (địa điểm hoạt động) sang nơi khác - hợp với 'from the capital to a smaller city'. Retrain là đào tạo lại nhân viên; reassess là đánh giá lại; upgrade là nâng cấp - không diễn tả việc chuyển địa điểm.","extra":[{"en":"relocation package","vi":"gói hỗ trợ chuyển nơi làm việc"},
{"en":"head office","vi":"trụ sở chính"},
{"en":"premises","vi":"cơ sở, mặt bằng"}]},
{"id":"q0916","unit":6,"stem":"The software company decided to ______ its flagship product with a new name, redesigned interface and a fresh advertising campaign.","options":["downgrade","relaunch","deregulate","decentralize"],"answer":1,"explain":"Relaunch là tái ra mắt sản phẩm (đổi tên, thiết kế lại, quảng bá mới). Downgrade là hạ cấp; deregulate là bãi bỏ quy định; decentralize là phân quyền - không phù hợp với bối cảnh ra mắt lại sản phẩm.","extra":[{"en":"rebrand","vi":"đổi thương hiệu"},
{"en":"product lifecycle","vi":"vòng đời sản phẩm"},
{"en":"launch campaign","vi":"chiến dịch ra mắt"}]},
{"id":"q0917","unit":6,"stem":"Because the new system uses different technology, all sales staff must be ______ before the end of the month.","options":["relocated","downsized","retrained","deregulated"],"answer":2,"explain":"Retrain là đào tạo lại để nhân viên có kỹ năng dùng hệ thống mới. Relocated là bị chuyển địa điểm, downsized (về nhân sự thường dùng cho công ty, không dùng để hỏi 'staff must be ...' với nghĩa đào tạo), deregulated dùng cho ngành - không hợp nghĩa.","extra":[{"en":"upskill","vi":"nâng cao kỹ năng"},
{"en":"on-the-job training","vi":"đào tạo tại chỗ"},
{"en":"skills gap","vi":"khoảng cách kỹ năng"}]},
{"id":"q0918","unit":6,"stem":"Management agreed to ______ the project's budget after unexpected raw-material costs made the original figures unrealistic.","options":["relaunch","relocate","downgrade","reassess"],"answer":3,"explain":"Reassess là đánh giá/định mức lại cho sát thực tế khi điều kiện thay đổi. Relaunch là ra mắt lại; relocate là di dời; downgrade là hạ cấp - không có nghĩa xem xét lại ngân sách.","extra":[{"en":"revise the forecast","vi":"điều chỉnh dự báo"},
{"en":"budget review","vi":"rà soát ngân sách"},
{"en":"contingency plan","vi":"kế hoạch dự phòng"}]},
{"id":"q0919","unit":6,"stem":"The airline passenger was ______ from business class to economy because of an overbooked flight.","options":["downgraded","upgraded","updated","relocated"],"answer":0,"explain":"Downgrade là bị hạ hạng (từ business xuống economy). Upgraded là được nâng hạng - nghĩa ngược lại; updated là được cập nhật thông tin; relocated là bị chuyển địa điểm sinh sống/làm việc.","extra":[{"en":"overbooked","vi":"bị đặt vượt quá chỗ"},
{"en":"compensation","vi":"tiền đền bù"},
{"en":"fare class","vi":"hạng vé"}]},
{"id":"q0920","unit":6,"stem":"The IT department asked all employees to ______ their passwords and install the latest security patch.","options":["downsize","update","restructure","cater"],"answer":1,"explain":"Update là cập nhật (mật khẩu, phần mềm) lên phiên bản mới nhất. Downsize và restructure là thay đổi quy mô/cơ cấu tổ chức, cater là phục vụ nhu cầu - không dùng với 'passwords' và 'patch'.","extra":[{"en":"security patch","vi":"bản vá bảo mật"},
{"en":"software release","vi":"bản phát hành phần mềm"},
{"en":"roll out","vi":"triển khai"}]},
{"id":"q0921","unit":6,"stem":"Which pair correctly shows the difference between 'upgrade' and 'update'?","options":["An upgrade makes something worse; an update makes it better","An upgrade is done by staff; an update is done by customers","An upgrade replaces something with a better version; an update makes existing information or software current","An upgrade reduces cost; an update increases cost"],"answer":2,"explain":"Upgrade là nâng lên mức/ phiên bản tốt hơn (thường có thay đổi lớn), còn update là làm cho thông tin/phần mềm hiện tại trở nên mới nhất. Đáp án 2 sai vì làm tồi đi là downgrade; hai đáp án còn lại bịa ra sự phân biệt không có.","extra":[{"en":"version upgrade","vi":"nâng cấp phiên bản"},
{"en":"latest version","vi":"phiên bản mới nhất"},
{"en":"backward compatible","vi":"tương thích ngược"}]},
{"id":"q0922","unit":6,"stem":"Which word is formed by adding the prefix 'de-' and means 'to remove government controls from an industry'?","options":["decentralize","downgrade","demotivate","deregulate"],"answer":3,"explain":"Deregulate = de- (bỏ) + regulate (quy định): bỏ quy định của nhà nước. Decentralize là bỏ sự tập trung quyền lực trong tổ chức, downgrade là hạ cấp, demotivate là làm mất động lực - đều dùng 'de-' nhưng nghĩa khác.","extra":[{"en":"regulatory body","vi":"cơ quan quản lý"},
{"en":"compliance","vi":"tuân thủ"},
{"en":"liberalize","vi":"tự do hóa"}]},
{"id":"q0923","unit":6,"stem":"A manager says: 'We need to ______ our approach — what worked five years ago clearly isn't working now.' Which word best fits, meaning 'think about and judge again'?","options":["reassess","relocate","relaunch","retrain"],"answer":0,"explain":"Reassess là xem xét và đánh giá lại (phương pháp). Relocate là di dời, relaunch là ra mắt lại sản phẩm, retrain là đào tạo lại người - không hợp với 'approach'.","extra":[{"en":"re-evaluate","vi":"đánh giá lại"},
{"en":"rethink the strategy","vi":"suy nghĩ lại chiến lược"},
{"en":"course correction","vi":"điều chỉnh hướng đi"}]},
{"id":"q0924","unit":6,"stem":"The prefix 're-' in 'restructure', 'relocate' and 'relaunch' most commonly indicates ______.","options":["doing something less than before","doing something again or in a new way","removing something completely","doing something before others"],"answer":1,"explain":"Tiền tố re- nghĩa là 'lại, một lần nữa' (restructure = cấu trúc lại, relocate = chuyển lại, relaunch = ra mắt lại). Giảm bớt là 'de-/down-', loại bỏ hoàn toàn là 'un-/de-', làm trước là 'pre-'.","extra":[{"en":"revamp","vi":"đổi mới, làm mới"},
{"en":"overhaul","vi":"đại tu, cải tổ"},
{"en":"turn around","vi":"xoay chuyển tình thế"}]},
{"id":"q0925","unit":6,"stem":"A company that is 'agile' is one that ______.","options":["has a very large number of employees","always follows a fixed five-year plan","can adapt quickly to changes in the market","avoids taking any risks"],"answer":2,"explain":"Agile là linh hoạt, nhanh nhẹn, thích ứng nhanh với thay đổi của thị trường. Kế hoạch cố định 5 năm và tránh rủi ro là những đặc điểm đối lập; quy mô nhân sự lớn không liên quan đến sự linh hoạt.","extra":[{"en":"agile methodology","vi":"phương pháp phát triển linh hoạt"},
{"en":"respond to market changes","vi":"phản ứng với thay đổi thị trường"},
{"en":"time to market","vi":"thời gian đưa sản phẩm ra thị trường"}]},
{"id":"q0926","unit":6,"stem":"Large, slow-moving corporations are often less ______ than small start-ups when responding to sudden shifts in customer demand.","options":["outstanding","untapped","embedded","agile"],"answer":3,"explain":"Agile (linh hoạt, nhanh nhẹn) hợp với việc phản ứng nhanh trước thay đổi nhu cầu. Outstanding là xuất sắc/chưa thanh toán; untapped là chưa khai thác; embedded là được gắn sâu vào - không tạo thành so sánh hợp lý ở đây.","extra":[{"en":"nimble","vi":"nhanh nhạy"},
{"en":"bureaucratic","vi":"quan liêu"},
{"en":"start-up culture","vi":"văn hóa khởi nghiệp"}]},
{"id":"q0927","unit":6,"stem":"The company's decision to ______ its supply chain to environmental targets means every supplier must meet the same emissions standards.","options":["align","venture","capture","edge"],"answer":0,"explain":"Align ... to/with là điều chỉnh cho phù hợp, thống nhất với mục tiêu. Venture là mạo hiểm, capture là giành được, edge là làm viền/nhích dần - không hợp nghĩa 'điều chỉnh cho khớp với mục tiêu'.","extra":[{"en":"be aligned with","vi":"phù hợp với"},
{"en":"strategic alignment","vi":"sự thống nhất chiến lược"},
{"en":"emissions standard","vi":"tiêu chuẩn khí thải"}]},
{"id":"q0928","unit":6,"stem":"Sustainability has become so ______ in the firm's culture that it influences every purchasing decision.","options":["untapped","embedded","premium","outstanding"],"answer":1,"explain":"Embedded là gắn sâu, ăn sâu vào (văn hóa, quy trình). Untapped là chưa được khai thác; premium là cao cấp; outstanding là xuất sắc - không đi với 'in the firm's culture' để chỉ mức độ ăn sâu.","extra":[{"en":"embed values","vi":"thấm nhuần giá trị"},
{"en":"corporate culture","vi":"văn hóa doanh nghiệp"},
{"en":"deeply rooted","vi":"ăn sâu, bén rễ"}]},
{"id":"q0929","unit":6,"stem":"Foreign firms must respect the local business ______ , such as the custom of exchanging gifts before negotiations begin.","options":["turnover","clientele","norms","exposure"],"answer":2,"explain":"Norms là chuẩn mực, quy ước chung của một xã hội/ngành (ví dụ tập quán tặng quà trước đàm phán). Turnover là tỷ lệ luân chuyển, clientele là nhóm khách hàng, exposure là sự quảng bá/tiếp xúc - không nói về quy ước.","extra":[{"en":"social norms","vi":"chuẩn mực xã hội"},
{"en":"cultural sensitivity","vi":"sự nhạy cảm văn hóa"},
{"en":"business etiquette","vi":"phép tắc kinh doanh"}]},
{"id":"q0930","unit":6,"stem":"The hotel chain tries to ______ different tastes by offering vegetarian, halal and gluten-free menus in all its restaurants.","options":["edge out","venture into","align with","cater to"],"answer":3,"explain":"Cater to (cater for) là phục vụ, đáp ứng nhu cầu/khẩu vị của các nhóm khác nhau. Edge out là loại trừ dần đối thủ, venture into là mạo hiểm bước vào, align with là điều chỉnh cho khớp - không hợp với bối cảnh phục vụ nhu cầu.","extra":[{"en":"cater for","vi":"phục vụ, đáp ứng"},
{"en":"dietary requirements","vi":"yêu cầu về chế độ ăn"},
{"en":"tailor to","vi":"điều chỉnh cho phù hợp"}]},
{"id":"q0931","unit":6,"stem":"A café chain hires an experienced ______ to train staff in preparing espresso drinks consistently.","options":["barista","clientele","venture","substitute"],"answer":0,"explain":"Barista là người pha chế cà phê chuyên nghiệp. Clientele là nhóm khách hàng, venture là dự án mạo hiểm, substitute là sản phẩm/người thay thế - không phải một chức danh người pha cà phê.","extra":[{"en":"specialty coffee","vi":"cà phê đặc sản"},
{"en":"front-of-house staff","vi":"nhân viên phục vụ khu vực khách"},
{"en":"espresso machine","vi":"máy pha espresso"}]},
{"id":"q0932","unit":6,"stem":"The boutique's exclusive ______ includes wealthy professionals who are willing to pay high prices for personalised service.","options":["turnover","clientele","norms","exposure"],"answer":1,"explain":"Clientele là nhóm/tập khách hàng thường xuyên của một cửa hàng, nhà hàng, dịch vụ. Turnover là doanh thu/tỷ lệ luân chuyển, norms là chuẩn mực, exposure là sự quảng bá - không chỉ nhóm khách hàng.","extra":[{"en":"target clientele","vi":"nhóm khách hàng mục tiêu"},
{"en":"loyal customer base","vi":"tập khách hàng trung thành"},
{"en":"upmarket","vi":"cao cấp (thị trường)"}]},
{"id":"q0933","unit":6,"stem":"Which word is closest in meaning to 'outstanding' in the sentence: 'The sales team delivered an outstanding performance this quarter'?","options":["unpaid","average","exceptional","unfinished"],"answer":2,"explain":"Outstanding ở đây là xuất sắc, nổi bật, đồng nghĩa với exceptional. Lưu ý outstanding còn có nghĩa 'chưa thanh toán/chưa giải quyết' (outstanding invoice) nhưng ngữ cảnh 'performance' thì không phải; average là trung bình, trái nghĩa.","extra":[{"en":"outstanding invoice","vi":"hóa đơn chưa thanh toán"},
{"en":"outstanding balance","vi":"số dư còn nợ"},
{"en":"top performer","vi":"người có thành tích hàng đầu"}]},
{"id":"q0934","unit":6,"stem":"The accounts clerk was reminded that two ______ invoices still had to be paid before the end of the financial year.","options":["premium","untapped","embedded","outstanding"],"answer":3,"explain":"Outstanding invoices là hóa đơn chưa thanh toán. Premium là cao cấp/phí bảo hiểm, untapped là chưa khai thác, embedded là gắn vào - không dùng để chỉ hóa đơn còn nợ.","extra":[{"en":"settle an invoice","vi":"thanh toán hóa đơn"},
{"en":"overdue payment","vi":"khoản thanh toán quá hạn"},
{"en":"accounts payable","vi":"các khoản phải trả"}]},
{"id":"q0935","unit":6,"stem":"A new brand has begun to ______ out established rivals in the premium coffee market by offering a better loyalty scheme.","options":["edge","cater","relocate","downsize"],"answer":0,"explain":"Edge out là dần dần vượt lên/loại bỏ đối thủ với lợi thế nhỏ. Cater là phục vụ nhu cầu, relocate là di dời, downsize là thu nhỏ quy mô - không có nghĩa lấn át đối thủ.","extra":[{"en":"competitive edge","vi":"lợi thế cạnh tranh"},
{"en":"market leader","vi":"dẫn đầu thị trường"},
{"en":"loyalty scheme","vi":"chương trình khách hàng thân thiết"}]},
{"id":"q0936","unit":6,"stem":"Having a patented technology gives the firm a competitive ______ over its rivals.","options":["venture","edge","turnover","clientele"],"answer":1,"explain":"Competitive edge là lợi thế cạnh tranh. Venture là dự án mạo hiểm, turnover là doanh thu/tỷ lệ luân chuyển, clientele là nhóm khách - không tạo cụm collocation đúng.","extra":[{"en":"gain an edge","vi":"giành lợi thế"},
{"en":"unique selling point","vi":"điểm bán hàng độc đáo"},
{"en":"barrier to entry","vi":"rào cản gia nhập thị trường"}]},
{"id":"q0937","unit":6,"stem":"The start-up hopes to ______ 10% of the regional market within two years by undercutting its competitors' prices.","options":["cater","align","capture","relaunch"],"answer":2,"explain":"Capture (a share of the market) là giành được/chiếm lĩnh một phần thị phần. Cater là phục vụ nhu cầu, align là điều chỉnh cho khớp, relaunch là tái phát động - không đi với 'market share'.","extra":[{"en":"market share","vi":"thị phần"},
{"en":"undercut","vi":"bán rẻ hơn đối thủ"},
{"en":"gain ground","vi":"giành thêm thị phần"}]},
{"id":"q0938","unit":6,"stem":"Hot chocolate and pastries ______ each other well, so the cafe sells them together as a combined offer.","options":["compliment","substitute","capture","complement"],"answer":3,"explain":"Complement là bổ sung, bổ trợ cho nhau (sản phẩm bổ sung). 'Compliment' là lời khen - dễ nhầm do phát âm giống. Substitute là thay thế (cạnh tranh, không đi cùng); capture là giành lấy.","extra":[{"en":"complementary products","vi":"sản phẩm bổ sung"},
{"en":"bundle offer","vi":"gói ưu đãi kết hợp"},
{"en":"add-on","vi":"sản phẩm/dịch vụ bán kèm"}]},
{"id":"q0939","unit":6,"stem":"A printer and ink cartridges are examples of ______ goods, because demand for one depends on demand for the other.","options":["complementary","substitute","premium","untapped"],"answer":0,"explain":"Complementary goods là hàng hóa bổ sung, được dùng cùng nhau (máy in và mực in). Substitute goods là hàng thay thế (cạnh tranh nhau như trà và cà phê). Premium và untapped không phải thuật ngữ phân loại quan hệ cầu này.","extra":[{"en":"substitute goods","vi":"hàng thay thế"},
{"en":"cross elasticity","vi":"độ co giãn chéo"},
{"en":"demand for","vi":"nhu cầu đối với"}]},
{"id":"q0940","unit":6,"stem":"When the price of butter rose sharply, many customers bought margarine instead, which acted as a ______.","options":["complement","substitute","clientele","venture"],"answer":1,"explain":"Substitute là sản phẩm thay thế cho sản phẩm khác (bơ - bơ thực vật). Complement là sản phẩm đi kèm bổ sung, clientele là khách hàng, venture là việc kinh doanh mạo hiểm - không đúng nghĩa.","extra":[{"en":"close substitute","vi":"sản phẩm thay thế gần giống"},
{"en":"price-sensitive","vi":"nhạy cảm về giá"},
{"en":"switch to","vi":"chuyển sang"}]},
{"id":"q0941","unit":6,"stem":"The team leader asked a colleague to ______ for her at the client meeting because she was ill.","options":["complement","capture","substitute","venture"],"answer":2,"explain":"Substitute for somebody là thay thế, làm thay ai. Complement là bổ sung, capture là giành lấy, venture là mạo hiểm - đều không dùng với 'for her' theo nghĩa làm thay.","extra":[{"en":"stand in for","vi":"làm thay"},
{"en":"cover for","vi":"thay ca, làm thay"},
{"en":"a temporary replacement","vi":"người thay thế tạm thời"}]},
{"id":"q0942","unit":6,"stem":"Two firms in different industries agree to promote each other's products in their own stores and mailings. This is called ______.","options":["restructuring","deregulation","downsizing","cross-promotion"],"answer":3,"explain":"Cross-promotion là quảng cáo chéo: hai bên quảng bá sản phẩm của nhau cho khách hàng của mình. Restructuring, deregulation, downsizing là thay đổi cấu trúc/quy định/quy mô - không liên quan đến marketing.","extra":[{"en":"strategic partnership","vi":"quan hệ đối tác chiến lược"},
{"en":"co-branding","vi":"đồng thương hiệu"},
{"en":"joint campaign","vi":"chiến dịch chung"}]},
{"id":"q0943","unit":6,"stem":"A small bakery wanted maximum ______ before opening its second shop, so it gave free samples at the local market.","options":["exposure","turnover","norms","clientele"],"answer":0,"explain":"Exposure ở đây là sự xuất hiện trước công chúng/được quảng bá để nhiều người biết. Turnover là doanh thu, norms là chuẩn mực, clientele là tập khách hàng - không đồng nghĩa với 'được nhiều người biết đến'.","extra":[{"en":"media exposure","vi":"độ phủ truyền thông"},
{"en":"brand awareness","vi":"mức độ nhận biết thương hiệu"},
{"en":"free sample","vi":"hàng mẫu miễn phí"}]},
{"id":"q0944","unit":6,"stem":"Sponsoring the national football team gave the sportswear brand huge media ______ overseas.","options":["substitute","exposure","venture","norms"],"answer":1,"explain":"Media exposure là sự xuất hiện trên truyền thông, giúp thương hiệu được biết đến rộng rãi. Substitute là thay thế, venture là mạo hiểm, norms là chuẩn mực - không hợp với 'media'.","extra":[{"en":"sponsorship deal","vi":"hợp đồng tài trợ"},
{"en":"publicity","vi":"sự quảng bá"},
{"en":"raise one's profile","vi":"nâng cao danh tiếng"}]},
{"id":"q0945","unit":6,"stem":"Which word is closest in meaning to 'premium' in: 'The company sells premium chocolate at a higher price than ordinary brands'?","options":["low-cost","discounted","high-quality","unbranded"],"answer":2,"explain":"Premium là cao cấp, chất lượng cao, giá cao hơn bình thường. Low-cost, discounted và unbranded đều thể hiện giá rẻ/không thương hiệu - trái nghĩa.","extra":[{"en":"premium brand","vi":"thương hiệu cao cấp"},
{"en":"charge a premium","vi":"tính giá cao hơn"},
{"en":"upmarket","vi":"hướng đến phân khúc cao"}]},
{"id":"q0946","unit":6,"stem":"Customers are willing to pay a ______ for products that are ethically produced and beautifully packaged.","options":["turnover","substitute","clientele","premium"],"answer":3,"explain":"Pay a premium là sẵn sàng trả thêm một khoản/giá cao hơn bình thường. Turnover, substitute, clientele không đi với 'pay a ...' theo nghĩa trả giá cao hơn.","extra":[{"en":"price premium","vi":"phần giá cao hơn"},
{"en":"ethical sourcing","vi":"tìm nguồn cung có đạo đức"},
{"en":"luxury segment","vi":"phân khúc xa xỉ"}]},
{"id":"q0947","unit":6,"stem":"A high staff ______ means that employees keep leaving the company and have to be replaced, which raises recruitment and training costs.","options":["turnover","exposure","norm","premium"],"answer":0,"explain":"Staff turnover là tỷ lệ nhân viên rời công ty và được thay thế bằng người mới. Exposure là sự quảng bá, norm là chuẩn mực, premium là giá cao cấp - không chỉ tỷ lệ nghỉ việc.","extra":[{"en":"staff retention","vi":"giữ chân nhân viên"},
{"en":"recruitment costs","vi":"chi phí tuyển dụng"},
{"en":"exit interview","vi":"phỏng vấn khi nghỉ việc"}]},
{"id":"q0948","unit":6,"stem":"The HR manager is worried because annual staff turnover has risen from 8% to 25%. What does this figure measure?","options":["The total revenue earned by each employee","The proportion of employees who leave and are replaced","The number of new products launched","The percentage of staff promoted"],"answer":1,"explain":"Staff turnover đo tỷ lệ nhân viên nghỉ và được thay thế trong năm. Doanh thu theo đầu người là năng suất, số sản phẩm mới và tỷ lệ thăng chức là các chỉ số khác.","extra":[{"en":"attrition","vi":"sự hao hụt nhân sự"},
{"en":"high turnover","vi":"tỷ lệ nghỉ việc cao"},
{"en":"workforce stability","vi":"sự ổn định lực lượng lao động"}]},
{"id":"q0949","unit":6,"stem":"Market research shows that rural areas are an ______ market for online banking, since few providers have targeted them so far.","options":["outstanding","embedded","untapped","premium"],"answer":2,"explain":"Untapped market là thị trường chưa được khai thác. Outstanding là xuất sắc/chưa thanh toán, embedded là gắn sâu, premium là cao cấp - không phải 'chưa ai khai thác'.","extra":[{"en":"tap into","vi":"khai thác"},
{"en":"niche market","vi":"thị trường ngách"},
{"en":"growth potential","vi":"tiềm năng tăng trưởng"}]},
{"id":"q0950","unit":6,"stem":"The firm decided to ______ into the electric-vehicle sector, despite the high risk of losing its initial investment.","options":["cater","edge","update","venture"],"answer":3,"explain":"Venture into là mạo hiểm bước vào lĩnh vực mới. Cater (to) là phục vụ nhu cầu, edge là nhích/lấn, update là cập nhật - không diễn tả việc dấn thân vào lĩnh vực rủi ro.","extra":[{"en":"joint venture","vi":"liên doanh"},
{"en":"venture capital","vi":"vốn đầu tư mạo hiểm"},
{"en":"nothing ventured, nothing gained","vi":"không liều thì không có lợi"}]},
{"id":"q0951","unit":6,"stem":"A business ______ is a new commercial undertaking that involves risk, such as a start-up launched in an unfamiliar market.","options":["venture","turnover","clientele","exposure"],"answer":0,"explain":"Business venture là dự án kinh doanh mới có rủi ro (khởi nghiệp). Turnover, clientele, exposure là các khái niệm về doanh thu/nhân sự, khách hàng, quảng bá - không phải một dự án.","extra":[{"en":"start-up","vi":"công ty khởi nghiệp"},
{"en":"risky venture","vi":"dự án rủi ro"},
{"en":"entrepreneur","vi":"doanh nhân khởi nghiệp"}]},
{"id":"q0952","unit":6,"stem":"Which sentence uses 'cater' correctly?","options":["The agency caters the needs for small businesses of.","The agency specialises in catering to the needs of small businesses.","The agency caters out small businesses' needs.","The agency is catering from small businesses' needs."],"answer":1,"explain":"Cater to/for + noun là phục vụ, đáp ứng nhu cầu của ai. Các cấu trúc 'cater the needs for', 'cater out', 'cater from' đều sai về giới từ/trật tự từ.","extra":[{"en":"cater for","vi":"phục vụ, đáp ứng"},
{"en":"specialise in","vi":"chuyên về"},
{"en":"meet the needs of","vi":"đáp ứng nhu cầu của"}]},
{"id":"q0953","unit":6,"stem":"Which of the following is a typical consequence of deregulating a market?","options":["The government fixes all prices","Companies must report more data to regulators","More companies enter the market and competition increases","Imports are banned"],"answer":2,"explain":"Bãi bỏ quy định thường mở cửa thị trường, thu hút nhiều công ty tham gia và tăng cạnh tranh. Các đáp án còn lại (nhà nước ấn định giá, báo cáo nhiều hơn, cấm nhập khẩu) là hành động tăng cường kiểm soát.","extra":[{"en":"barriers to entry","vi":"rào cản gia nhập"},
{"en":"market liberalisation","vi":"tự do hóa thị trường"},
{"en":"price controls","vi":"kiểm soát giá"}]},
{"id":"q0954","unit":6,"stem":"Which is the best synonym for 'to restructure' in the sentence 'The bank will restructure its debt repayments'?","options":["repay","reject","relocate","reorganize"],"answer":3,"explain":"Restructure là tái cơ cấu, sắp xếp lại - đồng nghĩa reorganize. Repay là trả nợ, reject là từ chối, relocate là di dời - không có nghĩa tổ chức lại.","extra":[{"en":"debt restructuring","vi":"tái cơ cấu nợ"},
{"en":"reorganization","vi":"sự tổ chức lại"},
{"en":"renegotiate terms","vi":"đàm phán lại điều khoản"}]},
{"id":"q0955","unit":6,"stem":"After a series of failed products, the CEO announced a strategic ______ in which the firm would focus on its two most profitable lines.","options":["shift","turnover","substitute","exposure"],"answer":0,"explain":"A strategic shift là sự chuyển hướng chiến lược (tập trung vào hai dòng sinh lời nhất). Turnover, substitute, exposure không tạo thành cụm hợp lý với 'strategic'.","extra":[{"en":"core business","vi":"hoạt động kinh doanh cốt lõi"},
{"en":"diversify","vi":"đa dạng hóa"},
{"en":"refocus","vi":"tái định hướng, tập trung lại"}]},
{"id":"q0956","unit":6,"stem":"A company that sells both luxury watches and cheaper fashion watches is trying to ______ its product range to appeal to more types of customer.","options":["downsize","diversify","decentralize","relocate"],"answer":1,"explain":"Diversify là đa dạng hóa (danh mục sản phẩm) để thu hút nhiều nhóm khách. Downsize là thu nhỏ quy mô, decentralize là phân quyền, relocate là di dời - không liên quan việc mở rộng chủng loại.","extra":[{"en":"product range","vi":"dải sản phẩm"},
{"en":"diversification","vi":"sự đa dạng hóa"},
{"en":"market segment","vi":"phân khúc thị trường"}]},
{"id":"q0957","unit":6,"stem":"Which action would be MOST likely to help a firm that sells to a very narrow range of customers capture a larger share of the market?","options":["Reducing its marketing budget","Raising prices on its only product","Adding new product lines for untapped customer groups","Closing its online store"],"answer":2,"explain":"Mở rộng dòng sản phẩm cho nhóm khách chưa được khai thác (untapped) là cách hợp lý để giành thị phần. Cắt marketing, tăng giá hay đóng cửa hàng online đều thu hẹp khả năng tiếp cận.","extra":[{"en":"new product line","vi":"dòng sản phẩm mới"},
{"en":"customer segment","vi":"nhóm khách hàng"},
{"en":"expand reach","vi":"mở rộng phạm vi tiếp cận"}]},
{"id":"q0958","unit":6,"stem":"A retailer with 200 stores finds that local managers are better at judging regional tastes than head office. Which strategy is MOST appropriate?","options":["Centralize all decisions at head office","Downgrade its premium range","Deregulate its supply contracts","Decentralize purchasing decisions to regional managers"],"answer":3,"explain":"Khi quản lý địa phương hiểu rõ thị hiếu vùng, nên phân quyền (decentralize) quyết định mua hàng cho họ. Tập trung hóa làm ngược lại; downgrade là hạ cấp; deregulate là việc của nhà nước/ngành, không phải chiến lược nội bộ này.","extra":[{"en":"regional manager","vi":"giám đốc khu vực"},
{"en":"local knowledge","vi":"hiểu biết địa phương"},
{"en":"empower","vi":"trao quyền"}]},
{"id":"q0959","unit":6,"stem":"A bank wants to cut costs and increase efficiency by merging overlapping teams and removing layers of management. Which term best describes its plan?","options":["restructuring","relaunching","upgrading","capturing"],"answer":0,"explain":"Gộp nhóm trùng lặp và loại bỏ tầng quản lý là tái cơ cấu (restructuring). Relaunch là ra mắt lại sản phẩm, upgrade là nâng cấp, capture là giành thị phần - không mô tả việc sắp xếp lại bộ máy.","extra":[{"en":"layers of management","vi":"các tầng quản lý"},
{"en":"overlap","vi":"sự chồng chéo"},
{"en":"efficiency drive","vi":"chiến dịch nâng cao hiệu quả"}]},
{"id":"q0960","unit":6,"stem":"A fashion brand's sales fell after customers began to see it as old-fashioned. Which response would be the MOST strategic?","options":["Cut all employee wages by 20%","Relaunch the brand with a new image targeted at younger customers","Relocate the factory without changing the products","Stop selling online"],"answer":1,"explain":"Relaunch thương hiệu với hình ảnh mới nhắm tới khách trẻ giải quyết gốc rễ vấn đề (hình ảnh lỗi thời). Cắt lương, chỉ chuyển nhà máy hay ngừng bán online không xử lý vấn đề nhận diện thương hiệu.","extra":[{"en":"brand image","vi":"hình ảnh thương hiệu"},
{"en":"target audience","vi":"đối tượng mục tiêu"},
{"en":"rebranding exercise","vi":"đợt đổi thương hiệu"}]},
{"id":"q0961","unit":6,"stem":"The restaurant chain's profits increased after it began to ______ to the growing number of customers who prefer plant-based meals.","options":["venture","edge","cater","capture"],"answer":2,"explain":"Cater to là đáp ứng nhu cầu của một nhóm khách hàng (người ăn chay). Venture không đi với 'to' theo nghĩa này, edge to và capture to không có nghĩa hợp lý.","extra":[{"en":"plant-based","vi":"dựa trên thực vật"},
{"en":"consumer preference","vi":"sở thích người tiêu dùng"},
{"en":"niche","vi":"phân khúc ngách"}]},
{"id":"q0962","unit":6,"stem":"Which of the following sentences contains a word-form error?","options":["The company's restructure caused considerable anxiety.","The decentralization of power improved morale.","The deregulation of the industry attracted new investors.","The relocation of the factory was announced yesterday."],"answer":3,"explain":"Sau 'The company's' cần danh từ: 'restructuring' (sự tái cơ cấu), không phải 'restructure' (động từ). Ba câu còn lại dùng đúng danh từ relocation, decentralization, deregulation.","extra":[{"en":"restructuring","vi":"sự tái cơ cấu"},
{"en":"relocation","vi":"sự di dời"},
{"en":"decentralization","vi":"sự phân quyền"}]},
{"id":"q0963","unit":6,"stem":"Choose the correct noun form: 'The ______ of staff was necessary because the new machines required different skills.'","options":["retraining","retrain","retrained","retrains"],"answer":0,"explain":"Sau 'The ...  of' cần danh từ: retraining (việc đào tạo lại). Retrain là động từ nguyên mẫu, retrained là quá khứ/phân từ, retrains là ngôi thứ ba số ít - đều không đứng sau 'The'.","extra":[{"en":"training programme","vi":"chương trình đào tạo"},
{"en":"skill set","vi":"bộ kỹ năng"},
{"en":"staff development","vi":"phát triển nhân sự"}]},
{"id":"q0964","unit":6,"stem":"Which word has the opposite meaning to 'upgrade' when it refers to a position or service level?","options":["update","downgrade","relocate","reassess"],"answer":1,"explain":"Downgrade (hạ cấp, giảm bậc) là từ trái nghĩa với upgrade (nâng cấp, thăng chức). Update là cập nhật, relocate là di dời, reassess là đánh giá lại - không phải trái nghĩa.","extra":[{"en":"demote","vi":"giáng chức"},
{"en":"promote","vi":"thăng chức"},
{"en":"scale back","vi":"thu hẹp"}]},
{"id":"q0965","unit":6,"stem":"Credit-rating agencies ______ the country's debt from 'stable' to 'speculative' after the budget crisis.","options":["upgraded","relaunched","downgraded","catered"],"answer":2,"explain":"Downgrade ở đây là hạ xếp hạng tín nhiệm (từ stable xuống speculative) sau khủng hoảng. Upgrade là nâng hạng - ngược nghĩa; relaunch và cater không dùng với xếp hạng tín nhiệm.","extra":[{"en":"credit rating","vi":"xếp hạng tín nhiệm"},
{"en":"sovereign debt","vi":"nợ quốc gia"},
{"en":"speculative grade","vi":"hạng đầu cơ (rủi ro cao)"}]},
{"id":"q0966","unit":6,"stem":"The analyst warned that the firm was ______ to currency fluctuations because most of its revenue came from a single foreign market.","options":["embedded","outstanding","untapped","exposed"],"answer":3,"explain":"Be exposed to là bị phơi nhiễm, chịu rủi ro từ (biến động tỷ giá). Embedded là được gắn sâu vào, outstanding là chưa thanh toán/xuất sắc, untapped là chưa khai thác - không có nghĩa chịu rủi ro.","extra":[{"en":"currency fluctuation","vi":"biến động tỷ giá"},
{"en":"exposure to risk","vi":"mức độ chịu rủi ro"},
{"en":"hedge against","vi":"phòng ngừa rủi ro"}]},
{"id":"q0967","unit":6,"stem":"In which situation is 'exposure' used with a RISK meaning rather than an ADVERTISING meaning?","options":["The bank's exposure to bad loans was larger than expected.","The film's exposure on TV doubled ticket sales.","The band gained exposure through social media.","The new product needs more exposure in stores."],"answer":0,"explain":"Ở câu 1, exposure to bad loans là mức độ chịu rủi ro từ các khoản nợ xấu. Ba câu còn lại dùng exposure với nghĩa được công chúng biết đến/quảng bá.","extra":[{"en":"bad loan","vi":"nợ xấu"},
{"en":"risk exposure","vi":"mức độ chịu rủi ro"},
{"en":"financial exposure","vi":"rủi ro tài chính"}]},
{"id":"q0968","unit":6,"stem":"A coffee chain stopped competing on price and instead opened premium stores with highly trained baristas. This strategy is intended to ______.","options":["reduce staff turnover by cutting wages","attract customers who value quality and service over low prices","increase the range of substitute goods","make its brand less visible"],"answer":1,"explain":"Mở cửa hàng cao cấp với barista được đào tạo nhắm đến khách hàng coi trọng chất lượng/dịch vụ hơn giá rẻ. Cắt lương không giảm turnover; tăng hàng thay thế và giảm hiện diện thương hiệu không phải mục tiêu.","extra":[{"en":"value proposition","vi":"đề xuất giá trị"},
{"en":"differentiation","vi":"sự khác biệt hóa"},
{"en":"quality over price","vi":"chất lượng hơn giá cả"}]},
{"id":"q0969","unit":6,"stem":"The manager praised the team's ______ results: sales were 40% above target in a difficult quarter.","options":["outstanded","outstand","outstanding","outstandingly"],"answer":2,"explain":"Trước danh từ 'results' cần tính từ: outstanding (xuất sắc). Outstandingly là trạng từ, outstand và outstanded không phải dạng chuẩn dùng như tính từ.","extra":[{"en":"exceed target","vi":"vượt chỉ tiêu"},
{"en":"achieve results","vi":"đạt kết quả"},
{"en":"quarterly performance","vi":"hiệu quả hoạt động theo quý"}]},
{"id":"q0970","unit":6,"stem":"A software engineer is 'embedded' in the marketing team for six months. This means she ______.","options":["has been dismissed from the company","only checks the team's reports","works for a competitor","works as a member of that team, close to its daily work"],"answer":3,"explain":"Embedded ở đây là được cử/gắn vào làm việc trực tiếp như một thành viên của nhóm. Bị sa thải, chỉ xem báo cáo hay làm cho đối thủ đều không đúng nghĩa.","extra":[{"en":"cross-functional team","vi":"nhóm liên chức năng"},
{"en":"secondment","vi":"biệt phái"},
{"en":"embedded system","vi":"hệ thống nhúng"}]},
{"id":"q0971","unit":6,"stem":"Two supermarkets and a bank agree to include each other's leaflets in customers' monthly mailings. What is the main benefit?","options":["Each partner reaches the other's customers at a low cost","All three firms can raise prices by law","Each firm reduces its staff turnover","The firms become competitors"],"answer":0,"explain":"Cross-promotion giúp mỗi bên tiếp cận khách hàng của bên kia với chi phí thấp. Tăng giá theo luật, giảm turnover và trở thành đối thủ đều không phải lợi ích của hoạt động này.","extra":[{"en":"mailing","vi":"thư/ấn phẩm gửi hàng loạt"},
{"en":"reach","vi":"tiếp cận"},
{"en":"marketing partnership","vi":"hợp tác marketing"}]},
{"id":"q0972","unit":6,"stem":"A global company learns that its advertising slogan has an offensive meaning in another language. Which concept does this problem highlight?","options":["the benefits of deregulation","the importance of understanding local cultural norms","the advantages of staff turnover","the need for downsizing"],"answer":1,"explain":"Slogan gây phản cảm ở ngôn ngữ khác cho thấy tầm quan trọng của việc hiểu chuẩn mực văn hóa địa phương (cultural norms). Deregulation, turnover, downsizing không liên quan đến vấn đề văn hóa/ngôn ngữ.","extra":[{"en":"cultural awareness","vi":"nhận thức văn hóa"},
{"en":"localise","vi":"địa phương hóa"},
{"en":"lost in translation","vi":"mất nghĩa khi dịch"}]},
{"id":"q0973","unit":6,"stem":"A firm prepares to enter a new country. Which is the most sensible first step according to a strategic approach?","options":["Close its home-country operations","Cancel all marketing plans","Reassess the risks and research the local market before committing funds","Increase staff turnover"],"answer":2,"explain":"Đánh giá lại rủi ro và nghiên cứu thị trường trước khi bỏ vốn là bước chiến lược hợp lý. Đóng hoạt động trong nước, hủy marketing hay tăng turnover đều là hành động phản tác dụng.","extra":[{"en":"market entry","vi":"thâm nhập thị trường"},
{"en":"feasibility study","vi":"nghiên cứu khả thi"},
{"en":"risk assessment","vi":"đánh giá rủi ro"}]},
{"id":"q0974","unit":6,"stem":"The new CEO, who prefers a flat structure and quick decisions, wants the company to become more ______ and less bureaucratic.","options":["outstanding","premium","embedded","agile"],"answer":3,"explain":"Agile là linh hoạt, ra quyết định nhanh, đối lập với quan liêu. Outstanding là xuất sắc, premium là cao cấp, embedded là gắn sâu - không đối lập với bureaucratic.","extra":[{"en":"flat structure","vi":"cấu trúc phẳng"},
{"en":"bureaucracy","vi":"bộ máy quan liêu"},
{"en":"streamlined","vi":"tinh gọn"}]},
{"id":"q0975","unit":6,"stem":"Which word could replace 'capture' in: 'The new smartphone captured 12% of the market in its first year'?","options":["gained","photographed","lost","recorded"],"answer":0,"explain":"Capture a share nghĩa là giành được thị phần, đồng nghĩa gained. Photographed/recorded là nghĩa chụp/ghi lại (sai ngữ cảnh), lost là mất - trái nghĩa.","extra":[{"en":"win business","vi":"giành được hợp đồng"},
{"en":"grab market share","vi":"chiếm thị phần"},
{"en":"secure","vi":"đảm bảo, giành được"}]},
{"id":"q0976","unit":6,"stem":"A company selling high-priced organic baby food claims its range is 'premium'. Which feature would MOST support that claim?","options":["The lowest price in the market","Certified ingredients and superior quality control","Standard packaging used by all rivals","Free delivery on all orders"],"answer":1,"explain":"Premium là cao cấp, nên nguyên liệu được chứng nhận và kiểm soát chất lượng vượt trội phù hợp nhất. Giá rẻ nhất, bao bì phổ thông, miễn phí giao hàng không phản ánh sản phẩm cao cấp.","extra":[{"en":"certified organic","vi":"hữu cơ có chứng nhận"},
{"en":"quality control","vi":"kiểm soát chất lượng"},
{"en":"premium pricing","vi":"định giá cao cấp"}]},
{"id":"q0977","unit":6,"stem":"After a poor year, the firm decided to ______ its priorities and concentrate on products with the highest margins.","options":["relocate","decentralize","reassess","deregulate"],"answer":2,"explain":"Reassess its priorities là đánh giá lại các ưu tiên. Relocate là di dời, decentralize là phân quyền, deregulate là bãi bỏ quy định - không hợp với 'priorities'.","extra":[{"en":"profit margin","vi":"biên lợi nhuận"},
{"en":"prioritise","vi":"ưu tiên"},
{"en":"refocus on","vi":"tập trung lại vào"}]},
{"id":"q0978","unit":6,"stem":"The team moved the launch date forward to align with the competitor's schedule. In this context, 'align with' is closest to ______.","options":["argue with","compete against","withdraw from","coordinate with"],"answer":3,"explain":"Align with là phối hợp/điều chỉnh cho khớp với, nghĩa gần coordinate with. Argue with là tranh cãi; compete against là cạnh tranh với; withdraw from là rút khỏi.","extra":[{"en":"coordinate","vi":"phối hợp"},
{"en":"synchronise","vi":"đồng bộ hóa"},
{"en":"launch date","vi":"ngày ra mắt"}]},
{"id":"q0979","unit":6,"stem":"A government deregulates the telecoms industry. Which would be the MOST likely long-term benefit to consumers?","options":["Lower prices as companies compete for customers","A single national provider","Stricter licence conditions","Higher import duties on phones"],"answer":0,"explain":"Bãi bỏ quy định thường làm tăng cạnh tranh và giảm giá cho người tiêu dùng. Một nhà cung cấp quốc gia, điều kiện cấp phép chặt hơn hoặc thuế nhập khẩu cao đều là tăng kiểm soát.","extra":[{"en":"consumer choice","vi":"sự lựa chọn của người tiêu dùng"},
{"en":"licence","vi":"giấy phép"},
{"en":"import duty","vi":"thuế nhập khẩu"}]},
{"id":"q0980","unit":6,"stem":"Which phrase best describes what happens when a business 'edges' its way into a market?","options":["It leaves suddenly","It enters gradually and carefully","It dominates immediately","It merges with all competitors"],"answer":1,"explain":"Edge into/edge one's way là tiến vào dần dần, thận trọng. Rời đi đột ngột, thống trị ngay lập tức hay sáp nhập với mọi đối thủ không phải nghĩa của 'edge'.","extra":[{"en":"gradually","vi":"dần dần"},
{"en":"foothold","vi":"chỗ đứng ban đầu"},
{"en":"market entry strategy","vi":"chiến lược thâm nhập thị trường"}]},
{"id":"q0981","unit":6,"stem":"A struggling manufacturer has been advised to downsize. Which of the following would NOT be a typical part of this strategy?","options":["Closing a loss-making plant","Offering voluntary redundancy","Hiring hundreds of new employees for expansion","Selling surplus equipment"],"answer":2,"explain":"Downsize là thu hẹp quy mô: đóng nhà máy lỗ, cho nghỉ tự nguyện, bán thiết bị dư thừa. Tuyển hàng trăm nhân viên để mở rộng là ngược lại với downsizing.","extra":[{"en":"voluntary redundancy","vi":"tự nguyện nghỉ việc (có bồi thường)"},
{"en":"surplus","vi":"dư thừa"},
{"en":"plant closure","vi":"đóng nhà máy"}]},
{"id":"q0982","unit":6,"stem":"The firm's strategy of ______ staff rather than hiring new ones saves recruitment costs and preserves valuable company knowledge.","options":["downsizing","deregulating","relocating","retraining"],"answer":3,"explain":"Retraining là đào tạo lại nhân viên hiện có thay vì tuyển mới, tiết kiệm chi phí và giữ kiến thức công ty. Downsizing là cắt giảm, deregulating là việc của nhà nước, relocating là di dời - không hợp với 'rather than hiring'.","extra":[{"en":"upskilling","vi":"nâng cao kỹ năng"},
{"en":"retain talent","vi":"giữ chân nhân tài"},
{"en":"internal promotion","vi":"thăng chức nội bộ"}]},
{"id":"q0983","unit":6,"stem":"The software update was ______ so that the platform would continue to meet new data-protection laws.","options":["compulsory","untapped","premium","agile"],"answer":0,"explain":"Compulsory là bắt buộc - hợp với việc phải đáp ứng luật mới. Untapped là chưa khai thác, premium là cao cấp, agile là linh hoạt - không diễn tả sự bắt buộc về pháp lý.","extra":[{"en":"data protection","vi":"bảo vệ dữ liệu"},
{"en":"comply with","vi":"tuân thủ"},
{"en":"mandatory","vi":"bắt buộc"}]},
{"id":"q0984","unit":6,"stem":"A luxury hotel wants to expand its ______ to include corporate clients, who book regularly and in large numbers.","options":["turnover","clientele","venture","norms"],"answer":1,"explain":"Expand its clientele là mở rộng nhóm khách hàng (thêm khách doanh nghiệp). Turnover là doanh thu/tỷ lệ luân chuyển, venture là dự án mạo hiểm, norms là chuẩn mực - không hợp với 'include corporate clients'.","extra":[{"en":"corporate client","vi":"khách hàng doanh nghiệp"},
{"en":"repeat business","vi":"khách quay lại"},
{"en":"block booking","vi":"đặt phòng số lượng lớn"}]},
{"id":"q0985","unit":6,"stem":"What does the phrase 'a first-mover advantage' in strategy refer to?","options":["The advantage of copying a competitor's product","The right to move a factory abroad","The benefit gained by being first to enter a new market","The profit made by selling old stock"],"answer":2,"explain":"First-mover advantage là lợi thế của công ty vào thị trường mới đầu tiên (có thương hiệu, khách hàng trước). Sao chép đối thủ, quyền chuyển nhà máy hay bán hàng tồn không phải nghĩa của cụm này.","extra":[{"en":"early adopter","vi":"người dùng đầu tiên"},
{"en":"pioneer","vi":"người tiên phong"},
{"en":"head start","vi":"lợi thế xuất phát sớm"}]},
{"id":"q0986","unit":6,"stem":"A company's strategy is to move into markets where nobody else sells yet. This is an attempt to find ______ opportunities.","options":["outstanding","premium","complementary","untapped"],"answer":3,"explain":"Untapped opportunities là cơ hội chưa được khai thác, hợp với 'nobody else sells yet'. Outstanding, premium, complementary đều không có nghĩa chưa ai khai thác.","extra":[{"en":"gap in the market","vi":"khoảng trống thị trường"},
{"en":"blue ocean","vi":"đại dương xanh (thị trường chưa cạnh tranh)"},
{"en":"emerging market","vi":"thị trường mới nổi"}]},
{"id":"q0987","unit":6,"stem":"Which pair of words are most likely to be used as business 'substitutes' for customers?","options":["tea and coffee","cars and fuel","printers and ink","phones and chargers"],"answer":0,"explain":"Trà và cà phê là hàng thay thế (người dùng chọn cái này thay cái kia). Xe - nhiên liệu, máy in - mực, điện thoại - sạc là các cặp hàng bổ sung (complements) dùng cùng nhau.","extra":[{"en":"complementary goods","vi":"hàng bổ sung"},
{"en":"alternative","vi":"giải pháp thay thế"},
{"en":"consumer choice","vi":"lựa chọn của người tiêu dùng"}]},
{"id":"q0988","unit":6,"stem":"When a hospital's 'turnover' of nurses is high, which measure is MOST likely to reduce it?","options":["Increasing weekend hours without extra pay","Improving pay, training and working conditions","Removing all career-development schemes","Hiring only temporary staff"],"answer":1,"explain":"Cải thiện lương, đào tạo và điều kiện làm việc giúp giữ chân nhân viên, giảm turnover. Tăng giờ làm không trả thêm, bỏ phát triển nghề nghiệp, thuê chỉ nhân viên tạm thời đều làm turnover tăng.","extra":[{"en":"retention rate","vi":"tỷ lệ giữ chân"},
{"en":"working conditions","vi":"điều kiện làm việc"},
{"en":"career development","vi":"phát triển sự nghiệp"}]},
{"id":"q0989","unit":6,"stem":"The more 'embedded' a company's ethical policies are, the more likely it is that ______.","options":["they will be ignored by managers","they will be easy to cancel","they will guide everyday decisions and behaviour","they will apply only to the board"],"answer":2,"explain":"Embedded policies là chính sách ăn sâu vào quy trình, nên chi phối quyết định và hành vi hằng ngày. Bị bỏ qua, dễ hủy hoặc chỉ áp dụng cho ban giám đốc là hàm ý của chính sách bề nổi.","extra":[{"en":"code of conduct","vi":"quy tắc ứng xử"},
{"en":"corporate governance","vi":"quản trị doanh nghiệp"},
{"en":"ethical standards","vi":"chuẩn mực đạo đức"}]},
{"id":"q0990","unit":6,"stem":"A manager says: 'Let's not ______ into a new market until we've tested our prototype.' Which word fits best?","options":["cater","update","complement","venture"],"answer":3,"explain":"Venture into là dấn thân, mạo hiểm bước vào (thị trường mới). Cater, update, complement không đi với 'into' theo nghĩa bước vào thị trường.","extra":[{"en":"prototype","vi":"mẫu thử nghiệm"},
{"en":"pilot scheme","vi":"chương trình thí điểm"},
{"en":"test the waters","vi":"thăm dò thị trường"}]},
{"id":"q0991","unit":6,"stem":"Which statement about 'agile' organizations is most accurate?","options":["They use short cycles of planning and feedback so they can change direction quickly","They avoid customer feedback until a product is complete","They set strategy once and never revise it","They rely on large multi-layered management"],"answer":0,"explain":"Tổ chức agile dùng chu kỳ ngắn lập kế hoạch - phản hồi để thay đổi hướng nhanh. Các đáp án còn lại (tránh phản hồi, không điều chỉnh, nhiều tầng quản lý) mô tả mô hình cứng nhắc, trái ngược.","extra":[{"en":"iterative","vi":"lặp đi lặp lại cải tiến"},
{"en":"sprint","vi":"giai đoạn làm việc ngắn"},
{"en":"customer feedback","vi":"phản hồi của khách hàng"}]},
{"id":"q0992","unit":6,"stem":"A new coffee shop wants to gain publicity cheaply. Which action involves cross-promotion?","options":["Doubling the price of all drinks","Giving customers a voucher for the cinema next door, which in turn promotes the cafe","Hiring a larger team of baristas","Moving to a more expensive location"],"answer":1,"explain":"Cross-promotion là hai doanh nghiệp quảng bá cho nhau (phiếu giảm giá rạp chiếu phim và quán cà phê). Tăng giá, thuê thêm barista hay chuyển địa điểm không phải quảng cáo chéo.","extra":[{"en":"voucher","vi":"phiếu giảm giá"},
{"en":"partner business","vi":"doanh nghiệp đối tác"},
{"en":"word-of-mouth","vi":"truyền miệng"}]},
{"id":"q0993","unit":6,"stem":"Which of the following is the BEST definition of 'norms' in a business context?","options":["The lowest prices a company may charge","Legal documents that create a company","Accepted standards of behaviour or practice within a group or industry","Reports prepared by external auditors"],"answer":2,"explain":"Norms là các chuẩn mực, quy ước hành vi/thực hành được chấp nhận trong một nhóm hay ngành. Mức giá thấp nhất, văn bản thành lập công ty và báo cáo kiểm toán là các khái niệm khác.","extra":[{"en":"industry standard","vi":"tiêu chuẩn ngành"},
{"en":"accepted practice","vi":"thực hành được chấp nhận"},
{"en":"break with convention","vi":"phá vỡ quy ước"}]},
{"id":"q0994","unit":6,"stem":"The two coffee chains now compete in the same city. One of them tries to 'edge' ahead by opening ten minutes earlier. Here, 'edge ahead' means ______.","options":["fall slightly behind","refuse to compete","merge together","move slightly in front"],"answer":3,"explain":"Edge ahead là nhích lên trước một chút (lợi thế nhỏ). Fall behind là tụt lại, refuse to compete là từ chối cạnh tranh, merge là hợp nhất - không đúng.","extra":[{"en":"slight lead","vi":"lợi thế nhỏ"},
{"en":"stay ahead of the competition","vi":"đi trước đối thủ"},
{"en":"outperform","vi":"làm tốt hơn"}]},
{"id":"q0995","unit":6,"stem":"A pharmaceutical firm decides to relocate its research division abroad to access a larger pool of skilled scientists. What is the primary motive?","options":["Gaining access to skilled labour","Reducing the number of products","Cutting its marketing budget to zero","Avoiding all taxes legally"],"answer":0,"explain":"Mục đích nêu rõ trong đề: tiếp cận nguồn nhân lực có kỹ năng. Giảm số sản phẩm hay cắt marketing không liên quan; né mọi loại thuế hợp pháp không phải động cơ được nêu.","extra":[{"en":"talent pool","vi":"nguồn nhân tài"},
{"en":"offshoring","vi":"chuyển hoạt động ra nước ngoài"},
{"en":"research and development","vi":"nghiên cứu và phát triển"}]},
{"id":"q0996","unit":6,"stem":"After a data breach, the company 'relaunched' its app. Which was the MOST likely reason?","options":["To increase the number of customer complaints","To restore customer trust with a redesigned, more secure version","To discourage new users from downloading it","To avoid updating its software"],"answer":1,"explain":"Relaunch ứng dụng thiết kế lại, an toàn hơn nhằm khôi phục niềm tin khách hàng sau sự cố. Tăng khiếu nại, làm nản người dùng hay tránh cập nhật là các mục đích phi lý.","extra":[{"en":"data breach","vi":"vụ rò rỉ dữ liệu"},
{"en":"restore trust","vi":"khôi phục niềm tin"},
{"en":"damage limitation","vi":"hạn chế thiệt hại"}]},
{"id":"q0997","unit":6,"stem":"Which word is formed with the prefix 'up-' and can mean 'to raise to a higher position or standard'?","options":["update","uplift","upgrade","uproot"],"answer":2,"explain":"Upgrade (nâng cấp/thăng chức) là từ cần chọn. Uplift là sự nâng lên (cảm xúc, doanh số) ít dùng nghĩa thăng cấp; uproot là nhổ rễ/di dời cưỡng bức; update chỉ cập nhật cho mới chứ không nâng chất lượng/cấp bậc.","extra":[{"en":"promote","vi":"thăng chức"},
{"en":"raise standards","vi":"nâng cao tiêu chuẩn"},
{"en":"state-of-the-art","vi":"hiện đại nhất"}]},
{"id":"q0998","unit":6,"stem":"A café owner is deciding whether to 'update' or 'upgrade' the coffee machine. Which statement is correct?","options":["Updating means selling the machine, upgrading means renting it","Both words mean to lower quality","Upgrading is cheaper than updating in every case","Updating only installs the latest software, whereas upgrading means buying a better model"],"answer":3,"explain":"Update chỉ là cập nhật phần mềm/thông tin mới nhất, còn upgrade là nâng cấp, mua máy tốt hơn. Bán hoặc thuê máy, hạ chất lượng, hay luôn rẻ hơn đều không đúng.","extra":[{"en":"firmware","vi":"phần mềm điều khiển thiết bị"},
{"en":"capital expenditure","vi":"chi tiêu vốn"},
{"en":"obsolete","vi":"lỗi thời"}]},
{"id":"q0999","unit":6,"stem":"When a business 'captures' the attention of a new audience, it ______.","options":["succeeds in attracting and holding their interest","records them on camera","sells them a substitute","reassesses their needs"],"answer":0,"explain":"Capture attention là thu hút và giữ sự chú ý của đối tượng mới. Quay phim là nghĩa đen nhưng không hợp ngữ cảnh; bán hàng thay thế hay đánh giá lại nhu cầu là nghĩa khác.","extra":[{"en":"attract attention","vi":"thu hút sự chú ý"},
{"en":"engage","vi":"thu hút, tương tác"},
{"en":"target audience","vi":"đối tượng mục tiêu"}]},
{"id":"q1000","unit":6,"stem":"After reviewing exit-interview data, HR found that staff turnover was highest among employees with less than a year's service. Which conclusion is best supported?","options":["Long-serving staff are leaving in large numbers","New employees may not be receiving adequate induction and support","The company should stop all recruitment","Turnover measures only sales revenue"],"answer":1,"explain":"Turnover cao nhất ở người dưới 1 năm gợi ý nhân viên mới chưa được hướng dẫn và hỗ trợ đủ. Câu 2 trái dữ liệu; ngừng tuyển dụng là suy diễn thái quá; turnover không đo doanh thu bán hàng.","extra":[{"en":"induction","vi":"buổi định hướng nhân viên mới"},
{"en":"onboarding","vi":"quy trình đón nhận nhân viên mới"},
{"en":"probation period","vi":"thời gian thử việc"}]},
{"id":"q1001","unit":6,"stem":"A government agency downgrades the safety rating of a car model after crash tests. What is the most likely effect on the manufacturer?","options":["A rise in premium pricing power","Increased brand exposure only in positive terms","Falling sales and damaged reputation","A guaranteed increase in market share"],"answer":2,"explain":"Hạ xếp hạng an toàn thường làm doanh số giảm và uy tín bị tổn hại. Các đáp án còn lại (quyền định giá cao, quảng bá toàn tích cực, chắc chắn tăng thị phần) trái với hậu quả logic.","extra":[{"en":"safety rating","vi":"xếp hạng an toàn"},
{"en":"reputation","vi":"danh tiếng"},
{"en":"product recall","vi":"thu hồi sản phẩm"}]},
{"id":"q1002","unit":6,"stem":"A retailer wants to reassess its stock levels before the holiday season. Which of the following would it MOST likely review?","options":["The CEO's personal calendar","Staff birthdays","The colour of its logo","Sales forecasts and current inventory"],"answer":3,"explain":"Đánh giá lại tồn kho cần xem dự báo doanh số và hàng tồn hiện có. Lịch cá nhân của CEO, sinh nhật nhân viên hay màu logo không liên quan.","extra":[{"en":"stock level","vi":"mức tồn kho"},
{"en":"seasonal demand","vi":"nhu cầu theo mùa"},
{"en":"peak season","vi":"mùa cao điểm"}]},
{"id":"q1003","unit":6,"stem":"A restaurant owner explains: 'We can't survive on price alone, so we will ______ for customers who want a special experience.' Which word completes it best?","options":["cater","relocate","deregulate","downsize"],"answer":0,"explain":"Cater for customers who want ... là phục vụ nhóm khách tìm trải nghiệm đặc biệt. Relocate, deregulate, downsize không đi với 'for customers' theo nghĩa phục vụ nhu cầu.","extra":[{"en":"experience economy","vi":"nền kinh tế trải nghiệm"},
{"en":"differentiate","vi":"tạo sự khác biệt"},
{"en":"target market","vi":"thị trường mục tiêu"}]},
{"id":"q1004","unit":6,"stem":"A start-up founder wants to ______ a new market segment: busy professionals who prefer high-quality coffee delivered to their desks.","options":["cater from","tap into","edge over","venture on"],"answer":1,"explain":"Tap into là khai thác (phân khúc mới). 'Cater from', 'edge over', 'venture on' không phải cụm đúng với nghĩa khai thác một phân khúc; cách đúng là 'venture into' hoặc 'tap into'.","extra":[{"en":"market segment","vi":"phân khúc thị trường"},
{"en":"tap into the market","vi":"khai thác thị trường"},
{"en":"delivery service","vi":"dịch vụ giao hàng"}]},
{"id":"q1005","unit":6,"stem":"Which word best completes: 'The airline decided to ______ its fleet by replacing older jets with fuel-efficient models.'","options":["downsize","deregulate","upgrade","decentralize"],"answer":2,"explain":"Upgrade the fleet là nâng cấp đội bay bằng máy bay mới tiết kiệm nhiên liệu. Downsize là thu nhỏ quy mô, deregulate là bỏ quy định, decentralize là phân quyền - không mô tả việc thay máy bay cũ.","extra":[{"en":"fleet","vi":"đội tàu/xe/máy bay"},
{"en":"fuel-efficient","vi":"tiết kiệm nhiên liệu"},
{"en":"capital investment","vi":"đầu tư vốn"}]},
{"id":"q1006","unit":7,"stem":"Before recommending a portfolio, the adviser asked the client how much temporary loss she could accept without selling in panic. The questionnaire was designed to measure her ______.","options":["credit rating","market share","risk tolerance","repayment period"],"answer":2,"explain":"Risk tolerance là mức độ rủi ro/thua lỗ mà nhà đầu tư có thể chấp nhận. Credit rating là xếp hạng tín nhiệm của người vay, market share là thị phần, repayment period là thời hạn trả nợ nên không đo mức chịu rủi ro.","extra":[{"en":"evaluate one's risk tolerance","vi":"đánh giá khả năng chịu rủi ro"},
{"en":"high tolerance for risk","vi":"khả năng chịu rủi ro cao"}]},
{"id":"q1007","unit":7,"stem":"Market research showed that customers would still buy the smartphone even if its price rose by 10 percent. This suggests that the target segment has a high ______.","options":["price tolerance","inventory turnover","loan principal","export restriction"],"answer":0,"explain":"Price tolerance là mức giá tăng mà khách hàng còn chấp nhận mua. Inventory turnover là vòng quay hàng tồn kho, loan principal là gốc vay, export restriction là hạn chế xuất khẩu; không liên quan đến thái độ của khách với giá.","extra":[{"en":"estimate consumers' price tolerance","vi":"ước lượng mức chịu giá của người tiêu dùng"},
{"en":"price-sensitive customers","vi":"khách hàng nhạy cảm về giá"}]},
{"id":"q1008","unit":7,"stem":"Which sentence uses the phrase correctly?","options":["The economic downturns of the new product was very successful.","Our economic downturn increased our profit margin dramatically last year.","Retailers often cut staff during economic downturns, when demand declines.","He signed an economic downturn with a supplier."],"answer":2,"explain":"Economic downturn là giai đoạn suy thoái, nhu cầu giảm, nên đi với 'demand declines' là hợp lý. Các câu còn lại dùng nó như một sản phẩm, một lợi nhuận tăng hoặc một hợp đồng, đều sai nghĩa.","extra":[{"en":"weather an economic downturn","vi":"vượt qua suy thoái kinh tế"},
{"en":"experience weaker sales","vi":"doanh số giảm sút"}]},
{"id":"q1009","unit":7,"stem":"The loan agreement states that the borrower must repay the ______ of $500,000 plus interest over five years.","options":["principle","principals","principally","principal"],"answer":3,"explain":"Loan principal (gốc vay) là số tiền vay ban đầu chưa tính lãi. 'Principle' nghĩa là nguyên tắc, hai dạng còn lại sai từ loại hoặc số nhiều không phù hợp.","extra":[{"en":"principal and interest","vi":"gốc và lãi"},
{"en":"outstanding principal","vi":"dư nợ gốc"}]},
{"id":"q1010","unit":7,"stem":"The board refused to compromise on its ethical ______, even though it cost the firm a valuable contract.","options":["principals","principles","principle","principal"],"answer":1,"explain":"Principles (số nhiều) = các nguyên tắc đạo đức. Principals là người đứng đầu/ gốc vay, nên không hợp với 'ethical'. 'Principle' số ít không đi với 'its ... even though' tự nhiên bằng dạng số nhiều ở đây.","extra":[{"en":"in principle","vi":"về nguyên tắc"},
{"en":"a matter of principle","vi":"vấn đề nguyên tắc"}]},
{"id":"q1011","unit":7,"stem":"Several venture investors took significant ______ in the early-stage company, expecting it to expand beyond its domestic market.","options":["stocks","stakes","steaks","shares price"],"answer":1,"explain":"Take a stake in a company = nắm giữ phần vốn góp/ lợi ích trong công ty. 'Stocks' là cổ phiếu nói chung (không đi với 'take ... in' tự nhiên ở nghĩa này), 'steaks' là món bít tết, 'shares price' sai ngữ pháp.","extra":[{"en":"hold a minority stake","vi":"nắm cổ phần thiểu số"},
{"en":"stakeholder","vi":"bên liên quan"}]},
{"id":"q1012","unit":7,"stem":"The start-up needs to ______ external funding before it can open its second factory.","options":["remain","distinguish","cater","obtain"],"answer":3,"explain":"Obtain funding = huy động/ nhận được vốn. Remain là vẫn còn, distinguish là phân biệt, cater là phục vụ; không có collocation với 'external funding'.","extra":[{"en":"seek support from investors","vi":"tìm kiếm sự hỗ trợ từ nhà đầu tư"},
{"en":"contribute capital","vi":"góp vốn"}]},
{"id":"q1013","unit":7,"stem":"The finance director asked the team to ______ cash flow for the next quarter to make sure enough money would be available.","options":["forbid","forgo","forecast","foresee to"],"answer":2,"explain":"Forecast cash flow = dự báo dòng tiền. Forbid là cấm, forgo là từ bỏ, 'foresee to' sai cấu trúc.","extra":[{"en":"cash flow forecast","vi":"dự báo dòng tiền"},
{"en":"cash flow problems","vi":"vấn đề về dòng tiền"}]},
{"id":"q1014","unit":7,"stem":"The company keeps a reserve of liquid funds so that it can meet its short-term ______ even if customers pay late.","options":["expansions","obligations","reputations","specifications"],"answer":1,"explain":"Meet short-term obligations = thanh toán các nghĩa vụ ngắn hạn (lương, nợ đến hạn). Expansions là mở rộng, reputations là danh tiếng, specifications là thông số kỹ thuật nên không đi với 'meet' theo nghĩa nợ.","extra":[{"en":"meet financial obligations","vi":"đáp ứng nghĩa vụ tài chính"},
{"en":"short-term liabilities","vi":"nợ ngắn hạn"}]},
{"id":"q1015","unit":7,"stem":"Before choosing a bank, the treasurer decided to ______ several loan offers, looking closely at interest rates and fees.","options":["compete","complement","comply","compare"],"answer":3,"explain":"Compare loan offers = so sánh các đề nghị vay. Compete là cạnh tranh, complement là bổ sung cho nhau, comply là tuân thủ; đều không đi với 'offers' theo nghĩa này.","extra":[{"en":"distinguish A from B","vi":"phân biệt A với B"},
{"en":"additional interest","vi":"lãi bổ sung"}]},
{"id":"q1016","unit":7,"stem":"A longer ______ usually lowers the monthly installment but increases the total interest paid.","options":["lead time","product life cycle","repayment period","shelf life"],"answer":2,"explain":"Repayment period là thời hạn trả nợ; kéo dài thì mỗi kỳ trả ít hơn nhưng tổng lãi cao hơn. Lead time là thời gian chờ giao hàng, product life cycle là vòng đời sản phẩm, shelf life là hạn sử dụng.","extra":[{"en":"monthly installment","vi":"khoản trả góp hàng tháng"},
{"en":"grace period","vi":"thời gian ân hạn"}]},
{"id":"q1017","unit":7,"stem":"The retailer decided to adopt JIT manufacturing mainly in order to ______.","options":["raise its loan principal","reduce inventory costs","increase treasury stock","avoid regulatory compliance"],"answer":1,"explain":"JIT (just-in-time) giúp nhận nguyên liệu đúng lúc cần nên giảm chi phí tồn kho. Loan principal, treasury stock và regulatory compliance không phải mục tiêu của JIT.","extra":[{"en":"just-in-time delivery","vi":"giao hàng đúng lúc"},
{"en":"stockout","vi":"hết hàng"}]},
{"id":"q1018","unit":7,"stem":"After paying dividends, the firm decided to reinvest the rest of its profit. The ______ on its balance sheet therefore increased again this year.","options":["cash equivalents deficit","treasury stock fee","retained earnings balance","loan default"],"answer":2,"explain":"Retained earnings = lợi nhuận giữ lại sau khi chia cổ tức; số dư (balance) tăng khi công ty tái đầu tư. Các phương án còn lại hoặc không phải khoản mục vốn chủ sở hữu hoặc là cụm vô nghĩa.","extra":[{"en":"reinvest retained earnings","vi":"tái đầu tư lợi nhuận giữ lại"},
{"en":"dividend payout","vi":"chi trả cổ tức"}]},
{"id":"q1019","unit":7,"stem":"The owner lost his job and was unable to ______ the loan, so the bank began legal proceedings.","options":["default in","default of","default on","default at"],"answer":2,"explain":"Collocation chuẩn là 'default on a loan' = vỡ nợ, không trả được nợ. Các giới từ in/of/at không dùng.","extra":[{"en":"loan default","vi":"vỡ nợ khoản vay"},
{"en":"default on debt obligations","vi":"không thực hiện nghĩa vụ nợ"}]},
{"id":"q1020","unit":7,"stem":"The bank charged the start-up a higher interest rate because the likelihood that it would fail to repay was judged to be high. This likelihood is called ______.","options":["price tolerance","default risk","exchange gain","interest cover"],"answer":1,"explain":"Default risk = rủi ro người vay không trả được nợ, nên lãi suất cao hơn. Price tolerance liên quan đến khách hàng, exchange gain là lãi tỷ giá, interest cover là khả năng chi trả lãi (một chỉ số, không phải khả năng vỡ nợ).","extra":[{"en":"credit risk","vi":"rủi ro tín dụng"},
{"en":"credit rating","vi":"xếp hạng tín nhiệm"}]},
{"id":"q1021","unit":7,"stem":"A coffee brand and a bakery launched a ______ in which each handed out vouchers for the other's products.","options":["joint liquidation","hostile takeover","cost-cutting scheme","cross-promotion campaign"],"answer":3,"explain":"Cross-promotion campaign = chiến dịch quảng bá chéo giữa hai thương hiệu bổ trợ nhau. Liquidation là thanh lý, hostile takeover là thâu tóm thù địch, cost-cutting là cắt giảm chi phí.","extra":[{"en":"promote complementary products","vi":"quảng bá sản phẩm bổ trợ"},
{"en":"expand customer exposure","vi":"mở rộng độ tiếp cận khách hàng"}]},
{"id":"q1022","unit":7,"stem":"Which item would normally be included in 'cash and cash equivalents' on a balance sheet?","options":["A factory building","Goodwill from an acquisition","Treasury bills maturing in two months","Raw materials in the warehouse"],"answer":2,"explain":"Cash equivalents là các khoản đầu tư rất thanh khoản, đáo hạn ngắn (ví dụ tín phiếu kho bạc kỳ hạn ngắn). Nhà xưởng, lợi thế thương mại và nguyên liệu không thể quy đổi thành tiền nhanh nên không thuộc nhóm này.","extra":[{"en":"highly liquid investments","vi":"khoản đầu tư có tính thanh khoản cao"},
{"en":"cash equivalents balance","vi":"số dư các khoản tương đương tiền"}]},
{"id":"q1023","unit":7,"stem":"An airline signed fuel ______ to protect itself against sudden increases in the price of jet fuel.","options":["retained contracts","derivative contracts","default contracts","tolerance contracts"],"answer":1,"explain":"Derivative contracts (hợp đồng phái sinh) là công cụ dùng để phòng ngừa biến động giá. Ba cụm còn lại không phải thuật ngữ tài chính chuẩn.","extra":[{"en":"hedge against price fluctuations","vi":"phòng ngừa biến động giá"},
{"en":"futures contract","vi":"hợp đồng tương lai"}]},
{"id":"q1024","unit":7,"stem":"Exporters often use forward contracts to ______ currency fluctuations.","options":["hedge from","hedge against","hedge to","hedge on"],"answer":1,"explain":"'Hedge against' = phòng ngừa (rủi ro). Các giới từ from/to/on không phải collocation.","extra":[{"en":"volatile exchange rates","vi":"tỷ giá biến động mạnh"},
{"en":"forward contract","vi":"hợp đồng kỳ hạn"}]},
{"id":"q1025","unit":7,"stem":"Environmental pressure groups campaigned for months to ______ the government to tighten emission rules.","options":["press out","push against","take a stake in","put pressure on"],"answer":3,"explain":"'Put pressure on the government' = gây áp lực lên chính phủ. Các cụm còn lại sai nghĩa hoặc cấu trúc (take a stake in = nắm phần vốn).","extra":[{"en":"lobby policymakers","vi":"vận động hành lang với người làm chính sách"},
{"en":"be opposed to a policy","vi":"phản đối chính sách"}]},
{"id":"q1026","unit":7,"stem":"The company's ______ business strategy allowed it to change direction quickly when competitors launched cheaper products.","options":["rigid","obsolete","agile","embedded"],"answer":2,"explain":"Agile = nhanh nhẹn, linh hoạt, thích ứng nhanh. Rigid là cứng nhắc (ngược nghĩa), obsolete là lỗi thời, embedded là ăn sâu, không giúp đổi hướng nhanh.","extra":[{"en":"remain agile","vi":"giữ sự linh hoạt"},
{"en":"agile workforce","vi":"lực lượng lao động linh hoạt"}]},
{"id":"q1027","unit":7,"stem":"The supplier failed to meet the client's technical ______, so the entire batch of components was returned.","options":["speculations","specifications","spectators","specialities"],"answer":1,"explain":"Technical specifications = thông số kỹ thuật; meet specifications = đáp ứng thông số. Speculations là suy đoán, spectators là khán giả, specialities là đặc sản/chuyên môn.","extra":[{"en":"product specifications","vi":"thông số sản phẩm"},
{"en":"within tolerance","vi":"trong ngưỡng dung sai"}]},
{"id":"q1028","unit":7,"stem":"Strict quality assurance ______ are carried out at every stage so that faulty products never leave the plant.","options":["pressures","principals","proceeds","procedures"],"answer":3,"explain":"Quality assurance procedures = quy trình đảm bảo chất lượng. Pressures là áp lực, principals là gốc vay/người đứng đầu, proceeds là tiền thu được; không đi với quality assurance.","extra":[{"en":"quality assurance standards","vi":"tiêu chuẩn đảm bảo chất lượng"},
{"en":"ensure product quality","vi":"đảm bảo chất lượng sản phẩm"}]},
{"id":"q1029","unit":7,"stem":"By repurchasing its own shares, the company created ______, which it may resell later.","options":["preferred debt","working capital","goodwill reserves","treasury stock"],"answer":3,"explain":"Treasury stock (cổ phiếu quỹ) là cổ phiếu do chính công ty mua lại. Working capital là vốn lưu động, goodwill là lợi thế thương mại, 'preferred debt' không phải khái niệm này.","extra":[{"en":"outstanding shares","vi":"cổ phiếu đang lưu hành"},
{"en":"share buyback","vi":"mua lại cổ phiếu"}]},
{"id":"q1030","unit":7,"stem":"The two firms signed a joint venture ______ setting out how profits and management responsibilities would be shared.","options":["argument","agreement","agenda","appraisal"],"answer":1,"explain":"Joint venture agreement = thỏa thuận liên doanh quy định phân chia lợi nhuận và trách nhiệm. Argument là tranh luận, agenda là chương trình nghị sự, appraisal là thẩm định.","extra":[{"en":"joint venture partner","vi":"đối tác liên doanh"},
{"en":"form a strategic partnership","vi":"hình thành quan hệ đối tác chiến lược"}]},
{"id":"q1031","unit":7,"stem":"The government plans to ______ new legislation next year requiring all listed companies to publish their carbon emissions.","options":["enforce out","enact","enlarge","enrol"],"answer":1,"explain":"Enact legislation = ban hành luật. Enlarge là mở rộng, enrol là đăng ký tuyển sinh; 'enforce out' không tồn tại (enforce = thi hành luật đã có, không phải ban hành).","extra":[{"en":"newly enacted regulations","vi":"quy định mới ban hành"},
{"en":"implement legislation","vi":"thực thi luật"}]},
{"id":"q1032","unit":7,"stem":"Smaller banks complain that the cost of ______ has risen sharply because they must now file far more reports to the regulator.","options":["retained earnings","price tolerance","cash equivalents","regulatory compliance"],"answer":3,"explain":"Regulatory compliance = tuân thủ quy định; việc nộp thêm báo cáo làm tăng chi phí này. Các cụm khác là khái niệm tài chính/marketing không liên quan đến báo cáo cho cơ quan quản lý.","extra":[{"en":"compliance officer","vi":"cán bộ tuân thủ"},
{"en":"comply with regulations","vi":"tuân thủ quy định"}]},
{"id":"q1033","unit":7,"stem":"Because of ______ exchange rates, the importer could not predict how much its euro invoices would cost in dollars.","options":["stable","fixed","favourable","volatile"],"answer":3,"explain":"Volatile = biến động mạnh, khó đoán. Stable và fixed nghĩa là ổn định/cố định nên sẽ không gây khó dự đoán; favourable là thuận lợi, không nói đến sự bất định.","extra":[{"en":"currency fluctuations","vi":"biến động tiền tệ"},
{"en":"exchange rate risk","vi":"rủi ro tỷ giá"}]},
{"id":"q1034","unit":7,"stem":"The ______ needed to open the franchise outlet, including equipment and deposit, was estimated at $80,000.","options":["additional interest","initial investment","default risk","export restriction"],"answer":1,"explain":"Initial investment = vốn đầu tư ban đầu (thiết bị, tiền đặt cọc). Additional interest là lãi bổ sung, default risk là rủi ro vỡ nợ, export restriction là hạn chế xuất khẩu.","extra":[{"en":"commit money to something","vi":"cam kết đầu tư tiền vào việc gì"},
{"en":"break-even point","vi":"điểm hòa vốn"}]},
{"id":"q1035","unit":7,"stem":"A sudden ______ on grain meant that farmers could no longer sell their harvest to overseas buyers.","options":["retained earning","joint venture","export restriction","price tolerance"],"answer":2,"explain":"Export restriction = hạn chế xuất khẩu, khiến không bán được ra nước ngoài. Các lựa chọn khác không mô tả một biện pháp của chính phủ chặn bán hàng ra nước ngoài.","extra":[{"en":"trade barrier","vi":"rào cản thương mại"},
{"en":"import quota","vi":"hạn ngạch nhập khẩu"}]},
{"id":"q1036","unit":7,"stem":"Many small firms now sell their goods ______ using online marketplaces, without opening any physical branch abroad.","options":["by borders","across borders","over border","at the borders"],"answer":1,"explain":"'Across borders' = xuyên biên giới (bán hàng quốc tế). Các giới từ còn lại không tạo thành cụm cố định với nghĩa này.","extra":[{"en":"cross-border trade","vi":"thương mại xuyên biên giới"},
{"en":"expand beyond the domestic market","vi":"mở rộng ra ngoài thị trường nội địa"}]},
{"id":"q1037","unit":7,"stem":"Which sentence correctly distinguishes between 'stock' and 'inventory' in British and American usage?","options":["In American English, 'inventory' means the shares a person owns only.","'Stock' always means cash held in the bank.","In British English, 'stock' of goods is often called 'inventory' in American English.","'Inventory' refers exclusively to a company's loans."],"answer":2,"explain":"Stock (Anh) và inventory (Mỹ) đều chỉ hàng tồn kho; nhưng stock còn có nghĩa cổ phiếu. Các câu còn lại gán sai nghĩa: inventory không phải cổ phiếu, tiền gửi hay khoản vay.","extra":[{"en":"stock control","vi":"kiểm soát hàng tồn"},
{"en":"stock market","vi":"thị trường chứng khoán"}]},
{"id":"q1038","unit":7,"stem":"Which sentence uses 'stakes' correctly?","options":["Employees have high stakes in the company's success because their bonuses depend on it.","The company sold its stakes of fish in the market.","The stakes of the loan were repaid in full.","He ordered two stakes at the shareholder meeting."],"answer":0,"explain":"Stake = lợi ích/phần góp vốn trong thứ gì. Đáp án đúng nói về lợi ích của nhân viên. Các câu còn lại nhầm với steak (món bít tết) hoặc dùng sai nghĩa.","extra":[{"en":"hold a stake in","vi":"nắm cổ phần trong"},
{"en":"a high-stakes decision","vi":"quyết định có tính sống còn"}]},
{"id":"q1039","unit":7,"stem":"The borrower's ______ is the amount originally lent; the ______ is the extra charge paid for borrowing it.","options":["principal / interest","interest / principal","principle / interest","capital / principal"],"answer":0,"explain":"Principal là gốc, interest là lãi. Đảo ngược thì sai nghĩa; 'principle' là nguyên tắc; 'capital / principal' đặt sai vị trí vì lãi không phải principal.","extra":[{"en":"principal and interest","vi":"gốc và lãi"},
{"en":"compound interest","vi":"lãi kép"}]},
{"id":"q1040","unit":7,"stem":"Customers were prepared to pay a premium for the product, which shows that the firm had correctly ______ their price tolerance.","options":["exported","enacted","embedded","estimated"],"answer":3,"explain":"Estimate price tolerance = ước lượng mức chịu giá của khách. Export là xuất khẩu, enact là ban hành luật, embed là gắn vào; không đi với 'price tolerance'.","extra":[{"en":"proposed selling price","vi":"giá bán đề xuất"},
{"en":"realistic price","vi":"mức giá thực tế"}]},
{"id":"q1041","unit":7,"stem":"Unlike a 'default', which is a failure to pay, 'default risk' refers to ______.","options":["the standard setting of a machine","the interest earned on savings","the speed of delivery","the possibility that a borrower will fail to pay"],"answer":3,"explain":"Default là sự vỡ nợ đã xảy ra, còn default risk là khả năng/xác suất vỡ nợ. Các phương án còn lại nói về cài đặt mặc định, lãi tiền gửi và tốc độ giao hàng.","extra":[{"en":"default setting","vi":"cài đặt mặc định"},
{"en":"in default","vi":"đang vỡ nợ"}]},
{"id":"q1042","unit":7,"stem":"After the product launch failed, the business ______ to achieve its objectives for the third quarter in a row.","options":["avoided","enacted","failed","distinguished"],"answer":2,"explain":"'Fail to achieve objectives' = không đạt mục tiêu. Avoid thường theo sau bởi V-ing, enact là ban hành, distinguish là phân biệt.","extra":[{"en":"meet objectives","vi":"đạt mục tiêu"},
{"en":"fall short of targets","vi":"không đạt chỉ tiêu"}]},
{"id":"q1043","unit":7,"stem":"The finance manager said that rising interest rates would ______ the cost of borrowing and make expansion projects more expensive.","options":["decrease","increase","withdraw","cater"],"answer":1,"explain":"Lãi suất tăng thì chi phí đi vay tăng (increase the cost of borrowing). Decrease thì ngược nghĩa; withdraw là rút; cater là phục vụ.","extra":[{"en":"borrowing costs","vi":"chi phí vay mượn"},
{"en":"base rate","vi":"lãi suất cơ bản"}]},
{"id":"q1044","unit":7,"stem":"The entrepreneur wanted to ______ her business beyond its domestic market, but she lacked industry knowledge and business connections abroad.","options":["expand","expose","expel","expire"],"answer":0,"explain":"Expand a business beyond the domestic market = mở rộng ra ngoài thị trường nội địa. Expose là phơi bày, expel là trục xuất, expire là hết hạn.","extra":[{"en":"business connections","vi":"các mối quan hệ kinh doanh"},
{"en":"enter a new market","vi":"thâm nhập thị trường mới"}]},
{"id":"q1045","unit":7,"stem":"Because the economy had slowed down, the retailer began to ______ weaker sales across all its stores.","options":["exercise","extend","exempt","experience"],"answer":3,"explain":"Experience weaker sales = trải qua doanh số suy yếu. Exercise là thực thi quyền, extend là gia hạn, exempt là miễn trừ; không hợp với 'weaker sales'.","extra":[{"en":"sales slump","vi":"doanh số sụt giảm"},
{"en":"sluggish demand","vi":"nhu cầu trì trệ"}]},
{"id":"q1046","unit":7,"stem":"A manager is told to ______ the need for growth with the need for financial stability. Which verb fits best?","options":["bargain","balance","bounce","burden"],"answer":1,"explain":"Balance A with B = cân bằng giữa A và B. Bargain là mặc cả, bounce là nảy/trả lại (séc), burden là gây gánh nặng; không đi với 'with' theo nghĩa này.","extra":[{"en":"strike a balance","vi":"tìm điểm cân bằng"},
{"en":"trade-off","vi":"sự đánh đổi"}]},
{"id":"q1047","unit":7,"stem":"The company's treasury stock is NOT counted as ______.","options":["repurchased shares","company-held shares","outstanding shares","shares bought back"],"answer":2,"explain":"Cổ phiếu quỹ do công ty giữ nên không tính vào cổ phiếu đang lưu hành (outstanding shares). Ba phương án còn lại đều mô tả chính cổ phiếu quỹ.","extra":[{"en":"hold treasury shares","vi":"nắm giữ cổ phiếu quỹ"},
{"en":"issued share capital","vi":"vốn cổ phần đã phát hành"}]},
{"id":"q1048","unit":7,"stem":"The two rival airlines decided to ______ a joint venture to share the cost of building a new maintenance centre.","options":["estimate","establish","exceed","enclose"],"answer":1,"explain":"Establish a joint venture = thành lập liên doanh. Estimate là ước tính, exceed là vượt quá, enclose là đính kèm.","extra":[{"en":"strategic alliance","vi":"liên minh chiến lược"},
{"en":"equity stake","vi":"phần vốn sở hữu"}]},
{"id":"q1049","unit":7,"stem":"Which of the following is the best example of an agile organization?","options":["A firm that follows a five-year plan whatever happens","A firm that avoids all new technology","A firm that reorganises teams within weeks to follow shifts in customer demand","A firm that refuses to listen to feedback"],"answer":2,"explain":"Agile = nhanh nhẹn, thay đổi nhanh theo thị trường. Ba lựa chọn còn lại mô tả công ty cứng nhắc, không đổi mới và không lắng nghe.","extra":[{"en":"respond quickly to change","vi":"phản ứng nhanh với thay đổi"},
{"en":"flexible working","vi":"làm việc linh hoạt"}]},
{"id":"q1050","unit":7,"stem":"The new factory is going to ______ the highest quality assurance standards to win contracts from global carmakers.","options":["mean","mind","mark","meet"],"answer":3,"explain":"Meet standards = đáp ứng tiêu chuẩn. Mean là có nghĩa, mind là bận tâm, mark là đánh dấu; không có collocation với 'standards' theo nghĩa đạt chuẩn.","extra":[{"en":"set a standard","vi":"đặt tiêu chuẩn"},
{"en":"ISO certification","vi":"chứng nhận ISO"}]},
{"id":"q1051","unit":7,"stem":"Consumer pressure groups argued that the labelling rules were misleading and demanded that the minister ______ them.","options":["withdraw","wither","withstand","withhold on"],"answer":0,"explain":"Withdraw rules = rút lại, bãi bỏ quy định. Wither là héo tàn, withstand là chịu đựng, 'withhold on' sai cấu trúc.","extra":[{"en":"consumer pressure groups","vi":"nhóm gây áp lực người tiêu dùng"},
{"en":"lobby against a bill","vi":"vận động phản đối dự luật"}]},
{"id":"q1052","unit":7,"stem":"Companies are required to hold enough ______ to meet their short-term financial obligations, such as paying suppliers and wages.","options":["goodwill and patents","cash and cash equivalents","fixed assets","long-term bonds"],"answer":1,"explain":"Cash and cash equivalents có thể dùng trả nợ ngắn hạn ngay. Goodwill, patents, tài sản cố định và trái phiếu dài hạn không thể quy đổi thành tiền nhanh.","extra":[{"en":"liquidity","vi":"tính thanh khoản"},
{"en":"current assets","vi":"tài sản ngắn hạn"}]},
{"id":"q1053","unit":7,"stem":"A trader who 'trades derivatives' is most likely buying and selling ______.","options":["only office furniture","the company's retained profits","bank branches","contracts whose value depends on an underlying asset"],"answer":3,"explain":"Derivative là công cụ có giá trị phụ thuộc vào tài sản cơ sở (hàng hóa, tiền tệ, cổ phiếu). Các lựa chọn khác không phải sản phẩm tài chính phái sinh.","extra":[{"en":"underlying asset","vi":"tài sản cơ sở"},
{"en":"options contract","vi":"hợp đồng quyền chọn"}]},
{"id":"q1054","unit":7,"stem":"The firm's accountant noted that ______ had grown by 12 percent because management chose to retain earnings instead of paying dividends.","options":["accumulated retained earnings","additional interest","treasury stock","default risk"],"answer":0,"explain":"Khi giữ lại lợi nhuận thay vì chia cổ tức, lợi nhuận giữ lại lũy kế (accumulated retained earnings) tăng. Các phương án khác không phản ánh việc không chi trả cổ tức.","extra":[{"en":"retain earnings","vi":"giữ lại lợi nhuận"},
{"en":"dividend policy","vi":"chính sách cổ tức"}]},
{"id":"q1055","unit":7,"stem":"The CFO warned that the plan to build three new plants was too ambitious, because its success depended on forecast cash flow that might ______ if a downturn occurred.","options":["fall through the roof","fall behind with","fall out of","fall short"],"answer":3,"explain":"'Fall short' = thấp hơn kỳ vọng, không đạt dự báo. 'Fall through the roof' là tăng vọt, 'fall behind with' đi với khoản phải trả, 'fall out of' không hợp ngữ cảnh.","extra":[{"en":"cash flow shortfall","vi":"thiếu hụt dòng tiền"},
{"en":"contingency plan","vi":"kế hoạch dự phòng"}]},
{"id":"q1056","unit":7,"stem":"A lender decides to charge higher interest to customers with a poor repayment record. This reflects its assessment of ______.","options":["price tolerance","cross-promotion","technical specifications","default risk"],"answer":3,"explain":"Khách có lịch sử trả nợ kém có default risk cao, nên ngân hàng tính lãi cao hơn để bù rủi ro. Các cụm còn lại thuộc marketing và sản xuất.","extra":[{"en":"risk premium","vi":"phần bù rủi ro"},
{"en":"credit history","vi":"lịch sử tín dụng"}]},
{"id":"q1057","unit":7,"stem":"The sentence 'The investor has a high tolerance for risk' means that she ______.","options":["avoids all uncertain investments","cannot afford any loss","is willing to accept large possible losses for higher returns","never checks the market"],"answer":2,"explain":"High tolerance for risk = sẵn sàng chấp nhận rủi ro/thua lỗ lớn để đạt lợi nhuận cao. Các đáp án còn lại mô tả người ngại rủi ro hoặc không liên quan.","extra":[{"en":"risk-averse","vi":"ngại rủi ro"},
{"en":"risk appetite","vi":"khẩu vị rủi ro"}]},
{"id":"q1058","unit":7,"stem":"The new law is intended to ______ consumers who suffer from misleading advertising, but critics say it is too weak.","options":["protect","prohibit","prosper","propose"],"answer":0,"explain":"Protect consumers = bảo vệ người tiêu dùng, mục đích điển hình của luật. Prohibit là cấm (đi với hành vi chứ không phải người), prosper là thịnh vượng (nội động từ), propose là đề xuất.","extra":[{"en":"consumer protection","vi":"bảo vệ người tiêu dùng"},
{"en":"misleading advertising","vi":"quảng cáo gây hiểu lầm"}]},
{"id":"q1059","unit":7,"stem":"The two brands agreed to ______ their customer bases: each would promote the other's complementary products to its own loyal buyers.","options":["cross-examine","cross-subsidise","cross-promote","cross out"],"answer":2,"explain":"Cross-promote = quảng bá chéo. Cross-examine là chất vấn, cross-subsidise là bù lỗ chéo bằng nguồn khác, cross out là gạch bỏ.","extra":[{"en":"complementary products","vi":"sản phẩm bổ trợ"},
{"en":"strategic partnership","vi":"quan hệ đối tác chiến lược"}]},
{"id":"q1060","unit":7,"stem":"When the factory's raw materials arrive only hours before use, the company's ______ costs are kept low.","options":["legal","principal","inventory","derivative"],"answer":2,"explain":"JIT giúp giảm chi phí tồn kho (inventory costs) vì không phải lưu kho nhiều. Legal, principal và derivative không phải chi phí liên quan đến lượng hàng chứa trong kho.","extra":[{"en":"holding costs","vi":"chi phí lưu kho"},
{"en":"lead time","vi":"thời gian chờ giao hàng"}]},
{"id":"q1061","unit":7,"stem":"The company ______ because a key supplier delivered the parts late, which stops the whole JIT system.","options":["halted retained earnings","halted production","halted treasury stock","halted default"],"answer":1,"explain":"Hệ thống JIT rất dễ bị gián đoạn khi linh kiện đến trễ nên sản xuất phải dừng (halt production). Các lựa chọn khác kết hợp 'halt' với khái niệm tài chính, không hợp lý.","extra":[{"en":"supply chain disruption","vi":"gián đoạn chuỗi cung ứng"},
{"en":"buffer stock","vi":"hàng tồn đệm"}]},
{"id":"q1062","unit":2,"stem":"The quality assurance team discovered that several parts did not match the customer's ______, so the order was rejected.","options":["product specifications","price tolerance","loan principal","joint venture"],"answer":0,"explain":"Khi sản phẩm không khớp product specifications (thông số sản phẩm) thì bị loại. Các lựa chọn khác là khái niệm tài chính hoặc đối tác, không liên quan đến việc kiểm tra hàng.","extra":[{"en":"defect rate","vi":"tỷ lệ lỗi"},
{"en":"quality control","vi":"kiểm soát chất lượng"}]},
{"id":"q1063","unit":3,"stem":"Which description of 'treasury stock' is most accurate?","options":["Shares issued to the public for the first time","Shares that a company has bought back from shareholders and holds itself","Government bonds sold by the treasury","Cash held in the company's safe"],"answer":1,"explain":"Treasury stock/share là cổ phiếu công ty mua lại từ cổ đông và tự nắm giữ. IPO shares là cổ phiếu phát hành lần đầu, government bonds là trái phiếu chính phủ, cash là tiền mặt.","extra":[{"en":"stock repurchase","vi":"mua lại cổ phiếu"},
{"en":"earnings per share","vi":"lãi trên mỗi cổ phiếu"}]},
{"id":"q1064","unit":4,"stem":"If a company fails to pay the interest and principal on its bonds when they are due, it is said to be in ______.","options":["surplus","equilibrium","default","liquidity"],"answer":2,"explain":"In default = ở trong tình trạng vỡ nợ/không thực hiện nghĩa vụ trả nợ. Surplus là thặng dư, equilibrium là cân bằng, liquidity là tính thanh khoản.","extra":[{"en":"default on debt obligations","vi":"không thực hiện nghĩa vụ nợ"},
{"en":"bankruptcy","vi":"phá sản"}]},
{"id":"q1065","unit":5,"stem":"The industry association is trying to ______ policymakers so that the proposed tax on packaging is dropped.","options":["sponsor","lobby","outsource","auction"],"answer":1,"explain":"Lobby policymakers = vận động hành lang với nhà hoạch định chính sách. Sponsor là tài trợ, outsource là thuê ngoài, auction là bán đấu giá.","extra":[{"en":"lobbyist","vi":"người vận động hành lang"},
{"en":"back down","vi":"nhượng bộ"}]},
{"id":"q1066","unit":5,"stem":"A coalition of unions and consumer groups put pressure on parliament, and the minister was finally forced to ______ a bill that would have raised fees.","options":["withdraw","reinvest","hedge","reconcile"],"answer":0,"explain":"Withdraw a bill = rút dự luật. Reinvest là tái đầu tư, hedge là phòng ngừa rủi ro, reconcile là đối chiếu/hòa giải số liệu.","extra":[{"en":"coalition government","vi":"chính phủ liên minh"},
{"en":"reach a compromise","vi":"đạt thỏa hiệp"}]},
{"id":"q1067","unit":6,"stem":"The retailer's ______ approach enables it to restructure teams quickly whenever customer needs change.","options":["agile","embedded","litigious","sluggish"],"answer":0,"explain":"Agile approach = cách tiếp cận linh hoạt, nhanh. Embedded là ăn sâu, litigious là hay kiện tụng, sluggish là chậm chạp (ngược nghĩa).","extra":[{"en":"agile methodology","vi":"phương pháp linh hoạt"},
{"en":"restructure the workforce","vi":"tái cơ cấu lực lượng lao động"}]},
{"id":"q1068","unit":6,"stem":"The bank introduced a ______ with an online retailer: customers who use its credit card receive discounts on the retailer's products.","options":["hostile takeover","cross-promotional partnership","debt restructuring","forced liquidation"],"answer":1,"explain":"Cross-promotional partnership = hợp tác quảng bá chéo cho cả hai bên. Các cụm còn lại là thâu tóm thù địch, tái cơ cấu nợ và thanh lý bắt buộc, không mô tả ưu đãi qua lại giữa hai đối tác.","extra":[{"en":"loyalty scheme","vi":"chương trình khách hàng thân thiết"},
{"en":"co-branded card","vi":"thẻ đồng thương hiệu"}]},
{"id":"q1069","unit":4,"stem":"Which of the following BEST explains why a fund manager might use derivative contracts?","options":["To reduce exposure to unexpected movements in commodity prices","To increase the company's retained earnings directly","To pay the loan principal in advance","To avoid all regulatory compliance"],"answer":0,"explain":"Derivative dùng để phòng ngừa/giảm rủi ro biến động giá hàng hóa. Chúng không trực tiếp tăng lợi nhuận giữ lại, không dùng để trả gốc vay hoặc né tránh quy định.","extra":[{"en":"commodity price","vi":"giá hàng hóa"},
{"en":"exposure to risk","vi":"mức độ phơi nhiễm rủi ro"}]},
{"id":"q1070","unit":7,"stem":"Despite a small initial investment, the start-up generated a high return. This implies that ______.","options":["the firm had no costs at all","the firm paid out huge dividends","the loan principal was cancelled","the profit was large relative to the money first put in"],"answer":3,"explain":"Initial investment nhỏ mà lợi nhuận cao nghĩa là lợi nhuận lớn so với vốn ban đầu bỏ ra (ROI cao). Các ý còn lại bịa thêm dữ kiện không có trong câu.","extra":[{"en":"return on investment","vi":"tỷ suất hoàn vốn"},
{"en":"seed funding","vi":"vốn gieo mầm"}]},
{"id":"q1071","unit":7,"stem":"The firm did not want to increase the price because it was unsure about customers' price tolerance. The word 'tolerance' here is closest in meaning to ______.","options":["punishment","speed","acceptance","protection"],"answer":2,"explain":"Tolerance ở đây là mức độ chấp nhận được (acceptance). Punishment là hình phạt, speed là tốc độ, protection là sự bảo vệ nên không đúng nghĩa.","extra":[{"en":"price-sensitive","vi":"nhạy cảm về giá"},
{"en":"elasticity of demand","vi":"độ co giãn của cầu"}]},
{"id":"q1072","unit":7,"stem":"The borrower asked to extend the repayment period from three to five years. As a result, ______.","options":["the total interest would disappear","the principal would double","each monthly payment would fall but total interest would rise","the lender would become a shareholder"],"answer":2,"explain":"Kéo dài thời hạn trả nợ làm giảm khoản trả hàng tháng nhưng tăng tổng lãi (additional interest). Lãi không biến mất, gốc không nhân đôi, và người cho vay không thành cổ đông.","extra":[{"en":"additional interest","vi":"lãi bổ sung"},
{"en":"loan term","vi":"kỳ hạn vay"}]},
{"id":"q1073","unit":7,"stem":"The Board declared that the new factory must ensure product quality by applying ______ at every production stage.","options":["default procedures","cross-promotion procedures","treasury procedures","quality assurance procedures"],"answer":3,"explain":"Quality assurance procedures = quy trình đảm bảo chất lượng. Các cụm khác không phải thuật ngữ chuẩn và không liên quan chất lượng sản phẩm.","extra":[{"en":"inspection","vi":"kiểm tra"},
{"en":"zero-defect","vi":"không lỗi"}]},
{"id":"q1074","unit":7,"stem":"Exporters complained that ______ had made it impossible to sell steel to their biggest foreign customer.","options":["an early-stage company","a higher risk tolerance","a cross-promotion","a new export restriction"],"answer":3,"explain":"Export restriction chặn việc bán thép ra nước ngoài. Các lựa chọn khác không phải là rào cản chính phủ đối với thương mại.","extra":[{"en":"embargo","vi":"lệnh cấm vận"},
{"en":"tariff","vi":"thuế quan"}]},
{"id":"q1075","unit":7,"stem":"The company needs additional funds to cover its short-term financial obligations. Which source is most suitable?","options":["A short-term bank overdraft","Issuing 30-year bonds","Selling its headquarters building","Cutting its research budget permanently"],"answer":0,"explain":"Nghĩa vụ ngắn hạn cần nguồn vốn ngắn hạn như thấu chi ngân hàng. Trái phiếu 30 năm và bán trụ sở là giải pháp dài hạn/quá lớn, cắt R&D vĩnh viễn gây hại chiến lược.","extra":[{"en":"bank overdraft","vi":"thấu chi ngân hàng"},
{"en":"working capital","vi":"vốn lưu động"}]},
{"id":"q1076","unit":7,"stem":"The merged company had to make sure it complied with new ______ before it could trade in the overseas market.","options":["price tolerances","regulatory requirements","cash equivalents","derivative stakes"],"answer":1,"explain":"Regulatory requirements = yêu cầu quy định; công ty phải tuân thủ để hoạt động ở thị trường nước ngoài. Các cụm khác không phải thứ cần tuân thủ.","extra":[{"en":"regulatory body","vi":"cơ quan quản lý"},
{"en":"license to operate","vi":"giấy phép hoạt động"}]},
{"id":"q1077","unit":7,"stem":"Why did the CEO describe the joint venture agreement as 'essential'?","options":["It set out each partner's share of profit and responsibility.","It allowed the firms to avoid all taxes.","It cancelled the firms' existing debts.","It prevented any new competitor from entering the market."],"answer":0,"explain":"Joint venture agreement quy định phần chia lợi nhuận và trách nhiệm của các bên. Nó không miễn thuế, xóa nợ hay chặn đối thủ gia nhập thị trường.","extra":[{"en":"equity joint venture","vi":"liên doanh góp vốn"},
{"en":"profit sharing","vi":"chia sẻ lợi nhuận"}]},
{"id":"q1078","unit":7,"stem":"An analyst writes: 'The firm's profits will remain stable unless there is a sharp ______, when demand declines across the whole sector.' Which phrase completes the sentence?","options":["price tolerance","cash equivalent","joint venture","economic downturn"],"answer":3,"explain":"Economic downturn = suy thoái kinh tế, khi nhu cầu giảm trên diện rộng. Các cụm còn lại không mô tả tình trạng kinh tế vĩ mô.","extra":[{"en":"recession","vi":"suy thoái"},
{"en":"economic recovery","vi":"phục hồi kinh tế"}]},
{"id":"q1079","unit":7,"stem":"Which pair of words is correctly matched in meaning?","options":["Principal: the original amount of a loan / Principle: a basic rule or belief","Principal: a basic rule / Principle: the original amount of a loan","Principal: interest on a loan / Principle: a type of bond","Principal: a share certificate / Principle: a trade barrier"],"answer":0,"explain":"Principal (n) = gốc vay (hoặc người đứng đầu); principle = nguyên tắc. Các cặp còn lại đảo nghĩa hoặc gán nghĩa sai (lãi, trái phiếu, giấy chứng nhận cổ phiếu, rào cản thương mại).","extra":[{"en":"principal amount","vi":"số tiền gốc"},
{"en":"guiding principle","vi":"nguyên tắc chỉ đạo"}]},
{"id":"q1080","unit":7,"stem":"The treasurer prefers to keep a large part of the company's funds in cash equivalents because ______.","options":["they pay the highest return on the market","they cannot lose value under any circumstances","they can be converted into cash quickly with little risk","they never need to be reported"],"answer":2,"explain":"Cash equivalents là khoản đầu tư ngắn hạn, thanh khoản cao, rủi ro thấp nên chuyển thành tiền nhanh. Không phải lúc nào cũng có lợi suất cao nhất, không đảm bảo tuyệt đối, và vẫn phải báo cáo.","extra":[{"en":"money market fund","vi":"quỹ thị trường tiền tệ"},
{"en":"liquid assets","vi":"tài sản thanh khoản"}]},
{"id":"q1081","unit":7,"stem":"The decision to form a strategic partnership with a local firm helped the company to ______ the cost of entering the new market.","options":["share","shorten","sacrifice","shelve"],"answer":0,"explain":"Share the cost = chia sẻ chi phí với đối tác. Shorten là rút ngắn, sacrifice là hy sinh, shelve là gác lại; không hợp với 'cost of entering'.","extra":[{"en":"joint venture partner","vi":"đối tác liên doanh"},
{"en":"local partner","vi":"đối tác địa phương"}]},
{"id":"q1082","unit":7,"stem":"The directors' report says: 'We took out a loan with a fixed rate to ______ the risk of rising interest rates.' Which verb best fits?","options":["limit","lift","lobby","litter"],"answer":0,"explain":"Limit the risk = hạn chế rủi ro; vay lãi suất cố định giúp hạn chế rủi ro lãi suất tăng. Lift là nâng lên, lobby là vận động hành lang, litter là xả rác.","extra":[{"en":"fixed-rate loan","vi":"khoản vay lãi suất cố định"},
{"en":"floating rate","vi":"lãi suất thả nổi"}]},
{"id":"q1083","unit":7,"stem":"A company that holds treasury stock has the option to ______ it later.","options":["default on","hedge against","resell or cancel","lobby for"],"answer":2,"explain":"Công ty có thể bán lại hoặc hủy cổ phiếu quỹ. Default on là vỡ nợ, hedge against là phòng ngừa, lobby for là vận động; không áp dụng cho cổ phiếu.","extra":[{"en":"cancel shares","vi":"hủy cổ phiếu"},
{"en":"reissue shares","vi":"phát hành lại cổ phiếu"}]},
{"id":"q1084","unit":7,"stem":"The small manufacturer had no industry knowledge of the Asian market, so it sought support from a local partner with strong business connections. Why did it do so?","options":["To avoid paying any taxes abroad","To lower its own product quality","To become a competitor of the partner","To reduce the risks of entering an unfamiliar market"],"answer":3,"explain":"Đối tác địa phương có hiểu biết ngành và quan hệ giúp giảm rủi ro khi vào thị trường lạ. Các lý do còn lại không hợp lý hoặc trái với mục tiêu kinh doanh.","extra":[{"en":"local knowledge","vi":"hiểu biết địa phương"},
{"en":"market entry strategy","vi":"chiến lược thâm nhập thị trường"}]},
{"id":"q1085","unit":7,"stem":"The farm's income depends on the weather, so it signed derivative contracts to ______ against sudden changes in crop prices.","options":["hedge","hatch","hinder","humble"],"answer":0,"explain":"'Hedge against' = phòng ngừa rủi ro. Hatch là ấp trứng, hinder là cản trở, humble là hạ thấp.","extra":[{"en":"hedging strategy","vi":"chiến lược phòng ngừa rủi ro"},
{"en":"price fluctuations","vi":"biến động giá"}]},
{"id":"q1086","unit":7,"stem":"Which sentence contains a collocation error?","options":["The firm has defaulted at its loan.","The firm has defaulted on its loan.","The loan default damaged the firm's credit rating.","The firm faces a high default risk."],"answer":0,"explain":"Đúng phải là 'default on a loan'. 'Default at' sai giới từ. Ba câu còn lại đều đúng collocation (default on, loan default, default risk).","extra":[{"en":"credit rating","vi":"xếp hạng tín nhiệm"},
{"en":"non-performing loan","vi":"nợ xấu"}]},
{"id":"q1087","unit":7,"stem":"Which sentence misuses the verb 'enact'?","options":["Parliament enacted legislation on data privacy.","The newly enacted regulations take effect in May.","The government enacted a new law last year.","The government enacted down the tax on exports."],"answer":2,"explain":"'Enact down' không tồn tại; enact đi trực tiếp với law/legislation/regulations = ban hành. Ba câu còn lại đúng.","extra":[{"en":"implement legislation","vi":"thực thi luật"},
{"en":"come into force","vi":"có hiệu lực"}]},
{"id":"q1088","unit":7,"stem":"The price of our main raw material changes every week, so we need to ______ against these fluctuations.","options":["adhere","hedge","align","assert"],"answer":1,"explain":"Hedge against fluctuations = phòng ngừa biến động. Adhere to (tuân theo), align with (căn chỉnh), assert (khẳng định) không đi với 'against ... fluctuations' theo nghĩa phòng ngừa.","extra":[{"en":"commodity hedging","vi":"phòng ngừa giá hàng hóa"},
{"en":"futures market","vi":"thị trường tương lai"}]},
{"id":"q1089","unit":7,"stem":"What is the main benefit of a cash flow forecast for a small business?","options":["It shows whether there will be enough money to meet upcoming obligations.","It guarantees that profits will rise.","It replaces the need for an annual audit.","It sets the price of the company's shares."],"answer":0,"explain":"Dự báo dòng tiền cho biết tương lai có đủ tiền để đáp ứng nghĩa vụ sắp tới không. Nó không đảm bảo lợi nhuận, không thay thế kiểm toán, không định giá cổ phiếu.","extra":[{"en":"liquidity crunch","vi":"khủng hoảng thanh khoản"},
{"en":"operating cash flow","vi":"dòng tiền hoạt động"}]},
{"id":"q1090","unit":7,"stem":"The 'repayment period' of a mortgage is best defined as ______.","options":["the interest charged on the first year","the length of time over which the borrower repays the loan","the amount of the first deposit","the value of the property after ten years"],"answer":1,"explain":"Repayment period là khoảng thời gian trả hết khoản vay. Lãi năm đầu, tiền đặt cọc và giá trị tài sản không phải là thời hạn trả.","extra":[{"en":"mortgage loan","vi":"khoản vay thế chấp"},
{"en":"down payment","vi":"khoản trả trước"}]},
{"id":"q1091","unit":7,"stem":"We prefer to buy only what we need, when we need it. We therefore adopted JIT manufacturing. In this context, JIT stands for ______.","options":["just-in-time","joint investment trust","job in training","judicial interest tax"],"answer":0,"explain":"JIT = just-in-time (đúng lúc), hệ thống mua/giao nguyên liệu khi cần. Ba cách giải thích còn lại là bịa đặt, không có trong sản xuất.","extra":[{"en":"lean manufacturing","vi":"sản xuất tinh gọn"},
{"en":"kanban","vi":"hệ thống kanban"}]},
{"id":"q1092","unit":7,"stem":"When the firm announced it would repurchase shares, the market took it as a sign that management believed the shares were ______.","options":["outstanding","undervalued","overdue","embedded"],"answer":1,"explain":"Mua lại cổ phiếu thường là tín hiệu ban lãnh đạo cho rằng cổ phiếu đang bị định giá thấp (undervalued). Outstanding là đang lưu hành hoặc xuất sắc, overdue là quá hạn, embedded là ăn sâu.","extra":[{"en":"overvalued","vi":"bị định giá quá cao"},
{"en":"share price","vi":"giá cổ phiếu"}]},
{"id":"q1093","unit":7,"stem":"Which of the following is a likely CONSEQUENCE of a loan default?","options":["The borrower's credit rating falls and borrowing becomes more expensive.","The lender's principal is automatically doubled.","The borrower gains treasury stock.","The loan becomes a joint venture."],"answer":0,"explain":"Vỡ nợ làm xấu xếp hạng tín nhiệm và chi phí vay sau đó cao hơn. Các lựa chọn khác không là hệ quả thực tế của vỡ nợ.","extra":[{"en":"credit crunch","vi":"thắt chặt tín dụng"},
{"en":"collateral","vi":"tài sản thế chấp"}]},
{"id":"q1094","unit":7,"stem":"A restriction on imports and exports is often justified by governments as a means to ______ domestic industries.","options":["pursue","prepare","preview","protect"],"answer":3,"explain":"Protect domestic industries = bảo hộ các ngành trong nước, lý do thường dùng cho hạn chế thương mại. Pursue, prepare, preview không hợp với 'domestic industries' theo nghĩa này.","extra":[{"en":"protectionism","vi":"chủ nghĩa bảo hộ"},
{"en":"free trade agreement","vi":"hiệp định thương mại tự do"}]},
{"id":"q1095","unit":7,"stem":"Before accepting the contract, the supplier checked whether it could meet every item in the ______ requirements listed by the buyer.","options":["specification","speculation","spreadsheet","settlement"],"answer":0,"explain":"Specification requirements = yêu cầu thông số kỹ thuật của bên mua. Speculation là đầu cơ, spreadsheet là bảng tính, settlement là thanh toán/dàn xếp.","extra":[{"en":"tender document","vi":"hồ sơ thầu"},
{"en":"comply with specifications","vi":"tuân thủ thông số"}]},
{"id":"q1096","unit":7,"stem":"The firm's accountant explained that 'retained earnings' means ______.","options":["money borrowed from shareholders","cash held in the company's bank","profit kept in the business rather than paid out as dividends","the value of its patents"],"answer":2,"explain":"Retained earnings là phần lợi nhuận giữ lại để tái đầu tư thay vì chia cổ tức. Tiền vay, tiền mặt và giá trị bằng sáng chế là các khoản mục khác.","extra":[{"en":"reserves","vi":"quỹ dự trữ"},
{"en":"net profit","vi":"lợi nhuận ròng"}]},
{"id":"q1097","unit":7,"stem":"The two firms worked together on a ______ that gave each of them a 50 percent stake in the new subsidiary.","options":["joint venture","hostile bid","share buyback","price war"],"answer":0,"explain":"Joint venture = liên doanh, mỗi bên có tỷ lệ sở hữu trong công ty con mới. Hostile bid là đề nghị thâu tóm thù địch, share buyback là mua lại cổ phiếu, price war là cuộc chiến giá.","extra":[{"en":"50-50 ownership","vi":"sở hữu chia đôi"},
{"en":"subsidiary","vi":"công ty con"}]},
{"id":"q1098","unit":7,"stem":"The organization has become more ______, which means it can reorganise teams and change plans quickly when the market changes.","options":["reluctant","redundant","regulated","agile"],"answer":3,"explain":"Agile = linh hoạt, thích ứng nhanh. Reluctant là miễn cưỡng, redundant là dư thừa, regulated là bị quản lý chặt; không nói về tốc độ thích ứng.","extra":[{"en":"adaptable","vi":"dễ thích nghi"},
{"en":"flat structure","vi":"cơ cấu phẳng"}]},
{"id":"q1099","unit":7,"stem":"Pressure groups usually try to influence policy by ______ rather than by standing for election.","options":["lobbying and campaigning","enacting and repealing","hedging and derivatives","refinancing and defaulting"],"answer":0,"explain":"Pressure groups ảnh hưởng chính sách bằng vận động hành lang và các chiến dịch. Ban hành/bãi bỏ luật là việc của cơ quan lập pháp; hedging và refinancing là hoạt động tài chính.","extra":[{"en":"lobby group","vi":"nhóm vận động hành lang"},
{"en":"public campaign","vi":"chiến dịch công khai"}]},
{"id":"q1100","unit":7,"stem":"Investors who put their savings into a fund with a very low risk tolerance are most likely to choose ______.","options":["highly speculative derivatives","unsecured loans to start-ups","short-term government securities","shares in an untested company"],"answer":2,"explain":"Người có risk tolerance thấp ưu tiên tài sản an toàn như chứng khoán chính phủ ngắn hạn. Phái sinh đầu cơ, cho vay không bảo đảm và cổ phiếu công ty chưa kiểm chứng đều rủi ro cao.","extra":[{"en":"conservative portfolio","vi":"danh mục thận trọng"},
{"en":"capital preservation","vi":"bảo toàn vốn"}]}];
